object Workspace {
  import Main._
  import java.util.Arrays.sort

  import scala.collection.mutable
  import math.{abs, max, min}
  import mutable.ArrayBuffer

  class BIT(n: Int, zero: Int)(f: (Int, Int) => Int) {
    def this(n: Int) = this(n, 0)(_ + _)

    private val N = {
      val a = Integer.highestOneBit(n)
      if (a == n) a else a << 1
    }
    private val bit = if (zero != 0) Array.fill[Int](N + 1)(zero) else Array.ofDim[Int](N + 1)

    /**
     * 1 index
     * addとindex違うよ
     * cumsumなんかといっしょ
     */
    def sum(i: Int): Int = {
      assert(i <= n)
      var x = i
      var s: Int = zero
      while(x > 0) {
        s = f(s, bit(x))
        x -= x & -x
      }
      s
    }

    /**
     * 0 index
     */
    def add(i: Int, a: Int): Unit = {
      assert(i < n)
      var x = i + 1
      while(x <= N) {
        bit(x) = f(bit(x), a)
        x += x & -x
      }
    }

    def sumAll: Int = sum(n)

    // A がLongとかじゃない場合はこれらを実装しないと下の奴らが使えない
    private def sub(a: Int, b: Int) = a - b
    private def lt(a: Int, b: Int) = a < b

    /**
     * [l, r)
     */
    def query(l: Int, r: Int): Int = {
      assert(r > l)
      sub(sum(r), sum(l))
    }

    def lowerBound(W: Int): Int = {
      var k = N
      var x = 0
      var w = W
      while(k > 0) {
        if (x + k <= N && lt(bit(x + k), w)) {
          w = sub(w, bit(x + k))
          x += k
        }
        k /= 2
      }
      math.min(n, x)
    }
  }
}

class Main(out: java.io.PrintWriter, sc: Main.InputReader) {
  import sc._
  import Main._
  import java.util.Arrays.sort

  import scala.collection.mutable
  import math.{abs, max, min}
  import mutable.ArrayBuffer
  import Workspace._

  // toIntとか+7とかするならvalにしろ
  final private[this] val MOD = 1000000007

  def solve(): Unit = {
    val N, M = ni()
    val A = na(N, -1)
    val c0 = new BIT(M + 1)
    val c1 = new BIT(M + 1)
    var sum = 0L
    REP(N - 1) { i =>
      val diff = (M + A(i + 1) - A(i)) % M
      sum += diff
      val s = (A(i) + 1) % M
      val t = A(i + 1)
      debug(s"i:$i diff:$diff s:$s t$t")
      if (s < t) {
        c1.add(s, 1)
        c1.add(t + 1, -1)
        c0.add(s, -s)
        c0.add(t + 1, s)
      } else {
        c1.add(s, 1)
        c1.add(M, -1)
        c0.add(s, -(s - 1))
        c0.add(M, s - 1)

        c1.add(0, 1)
        c1.add(t + 1, -1)
        c0.add(0, M - s)
        c0.add(t + 1, -(M - s))
      }
    }
    var reduce = 0L
    REP(M) { i =>
      debug(s"$i ${c0.sum(i + 1)} ${c1.sum(i + 1)}")
      reduce = max(reduce, c0.sum(i + 1) + c1.sum(i + 1).toLong * i)
    }
    out.println(sum - reduce)
  }
}

