  import Workspace._

  // toIntとか+7とかするならvalにしろ
  final private[this] val MOD = 1000000007

  def solve(): Unit = {
    val N, M = ni()
    val A = na(N, -1)
    val c0 = new BIT(M + 1)
    val c1 = new BIT(M + 1)
    var sum = 0L
    REP(N - 1) { i =>
      val diff = (M + A(i + 1) - A(i)) % M
      sum += diff
      val s = (A(i) + 1) % M
      val t = A(i + 1)
      debug(s"i:$i diff:$diff s:$s t$t")
      if (s < t) {
        c1.add(s, 1)
        c1.add(t + 1, -1)
        c0.add(s, -s)
        c0.add(t + 1, s)
      } else {
        c1.add(s, 1)
        c1.add(M, -1)
        c0.add(s, -s)
        c0.add(M, s)

        c1.add(0, 1)
        c1.add(t + 1, -1)
        c0.add(0, M - s)
        c0.add(t + 1, -(M - s))
      }
    }
    var reduce = 0L
    REP(M) { i =>
      val v = c0.sum(i + 1) + c1.sum(i + 1) * i
//      debug(s"$i ${c0.sum(i + 1)} ${c1.sum(i + 1)}")
      debug(s"i:$i v:$v")
      reduce = max(reduce, v)
    }
    out.println(sum - reduce)
  }
}

