int const MAXN = 1e5 + 5;
int Be[MAXN * 4], En[MAXN * 4], Dis[MAXN * 4];
int a[MAXN];

void Add(int x, int len, int b, int e, int f) {
  Be[x] += b;
  En[x] += f * len;
  Dis[x] += f;
}
void Pushdown(int x, int l, int r) {
  int mid = (l + r) >> 1;
  Add(lc, mid - l + 1, Be[x], Be[x] + Dis[x] * (mid - l), Dis[x]);
  Add(rc, r - mid, Be[x] + Dis[x] * (mid - l + 1), En[x], Dis[x]);
  Be[x] = En[x] = Dis[x] = 0;
}
void Modify(int x, int l, int r, int i, int j, int b, int e) {
  if (i > j) return;
  if (i <= l && r <= j) return Add(x, r - l + 1, b, e, 1);
  Pushdown(x, l, r);
  int mid = (l + r) >> 1, fmid = b + mid - i;
  if (i <= mid) Modify(lc, l, mid, i, min(mid, j), b, min(e, fmid));
  if (j > mid) Modify(rc, mid + 1, r, max(i, mid + 1), j, max(b, fmid + 1), e);
}
int Query(int x, int l, int r, int to) {
  if (l == r) return Be[x];
  int mid = (l + r) >> 1;
  Pushdown(x, l, r);
  if (to <= mid) return Query(lc, l, mid, to);
  else return Query(rc, mid + 1, r, to);
}

