typedef long long LL;

const int MaxN = 4e5;
int n, m, tot;
int a[MaxN + 5];
int left[MaxN + 5];
int r[MaxN + 5];
LL right[MaxN + 5];
struct SEG {
	int l, r;
}seg[MaxN + 5];

void Init()
{
	for (int i = 1; i <= n; i++) scanf("%d", &a[i]);
	for (int i = 1; i <= n - 1; i++) {
		if (a[i] < a[i + 1]) {
			left[a[i]]++;
			r[a[i + 1]]++;
			right[a[i + 1]] += (LL)a[i + 1] - a[i];
			seg[++tot].l = a[i];
			seg[tot].r = a[i + 1];
		}
		else {
			left[a[i]]++;
			r[a[i + 1]]++;
			right[a[i + 1] + m] += (LL)a[i + 1] + m - a[i];
			seg[++tot].l = a[i];
			seg[tot].r = a[i + 1] + m;
		}
	}
}

void Solve()
{
	LL now = 0, cnt = 0;
	for (int i = 1; i <= tot; i++) {
		if (seg[i].l == 1) now = now + seg[i].r - seg[i].l, cnt++;
			else if (seg[i].r >= m + 1) now = now + seg[i].r - m, cnt++;	
				else now += seg[i].r - seg[i].l;
	}
	LL ans = now; 
	//printf("%lld\n", ans);
	for (int i = 2; i <= m; i++) {
		//printf("cnt : %lld\n", cnt);
		cnt -= (r[i - 1] + r[m + i - 1]);
		//printf("cnt : %lld\n", cnt);
		now += right[i - 1] + right[m + i - 1] - r[i - 1] - r[m + i - 1];
		now -= cnt;
		//printf("%lld\n", now + cnt);
		ans = min(ans, now + cnt);
		cnt += left[i] + left[m + i];
	}
	printf("%lld\n", ans);
}

int main()
{
	while (~scanf("%d%d", &n, &m)) {
		Init();
		Solve();
	}
	return 0;
}

