	LL origin = 0;
	For(i, 1, n) scanf("%d", &A[i]);
	For(i, 2, n) origin += (A[i] - A[i - 1] + m) % m;

	int tot = 0, sum = 0;

	For(i, 2, n) if((A[i] - A[i - 1] + m) % m > 1){
