  array.resize(n);
  for( int i = 0;i < n;++i )
    cin >> array[i];

  int min = INT_MAX;
  for( int i = 1;i <= m;++i )
  {
    int tmp = 0;
    for( int j = 0;j < n - 1;++j )
    {
      if( array[j] < array[j + 1] )
      {
        if( array[j] < i && i <= array[j + 1] )
        {
          tmp += 1 + array[j + 1] - i;
        }
        else
        {
          tmp += array[j + 1] - array[j];
        }
      }
      else if( array[j] > array[j + 1] )
      {
        if( array[j] < i )
        {
          tmp += 1 + array[j + 1] + ( m - i );
        }
        else if( i <= array[j + 1] )
        {
          tmp += 1 + array[j + 1] - i;
        }
        else
        {
          tmp += array[j + 1] + ( m - array[j] );
        }
      }
      if( min < tmp )
        break;
    }
    if( min > tmp )
      min = tmp;
  }
  cout << min;
}

