      uping++;
      ei++;
    }
    while (ei < es.size() && es[ei].y == m && es[ei].type == 1) {
      if (es[ei].dir == 1) uping--;
      else downing--;
      saving -= es[ei].save;
      ei++;
    }
    saving += uping + downing;
  }
  cout << ans << endl;
  return 0;
}

