lint num[100010];
priority_queue<pll, vector<pll>, std::greater<pll> > pq;

int main(void) {
	lint N, M;
	scanf("%lld %lld", &N, &M);
	lint subbing = 0, cur = 0;

	for (int i = 1; i <= N; i++) {
		scanf("%lld", &num[i]);
	}
	for (int i = 1; i < N; i++) {
		if ((num[i + 1] - num[i] + M) % M > 1) {
			pq.push(pll(((num[i] + 1) % M + 1), -1));
			pq.push(pll(num[i + 1] % M + 1, ((num[i + 1] - num[i] + M) % M) - 1));
		}
		cur += (num[i + 1] - num[i] + M) % M;

		if (num[i] > 1 && num[i] < M && num[i + 1] < num[i]) {
			cur -= (M - num[i]);
			subbing++;
		}
	}

	while (!pq.empty() && pq.top().first <= 1) {
		pq.pop();
	}
	lint ans = 1000000000000LL;
	for (int i = 2; i <= M; i++) {
		while (!pq.empty() && pq.top().first == i) {
			if (pq.top().second == -1) {
				subbing++;
			}
			else {
				subbing--;
				cur += pq.top().second;
			}
			pq.pop();
		}

		cur -= subbing;
		ans = std::min(ans, cur);
	}

	printf("%lld", ans);

	return 0;
}

