inline li calc(li init, li val) {
    //dumpi2(kuriagari_from);
    //dumpi(kuriagari_sum);
    //dumpi(kuriagaranai_from);
    //dumpi(kuriagaranai_sum);
    li res = 0;
    {
        //kuriagari
        auto pos = partition_point(allof(kuriagari_from), [&val](PI x) {
            return x.F < val;
        }) - kuriagari_from.begin();
        li num = kuriagari_from.size() - pos;
        li sum_from = kuriagari_sum.back() - kuriagari_sum[pos];
        li sum_dest = (val + m) * num - num;
        res += sum_dest - sum_from;
    }
    {
        // kuriagaranaikuriagaranai_sum
        auto pos = partition_point(allof(kuriagaranai_from), [&val](PI x) {
            return x.F < val;
        }) - kuriagaranai_from.begin();
        li num = kuriagaranai_from.size() - pos;
        li sum_from = kuriagaranai_sum.back() - kuriagaranai_sum[pos];
        li sum_dest = (val - 1) * num;
        res += sum_dest - sum_from;
    }

    return init - res;
}

