		if (A[i - 1] < A[i]) {
			sum += A[i] - A[i - 1];
			update(A[i - 1] + 1, A[i] - 1, 1);
			update(A[i], A[i], -(A[i] - A[i - 1] - 1));
		}
		else {
			cnt += M - A[i - 1];
			sum += A[i] - A[i - 1] + M; 
			update(A[i - 1] + 1, M, 1);
			update(1, A[i] - 1, 1);
			update(A[i], A[i], -(A[i] - A[i - 1] + M - 1));
		}
	}
	ll ans = cnt;
	for (int i = 1; i <= N; ++i) {
		cnt += query(i, i);
		ans = max(cnt, ans);
	}
	cout << sum - ans << '\n';
}

