class BinaryIndexedTree
{
public:
    int aib[100005];

    void U(int pos, int val)
    {
        for(; pos <= M; pos += (pos & (-pos)))
            aib[pos] += val;
    }

    void update(int st, int dr, int val)
    {
        if(st > dr) return;
        U(st, val);
        U(dr + 1, -val);
    }

    int Q(int pos)
    {
        int ans = 0;
        for(; pos > 0; pos -= (pos &(-pos)))
            ans += aib[pos];
        return ans;
    }
}A, B;

