	cin >> N >> M;
	vector<int> A(N);
	for (int i = 0; i < N; i++) cin >> A[i], A[i]--;
	int NOW = 0, ANS, MIN = 0;
	for (int i = 0; i < N - 1; i++) {
		if (A[i] > A[i + 1]) NOW += A[i + 1] + 1, MIN++;
		else NOW += A[i + 1] - A[i];
	}
	ANS = NOW;
	vector<pair<int, int> > L(N - 1), R(N - 1);
	for (int i = 0; i < N - 1; i++) {
