		a[i]--;
	}
	for (int i = 0; i + 1 < n; i++) {
		sum[a[i + 1]] += (a[i + 1] + m - a[i]) % m - 1;
		if (a[i] < a[i + 1]) {
			cnt[a[i] + 1]++;
			cnt[a[i + 1]]--;
		}
		else {
			if (a[i] + 1 < m) cnt[a[i] + 1]++;
