struct Solver {
   Solver() { fprintf(stderr, "--------Solver begin--------\n"); }
   ~Solver() { fprintf(stderr, "--------Solver end--------\n"); }
   void solve() {
      long n, m; scan(n, m);
      LI xs(n); for(long &x : xs) { scan(x); x -= 1; }
      LI lefts(n-1, 0);
      LI rights(n-1, 0);
      for(long i = 0; i < n-1; ++i) {
         long left = xs[i] + 2;
         long right = xs[i+1];
         if( xs[i+1] < xs[i] ) right += m;
         lefts[i] = left;
         rights[i] = right;
      }
      LI ys(2*m+1, 0);
      // step 1
      for(long i = 0; i < n - 1; ++i) {
         ys[lefts[i]] += 1;
         ys[rights[i]+1] -= 1;
      }
      // step 2
      long t = 0;
      for(long i = 0; i < 2 * m; ++i) {
         t += ys[i];
         ys[i] = t;
      }
      // step 3
      for(long i = 0; i < n - 1; ++i) {
         ys[rights[i]+1] += -(rights[i] - lefts[i] + 1);
      }
      // step 4
      long t2 = 0;
      for(long i = 0; i < 2 * m; ++i) {
         t2 += ys[i];
         ys[i] = t2;
      }
      // step 5
      for(long i = 0; i < m; ++i) {
         ys[i] += ys[i+m];
      }
      // check
      // for(long i = 0; i < m; ++i) {
      //    dumpll(i, ys[i]);
      // }
      long totaldist = 0;
      for(long i = 0; i < n - 1; ++i) {
         totaldist += (xs[i+1] - xs[i] + m) % m;
      }
      // dumpl(totaldist);
      long res = (1LL << 50);
      for(long i = 0; i < m; ++i) {
         res = std::min(res, totaldist - ys[i]);
      }
      printf("%ld\n", res);
   }
};

int main() {
   loop std::unique_ptr<Solver>(new Solver())->solve();
}

