				update2 (a[i-1]+1, m, -1);
				update2 (1, a[i], m-a[i-1]-1);
				update1 (1, a[i]);
			}
        }
	}
	for (int i=1; i<m; ++i) sum1[i] += sum1[i-1];
	for (int i=1; i<m; ++i) sum1[i] += sum1[i-1];
	for (int i=1; i<m; ++i) sum2[i] += sum2[i-1];
	ll minn = inf;
	for (int i=1; i<m; ++i) {
		minn = min(minn, tot-sum1[i]-sum2[i]);
	}
	printf ("%I64d\n", minn);
	return 0;
}

