const num nsz = 1e5, inf = 9e18;
num n, m, ans = inf;

struct segment_tree {
    num tr[4 * nsz + 5], fi[4 * nsz + 5], del[4 * nsz + 5];

    void inline up(num u) {
        tr[u] = tr[u << 1] + tr[u << 1 | 1];
    }

    void inline down(num u, num l, num r) {
        if (!fi[u] && !del[u])  return;
        num ls = u << 1, rs = u << 1 | 1, mid = (l + r) >> 1;
        num fl = fi[u], fr = fi[u] + (mid - l + 1) * del[u], el = fl + (mid - l) * del[u], er = fr + (r - mid - 1) * del[u];
        tr[ls] += (fl + el) * (mid - l + 1) / 2;
        tr[rs] += (fr + er) * (r - mid) / 2;
        fi[ls] += fi[u];
        fi[rs] += fi[u] + (mid - l + 1) * del[u];
        del[ls] += del[u];
        del[rs] += del[u];
        fi[u] = del[u] = 0;
    }

    void upd(num el, num er, num f, num de, num u = 1, num l = 1, num r = m) {
        if (l >= el && r <= er) {
            tr[u] += (f + f + (r - l) * de) * (r - l + 1) / 2;
            fi[u] += f;
            del[u] += de;
            return;
        }
        down(u, l, r);
        num mid = (l + r) >> 1;
        if (el <= mid) {
            upd(el, er, f, de, u << 1, l, mid);
        }
        if (er >= mid + 1) {
            upd(el, er, f + (mid - l + 1) * de, de, u << 1 | 1, mid + 1, r);
        }
        up(u);
    }

    num qry(num el, num er, num u = 1, num l = 1, num r = m) {
        if (l >= el && r <= er)  return tr[u];
        down(u, l, r);
        num mid = (l + r) >> 1, res = 0;
        if (el <= mid) {
            res += qry(el, er, u << 1, l, mid);
        }
        if (er >= mid + 1) {
            res += qry(el, er, u << 1 | 1, mid + 1, r);
        }
        return res;
    }
};
segment_tree tr;

