const int N = 1e5 + 20;
long long int ero[N], cnt[N], late[N], ans[N];
int dist(int a, int b, int n){
	if(a < b)
		return b - a;
	return n - a + b;
}
int main(){
	int n, m;
	long long int cost = 0;
	scanf("%d%d", &m, &n);
	int last = -1;
	while(m--){
		int x;
		scanf("%d", &x);
		if(last != -1){
			cost += dist(last, x, n);
			ero[x] += dist(last, x, n) - 1;
			cnt[x]++;
			if(last != n)
				last++;
			else
				last = 1;
			if(last > x){
				late[last]--;
			}else{
				cnt[last]--;
			}
		}
		last = x;
	}

	int curEro = 0, curCnt = 0;
	for(int i = n; i > 0; i--){
		curEro += ero[i];
		curEro -= curCnt;
//		cout << curEro << ' ';
		ans[i] = curEro;
		curCnt += cnt[i];
		cnt[i] = 0;
		ero[i] = 0;
	}
//	cout << endl;
	long long int mx = 0;
	for(int i = n; i > 0; i--){
		curEro -= curCnt;
//		cout << curEro << ' ';
		mx = max(mx, ans[i] + curEro);
		curCnt += late[i];
		cnt[i] = 0;
		ero[i] = 0;
	}
//	cout << cost << endl;
	printf("%lld", cost - mx);
	return 0;
}

