// [f,e)
void add(int f, int e, int x) {
    for (int i = 0; i <= n / 500; i++) {
        int l = i * 400, r = (i + 1) * 400;
        if (f >= r || e <= l)
            continue;
        if (f <= l && e >= r)
            bucket[i] += x;
        else {
            for (int j = max(f, l); j < min(e, r); j++) {
                datas[j] += x;
            }
        }
    }
}

int main() {
    cin >> n >> m;
    for (int i = 0; i < n; i++) {
        cin >> a[i];
    }
    for (int i = 0; i < n - 1; i++) {
        int dif = (m + a[i + 1] - a[i]) % m;
        add(m + a[i + 1] - dif + 1, m + a[i + 1] + 1, 1);
        datas[a[i + 1]] -= dif;
    }
    for (int i = 0; i <= m * 2 + 1; i++) {
        datas[i] += bucket[i / 400];
    }
    for (int i = m * 2 + 1; i > 0; i--) {
        datas[i - 1] += datas[i];
    }
    int dmin = 99999999;
    for (int i = 1; i <= m; i++) {
        if (datas[i] + datas[i + m] < dmin) {
            dmin = datas[i] + datas[i + m];
        }
    }
    cout << dmin << endl;
    return 0;
}

