			foo += -1ll * (a[i + 1] + 1) ;
			sl[a[i] + 1] ++ ; sl[a[i + 1] + 1] -- ;
			S[a[i] + 1] += foo ; S[a[i + 1] + 1] -= foo ;
		}
		else {
			sl[a[i] + 1] ++ ; sl[1] ++ ; sl[a[i + 1] + 1] -- ;
			S[a[i] + 1] += foo - 1ll * (a[i + 1] + m + 1) ;
			S[1] += foo - 1ll * (a[i + 1] + 1) ;
			S[a[i + 1] + 1] -= foo - 1ll * (a[i + 1] + 1) ;
		}
	}	

	long long best = 0 ;

	for (int i = 1; i <= m; ++ i) {
		sl[i] += sl[i - 1] ; S[i] += S[i - 1] ;
		best = max(best, S[i] + 1ll * sl[i] * i) ;
	}

	cout << sum - best << endl ;

	return 0 ;
}

