typedef long long LL;

int N, M;
int v[100005];

class BinaryIndexedTree
{
public:
    LL aib[100005];

    void U(int pos, LL val)
    {
        for(; pos <= M; pos += (pos & (-pos)))
            aib[pos] += val;
    }

    void update(int st, int dr, LL val)
    {
        if(st > dr) return;
        U(st, val);
        U(dr + 1, -val);
    }

    LL Q(LL pos)
    {
        LL ans = 0;
        for(; pos > 0; pos -= (pos &(-pos)))
            ans += aib[pos];
        return ans;
    }
}A, B;

int main()
{
    #ifdef FILE_IO
    freopen("1.in", "r", stdin);
    freopen("1.out", "w", stdout);
    #endif

    scanf("%d%d", &N, &M);
    for(int i = 1; i <= N; i++)
        scanf("%d", &v[i]);

    for(int u = 1; u < N; u++)
    {
        int p1 = v[u];
        int p2 = v[u + 1];

        if(p1 < p2)
        {
            B.update(1, p1, p2 - p1);

            A.update(p1 + 1, p2, -1);
            B.update(p1 + 1, p2, p2 + 1);

            B.update(p2 + 1, M, p2 - p1);
        }
        else
        {
            A.update(1, p2, -1);
            B.update(1, p2, p2 + 1);

            B.update(p2 + 1, p1, M - p1 + p2);

            A.update(p1 + 1, M, -1);
            B.update(p1 + 1, M, M + p2);
        }
    }

    LL mn = 1LL << 60;
    for(int i = 1; i <= M; i++)
    {
        LL x = 1LL * A.Q(i) * i + B.Q(i);
        mn = min(mn, x);
    }

    printf("%lld\n", mn);

    return 0;
}

