typedef long long ll;
const int MAX_N=1e5+10;
int a[MAX_N],val[MAX_N];
ll sum,cnt,cnt2;
vector<int> in[MAX_N],out[MAX_N],in2[MAX_N],out2[MAX_N];
inline void change_val(int idx,int new_val){
	sum-=val[idx];
	val[idx]=new_val;
	sum+=new_val;
}
int main(){
	int N,M;
	scanf("%d%d",&N,&M);
	for(int i=1;i<=N;i++){
		scanf("%d",a+i);
		if(i>1){
			int s=a[i-1],t=a[i];
			if(s<t){
				val[i]=t-s;
				sum+=t-s;
				in[s+1].push_back(i);
				out[t].push_back(i);
			}else{
				val[i]=t+1;
				sum+=t+1;
				cnt2++;
				in2[t+1].push_back(i);
				out2[s].push_back(i);
			}
		}
	}
	ll ans=sum-cnt2;
	for(int k=2;k<=M;k++){
		for(int& v:in[k]){
			int t=a[v];
			change_val(v,t+1);
			cnt++;
		}
		for(int& v:in2[k]){
			int s=a[v-1],t=a[v];
			change_val(v,M-s+t);
			cnt2--;
		}
		ans=min(ans,sum-(cnt+cnt2)*k);
		for(int& v:out[k]){
			int s=a[v-1],t=a[v];
			change_val(v,t-s);
			cnt--;
		}
		for(int& v:out2[k]){
			int s=a[v-1],t=a[v];
			change_val(v,M+1+t);
			cnt2++;
		}
	}
	printf("%lld\n",ans);
	return 0;
}

