#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
const int N = 1 << 17;
struct Segt {
	ll sum[N << 1], add[N << 1];
	Segt() {
		memset(sum, 0, sizeof sum);
		memset(add, 0, sizeof add);
	}
	void pd(int i, int l) {
		if (add[i]) {
			sum[i] += add[i] * l;
			if (i < N) {
				add[i + i] += add[i];
				add[i + i + 1] += add[i];
			}
			add[i] = 0;
		}
	}
	void upd(int i, int a, int b, int l, int r, int v) {
		if (l <= a && b <= r) {
			add[i] += v;
			pd(i, b - a); return;
		}
		pd(i, b - a);
		if (r <= a || b <= l) return;
		int md = (a + b) >> 1;
		upd(i + i, a, md, l, r, v);
		upd(i + i + 1, md, b, l, r, v);
		sum[i] = sum[i + i] + sum[i + i + 1];
	}
	ll qry(int i, int a, int b, int l, int r) {
		pd(i, b - a);
		if (l <= a && b <= r) return sum[i];
		if (r <= a || b <= l) return 0;
		int md = (a + b) >> 1;
		ll L = qry(i + i, a, md, l, r);
		ll R = qry(i + i + 1, md, b, l, r);
		return L + R;
	}
} segt;
