# define int long long

int n, m;
int a[N], dist[N];
ll ans[N];
ll sum;

int c1[N], c2[N], c3[N];
ll t1[N], t2[N], t3[N];

void add(int v, int val){
  for(; v < N; v += v & -v){
    c1[v] += (val > 0 ? 1 : -1);
    t1[v] += val;
  }
}

void add2(int v, int val){
  for(; v < N; v += v & -v){
    c2[v] += (val > 0 ? 1 : -1);
    t2[v] += val;
  }
}

void add3(int v, int val){
  for(; v < N; v += v & -v){
    c3[v]++;
    t3[v] += val;
  }
}



pair < ll, ll > get1(int v){
  pair < ll, ll > ans;
  for(; v > 0; v -= v & -v){
    ans.first += c1[v];
    ans.second += t1[v];
  }
  return ans;
}

pair < ll, ll > get2(int v){
  pair < ll, ll > ans;
  for(; v > 0; v -= v & -v){
    ans.first += c2[v];
    ans.second += t2[v];
  }
  return ans;
}


pair < ll, ll > get3(int v){
  pair < ll, ll > ans;
  for(; v > 0; v -= v & -v){
    ans.first += c3[v];
    ans.second += t3[v];
  }
  return ans;
}

main(){
  scanf("%lld %lld", &n, &m);
  for(int i = 1; i <= n; ++i){
    scanf("%lld", a + i);
  }
  /// when optimal
  /// a[i] < fav <= a[i + 1]
  /// 1 + a[i + 1] - fav - a[i + 1] + a[i]
  /// 1 - fav + a[i]
  /// a[i] > a[i + 1] && fav <= a[i + 1]
  /// 1 + a[i + 1] - fav - a[i + 1] + a[i] - m
  /// 1 - fav + a[i] - m
  /// 1 + (a[i + 1] - fav + m) - (a[i] - a[i + 1] + m)
  /// 1 + a[i + 1] - fav - a[i] + a[i + 1]
  /// 1 + 2 * a[i + 1] - a[i]
  for(int i = 1; i < n; ++i){
    assert(a[i] != a[i + 1]);
    if(a[i] < a[i + 1]){
      dist[i] = a[i + 1] - a[i];
      add(a[i] + 1, a[i]);
      add(a[i + 1] + 1, -a[i]);
    } else{
      dist[i] = a[i + 1] - a[i] + m;
      add2(1, a[i]);
      add2(a[i + 1] + 1, -a[i]);
      add3(a[i] + 1, a[i] + 2 * a[i + 1]);
    }
    sum += dist[i];
  }
  ll wow = (ll)(1e18);
  for(int i = 1; i <= m; ++i){
    pair < ll, ll > e = get1(i);
    ans[i] = e.first - e.first * i + e.second;
    e = get2(i);
    ans[i] += e.first - e.first * i + e.second - m * e.first;
    e = get3(i);
    ans[i] += e.first + e.first * i - e.second;
  //  printf("%lld\n", ans[i] + sum);
    wow = min(wow, ans[i] + sum);
  }

  printf("%lld", wow);
  return 0;
}

