			int z=x+2;
			if(z<=y) add(z,y,-1);
			z=y+1;
			if(z>m) z-=m;
			add(z,z,y-x-1);
			tot+=y-x;
		}else{
			int z=x+2;
			if(z>m){
				z-=m;
				if(z<=y) add(z,y,-1);
			}else add(z,y,-1);
			add(y+1,y+1,y-x+m-1);
			tot+=y;
		}
//		printf("%d\n",tot);
