ll constPref[200005];
ll linearPref[200005];
ll ret;
int n, m;
int l[200005];

void constLift(int a, int b, int inc) {
  if(a > b) return;
  constPref[a] += inc;
  constPref[b+1] -= inc;
}
void linearLift(int a, int b, int inc) {
  if(a > b) return;
  linearPref[a] += inc;
  linearPref[b+1] -= inc;
}

void upd(int lhs, int rhs) {
  if(lhs < rhs) {
    int fullCost = rhs - lhs;
    // 1 through lhs incur full cost
    constLift(1, lhs, fullCost);
    // rhs+1 to m incur full cost
    constLift(rhs+1, m, fullCost);
    // 0 incurs rhs + 1
    // rhs incurs 1
    linearLift(lhs+1, rhs, -1);
    constLift(lhs+1, rhs, rhs + 1);
    return;
  }
  assert(lhs > rhs);
  // rhs ... lhs
  int fullCost = m - (lhs - rhs);
  assert(fullCost >= 1 && fullCost < m);
  // everything from rhs+1 to lhs incurs full cost
  constLift(rhs+1, lhs, fullCost);
  // lhs+1 incurs full cost
  // 1 incurs fullcost + lhs
  // 0 incurs fullcost + lhs + 1
  constLift(lhs+1, m, fullCost + lhs + 1);
  linearLift(lhs+1, m, -1);
  // rhs incurs 1
  // 1 incur rhs
  // 0 incurs rhs + 1
  constLift(1, rhs, rhs+1);
  linearLift(1, rhs, -1);
}

void collapse() {
  ret = 1e18;
  for(int i = 1; i <= m; i++) {
    linearPref[i] += linearPref[i-1];
    constPref[i] += constPref[i-1];
    ret = min(ret, linearPref[i] * i + constPref[i]);
  }
}

void solve() {
  cin >> n >> m;
  for(int i = 0; i < n; i++) {
    cin >> l[i];
  }
  for(int i = 1; i < n; i++) {
    upd(l[i-1], l[i]);
  }
  collapse();
  cout << ret << "\n";
}

void casesolve() {
  int t;
  cin >> t;
  for(int i = 1; i <= t; i++) {
    cout << "Case #" << i << " ";
    solve();
  }
}

