const int maxn=100005;
int n,m;
ll ans=(ll)INF*(ll)INF;
int ar[maxn];
pll coef[maxn*4],cons[maxn*4];//first tree.value second tree.tag

void Push(int node,pll tree[]){
	ll add=tree[node].se;
	if(add){
		tree[node*2].se+=add;
		tree[node*2+1].se+=add;
		tree[node].fi+=add;
		tree[node].se=0;
	}
}

void Pull(int node,pll tree[]){
	tree[node].fi=tree[node*2].fi+tree[node*2+1].fi;
}

void update(int l,int r,int vl,int vr,int node,pll tree[],int val){
	if(l>vr||r<vl)return;
	if(l>=vl&&r<=vr){
		tree[node].se+=val;
		Push(node,tree);
		return;
	}
	Push(node,tree);
	int mid=(l+r)>>1;
	update(l,mid,vl,vr,node*2,tree,val);
	update(mid+1,r,vl,vr,node*2+1,tree,val);
	Pull(node,tree);
}

ll query(int l,int r,int vl,int vr,int node,pll tree[]){
	if(l>vr||r<vl)return 0;
	if(l>=vl&&r<=vr)return tree[node].fi+tree[node].se;
	int mid=(l+r)>>1;
	Push(node,tree);
	return query(l,mid,vl,vr,node*2,tree)+query(mid+1,r,vl,vr,node*2+1,tree);
}

void add_ans(int a,int b){
	if(a<b){
		update(1,m,1,a,1,coef,b-a);
		update(1,m,a+1,b,1,cons,-1);
		update(1,m,a+1,b,1,coef,1+b);
		update(1,m,b+1,m,1,coef,b-a);
	}
	else{
		update(1,m,a+1,m,1,coef,1+m+b);
		update(1,m,a+1,m,1,cons,-1);
		update(1,m,1,b,1,coef,1+b);
		update(1,m,1,b,1,cons,-1);
		update(1,m,b+1,a,1,coef,m-a+b);
	}
}

