		ll cs=query(1,m,i,i,1,cons);
		ll cur=co+cs*i;
//		cout<<co<<" "<<cs<<" "<<cur<<endl;
		ans=min(cur,ans);
	}
	printf("%lld",ans);
	return 0;
}

