	for (int i = 2; i <= n; ++i) {
		if (a[i] > a[i - 1]) {
			ans += a[i] - a[i - 1];
			SegmentTree::add(1, 1, m, a[i - 1] + 1, a[i], 0);
		} else {
			ans += m - a[i - 1] + a[i];
			SegmentTree::add(1, 1, m, a[i - 1] + 1, m, 0);
			SegmentTree::add(1, 1, m, 1, a[i], m - a[i - 1]);
		}
	}

	SegmentTree::pushdown(1, 1, m);
	printf("%lld\n", ans - SegmentTree::mx[1]);
	return 0;
}

