struct Segment {

	vector<ll> a, t, prev;
	Segment(int n) : a(n), t(4 * n), prev(4 * n) {

	}


	void update(int v, int tl, int tr, int l, int r, ll add = 0) {
		if (l > r)
			return;
		if (l == tl && tr == r) {
			t[v] += 1;
			prev[v] += add - 1;
		}

		else {
			int tm = (tl + tr) / 2;
			update(v * 2, tl, tm, l, min(r, tm), add);
			if (tm >= l && r >= max(l, tm + 1)) {
				add += tm - l + 1;
			}
			update(v * 2 + 1, tm + 1, tr, max(l, tm + 1), r, add);
		}
	}

	ll get(int v, int tl, int tr, int pos) {
		if (tl == tr)
			return t[v] + prev[v] ;
		int tm = (tl + tr) / 2;
		if (pos <= tm)
			return t[v] * (pos - tl + 1) + prev[v] + get(v * 2, tl, tm, pos);
		else
			return t[v] * (pos - tl + 1) + prev[v] + get(v * 2 + 1, tm + 1, tr, pos);
	}
};
