#include <bits/stdc++.h>
using namespace std;
int a[100010];
int n, m;
long long P[100010];
long long Q[100010];

long long sum[100010];
int cnt[100010];

void forward() {
	for(int i = 2; i <= n; i++) {
		if(a[i-1] <= a[i]) {
			sum[a[i-1] + 1] += a[i-1];
			sum[a[i] + 1] -= a[i-1];
			cnt[a[i-1] + 1] += 1;
			cnt[a[i] + 1] -= 1;
		}
	}
	long long cursum = 0;
	int cunt = 0;
	for(int i = 1; i <= m; i++) {
		cursum += sum[i];
		cunt += cnt[i];
		P[i] = 1LL * i * cunt - cursum;
		P[i] -= cunt;
	}
}
void backward() {
	memset(sum, 0, sizeof sum);
	memset(cnt, 0, sizeof cnt);

	for(int i = 2; i <= n; i++) {
		if(a[i-1] > a[i]) {
			sum[a[i]] += m - a[i-1];
			cnt[a[i]] += 1;
		}
	}
	long long cursum = 0;
	int cunt = 0;
	for(int i = m; i >= 1; i--) {
		cursum += sum[i];
		cunt += cnt[i];
		Q[i] = 1LL * i * cunt + cursum;
		Q[i] -= cunt;
	}
}


int main (int argc, char const* argv[])
{
	scanf("%d %d", &n, &m);
	for(int i = 1; i <= n; i++) {
		scanf("%d", &a[i]);
	}	
	forward();
	backward();

	long long tot = 0;
	for(int i = 2; i <= n; i++) {
		if(a[i-1] <= a[i]) {
			tot += a[i] - a[i-1];
		} else {
			tot += m - a[i-1] + a[i];
		}
	}
	long long ans = tot;
	for(int i = 1; i <= m; i++) {
		long long res = tot - P[i] - Q[i];
		ans = min(ans, res);
	}
	printf("%lld\n", ans);
	return 0;
}

