		}
		if (x<a1){
			return a2-a1;
		}
		if (x>a2){
			return a2-a1;
		}
	}else if (a1>a2){
		if (x==a1 || x==a2){
			if (x==a2){
				return 1;
			}
			return m-a1+a2;
		}
		if (a2<x && x<a1){
			return m-a1+a2;
		}
		if (x<a2){
			return 1+a2-x;
		}
		if (x>a1){
