struct SegTree {
    ll sum, add;
    int flag, on;
}t[N * 4];

void build(int x, int b, int e){
    if(b == e){
        t[x].sum = 0;
        t[x].add = 0;
        t[x].flag = 0;
        return ;
    }
    int m = (b + e) >> 1;
    build(x + x, b, m);
    build(x + x + 1, m + 1, e);
    t[x].sum = t[x].add = t[x].flag = 0;
}

void modify_sum(int x, int b, int e, int l, int r, int v){
    if(b > r || e < l) return ;
    if(b >= l && e <= r){
        t[x].sum += v;
        t[x].flag = 1;
        return ;
    }
    int m = (b + e) >> 1;
    modify_sum(x + x, b, m, l, r, v);
    modify_sum(x + x + 1, m + 1, e, l, r, v);
}

void modify_add(int x, int b, int e, int l, int r, int v){
    if(b > r || e < l) return ;
    if(b >= l && e <= r){
        t[x].add += v;
        t[x].on = 1;
        return ;
    }
    int m = (b + e) >> 1;
    modify_add(x + x, b, m, l, r, v);
    modify_add(x + x + 1, m + 1, e, l, r, v);
}

void lazy_add(int x, int b, int e){
    if(b != e){
        if(t[x].on > 0){
            t[x + x].add += t[x].add;
            t[x + x + 1].add += t[x].add;
            t[x].add = 0;
            t[x].on = 0;
            t[x + x].on = 1;
            t[x + x + 1].on = 1;
        }
    }
}

ll get_add(int x, int b, int e, int l, int r){
    lazy_add(x, b, e);
    if(b > r || e < l) return 0;
    if(b >= l && e <= r){
        return t[x].add;
    }
    int m = (b + e) >> 1;
    return get_add(x + x, b, m, l, r) +
           get_add(x + x + 1, m + 1, e, l, r);
}

void lazy_sum(int x, int b, int e){
    if(b != e){
        if(t[x].flag > 0){
            t[x + x].sum += t[x].sum;
            t[x + x + 1].sum += t[x].sum;
            t[x].sum = 0;
            t[x].flag = 0;
            t[x + x].flag = 1;
            t[x + x + 1].flag = 1;
        }
    }
}

ll get_sum(int x, int b, int e, int l, int r){
    lazy_sum(x, b, e);
    if(b > r || e < l) return 0;
    if(b >= l && e <= r){
        return t[x].sum;
    }
    int m = (b + e) >> 1;
    return get_sum(x + x, b, m, l, r) +
           get_sum(x + x + 1, m + 1, e, l, r);
}

