	ll tmp = 0;
	rep(i, n - 1) {
		int normal = (a[i + 1] - a[i] + m) % m;
		int warp = (a[i + 1] - 0 + m) % m + 1;
		tmp += min(normal, warp);
	}

	// これをもとに x = 1, 2, 3, ... のときも求める
	// imos法でxがa[i]とa[i + 1]の間(両端覗く)にあるか求める
	vector<int> num(m, 0);
	rep(i, n - 1) {
		// 隣り合っているときはなにもいない これいらなそう
		if ((a[i + 1] - a[i] + m) % m == 1) continue;

		++num[(a[i] + 1) % m];
		--num[a[i + 1]];
		if (a[i + 1] < a[i] && a[i + 1] != 0) {
			// 0をまたぐとき
			++num[0];
		}
