    ll total = 0;
    for (ll i = 1; i < n; i++) {
        int start = pos.at(i - 1);
        const int end = pos.at(i);
        total += (end - start + m) % m;
        start = (start + 1) % m + 1;
        if (start < end) {
            if (end <= m - 2) {
                imos.at(start) += 1;
                imos.at(end + 1) += -end + start - 2;
                imos.at(end + 2) += end - start + 1;
            } else if (end == m - 1) {
                imos.at(start) += 1;
                imos.at(m) += -end + start - 2;
            } else {
                imos[start] += 1;
            }
        } else if (start > end) {
            if (end <= start - 3) {
                imos.at(1) += m - start + 2;
                imos.at(2) += -m + start - 1;
                imos.at(end + 1) += -m + start - end - 2;
                imos.at(end + 2) += m - start + end + 1;
                imos.at(start) += 1;
            } else if (end == start - 2) {
                imos.at(1) += m - start + 2;
                imos.at(2) += -m + start - 1;
                imos.at(end + 1) += -m + start - end - 2;
                imos.at(end + 2) += m - start + end + 2;
            } else {
                imos.at(1) += m - start + 2;
                imos.at(2) += -m + start - 1;
                imos.at(end + 1) += -m;
                imos.at(end + 2) += m;
            }
        } else {
            if (start <= n - 2) {
                imos[start] += 1;
                imos[start + 1] += -2;
                imos[start + 2] += 1;
            } else if (start == n - 1) {
                imos[start] += 1;
                imos[start + 1] += -2;
            } else {
                imos[start] += 1;
            }
        }
    }
    vector<ll> tmp(m + 1, 0);
    for (ll i = 1; i <= m; i++) {
        if (i == 1) {
            tmp.at(i) = imos.at(i);
        } else {
            tmp.at(i) = tmp.at(i - 1) + imos.at(i);
        }
    }
    vector<ll> adv(m + 1, 0);
    for (ll i = 1; i <= m; i++) {
        if (i == 1) {
            adv.at(i) = tmp.at(i);
        } else {
            adv.at(i) = adv.at(i - 1) + tmp.at(i);
        }
    }
    ll maxi = -1;
    for (ll i = 1; i <= m; i++) {
        if (maxi < adv[i]) {
            maxi = adv[i];
        }
    }
    cout << total - maxi << endl;

    return 0;
}

