void addprog(int l, int r, int start) {
    int len = r - l + 1;
    int fin = start - len + 1;
    c[l] += start;
    c[l + 1] -= start + 1;
    c[r + 1] -= fin - 1;
    c[r + 2] += fin;
}

void addconst(int l, int r, int cns) {
    c[l] += cns;
    c[l + 1] -= cns;
    c[r + 1] -= cns;
    c[r + 2] += cns;
}

