            scanf("%d",&op[i]);
        for(int i=1;i<n;i++)
        {
            if((op[i]+1)%m==(op[i+1])%m)
              continue;
            if(op[i]+2>m)
                add((op[i]+2)%m,op[i+1],1,1,m,1);
            else add(op[i]+2,op[i+1],1,1,m,1);
        }
        refresh(1,m,1);
        ll sum=0;
        for(int i=1;i<n;i++)
        {
            sum+=((op[i+1]-op[i])%m+m)%m;
        }
        printf("%lld\n",sum-ans);
    }
    return 0;
}

