void upd(int v  , int tl, int tr , int pos , int x){
	t[v].pb(x);
	if(tl == tr)return;
	int tm = (tl + tr) >> 1;
	if(pos <= tm)
		upd(v << 1,  tl , tm , pos , x);
	else 
		upd(v << 1|1, tm + 1,  tr , pos , x);
}
pii comb(pii a , pii b){
	return {a.fi + b.fi , b.se + a.se};
}
pii flex(vector < int > &a , vector < int > &b , int x , int lim){
	if(sz(a) == 0)return {0,0};
	int l = 0 , r = sz(a) - 1 , p = sz(a) - 1 , p2 = sz(a) - 1;
    if(a[r] < x or a[0] > lim)
		return {0,0};
	while(l <= r){
		int m = (l + r) >> 1;
		if(a[m] >= x)
			p = m , r = m - 1;
		else l = m + 1;			
	}
	l = 0 , r = sz(a) - 1;
	while(l <= r){
		int m = (l + r) >> 1;
		if(a[m] <= lim)
			p2 = m , l = m + 1;
		else r = m - 1;			
	}

	if(p > p2)return{0,0};
	int sum = b[p];
	if(p2 != sz(a) - 1)sum -= b[p2 + 1];
	return {sum , p2 - p + 1};
}

pii get(int v , int tl , int tr , int l , int r , int x , int lim){
	if(l > r or l > tr or tl > r)
		return {0,0};
	if(l <= tl and tr <= r){
		return flex(t[v] , sum[v] , x , lim);		
	}
	int tm = (tl + tr) >> 1;
	return comb(get(v << 1, tl , tm , l , r , x, lim ) , get(v << 1|1 , tm + 1, tr , l , r , x , lim));
}
void Add(int x , int y){
	if(x < y){

		add(1 , x ,y - x);
		add(y + 1 , m, y - x);
		upd(1 , 1 , m + 1, x + 1 , y);
	}
    else {
		y += m;
        add(y - m + 1, x ,y - x);
		upd(1 , 1 , m + 1, x + 1 , y);
    }
}
