        if (a[i] < a[i + 1]) {
            evs.push_back({a[i], {1, 0}});
            evs.push_back({a[i + 1], {-1, a[i + 1] - a[i]}});
        } else {
            evs.push_back({a[i], {1, 0}});
            evs.push_back({m + 1, {-1, m + 1 - a[i]}});
            evs.push_back({1, {1, 0}});
            evs.push_back({a[i + 1], {-1, a[i + 1] - 1}});
        }
