    }
    sort(evs.begin(), evs.end());
    int cnt = 0;
    long long dst = 0;
    long long mx = 0;
    for (int i = 0; i < evs.size(); i++) {
        if (i > 0) {
            dst += cnt * (evs[i].first - evs[i - 1].first);
        }
        mx = max(mx, dst - cnt);
        cnt += evs[i].second.first;
        if (evs[i].second.first == -1) {
            dst -= evs[i].second.second;
        }
    }

