  std::vector<ll> cost(m+1,0),len(m+2,0);

  rep(i,1,n){
    cost[a[i]]+=(a[i]-now+m)%m-1;
    if(now<a[i]){
      ans+=a[i]-now;
      len[now+1]++;
      len[a[i]]--;
    }else{
      ans+=a[i];
      len[now+1]++;
      len[m+1]--;
      len[1]++;
      len[a[i]]--;
    }
    now=a[i];
  }

  rep(i,1,m+2)len[i]+=len[i-1];

  ll val=ans;
  rep(i,1,m){
    val-=len[i];
    val+=cost[i];
    chmin(ans,val);
  }

  std::cout<<ans<<"\n";

  return 0;
}

