int main() {
    ios::sync_with_stdio(0), cin.tie(0), cout.tie(0);
	int N, M; cin >> N >> M;
	vi arr (N);
	F0R(i, N) cin >> arr[i];
	F0R(i, N) arr[i]--;

	vector<pii> segments;
	ll total = 0;
	FOR(i, 1, N) {
		if (arr[i-1] > arr[i]) {
			segments.push_back({arr[i-1] - M, arr[i]});
			segments.push_back({arr[i-1], arr[i] + M});
			total += arr[i] - arr[i-1] + M;
		} else {
			segments.push_back({arr[i-1], arr[i]});
			total += arr[i] - arr[i-1];
		}
	}
	sort(segments.begin(), segments.end());

	ll bestcut = 0;
	ll cut = 0;
	int users = 0;
	multiset<pii> rhs;
	int i = 0;
	F0R(f, M) {
		while (!rhs.empty() && (*rhs.begin()).first < f) {
			cut -= (*rhs.begin()).second;
			rhs.erase(rhs.begin());
			--users;
		}
		while (i < segments.size() && segments[i].first < f) {
			users++;
			cut += f - segments[i].first - 1;
			rhs.insert({segments[i].second, segments[i].second - segments[i].first});
			++i;
		}
		cut += users;
		bestcut = max(bestcut, cut - users);
	}
	print(total - bestcut);
}

