const int MAXN = 1e5+5;

int n, m, a[MAXN];
int mm(int x){
	return (x%m+m)%m;
}
int dst(int v, int u){
	return mm(u-v);
}

int ddec[MAXN], dval[MAXN];
int main(){
	rii(n,m);
	FOR(i,0,n){
		ri(a[i]);
		a[i]--;
	}
	ll mn, val=0, dec=0;
	FOR(i,0,n-1){
		int v=a[i], u=a[i+1];
		int d = dst(v,u);
		int l=mm(u-(d-1)), r=u;
		ddec[l]++;
		ddec[r]--;
		dval[r]+=d-1;
		if(l>r){
			r+=m;
			if(l<a[0] && a[0]<=r) dec++;
			else{
				r-=m;
				l-=m;
				if(l<a[0] && a[0]<=r) dec++;
			}
		}else{
			if(l<a[0] && a[0]<=r) dec++;
		}
		val += min(d, 1+dst(a[0],u));
	}
	mn = val;
	FOR(ii,a[0],a[0]+m){
		int i=mm(ii);
		mn=min(val,mn);
		dec += ddec[i];
		val = val - dec;
		val += dval[i];
	}
	printf("%lld\n",mn);
}

