void add(vector<ll>& c1, vector<ll>& c0, int l, int r, int s) {
  if (l <= r) {
    c1[l] += 1;
    c1[r + 1] -= 1;
    c0[l] += s - l;
    c0[r + 1] -= s - l;
  }
}

