template <typename Abelian>
struct BITRangeAdd {
  BITRangeAdd(int n_, const Abelian UNITY = 0) : n(n_), UNITY(UNITY) {
    ++n;
    dat_const.assign(n, UNITY);
    dat_linear.assign(n, UNITY);
  }

  void add(int left, int right, Abelian val) {
    if (right < ++left) return;
    for (int i = left; i < n; i += i & -i) {
      dat_const[i] -= val * (left - 1);
      dat_linear[i] += val;
    }
    for (int i = right + 1; i < n; i += i & -i) {
      dat_const[i] += val * right;
      dat_linear[i] -= val;
    }
  }

  Abelian sum(int idx) {
    Abelian res = UNITY;
    for (int i = idx; i > 0; i -= i & -i) res += dat_linear[i];
    res *= idx;
    for (int i = idx; i > 0; i -= i & -i) res += dat_const[i];
    return res;
  }

  Abelian sum(int left, int right) {
    if (right <= left) return UNITY;
    return sum(right) - sum(left);
  }

  Abelian operator[](const int idx) { return sum(idx, idx + 1); }

private:
  int n;
  const Abelian UNITY;
  vector<Abelian> dat_const, dat_linear;
};

int main() {
  int n, m; cin >> n >> m;
  vector<int> a(n); REP(i, n) cin >> a[i], --a[i];
  BITRangeAdd<ll> bit(m + 1);
  ll ans = 0;
  REP(i, n - 1) {
    if (a[i] < a[i + 1]) {
      ans += a[i + 1] - a[i];
      bit.add(a[i] + 2, a[i + 1] + 1, 1);
      bit.add(a[i + 1] + 1, a[i + 1] + 2, -((a[i + 1] + 1) - (a[i] + 2)));
    } else {
      ans += m - a[i] + a[i + 1];
      bit.add(a[i] + 2, m, 1);
      bit.add(m, m + 1, -max(m - (a[i] + 2), 0));
      // REP(j, m + 1) cout << bit[j] << " \n"[j == m];
      bit.add(0, 1, max(m - (a[i] + 2), 0));
      bit.add(a[i + 1] + 1, a[i + 1] + 2, -max(m - (a[i] + 2), 0));
      bit.add(a[i] + 1 == m ? 1 : 0, a[i + 1] + 1, 1);
      bit.add(a[i + 1] + 1, a[i + 1] + 2, -((a[i + 1] + 1) - (a[i] + 1 == m ? 1 : 0)));
    }
  }
  vector<ll> imos(m + 1);
  REP(i, m + 1) imos[i] = bit[i];
  FOR(i, 1, m + 1) imos[i] += imos[i - 1];
  // REP(i, m + 1) cout << imos[i] << " \n"[i == m];
  cout << ans - *max_element(ALL(imos)) << '\n';
  return 0;
}

