template<typename T>
struct cumulative_sum_linear {
    int n;
    vector<T> x, a, b;

    cumulative_sum_linear(int n = 0) : n(n), x(n), a(n+1), b(n+1) {}

    void add(int l, int r, T p, T q) {
        a[l] += p;
        a[r] -= p;
        a[l] -= q * l;
        a[r] += q * l;
        b[l] += q;
        b[r] -= q;
    }

    void build() {
        for (int i = 0; i < n; ++i) {
            x[i] = a[i] + b[i] * i;
            a[i+1] += a[i];
            b[i+1] += b[i];
        }
    }

    T operator[](int i) const { return x[i]; }
};

int main() {
    int n, m;
    cin >> n >> m;
    vector<int> a(n);
    rep(i, n) cin >> a[i], a[i]--;

    ll sum = 0;
    cumulative_sum_linear<ll> cnt(2 * m);

    rep(i, n-1) {
        int d = (a[i+1] - a[i] + m) % m;
        sum += d;
        int s = (a[i] + 1) % m;
        cnt.add(s, s + d, 0, 1);
    }

    cnt.build();
    vector<ll> x(m);
    rep(i, m) x[i] = cnt[i] + cnt[i+m];
    cout << sum - *max_element(x.begin(), x.end()) << '\n';
}

