        int l = a[i], r = a[i+1];
        if(l > r) r += m;
        ans += r-l;
        update(1, 1, 2*m-1, l, r, l+1);
        cnt[l]++, cnt[r+1]--;
    }
    rep(i, 1, 2*m) cnt[i] += cnt[i-1];
    LL mx = 0;
    rep(i, 1, m) {
        LL val = cal(i);
        if(i < m) val += cal(i+m);
        chkmax(mx, val);
    }
    ans -= mx;
    cout << ans;


    return 0;
}

