const int MAX_N = 100000 + 3;
int n, m, a[MAX_N], decc[MAX_N];
vector<int> vec1[MAX_N], vec2[MAX_N];
int cnt[MAX_N];
ll sum[MAX_N];

int main() {
	n = readInt(), m = readInt();
	for (int i = 0; i < n; ++i) a[i] = readInt();

	ll res = 0;
	for (int i = 0; i < n - 1; ++i) {
		if (a[i + 1] > a[i]) {
			vec1[a[i + 1]].push_back(a[i]);
		} else {
			cnt[a[i]]++;
			vec2[a[i + 1]].push_back(a[i]);
		}
		res += (a[i + 1] - a[i] + m) % m;
	}

	multiset<int> s;
	ll ss = 0;
	for (int i = m - 1; i >= 0; --i) {
		for (int j = 0; j < (int)vec1[i].size(); ++j)
			s.insert(vec1[i][j]), ss += vec1[i][j];
		while (!s.empty() && *s.rbegin() >= i) ss -= *s.rbegin(), s.erase(--s.end());
		decc[i] = (ll)(i - 1) * s.size() - ss;
	}

	for (int i = 1; i < m; ++i) sum[i] = sum[i - 1] + (ll)cnt[i] * i, cnt[i] += cnt[i - 1];
	for (int i = 1; i < m; ++i) decc[i] += (ll)cnt[i - 1] * (i - 1) - sum[i - 1];

	ss = 0;
	for (int i = m - 1, cc = 0; i >= 0; --i) {
		for (int j = 0; j < (int)vec2[i].size(); ++j)
			ss += vec2[i][j], ++cc;
		decc[i] += (ll)(m + i - 1) * cc - ss;
	}

	printf("%lld\n", res - *max_element(decc, decc + m));

	return 0;
}

