            res = (res * a) % mod;
        a = (a * a) % mod;
        n >>= 1;
    }
    return res;
}

void precalc() {
    fact[0] = fact[1] = 1;
    inv[0] = inv[1] = 1;
    for (ll i = 2; i < MAXN; ++i) {
        fact[i] = (fact[i - 1] * i) % mod;
        inv[i] = bpow(fact[i], mod - 2);
    }
}

ll C(ll n, ll k) {
    if (n < k)
        return 1;
    return (((fact[n] * inv[n - k]) % mod) * inv[k]) % mod;
}


