		cin >> a[i];
		--a[i];
	}
	const int k = n - 1;
	vector<pii> b(k);
	for(int i = 0; i < k; ++i){
		if(a[i + 1] < a[i]){
			b[i] = pii(a[i], a[i + 1] + m);
		}else{
			b[i] = pii(a[i], a[i + 1]);
		}
	}
	sort(b.begin(), b.end());
	priority_queue<pii, vector<pii>, greater<pii>> pq;
	ll current = 0;
	for(int i = 0; i < k; ++i){
		if(b[i].second >= m){
			pq.push(pii(b[i].second - m, i));
			current += b[i].second - m + 1;
		}else{
			current += b[i].second - b[i].first;
		}
	}
	ll best = current;
	for(int i = 1, j = 0; i < m; ++i){
		while(!pq.empty() && pq.top().first < i){
			const int t = pq.top().second;
			pq.pop();
			current -= 1;
			current += b[t].second - b[t].first;
		}
		current -= pq.size();
		best = min(best, current);
		while(j < k && b[j].first < i){
			pq.push(pii(b[j].second, j));
			++j;
		}
	}
