typedef pair<int,int> P;
int array[100005]={0};
int main(){
  int n,m;
  cin>>n>>m;
  vector<P> vec;
  int ans1=0,sum=0;
  for(int i=0;i<n;i++) cin>>array[i];
  for(int i=0;i<n-1;i++){
    vec.push_back(P(array[i],array[i+1]));
    if(array[i]>array[i+1]){
      ans1+=m-array[i];
    }
    int d=array[i+1]-array[i];
    sum+=d+(d>0?0:m);
  }
  sort(vec.begin(),vec.end());
  int s=0,kans=0;
  priority_queue<P,vector<P>,greater<P>> pque;
  for(int i=0;i<n-1;i++){
    if(vec[i].first>vec[i].second&&vec[i].second>=2){
      pque.push(P(vec[i].second,vec[i].first));
      kans+=m+1-vec[i].first;
      s++;
    }
  }
  int pos=0;
  int ans=sum-kans;
  for(int i=3;i<=m;i++){
    int npos=upper_bound(vec.begin(),vec.end(),P(i-1,0))-vec.begin();
    for(int j=pos;j<npos;j++){
      if(vec[j].second>=i){
        pque.push(P(vec[j].second,vec[j].first));
        int tk=i-vec[j].first-2;
        kans+=tk+(tk<0?m:0);
        s++;
      //  cout<<i<<" in:"<<j<<" point:"<<tk+(tk<0?m:0)<<endl;
      }
    }
    if(!pque.empty()){
      while(pque.top().first<i){
        P p=pque.top();
        pque.pop();
        s--;
        int d=p.first-p.second-1;
        kans-=d+(d<0?m:0);
      //  cout<<i<<" out:"<<p.second<<" "<<p.first<<" "<<d+(d<0?m:0)<<endl;
        if(pque.empty()) break;
      }
    }
    kans+=s;
    ans=min(ans,sum-kans);
    //cout<<i<<" "<<kans<<" "<<s<<endl;
    pos=npos;
  }
  cout<<min(ans,sum-ans1)<<endl;
}

