#include <bits/stdc++.h>
using namespace std;

typedef long long ll;
const int maxn = 1e5 + 10;
int n, h, x[maxn];
ll arr[3][maxn], r[maxn];

int prefix_rect(int l, int v){
	arr[1][1] += v;
	arr[1][l + 1] -= v;
	arr[0][l + 1] += ll(v) * l;
}

int rect(int l, int r, int v){
	prefix_rect(r, v);
	prefix_rect(l - 1, -v);
}

int prefix_tria(int l, int v){
	arr[2][1] += v;
	arr[2][l + 1] -= v;
	arr[0][l + 1] += ll(l) * (l + 1) * v / 2;
}

int tria(int l, int r, int v){
	prefix_tria(r, v);
	prefix_tria(l - 1, -v);
	rect(l, r, -l + 1);
}

void flatten(){
	ll s0 = 0, s1 = 0, s2 = 0;
	for(int i = 1; i < maxn; i++){
		s0 += arr[0][i], s1 += arr[1][i], s2 += arr[2][i];
		r[i] = ll(s0) + ll(i) * s1 + ll(i) * (i + 1) * s2 / 2;
	}

//	for(int i = 1; i <= h; i++){
//		cout << r[i] - r[i - 1] << ' ';
//	}
//	cout << endl;
}

void process(int i){
	int cut = x[i] - x[i - 1];
	if(cut < 0){
		cut += h;
	}
//	}cout << cut << endl;

	if(cut > x[i]){
		rect(1, h - x[i], x[i]);
		tria(1, cut - x[i], 1);
		rect(cut - x[i] + 1, h - x[i], cut - x[i]);
		tria(h - x[i] + 1, h + 1, 1);
	}else{
//		cout << "yup\n";
		rect(1, h - x[i], cut);
		tria(h - x[i] + 1, h - x[i] + cut, 1);
		rect(h - x[i] + cut + 1, h + 1, cut);
	}
}

int main(){
	ios_base::sync_with_stdio(false);

	cin >> n >> h;

	for(int i = 0; i < n; i++){
		cin >> x[i];

		if(i > 0){
			process(i);
		}
	}

	flatten();

	ll mn = 1e18;
	for(int i = 1; i <= h; i++){
		mn = min(mn, r[i] - r[i - 1]);
	}

	cout << mn << endl;

	return 0;
}

#include <bits/stdc++.h>

using namespace std;
using ll = long long;

#define let auto
#define conr auto const&

int const N = 200 * 1000 + 16;
int const M = 1000 * 1000 * 1000 + 7;

int n, m;
int a[N];
ll p[N+N];
ll b[N+N];

void add(int idx, ll v) {
  for(int i = idx; i <= m+m; i |= i+1)
    b[i] += v;
}

void add(int l, int r, ll v) {
  add(l, v);
  add(r+1, -v);
}

ll query(int idx) {
  ll sum = 0;
  for(int i = idx; i >= 0; i = (i&(i+1)) - 1)
    sum += b[i];
  return sum;
}

int dist(int x, int y) {
  return x < y ? y-x : y+m-x;
}


int main() {
  cin.tie(0);
  cin.sync_with_stdio(0);

  cin >> n >> m;
  for(int i = 0; i < n; ++i) {
    cin >> a[i];
    a[i]--;

    if(i) {
      int l = a[i-1];
      int r = a[i];
      if(r < l)
        r += m;
      int d = r-l;
      p[r] += d;
      add(l, r-1, -1);
    }
  }

  for(int i = m+m; i >= 0; --i)
    p[i] += query(i);

  for(int i = m+m-1; i >= 0; --i)
    p[i] += p[i+1];

  for(int i = 0; i < m; ++i) {
    p[i] += p[i+m];
    // cout << p[i] << " ";
  }

  int idx = max_element(p, p+m) - p;

  ll sum = 0;
  for(int i = 1; i < n; ++i) {
    int l = a[i-1];
    int r = a[i];
    int d = dist(l, r);
    if(r == idx)
      d = 1;
    else if(l != idx)
      d = min(d, 1 + dist(idx, r));
    sum += d;
  }
  cout << sum << endl;
}

