int main() {
    int n, m;
    scanf("%d%d", &n, &m);
    int pre = 0;
    scanf("%d", &pre);
    LL totall = 0;
    for(int i=2; i<=n; i++) {
        int x;
        scanf("%d", &x);
        if(x < pre)
            x += m;
        totall += x - pre;
        dis1[pre+1]++;
        dis1[x+1]--;
        dis2[pre+1] += pre+1;
        dis2[x+1] -= pre+1;
        pre = (x <= m ? x : x-m);
    }
    for(int i=1; i<=2*m; i++) {
        dis1[i] += dis1[i-1];
        dis2[i] += dis2[i-1];
    }
    LL answer = INF;
    for(int i=1; i<=m; i++) {
        LL x = dis1[i]*i - dis2[i] + dis1[i+m]*(i+m) - dis2[i+m];
        answer = min(answer, totall - x);
    }
    printf("%lld\n", answer);
}

