  for (int i = 1; i < n; ++i) {
    if (a[i] > a[i - 1]) {
      sum += a[i] - a[i - 1];
    } else {
      sum += a[i] + m - a[i - 1];
    }
  }
  for (int i = 1; i <= m; ++i) ret[i] = sum;
  // trace(sum);
  vector<ii> A;
