    } else {
      A.push_back({a[i - 1], 1});
      A.push_back({a[i] + m, -a[i - 1]});
    }
  }
  sort(A.begin(), A.end());
  int64 cnt = 0, acc = 0;
  for (int i = 1, j = 0; i <= m * 2; ++i) {
    for (; j < A.size() && A[j].first < i; ++j) {
