template<typename T> class BIT
{
   private:
      vector<T> bit;
      int len;
   public:
      BIT(int n) {
         len = n+1;
         bit.resize(len);
      }
      void add(int i, T x) {
         i += 1;
         while (i < len) {
            bit[i] += x;
            i += i & -i;
         }
      }
      int sum(int i) {
         i += 1;
         T s = 0;
         while (i > 0) {
            s += bit[i];
            i -= i & -i;
         }
         return s;
      }
};

signed main()
{
   int n; cin >> n >> m;
   V<int> a(n);
   REP(j, n) {
      cin >> a[j]; a[j]--;
   }

   V<int> dist(n-1);
   REP(j, n-1) {
      dist[j] = mod(a[j+1] - a[j]);
   }

   V<int> cost(m);
   REP(j, n-1) {
      int d = mod(0 - a[j]);      // distance to the favorite point
      if (d == 0 || dist[j] < d) {
         cost[0] += dist[j];
      } else {
         cost[0] += dist[j] - d + 1;
      }
   }

   BIT<int> diff(m+1);
   REP(j, n-1) {
      if (dist[j] == 0) continue;

      diff.add(       a[j+1],  dist[j]-1);
      diff.add(mod(a[j+1]+1), -dist[j]+1);
      if (mod(a[j]+1) < a[j+1]) {
         diff.add(mod(a[j]+1), -1);
         diff.add(     a[j+1],  1);
      } else {
         diff.add(mod(a[j]+1), -1);
         diff.add(          m,  1);
         diff.add(          0, -1);
         diff.add(     a[j+1],  1);
      }
   }

   REP(i, m-1) {
      cost[i+1] = cost[i] + diff.sum(i);
   }
   SORT(cost);
   cout << cost[0] << endl;

   return 0;
}

