class KT{
    public:
    int _n;
    vector<long long> range, d, d2;
    vector<pair<int, long long>> apEnds;
    KT(int n):range(n,0), d(n,0), d2(n,0), _n(n){}

    void addAP(int start, int end, long long a0=1, long long r=1){
        d[start]+=a0;
        if(end<_n-1){
            d[end+1]-=a0;
            d2[end+1]-=r;
            apEnds.push_back(make_pair(end+1,-r*(end-start)));
        }
        if(start<_n-1){
            d2[start+1]+=r;
        }
    }

    void update(){
        for(int i=1; i<_n; i++){
            d[i]+=d[i-1];
            d2[i]+=d2[i-1];
        }
        for(auto p:apEnds){
            d2[p.first]+=p.second;
        }
        for(int i=0; i<_n; i++){
            if(i) d2[i]+=d2[i-1];
            range[i]=d[i]+d2[i];
        }

    }
    void disp(){
        for(int i:range){
            cout<<i<<" ";
        }
    }

};




