	for(int i=0;i<N-1;++i){
		int from = A[i];
		int to = A[i+1];
		if( to < from ){
			to += M;
		}
		//from->to
		X0.add(1,to-from);
		X0.add(M+1,-(to-from));
		int T = to + 1;
		X0.add(from+1,T -(to-from));
		X0.add(to+1,-T +(to-from));
		X1.add(from+1,-1);
		X1.add(to+1,1);

