void addEvent(int a, int b, int v) {
	if(a > b) return;
	open[a].emplace_back(v);
	close[b].emplace_back(v);
}
void proc(int a, int b) {
	DBG(a); DBG(b);
	if(a == b) return;
	if(a < b) {
		addEvent(a + 1, b, a + 1);
	} else {
		addEvent(a + 1, m - 1, a + 1);
