            if(a[i]<m-1){modify(1,1,m,a[i]+2,m,1,-a[i]-1);}
            modify(1,1,m,1,a[i+1],1,dis-1-a[i]+1);
        }ans+=dis;
    }for(int i=1;i<=m;i++){
        Ans=min(Ans,ans-query(1,1,m,i));
    }printf("%lld\n",Ans);
}

