long long sol(int l,int r)
{
    long long ret=((1LL)<<55);
    while(l<r)
    {
        int m1=(l+r)/2;
        int m2=m1+1;
        long long x=getDist(m1);
        long long y=getDist(m2);
        if (x<y)
            ret=min(ret,x),r=m1-1;
