    }

    FOR(i,m,2*m+1) {
        add[i % m] += add[i];
        rem[i % m] += rem[i];
    }

    ll currScore = 0, bestScore = -INF;
    int best = -1;

    FOR(i,0,m-1) {
        currScore += add[i];
        currScore -= rem[i];

        if (currScore > bestScore) {
            bestScore = currScore;
            best = i;
        }
    }

    ll ans = 0;
    FOR(i,0,n-2) if (a[i] != a[i+1]) {
        int l = a[i], r = a[i+1];

        if (r < l) {
            r += m;
        }

        int here = r - l;

        if (best >= l && best <= r) {
            here = min(here, r - best + 1);
        }

        if (best + m <= r) {
            here = min(here, r - (best + m) + 1);
        }

        ans += here;
    }

    cout << ans;

    return 0;
}

