  for (int m = 1; m < M; ++m) {
    dp[m+1] = dp[m]-sum(m);
    for (int i = lower_bound(all(vp), pii(m, 0)) - vp.begin(); i < vp.size() && vp[i].fi == m ; ++i) {
      dp[m+1] += (a[vp[i].sc]+M-a[vp[i].sc - 1])%M - 1;
    }
  }

  ll ans = 1e18;
  for (int m = 1; m <= M; ++m) {
    ans = min(ans, dp[m]);
  }

  cout << ans << endl;

  return 0;
}

