  }

  ll ans=0;
  for(int i=1;i<n;i++){
    if((a[i]-a[i-1]+m)%m==1) ans++;
    else{
      if(a[i-1]<a[i]) add(a[i-1]+2,a[i]+1,1,0,0,m+1);
      else{
