			else high = (a[i + 1] + m + 1) % m, low = (a[i] + 1) % m;
			upper[high].push_back(i);
			lower[low].push_back(i);
			assert(high != low);
			// std::cerr << "i:" << i << " (" << low << "," << high << ")" << std::endl;
