        }
        else {
            ++covered[0],--covered[a[i]+1];
            if (a[i-1]<m-2) ++covered[a[i-1]+2];
        }
    }
    rep(i,m-1) covered[i+1]+=covered[i];
    ll cnt=0;
    rep2(i,1,n){
        if (a[i-1]<=a[i]) cnt+=a[i]-a[i-1];
        else cnt+=a[i]+1;
    }
    ll ans=cnt;
    rep2(i,1,m){
        cnt-=covered[i];
        cnt+=dat[i][1]-dat[i][0];
        chmin(ans,cnt);
    }
    cout << ans << endl;
}

