void solve() {
  inl(N , M);
  vl a(N); in(a);

  vl dp(2 * N + 10 , 0);

  ll ans = 0;
  rep(i , N - 1){
    ll s = a[i] , t = a[i + 1];
    if(s > t) t += M;
    ans += t - s;
    if(s + 1 == t) continue;
    // s + 2が1、tがt-s-1となる
    // -> 2階imosすると
    // s + 2が1、t+1がs-t、t+2がt-s-1となる
    dp[s + 2] += 1;
    dp[t + 1] += s - t;
    dp[t + 2] += t - s - 1;
    trc(dp);
  }

  // 2階積分する
  auto mkrui = [](auto v) -> decltype(v){
    decltype(v) ret(v.size() + 1);
    for(int i = 0 ; i < int(v.size()) ; i++) 
      ret[i + 1] = ret[i] + v[i];
    return ret;
  };
  dp = mkrui(dp); dp.erase(dp.begin());
  trc(dp);
  dp = mkrui(dp); dp.erase(dp.begin());

  trc(dp);
  for(int i = M + 1 ; i < sz(dp);i++){
    dp[(i - 1) % M + 1] += dp[i];
  }
  dp.resize(M + 1);
  trc(dp);

