			l += m;
			r += m;
			op[l]++;
			cl[r].push_back(l);
		} else {
			r += m;
			op[l]++;
			cl[r].push_back(l);
		}
	};
	int s = 0;
	for (int i = 0; i + 1 < n; i++) {
		add(a[i], a[i + 1]);
		s += (a[i + 1] - a[i] + m) % m;
	}
	int ans = s;
	int sum_l = 0;
	int sz = 0;
	for (int i = 0; i < 2 * m; i++) {
		int cur = s;
		cur -= (i * sz) - sum_l;
		cur += sz;
		ans = min(ans, cur);
		sum_l += i * op[i];
		sz += op[i];
		for (auto l : cl[i]) {
			sum_l -= l;
			sz--;
		}
	}
	cout << ans << endl;
}

