	if(l>=pos||!ct[x]) return; if(r<pos){CT+=ct[x],NUM+=sum[x];return;}
	int mid=((l+r)>>1); qry(L[x],l,mid,pos,CT,NUM),qry(R[x],mid+1,r,pos,CT,NUM);
}
