        cur = read();
        int mx = calc(pre, cur), pos = cur, l = 1, r = pos - mx + 1, f;
        if (l <= r && chk(l) && chk(r)) {
            tr.upd(l, r, mx, 0);
        }
        l = pos + 1;
        r = min(m, pos + m - mx + 1);
        if (l <= r && chk(l) && chk(r)) {
            tr.upd(l, r, mx, 0);
        }
        l = max(1, pos - mx + 2);
        r = pos;
        f = 1 + (pos - l);
        if (l <= r && chk(l) && chk(r)) {
            tr.upd(l, r, f + (l - 1), -1);
        }
        l = pos + m - mx + 2;
        r = m;
        f = mx - 1;
        if (l <= r && chk(l) && chk(r)) {
            tr.upd(l, r, f + (l - 1), -1);
        }
        pre = cur;
    }
