#include <cstdio>
#include <algorithm>
using namespace std;
typedef long long LL;
const int maxn=1e5+10;

struct node
{
	int l,r;
	node *ls,*rs;
	LL tms,s;
} *root;
int n,m;
int a[maxn];
LL ans,ori;

void buildtree(node *p,int l,int r)
{
	p->l=l;p->r=r;
	p->tms=p->s=0;
	if (l==r) return;
	p->ls=new node;
	p->rs=new node;
	buildtree(p->ls,l,(l+r)>>1);
	buildtree(p->rs,((l+r)>>1)+1,r);
	return;
}

LL gets(node *p,int pos)
{
	if (p->l==p->r) return p->s;
	else 
	{
		if (pos<=p->ls->r) return p->s+gets(p->ls,pos);
		else return p->s+gets(p->rs,pos);
	}
}

LL gettms(node *p,int pos)
{
	if (p->l==p->r) return p->tms;
	else 
	{
		if (pos<=p->ls->r) return p->tms+gettms(p->ls,pos);
		else return p->tms+gettms(p->rs,pos);
	}
}

void adds(node *p,int l,int r,LL val)
{
	if (l>r) return;
	if (l<=p->l && p->r<=r) 
	{
		p->s+=val;
		return;
	}

	if (l<=p->ls->r) adds(p->ls,l,r,val);
	if (p->rs->l<=r) adds(p->rs,l,r,val);
	return;
}

void addtms(node *p,int l,int r)
{
	if (l>r) return;
	if (l<=p->l && p->r<=r) 
	{
		p->tms++;
		return;
	}

	if (l<=p->ls->r) addtms(p->ls,l,r);
	if (p->rs->l<=r) addtms(p->rs,l,r);
	return;
}

int main()
{
	scanf("%d%d",&n,&m);
	for(int i=1;i<=n;i++)
		scanf("%d",&a[i]);

	root=new node;
	buildtree(root,1,m);
	for(int i=1;i<n;i++)
	{
		if (a[i]<a[i+1])
		{
			adds(root,a[i]+1,a[i+1],(LL)-a[i]-1);
			addtms(root,a[i]+1,a[i+1]);
		}
		else
		{
			adds(root,a[i]+1,m,(LL)-a[i]-1);
			addtms(root,a[i]+1,m);
			adds(root,1,a[i+1],m-a[i]-1);
			addtms(root,1,a[i+1]);
		}
	}

	ori=0;
	for(int i=1;i<n;i++)
		if (a[i]<a[i+1]) ori+=(LL)(a[i+1]-a[i]);
		else ori+=(LL)(a[i+1]+m-a[i]);
	ans=0;
	for(int i=1;i<=m;i++)
		ans=max(ans,gets(root,i)+gettms(root,i)*(LL)i);
	ans=ori-ans;

	printf("%lld\n",ans);
	return 0;	
}

