void push(int x,int l, int r){
  if(COEF[x]>=0){
    if(l==r){
      return;
    }
    int mid=(l+r)/2;
    SUM[2*x]+=SUM[x];
    COEF[2*x]+=COEF[x];

    SUM[2*x+1]+=SUM[x]+COEF[x]*(mid-l+1);
    COEF[2*x+1]+=COEF[x];

    COEF[x]=0;
    SUM[x]=0;
  }
}

ll res=-1;
ll tadd(int x,int a,int b,int l,int r,int coef){
  //db(x<<" "<<a<<" "<<b<<" "<<l<<" "<<r<<" "<<coef);
  if(b<l||a>r)return 0;
  push(x,l,r);
  if(a<=l&&r<=b){
    if(coef>=0){
      SUM[x]+=coef;
      COEF[x]+=1;
    }

    res=SUM[x];
    return r-l+1;
  }
  push(x,l,r);

  if(l==r){
    assert(0);
    res=SUM[x];

    return 1;
  }
  int mid=(l+r)/2;

  if(l<=mid)coef+=tadd(2*x,a,b,l,mid,coef);
  if(mid+1<=r)coef+=tadd(2*x+1,a,b,mid+1,r,coef);
  //pull();
  return coef;
}

