    for (int i = 0; i < n; ++i) {
        cin >> a[i];
    }

    for (int i = 0; i < n - 1; ++i) {
        if (a[i] < a[i + 1]) {
            con[1] += a[i + 1] - a[i];
            con[a[i] + 1] -= (a[i + 1] - a[i]);
            con[a[i] + 1] += a[i + 1] + 1;
            con[a[i + 1] + 1] -= (a[i + 1] + 1);
            con[a[i + 1] + 1] += (a[i + 1] - a[i]);
            --linear[a[i] + 1];
            ++linear[a[i + 1] + 1];
        } else {
            con[1] += a[i + 1] + 1;
            con[a[i + 1] + 1] -= (a[i + 1] + 1);
            con[a[i + 1] + 1] += (m - a[i] + a[i + 1]);
            con[a[i] + 1] -= (m - a[i] + a[i + 1]);
            con[a[i] + 1] += (a[i + 1] + m + 1);
            --linear[1];
            ++linear[a[i + 1] + 1];
            --linear[a[i] + 1];
        }
    }

    ll res = LONG_LONG_MAX;
    for (int i = 1; i <= m; ++i) {
        con[i] += con[i - 1];
        linear[i] += linear[i - 1];
        res = min(res, con[i] + linear[i] * i);
    }

    cout << res;

    return 0;
}

