            for (auto &p : idxr[i - 1]) {
                mid--;
                temp++;
                ll diff = a[p] - a[p - 1];
                if (diff < 0)
                    diff += m;
                temp += diff - 1;
            }
        }
        chmin(ret, temp);
    }
    cout << ret << "\n";
    return 0;
}

