void update(int node, int l, int r, int a, int b, ll aa, ll bb) {
	if (a <= l && r <= b) {
		st[node].a += aa;
		st[node].b += bb;
		return ;
	}
	int mid = (l + r) >> 1, A = node << 1, B = A | 1;
	if (mid >= a) {
		update(A, l, mid, a, b, aa, bb);
	}
	if (mid + 1 <= b) {
		int mv = (mid + 1) - a;
		int add = 0;
		if (mv > 0) {
			aa += bb * mv;
		}
		update(B, mid + 1, r, a, b, aa, bb);
	}
	return ;
}

ll ans = INFLL;

void dfs(int node, int l, int r) {
	if (l == r) {
		ans = min(ans, st[node].a);
		return ;
	}
	int mid = (l + r) >> 1, A = node << 1, B = A | 1;
	st[A].a += st[node].a;
	st[A].b += st[node].b;
	int mv = (mid + 1) - l;
	st[node].a += st[node].b * mv;
	st[B].a += st[node].a;
	st[B].b += st[node].b;

	dfs(A, l, mid);
	dfs(B, mid + 1, r);
	return ;
}

