void build(int node, int L, int R) {
//	if (L == 6 && R == 6) cout << node << endl;
//	if (node == 3) cout << L << " " << R << endl;
	val[node] = oo;
	_lz[L] = mp(0, 0);

	if (L == R) {
		val[node] = 0;
		leaf[node] = 1;
	}

	if (L < R) {
		int mid = (L + R) >> 1;
		build(node * 2, L, mid);
		build(node * 2 + 1, mid + 1, R);
	}
}

void pushdown(int node, int L, int R) {
	if (leaf[node]) {
		val[node] += _lz[node].FI;
		_lz[node] = mp(0, 0);
		return;
	}

	int mid = (L + R) >> 1;
	int rem = mid - L + 1;
	_lz[node * 2].FI += _lz[node].FI;
	_lz[node * 2].SE += _lz[node].SE;
	_lz[node * 2 + 1].FI += _lz[node].FI - _lz[node].SE * rem;
	_lz[node * 2 + 1].SE += _lz[node].SE;
	_lz[node] = mp(0, 0);
}

void update(int node, int L, int R, int l, int r, int v, int d) {
	if (l > R || r < L) return;
	pushdown(node, L, R);

	if (l <= L && R <= r) {
		int rem = L - l;
		_lz[node].FI += (v - d * rem);
		_lz[node].SE += d;
		return;
	}

	if (L < R) {
		int mid = (L + R) >> 1;
		update(node * 2, L, mid, l, r, v, d);
		update(node * 2 + 1, mid + 1, R, l, r, v, d);
	}
}

void finalBuild(int node, int L, int R) {
	pushdown(node, L, R);
//	if (L == R) {
//		cout << L << " " << val[node] << endl;
//	}
	if (L < R) {
		int mid = (L + R) >> 1;
		finalBuild(node * 2, L, mid);
		finalBuild(node * 2 + 1, mid + 1, R);
		val[node] = min(val[node * 2], val[node * 2 + 1]);
	}
}

