				++id; l[id]=v[i]+1; r[id]=v[i+1]+1;
				a[++tot]=(node){l[id],id};
				a[++tot]=(node){r[id],id};
			}
		}
		else
		{
			re+=m-v[i]+v[i+1];
			if(v[i]%m+1!=v[i+1])
			{
				int kk=m-v[i];
				++id; l[id]=1-kk; r[id]=v[i+1]+1;
				a[++tot]=(node){l[id],id};
				a[++tot]=(node){r[id],id};
			}
			if(v[i]<m-1)
			{
				++id; l[id]=v[i]+1,r[id]=m+1;
				a[++tot]=(node){l[id],id};
			}
		}
	}sort(a+1,a+tot+1,cmp);

	int pos=1;
	ll ans=0,sum=0,num=0;
	for(int i=1;i<=m;i++)
	{
		while(pos<=tot&&a[pos].p<=i)
		{
			id=a[pos].i;
			if(a[pos].p!=r[id]) sum+=l[id],num++;
			else sum-=l[id],num--;
			pos++;
		}
		ans=max(ans,num*(ll)i-sum);
	}
	printf("%lld\n",re-ans);

	return 0;
}

