    size_t idx = 0;
    int64_t cnt = 0, acc = 0;

    for(size_t x = 0; x < inc.size(); ++ x)
    {
      inc[x] = acc;
      acc += cnt;

      for(; idx < b.size() && b[idx].first < x + 1; ++ idx)
      {
        ++ cnt;
        heap.push(idx);
      }

      while(!heap.empty())
      {
        const auto i = heap.top();
        if(x < b[i].second) break;
        heap.pop();
        -- cnt;
        acc -= x - b[i].first;
      }
