struct seg{
	LL ls,rs; seg(){}
	seg(LL _ls,LL _rs){ls=_ls,rs=_rs;}
	bool operator <(const seg&ot)const{return rs>ot.rs;}
}q[M<<2];
LL K,n,m,rt[M<<2],L[M*21],R[M*21],cnt,ct[M*21]; LL maxn,tot,ans,sum[M*20];
void ins(LL &x,LL pre,LL l,LL r,LL pos){
	x=++cnt,L[x]=L[pre],R[x]=R[pre];
	sum[x]=sum[pre]+pos,ct[x]=ct[pre]+1;
	if(l==r) return; LL mid=((l+r)>>1);
	if(pos<=mid) ins(L[x],L[pre],l,mid,pos);
	else ins(R[x],R[pre],mid+1,r,pos);
}
void qry(LL x,LL l,LL r,LL pos,LL &CT,LL &NUM){
	if(l>=pos||!ct[x]) return; if(r<pos){CT+=ct[x],NUM+=sum[x];return;}
	LL mid=((l+r)>>1); qry(L[x],l,mid,pos,CT,NUM),qry(R[x],mid+1,r,pos,CT,NUM);
}
