void update(int L,int R,int p,int l,int r,int v){
	if(L==l&&R==r){
		val[p]+=v;
		return;
	}int mid=(L+R)>>1;
	if(mid>=r)update(L,mid,p<<1,l,r,v);
	else if(mid<l)update(mid+1,R,p<<1|1,l,r,v);
	else update(L,mid,p<<1,l,mid,v),update(mid+1,R,p<<1|1,mid+1,r,v);
}
void update_(int L,int R,int p,int l,int r,int v){
	if(L==l&&R==r){
//		printf("---%d %d %d %d %d\n",L,R,l,r,v);
		val[p]+=v;
		cnt[p]++;
		return;
	}int mid=(L+R)>>1;
	if(mid>=r)update_(L,mid,p<<1,l,r,v);
	else if(mid<l)update_(mid+1,R,p<<1|1,l,r,v);
	else update_(L,mid,p<<1,l,mid,v),update_(mid+1,R,p<<1|1,mid+1,r,v);
}
LL query(int L,int R,int p,int x){
//	printf("%lld %lld %lld %d %d\n",val[p]-(LL)cnt[p]*x,val[p],cnt[p],L,R);
	if(L==R)return val[p]-(LL)cnt[p]*x;
	int mid=(L+R)>>1;
	if(mid>=x)return query(L,mid,p<<1,x)+val[p]-(LL)cnt[p]*x;
	else return query(mid+1,R,p<<1|1,x)+val[p]-(LL)cnt[p]*x;
}
