typedef long long ll;
typedef tuple<int, int, int> T;

struct SegmentTree {
    int n;
    vector<ll> data;

    static ll INITIAL_VALUE;
    static ll merge(ll x, ll y); 
    void updateNode(int k, ll x);

    SegmentTree(int size) {
        n = 1;
        while (n < size) n *= 2;
        data.resize(2 * n - 1, INITIAL_VALUE);
    }

    int getLeaf(int k) {
        return data[k + n - 1];
    }

    void update(int a, int b, ll x, int k, int l, int r) {
        if (r <= a || b <= l) return;
        if (a <= l && r <= b) updateNode(k, x);
        else {
            update(a, b, x, k * 2 + 1, l, (l + r) / 2);
            update(a, b, x, k * 2 + 2, (l + r) / 2, r);
        }
    }

    void update(int a, int b, ll x) {
        return update(a, b, x, 0, 0, n);
    }

    ll query(int k) {
        ll res = 0;
        k += n - 1; 
        res += data[k];
        while (k > 0) {
            k = (k - 1) / 2;
            res += data[k];
        } 
        return res;       
    }
};

ll SegmentTree::INITIAL_VALUE = 0;

ll SegmentTree::merge(ll x, ll y) {
    return x + y;
}

void SegmentTree::updateNode(int k, ll x) {
    data[k] += x;
}

