	scanf("%d%d",&n,&m);
	for(int i = 1; i <= n; ++i) scanf("%d",&a[i]);
	for(int i = 1; i < n; ++i){
		if (a[i] < a[i + 1]){
			an[1] += a[i + 1] - a[i];
			an[a[i] + 1] -= a[i + 1] - a[i];
			an[a[i + 1] + 1] += a[i + 1] - a[i];
			an[a[i] + 1] += a[i + 1] + 1;
			++r[a[i] + 1];
			an[a[i + 1] + 1] -= a[i + 1] + 1;
			--r[a[i + 1] + 1];
		}
		else{
			an[a[i] + 1] += a[i + 1] + 1;
			++g[a[i] + 1];
			++r[1];
			an[1] += a[i + 1] + 1;
			an[a[i + 1] + 1] -= a[i + 1] + 1;
			--r[a[i + 1] + 1];
			an[a[i + 1] + 1] += m - a[i] + a[i + 1];
			an[a[i] + 1] -= m - a[i] + a[i + 1];
		}
	}
