struct node
{
	ll a0, d;
	node(ll a = 0, ll b = 0) { a0 = a, d = b; }
	node operator + (const node &p) const
		{
			return node(a0 + p.a0, d + p.d); 
		}
};
struct SegTree
{
	struct Tree { node x; } t[N << 2];
	void pushdown(int p, int l, int r)
		{
			if(t[p].x.a0 || t[p].x.d)
			{
				int mid = (l + r) >> 1;
				t[p << 1].x = t[p << 1].x + t[p].x;
				t[p << 1 | 1].x = t[p << 1 | 1].x + node(t[p].x.a0 + (mid + 1 - l) * t[p].x.d, t[p].x.d);
				t[p].x = node(0, 0); 
			}
		}
	void modify(int p, int l, int r, int ql, int qr, node y)
		{
			if(ql > qr) return; 
			if(ql <= l && r <= qr)
			{
				y = node(y.a0 + (l - ql) * y.d, y.d); 
				t[p].x = t[p].x + y; return; 
			}
			pushdown(p, l, r); int mid = (l + r) >> 1; 
			if(ql <= mid) modify(p << 1, l, mid, ql, qr, y); 
			if(mid < qr) modify(p << 1 | 1, mid + 1, r, ql, qr, y); 
		}
	void query(int p, int l, int r)
		{
			if(l == r) return (void) (f[l] = t[p].x.a0); 
			pushdown(p, l, r); int mid = (l + r) >> 1;
			query(p << 1, l, mid), query(p << 1 | 1, mid + 1, r); 
		}
} T; 

template < typename T >
inline T read()
{
	T x = 0, w = 1; char c = getchar();
	while(c < '0' || c > '9') { if(c == '-') w = -1; c = getchar(); }
	while(c >= '0' && c <= '9') x = x * 10 + c - '0', c = getchar();
	return x * w; 
}

