	{
		l = a[i - 1], r = a[i];
		if(a[i] >= a[i - 1])
		{
			T.modify(1, 1, m, l + 1, r, node(r - l, -1)); 
			T.modify(1, 1, m, 1, l, node(r - l, 0));
			T.modify(1, 1, m, r + 1, m, node(r - l, 0));
		}
		else
		{
			T.modify(1, 1, m, l + 1, m, node(r + m - l, -1));
			T.modify(1, 1, m, 1, r, node(r, -1));
			T.modify(1, 1, m, r + 1, l, node(r + m - l, 0));
		}
	}
