int main() {
	cin >> n >> m;
	REP(i, n) scanf("%d", a + i);

	REP(i, n - 1) {
		int idx = a[i] >= a[i + 1];

		int aa = a[i] + 1;
		int bb = a[i + 1];

		if (aa == m + 1) aic[1][1]++;
		else aic[0][aa]++;
		adc[idx][bb]++;
		dc[idx][bb] += (a[i + 1] - a[i] + m) % m - 1;
	}

	ll now = 0, aa = 0, p = 1;

	REP(i, 2 * m) {
		now += aa;
		sum[p] += now;

		int idx = i >= m;
		aa += aic[idx][p] - adc[idx][p];
		now -= dc[idx][p];

		p++;
		if (p > m) p = 1;
	}

	pll ma(-INF, 0);
	REP(i, m) chmax(ma, pll(sum[i], i));

