using namespace std;
int n,m,a[N]; LL F[N],S[N],ans;
void Mark(int l,int r,int u,int p)
{
	int x=u-p;
	if(x<l){ F[l]++,F[r+1]--,S[l]+=u-l+1,S[r+1]-=u-r; return ;}
	if(x>r){ S[l]+=p,S[r+1]-=p; return ;}
	S[l]+=p,S[x+1]-=p;
	F[x+1]++,F[r+1]--,S[x+1]+=u-x,S[r+1]-=u-r;
}
int main()
{
	int i,p;
	scanf("%d %d",&n,&m);
	for(i=1;i<=n;i++)
		scanf("%d",&a[i]);
	for(i=2;i<=n;i++){
		p=a[i]-a[i-1];
		if(p<0) p+=m;
		Mark(1,a[i],a[i]+1,p);
		Mark(a[i]+1,m,a[i]+m+1,p);
	  }
	for(i=1;i<=m;i++)
		F[i]+=F[i-1],S[i]+=S[i-1]-F[i];
	ans=INF;
	for(i=1;i<=m;i++)
		ans=min(ans,S[i]);
	cout<<ans;
	return 0;
}

