struct Segment {

	vector<int> a, t, prev;
	Segment(int n) : a(n), t(4 * n), prev(4 * n) {

	}


	void update(int v, int tl, int tr, int l, int r, int add = 0) {
		if (l > r)
			return;
		if (l == tl && tr == r) {
			t[v] += 1;
			prev[v] += add - 1;
		}

		else {
			int tm = (tl + tr) / 2;
			update(v * 2, tl, tm, l, min(r, tm), add);
			if (tm >= l && r > tm) {
				add += tm - l + 1;
			}
			update(v * 2 + 1, tm + 1, tr, max(l, tm + 1), r, add);
		}
	}

	int get(int v, int tl, int tr, int pos) {
		if (tl == tr)
			return t[v] + prev[v] ;
		int tm = (tl + tr) / 2;
		if (pos <= tm)
			return t[v] * (pos - tl + 1) + prev[v] + get(v * 2, tl, tm, pos);
		else
			return t[v] * (pos - tl + 1) + prev[v] + get(v * 2 + 1, tm + 1, tr, pos);
	}
};
int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(NULL);
	int n, m;
	cin >> n >> m;
	vector<int> arr(n);
	ll sum = 0;
	for (int i = 0; i < n; ++i) {
		cin >> arr[i];
	}

	Segment tree(m + 1);
	for (int i = 1; i < n; ++i) {
		if (arr[i] > arr[i - 1]) {
			sum += arr[i] - arr[i - 1];
			tree.update(1, 0, m , arr[i - 1] + 1, arr[i]);
		}
		else {
			sum += m - arr[i - 1] + arr[i];
			tree.update(1, 0, m, arr[i - 1] + 1, m);
			tree.update(1, 0, m, 1, arr[i], m - arr[i - 1]);
		}
		/*for (int j = 0; j <= m; ++j) {
			cout << tree.get(1, 0, m, j) << " ";
		}
		cout << endl;*/
	}

	ll maxVal = -2;
	for (int i = 0; i <= m; ++i) {
		ll v = tree.get(1, 0, m, i);
		maxVal = max(maxVal, v);
		//cout << v << " ";
	}

	cout << sum - maxVal << endl;
}

