		else {
			Q2[++N2] = LIST(a[i], a[i - 1]);
		}
	}
	sort(Q1 + 1, Q1 + 1 + N1);
	sort(Q2 + 1, Q2 + 1 + N2);
}
void solve_inc(LIST Q[], int N) {
	int HN = 0;
	make_heap(H + 1, H + 1 + HN);
	ll tot = 0;
	FOR(i, 1, N) tot += Q[i].y - Q[i].x;
	int last = 1, cnt = 0;
	FOR(i, 1, m) {
		while (last <= N && Q[last].x == i - 1) {
			tot -= Q[last].y - Q[last].x;
			tot += Q[last].y;
			H[++HN] = HEAP(last); push_heap(H + 1, H + 1 + HN);
			cnt++; last++;
		}
		ans[i] += tot - (ll)cnt * (i - 1);
		while (HN && Q[H[1].idx].y == i) {
			int idx = H[1].idx; pop_heap(H + 1, H + 1 + HN); HN--;
			tot -= Q[idx].y;
			tot += Q[idx].y - Q[idx].x;
			cnt--;
		}
	}
}
void solve_dec(LIST Q[], int N) {
	ll tot = 0, cnt = N;
	FOR(i, 1, N) tot += Q[i].x;
	ans[1] += tot;

	int last = 1;
	FOR(i, 2, m) {
		while (last <= N && Q[last].x == i - 1) {
			tot -= Q[last].x;
			tot += (m - Q[last].y) + Q[last].x;
			cnt--; last++;
		}
		ans[i] += tot + cnt * (1 - i);
	}
}

