  int s=0,kans=0;
  priority_queue<P,vector<P>,greater<P>> pque;
  for(int i=0;i<n-1;i++){
    if(vec[i].first>vec[i].second&&vec[i].second>=2){
      pque.push(P(vec[i].second,vec[i].first));
      kans+=m+1-vec[i].first;
      s++;
    }
  }
  int pos=0;
  int ans=sum-kans;
  for(int i=3;i<=m;i++){
    kans+=s;
    int npos=upper_bound(vec.begin(),vec.end(),P(i-1,0))-vec.begin();
    for(int j=pos;j<npos;j++){
      if(vec[j].second>=i){
        pque.push(P(vec[j].second,vec[j].first));
        int tk=i-vec[j].first-1;
        kans+=tk+(tk<0?m:0);
        s++;
      //  cout<<i<<" in:"<<j<<" point:"<<tk+(tk<0?m:0)<<endl;
      }
    }
    if(!pque.empty()){
      while(pque.top().first<i){
