struct Segment_Tree{
	public:
		int cnt;
		struct T{
			int lazy,ls,rs,left_range,right_range,val,pos;
		}tree[MAXN<<1];
		int seglen(int x){
			return tree[x].right_range-tree[x].left_range+1;
		}
		void update(int x){
			if(tree[tree[x].ls].val<tree[tree[x].rs].val){
				tree[x].val=tree[tree[x].ls].val;
				tree[x].pos=tree[tree[x].ls].pos;
			}
			else{
				tree[x].val=tree[tree[x].rs].val;
				tree[x].pos=tree[tree[x].rs].pos;
			}
		}

		void pushdown(int x){
			if(tree[x].lazy){
				tree[tree[x].ls].val+=seglen(tree[x].ls);
				tree[x].lazy=1;
				tree[tree[x].rs].val+=seglen(tree[x].rs);
				tree[x].lazy=1;
			}
			tree[x].lazy=0;
		}

		int Build(int l,int r){
			int now=++cnt;
			tree[now].left_range=l;
			tree[now].right_range=r;
			if(l==r){
				tree[now].val=0;
				tree[now].pos=l;
				return now;
			}
			int mid=(l+r)>>1;
			tree[now].ls=Build(l,mid);
			tree[now].rs=Build(mid+1,r);
			update(now);
			return now;
		}

		void add(int x,int l,int r,int val){
			pushdown(x);
			if(l<=tree[x].left_range && tree[x].right_range<=r){
				tree[x].val+=seglen(x);
				tree[x].lazy=1;
			}
			int mid=(tree[x].left_range+tree[x].right_range)>>1;
			if(l<=mid)add(tree[x].ls,l,r,val);
			if(r>=mid+1)add(tree[x].rs,l,r,val);
			update(x);
		}
}Seg;

