void solve(){
    i64 n,m;
    cin >> n >> m;
    vector<i64> a(n);
    rep(i,0,n){
        cin >> a[i];
        --a[i];
    }

    vector<queue<i64>> push(m);
    vector<i64> pop(a.size()-1);
    vector<i64> d(a.size()-1);
    rep(i,0,a.size()-1){
        if((a[i+1]-a[i]+m)%m<=1) continue;
        push[(a[i]+2)%m].push(i);
        pop[i]=(a[i+1]+1)%m;
        d[i]=(a[i+1]-a[i]+m)%m-1;
    }

    i64 ans=0,s=0;
    rep(i,0,a.size()-1){
        if(a[i]<a[i+1]) s+=a[i+1]-a[i];
        else s+=m-a[i]+a[i+1];
    }
    ans=s;

    vector<i64> k(m);
    vector<vector<i64>> erase_id(m);
    i64 c=0,cnt_id=0;
    rep(i_,0,2*m){
        i64 i=i_%m;
        while(!push[i].empty()){
            ++cnt_id;
            erase_id[pop[push[i].front()]].push_back(push[i].front());
            push[i].pop();
        }

        for(auto id:erase_id[i]){
            --cnt_id;
            c-=d[id];
        }
        erase_id[i].clear();

        c+=cnt_id;
        k[i]+=c;
        ans=min(ans,s-k[i]);
    }
    cout << ans << endl;
}

