	if (l==r){
		sum1+=a[k].sum1;
		sum2+=a[k].sum2;
		return;
	}
	pushdown(k,l,r);
	int mid=(l+r)>>1;
	if (mid>=x) query(k<<1,l,mid,x);
		else query(k<<1|1,mid+1,r,x);
}
