inline void AddPre(long long pc, long long px, int L, int R)
{
	prec[L] += pc;
	prec[R] -= pc;
	prex[L] += px;
	prex[R] -= px;
}

int main()
{
	scanf("%d%d", &n, &m);
	for (int i = 0;i < n;i++)
	{
