	}
	for (int i = 0;i < n - 1;i++)
	{
		if (a[i] < a[i + 1])
		{
			AddPre(a[i + 1] - a[i], 0, 0, a[i] + 1);
			AddPre(a[i + 1] - a[i], 0, a[i + 1] + 1, m + 1);
			AddPre(a[i + 1] + 1, -1, a[i] + 1, a[i + 1] + 1);
		}
