		{
			AddPre(m - a[i] + a[i + 1], 0, a[i + 1] + 1, a[i] + 1);
			AddPre(a[i + 1] + 1, -1, 0, a[i + 1] + 1);
			AddPre(m + a[i + 1] + 1, -1, a[i] + 1, m + 1);
