			muni[t + 1] += -(1 + t);
			muni[t + 1] += m - s + t;
			muni[s + 1] += -(m - s + t);
			puni[s + 1] += -1;
			puni[m + 1] += 1;
			muni[s + 1] += 1 + m + t;
			muni[m + 1] += -(1 + m + t);
		}
	}
