inline void plu1(int k,int l,int r,int v){
	a[k].lazy1+=v;
	a[k].sum1+=v*(r-l+1);
}
inline void plu2(int k,int l,int r,int v){
	a[k].lazy2+=v;
	a[k].sum2+=v*(r-l+1);	
}
inline void pushdown(int k,int l,int r){
	int mid=(l+r)>>1;
	if (a[k].lazy1){
		int mid=(l+r)>>1;
		plu1(k<<1,l,mid,a[k].lazy1);
		plu1(k<<1|1,mid+1,r,a[k].lazy1);
	}
	if (a[k].lazy2){
		plu2(k<<1,l,mid,a[k].lazy2);
		plu2(k<<1|1,mid+1,r,a[k].lazy2);		
	}
	a[k].lazy1=a[k].lazy2=0;
}
inline void pushup(int k){
	a[k].sum1=a[k<<1].sum1+a[k<<1|1].sum1;
	a[k].sum2=a[k<<1].sum2+a[k<<1|1].sum2;
}
void update(int k,int l,int r,int x,int y,int v){
	if (l==x&&r==y){
		plu1(k,l,r,v);
		plu2(k,l,r,1);
		return;
	}
	pushdown(k,l,r);
	int mid=(l+r)>>1;
	if (mid>=y) update(k<<1,l,mid,x,y,v);
		else if (mid<x) update(k<<1|1,mid+1,r,x,y,v);
			else update(k<<1,l,mid,x,mid,v),update(k<<1|1,mid+1,r,mid+1,y,v);
	pushup(k);
}
