const int N=1e5+5;

struct Tree{
	int left,right;
	long long val,tag;
	Tree *left_child,*right_child;
}t[N*4];

int n,m,T=1;
long long ans,tot;
int a[N];

void build(Tree *pos,int x,int y){
	pos->left=x;pos->right=y;
	pos->val=pos->tag=0ll;
	if(x==y) return;
	int mid=(x+y)>>1;
	pos->left_child=t+T;T++;
	pos->right_child=t+T;T++;
	build(pos->left_child,x,mid);
	build(pos->right_child,mid+1,y);
}

void inc(Tree *pos,long long v){
	if(pos->left==pos->right) pos->val+=v;
	else pos->tag+=v;
}

void down(Tree *pos){
	inc(pos->left_child,pos->tag);
	inc(pos->right_child,pos->tag);
	pos->tag=0;
}

void update(Tree *pos){
	pos->val=pos->left_child->tag+pos->left_child->val+pos->right_child->tag+pos->right_child->val;
}

void add(Tree *pos,int x,int y,long long v){
	if(pos->left>=x&&pos->right<=y){
		inc(pos,v);
		return;
	}
	if(pos->left>y||pos->right<x) return;
	down(pos);
	add(pos->left_child,x,y,v);
	add(pos->right_child,x,y,v);
	update(pos);
}

long long query(Tree *pos,int x,int y){
	if(pos->left>=x&&pos->right<=y) return pos->val+pos->tag;
	if(pos->left>y||pos->right<x) return 0ll;
	down(pos);
	long long ret=query(pos->left_child,x,y)+query(pos->right_child,x,y);
	update(pos);
	return ret;
}

void add(int x,int y,long long val){
	if(x<=y) add(t,x,y,val);
	else{
		add(t,x,m,val);
		add(t,1,y,val);
	}
}

