void seg(int cl, int cr, int k, int nl, int nr){
	if(cr <= nl || nr <= cl){
		return ;
	}
	if(cl <= nl && nr <= cr){
		dlt[k]++;
		return ; 
	}
	seg(cl, cr, k*2, nl, (nl+nr) >> 1);
	seg(cl, cr, k*2 + 1, (nl+nr) >> 1, nr);
}

void nod(int pos, int x, int k, int l, int r){
	if(l == r-1){
		dlt[k] += x;
		return ;
	}
	int m = (l+r) >> 1;
	if(pos < m) nod(pos, x, k*2, l, m);
	else nod(pos, x, k*2+1, m, r);
}

void outget(int k, int l, int r, int pls){
	pls += dlt[k];
	if(l == r-1){
		diff[l] = pls;
		return ;
	}
	outget(k*2, l, (l+r) >> 1, pls);
	outget(k*2 + 1, (l+r) >> 1, r, pls);
}

