int n, m;
int a[100010];
vector<vector<int> > vi(100010);
vector<vector<int> > vi2(100010);
long long res;
int a1[100010];
int a2[100010];

void solve()
{
	int i, j, k;
	long long sum = 0;
	for(i=0; i<n-1; i++){
		a1[i] = a[i];
		a2[i] = a[i+1];
	}
	for(i=0; i<n-1; i++){
		if(a1[i] < a2[i])
			sum += a2[i] - a1[i];
		else
			sum += a2[i] - a1[i] + m;
	}
	for(i=0; i<n-1; i++){
		vi[a1[i]].push_back(i);
		vi2[a1[i]].push_back(0);
		vi[a2[i]].push_back(i);
		vi2[a2[i]].push_back(1);
	}
	int cnt = 0;
	for(i=0; i<n-1; i++){
		if(a2[i] < a1[i]){
			cnt ++;
			sum -= m-a1[i];
		}
	}
	res = sum;
	for(i=1; i<m; i++){
		for(j=0; j<vi[i].size(); j++){
			if(vi2[i][j] == 0){
				cnt ++;
				sum ++;
			}
			else{
				cnt --;
				k = vi[i][j];
				sum += (a2[k]-a1[k]+m) % m;
				sum --;
			}
		}
		sum -= cnt;
		if(res > sum)
			res = sum;
	}
	printf("%lld\n", res);
}

int main()
{
	int i;
	scanf("%d%d", &n, &m);
	for(i=0; i<n; i++)
		scanf("%d", &a[i]);
	solve();
	return 0;
}

