void add_edge(Graph &G, ll from, ll to, ll cap, bool revFlag, ll revCap) {
    G[from].push_back(Edge(to, cap, (ll)G[to].size()));
    if(revFlag)
        G[to].push_back(Edge(from, revCap, (ll)G[from].size() - 1));
}

void solve() {
    ll n, m;
    cin >> n >> m;

    vec<ll> a(n);
    REP(i, n) {
        cin >> a[i];
        a[i]--;
    }

    vec<ll> l(m, 0), r(m, 0), cost(m, 0);
    REP(i, n - 1) {
        l[a[i]]++;
        r[a[i + 1]]++;
        cost[a[i + 1]] += (m + a[i + 1] - a[i]) % m - 1;
    }

    ll sum = 0;
    ll x = 0;
    ll con = 0;
    REP(i, n - 1) {
        sum += min((m + a[i + 1] - a[i]) % m, (m + a[i + 1] - x) % m + 1);
        if(a[i] < a[i + 1] and a[i] < x and x <= a[i + 1]) {
            con++;
        } else if(a[i] > a[i + 1] and (x <= a[i + 1] or a[i] < x)) {
            con++;
        }
    }

    ll ans = sum;
    while(x < m) {
        sum += cost[x];
        con -= r[x];
        sum -= con;
        con += l[x];
        chmin(ans, sum);
        x++;
    }
    cout << ans << en;
}

