const int N = 1e5 + 5;
int a[N], cnt[N], sz = 1, tll[N*4], trr[N*4];
ll t[N*4], tcnt[N*4];

void push( int v, int tl, int tr ){
    t[v<<1] += t[v];
    t[(v<<1)+1] += t[v];
    tcnt[(v<<1)] += tcnt[v];
    int len = ( tr - tl + 1 ) >> 1;
    t[(v<<1)+1] += tcnt[v] * 1ll * len;
    tcnt[(v<<1)+1] += tcnt[v];
    t[v] = 0;
    tcnt[v] = 0;
}

void add( int v, int tl, int tr, int l, int r, int beg ){
    if ( l > r ){
        return;
    }
    if ( ( l == tl ) && ( r == tr ) ){
        t[v] += beg;
        tcnt[v]++;
        return;
    }
    push( v, tl, tr );
    int tm = ( tl + tr ) >> 1;
    if ( r <= tm ){
        add( (v<<1), tl, tm, l, r, beg );
    }
    else
    if ( l >= tm + 1 ){
        add( (v<<1) + 1, tm + 1, tr, l, r, beg );
    }
    else{
        add( (v<<1), tl, tm, l, tm, beg );
        add( (v<<1) + 1, tm + 1, tr, tm + 1, r, beg + tm + 1 - l );
    }
}

ll get( int v, int tl, int tr, int idx ){
    if ( tl == tr ){
        return t[v];
    }
    push(v,tl,tr);
    int tm = ( tl + tr ) >> 1;
    if ( idx <= tm ){
        return get( (v<<1), tl, tm, idx );
    }
    return get( (v<<1) + 1, tm + 1, tr, idx );
}

ll ans = 0;

void build( int v, int tl, int tr ){
    if ( tl == tr ){
        tll[v] = tl;
        trr[v] = tr;
        return;
    }
    tll[v] = tl;
    trr[v] = tr;
    int tm = ( tl + tr ) >> 1;
    build( (v<<1), tl, tm );
    build( (v<<1) + 1, tm + 1, tr );
}

int main(){
    //freopen("input.txt","r",stdin);
    //freopen("output.txt","w",stdout);
    int n, m;
    scanf("%d %d",&n,&m);
    while( sz < m ){
        sz *= 2;
    }
    build( 1, 1, sz );
    for ( int i = 1; i <= n; i++ ){
        scanf("%d",&a[i]);
    }
    for ( int i = 1; i <= n - 1; i++ ){
        if ( a[i+1] >= a[i] ){
            add( 1, 1, sz, a[i] + 1, a[i+1], 0 );
        }
        else{
            add( 1, 1, sz, a[i] + 1, m, 0 );
            add( 1, 1, sz, 1, a[i+1], m - a[i] );
        }
    }
    int mxp = 0;
    ll mxv = 0, curv = 0;
    for ( int i = 1; i <= m; i++ ){
        curv = get(1,1,sz,i);
        if ( !mxp || ( mxv < curv ) ){
            mxp = i;
            mxv = curv;
        }
    }
    int x = mxp;
    for ( int i = 1; i <= n - 1; i++ ){
        if ( a[i+1] >= a[i] ){
            if ( ( x > a[i] ) && ( x <= a[i+1] ) ){
                ans += a[i+1] - x + 1;
            }
            else{
                ans += a[i+1] - a[i];
            }
        }
        else{
            if ( ( x > a[i] ) && ( x <= m ) ){
                ans += m - x + a[i+1] + 1;
            }
            else
            if ( ( x >= 1 ) && ( x <= a[i+1] ) ){
                ans += a[i+1] - x + 1;
            }
            else{
                ans += m - a[i] + a[i+1];
            }
        }
    }
    cout << ans << endl;
    return 0;
}

