    std::cin.tie(nullptr);
    cin>>n>>m;
    REP(i,n){
        cin>>a[i];
        if (i>1) {
            if(a[i]>a[i-1]){
                ans+=a[i]-a[i-1];
            }else{
                ans+=m+a[i]-a[i-1];
            }
        }
    }
    REP(i,n-1){
        if(a[i]<a[i+1]){
            imos[a[i]]++;
            imos[a[i+1]+1]--;
            imos2[a[i]]+=a[i];
            imos2[a[i+1]+1]-=a[i];

        }else{
            imos[a[i]]++;
