            imos2[a[i]]+=a[i];
            imos2[a[i+1]+m+1]-=a[i];
        }
    }
    REP(i,m*2){
        imos[i]+=imos[i-1];
        imos2[i]+=imos2[i-1];
    }
    REP(i,m){
        int hiku=imos[i]*i-imos2[i];
        hiku-=imos[i];
        hiku+=imos[i+m]*(i+m)-imos2[i+m];
        hiku-=imos[i+m];
        chmax(h, hiku);
    }
