int n, m, w[101000], S1[101000], S2[101000];
void Do(int b, int e) {
	if (b == e)return;
	if (b < e) {
		S1[1] += e - b;
		S1[b + 1] += b + 1;
		S2[b + 1]--;
		S2[e + 1]++;
		S1[e + 1] -= b + 1;
	}
	else {
		S1[1] += e - b + m;
		S2[b + 1]--;

		S1[b + 1] += b + 1;

		S2[1]--;
