int main() {
	cin.tie(0);
	ios_base::sync_with_stdio(false);

	cin >> N >> M;

	FOR(i, 0, N) {
		cin >> a[i];
		a[i]--;
	}

	VL data(3 * M);
	ans = 0;
	FOR(i, 0, N - 1) {
		LL A = a[i], B = a[i + 1];
		if (B < A)B += M;
		ans += B - A;
		if (A + 1 < B) {
			data[A + 2] += 1;
			data[B + 1] += -(B + 1 - (A + 2) + 1);
			data[B + 2] += B + 1 - (A + 2);
		}
	}

	FOR(i, 0, SZ(data) - 1) {
		data[i + 1] += data[i];
	}
	LL maxc = -1;

	FOR(i, 0, SZ(data) - 1) {
		data[i + 1] += data[i];
	}
	FOR(i, 0, M) {
		data[i + M] += data[i];
	}

	//FOR(i, 0, SZ(data)) {
	//	cout << setw(3) << setfill('.') << data[i] << " ";
	//}
	//cout << endl;

	FOR(i, M, 2 * M)maxc = max(maxc, data[i]);

	printf("%lld\n", ans - maxc);

	return 0;
}

