int main() {
    int n, m;
    cin >> n >> m;

    const int MAXM = 200005;

    vector<int> a(n);
    static vector<int> dest[MAXM];

    int64 sum = 0;
    for (int i = 0; i < n; i++) {
        cin >> a[i];
        a[i]--;

        if (i == 0) continue;
        if (a[i - 1] > a[i]) dest[a[i] + m].push_back(a[i - 1]);
        else dest[a[i] + m].push_back(a[i - 1] + m);

        sum += (a[i] - a[i - 1] + m) % m;
    }

    vector<int64> prize(2 * m, 0);
    priority_queue<int> Q;

    int64 score = 0;
    for (int i = 2 * m - 1; i >= 0; i--) {
        score -= Q.size();
        while (!Q.empty() and Q.top() > i) Q.pop();

        while (!dest[i].empty()) {
            int d = dest[i].back(); dest[i].pop_back();

            if (i >= d + 2) {
                Q.push(d + 2);
                score += i - d - 1;
            }
        }
        prize[i] += score;
    }

    int64 ans = sum;
    for (int i = 0; i < m; i++) {
        ans = min(ans, sum - prize[i] - prize[i + m]);
    } 
    cout << ans << endl;

    return 0;
}

