typedef long long int lli;

const lli maxn = lli(1e5)+5, inf = lli(1e18)+5;

lli res = inf, a[maxn], st0[4*maxn];
pair<lli, lli> st1[4*maxn];

inline lli left(lli node) { return (node<<1); }
inline lli right(lli node) { return (node<<1)+1; }

void upd0(lli node, lli L, lli R, lli a, lli b, lli v)
{
	if(a > R || b < L) return;
	else if(a <= L && R <= b) st0[node] += v;
	else
	{
		upd0(left(node), L, (L+R)/2, a, b, v), upd0(right(node), (L+R)/2+1, R, a, b, v);
	}
}

void upd1(lli node, lli L, lli R, lli a, lli b, lli v)
{
	if(a > R || b < L) return;
	else if(a <= L && R <= b) st1[node].first += v, st1[node].second++;
	else
	{
		upd1(left(node), L, (L+R)/2, a, b, v), upd1(right(node), (L+R)/2+1, R, a, b, v);
	}
}

void qry(lli node, lli L, lli R, pair<pair<lli, lli>, lli> a)
{
	a.first.first += st1[node].first, a.first.second += st1[node].second;
	a.second += st0[node];
	if(L == R)
	{
		res = min(res, a.first.first-a.first.second*L+a.second);
		//cout << L << " " << a.first.first-a.first.second*L+a.second << "\n";
	}
	else
	{
		qry(left(node), L, (L+R)/2, a), qry(right(node), (L+R)/2+1, R, a);
	}
}

int main(void)
{
	lli n, m;
	scanf("%lld%lld", &n, &m);

	for(lli i = 0;i < n;i++) scanf("%lld", &a[i]);

	for(lli i = 0;i < n-1;i++)
	{
		if(a[i] < a[i+1])
		{
			upd0(1, 1, m, 1, a[i], a[i+1]-a[i]);
			upd0(1, 1, m, a[i+1]+1, m, a[i+1]-a[i]);
			upd1(1, 1, m, a[i]+1, a[i+1], a[i+1]+1);
		}
		else
		{
			upd0(1, 1, m, a[i+1]+1, a[i], a[i+1]+m-a[i]);
			upd1(1, 1, m, a[i]+1, m, a[i+1]+m+1);
			upd1(1, 1, m, 1, a[i+1], a[i+1]+1);
		}
	}

	qry(1, 1, m, {{0, 0}, 0});
	printf("%lld\n", res);
}

