inline int read(){int x=0,f=1; char ch=getchar(); while(ch<'0'||ch>'9'){if(ch=='-') f=-1; ch=getchar();} while(ch>='0'&&ch<='9'){x=x*10+ch-'0';ch=getchar();} return x*f;}
const int maxn=1e5+5;
const ll inf=1e18;
struct node{
	ll sum1,lazy1,sum2,lazy2;
}a[100005*8];
int sum1,sum2,n,m,num[maxn];
inline void plu1(int k,int l,int r,int v){
	a[k].lazy1+=v;
	a[k].sum1+=v*(r-l+1);
}
inline void plu2(int k,int l,int r,int v){
	a[k].lazy2+=v;
	a[k].sum2+=v*(r-l+1);	
}
inline void pushdown(int k,int l,int r){
	int mid=(l+r)>>1;
	if (a[k].lazy1){
		int mid=(l+r)>>1;
		plu1(k<<1,l,mid,a[k].lazy1);
		plu1(k<<1|1,mid+1,r,a[k].lazy1);
	}
	if (a[k].lazy2){
		plu2(k<<1,l,mid,a[k].lazy2);
		plu2(k<<1|1,mid+1,r,a[k].lazy2);		
	}
	a[k].lazy1=a[k].lazy2=0;
}
inline void pushup(int k){
	a[k].sum1=a[k<<1].sum1+a[k<<1|1].sum1;
	a[k].sum2=a[k<<1].sum2+a[k<<1|1].sum2;
}
void update(int k,int l,int r,int x,int y,int v){
	if (l==x&&r==y){
		plu1(k,l,r,v);
		plu2(k,l,r,1);
		return;
	}
	pushdown(k,l,r);
	int mid=(l+r)>>1;
	if (mid>=y) update(k<<1,l,mid,x,y,v);
		else if (mid<x) update(k<<1|1,mid+1,r,x,y,v);
			else update(k<<1,l,mid,x,mid,v),update(k<<1|1,mid+1,r,mid+1,y,v);
	pushup(k);
}
void query(int k,int l,int r,int x){
	if (l==r){
		sum1+=a[k].sum1;
		sum2+=a[k].sum2;
		return;
	}
	pushdown(k,l,r);
	int mid=(l+r)>>1;
	if (mid>=x) query(k<<1,l,mid,x);
		else query(k<<1|1,mid+1,r,x);
}
inline void init(){
	n=read(); m=read();
	for (int i=1;i<=n;i++){
		num[i]=read();
	}
}
inline void solve(){
	ll cnt=0;
	for (int i=2;i<=n;i++){
		if (num[i]>=num[i-1]) update(1,1,2*m,num[i-1]+1,num[i],num[i-1]),update(1,1,2*m,num[i-1]+m+1,num[i]+m,num[i-1]+m),cnt+=num[i]-num[i-1];
			else {
				update(1,1,2*m,num[i-1]+1,num[i]+m,num[i-1]),cnt+=num[i]+m-num[i-1];
				if (num[i]==m){
					update(1,1,2*m,2,num[i-1],2);
				}
			}
	}
	ll ans=inf;
	for (int i=1;i<=2*m;i++){
		sum1=sum2=0;
		query(1,1,2*m,i);
		ans=min(ans,cnt-sum2*i+sum2+sum1);
	}
	printf("%lld\n",ans);
}
int main(){
//	freopen("C.in","r",stdin);
//	freopen("C.out","w",stdout); 
	init();
	solve();
	return 0;
}

