vector< int > pos[nmax + 1];

struct str {
    int x, dist;

    str() {}
    str (int _x, int _dist) {
        x = _x, dist = _dist;
    }

    inline bool operator < (const str &k) const {
        if (dist != k.dist) return (dist < k.dist);
        return (x < k.x);
    }
};
set< str > s;

inline int muta_de_la (int x, int y) {
    if (x <= y) return y - x;
    else        return y - x + m;
}

int main() {
    int n;
    cin >> n >> m;

    for (int i = 0; i < n; ++ i) {
        cin >> v[ i ];
    }

    i64 suma = 0, sb = 0;
    int catem = 0;

    for (int i = 1; i < n; ++ i) {
        dif[ i ] = muta_de_la(v[i - 1], v[ i ]);
        pos[ v[ i ] ].push_back( i );

        suma += min(dif[ i ], muta_de_la(1, v[ i ]) + 1);

        bagat[ i ] = dif[ i ] - (muta_de_la(1, v[ i ]) + 1);
        s.insert(str(i, bagat[ i ]));

        catem += (bagat[ i ] > 0);
    }

    sb = suma;

    for (int i = 1; i <= m; ++ i) { /// constanta e i - 1
        if (suma < sb) {
            sb = suma;
        }

        if (i == m) continue;

        for (auto j : pos[ i ]) { /// isi schimba mutatul
            set< str >::iterator it = s.find(str(j, bagat[ j ]));
            s.erase( it );
            suma -= min(dif[ j ], muta_de_la(i, v[ j ]) + 1);

            if (dif[ j ] > muta_de_la(i, v[ j ]) + 1) {
                -- catem;
            }

            bagat[ j ] = dif[ j ] - (muta_de_la(i + 1, v[ j ]) + 1) - i; /// toate dif au crescut cu i
            s.insert(str(j, bagat[ j ]));

            suma += min(dif[ j ], muta_de_la(i + 1, v[ j ]) + 1);
            catem += (bagat[ j ] > i);
        }

        suma -= catem;
        /// care devin mai bune cu favorit decat dif[ i ]
        /// care acum au diferentele 0
        set< str >::iterator it = s.lower_bound(str(0, -i));
        while (it != s.end() && it -> dist == -i) {
            ++ catem;
            ++ it;
        }

    }
    cout << sb << "\n";

    return 0;
}

