ll g(ll M, ll pv, ll v) {
	if(pv==v) return 0;
	ll a = pv <= v ? v-pv : v+M-pv;
	return a;
}

ll f(ll M, ll m, ll pv, ll v) {
	if(pv==v) return 0;
	ll a = g(M, pv, v);
	ll b = 1 + (m <= v ? v-m : v+M-m);
	ll rv = min(a, b);
//	DD(m);
//	DD(pv);
//	DD(v);
//	DD(rv);
	return rv;
}

ll naive(ll N, ll M, const VI& w) {
	ll ans = 1LL<<60;
	RANGE(m, 1, M+1) {
		ll lans = 0;
		RANGE(i, 1, N) {
			lans += f(M, m, w[i-1], w[i]);
		}
//		DD(m);
//		DD(lans);
		ans = min(ans, lans);
	}
	return ans;
}

ll solve(ll N, ll M, const VI& w) {
	auto MM = [=](ll val) {
		return (val-1+M)%M+1;
	};

	VI tl(2*M); // [i] : i-1 から i になるときの差分
	ll ans1 = 0;
	ll ansv1 = 0;
	RANGE(i, 1, N) {
		ll v = w[i];
		ll pv = w[i-1];

		// pv -> v
		ll lans1 = f(M, 1, pv, v);
		ans1 += lans1;

		if(pv!=v)
		{
			VI _tb(2*M);
			VI& tb = _tb;
//			VI& tb = tl;

			ll diff = g(M, pv, v)-f(M, v, pv, v);
			tb[MM(pv+2)]--;
			tb[MM(v+1)]+=1+diff;
			tb[MM(v+2)]+=-diff;

			ll lansv1 = 0;
			if((pv<=v && pv+1<v) || (pv>v && pv+1<v+M)) {
				if(MM(pv+2) <= v) {
					if(MM(pv+2)==1) lansv1 = -1;
				} else {
					lansv1 = -1;
				}
			}
			if(MM(v+1)==1) lansv1 = diff;

			ansv1 += lansv1;
//			DD(pv);
//			DD(v);
//			DD(lans1);
//			DD(lansv1);
			RANGE(m, 1, M+1) {
//				DD(f(M, m, pv, v));
			}
//			DD(tb);
			ll vv = lans1;
			ll vvv = lansv1;
//			DD(vv);
			RANGE(m, 2, M+1) {
				vvv += tb[m];
				vv += vvv;
//				DD(vv);
			}
			REP(j, tl.size()) tl[j] += tb[j];
		}
	}
//	DD(tl);
//	DD(ans1);
//	DD(ansv1);
	ll ans = ans1;
	ll v = ans1;
	ll vv = ansv1;
	RANGE(m, 2, M+1) {
		vv += tl[m];
		v += vv;
//		DD(v);
		ans = min(ans, v);
	}
	return ans;
}

