void MAIN() {
    scanf("%d%d", &N, &M);
    REP (i, N) scanf("%d", A+i), A[i]--;

    LL ans = 0;
    for (int i=1; i<N; i++) {
	int cur = A[i-1], nxt = A[i];
	if (nxt <= cur) nxt += M;
	ans += nxt - cur;
	S[cur+2]++;
	S[nxt+1] -= nxt - cur;
	S[nxt+2] += nxt - cur - 1;
    }
    REP (i, 2 * M+2) S[i+1] += S[i];
    REP (i, 2 * M+2) S[i+1] += S[i];

    LL ma = 0;
    REP (i, M) amax(ma, S[i] + S[i+M]);
    printf("%lld\n", ans - ma);
}

