      sum += a[i + 1] - a[i];
    } else {
      sum += m - (a[i] - a[i + 1]);
    }
  }
  vector<int> A(m + 1, 0);
  vector<int> B(m + 1, 0);
  for (int i = 0; i < n - 1; i++){
    if (a[i + 1] > a[i]){
      A[a[i] + 1]++;
      A[a[i + 1] + 1]--;
      B[a[i] + 1] -= a[i] + 1;
      B[a[i + 1] + 1] += a[i] + 1;
    } else {
      A[a[i] + 1]++;
      A[m]--;
      B[a[i] + 1] -= a[i] + 1;
      B[m] += a[i] + 1;
      A[0]++;
      A[a[i + 1] + 1]--;
      B[0] += m - a[i] - 1;
      B[a[i + 1] + 1] -= m - a[i] - 1;
    }
  }
