#define N 101010
LL st[ N << 2 ] , a[ N << 2 ] , d[ N << 2 ];
#define L(X) (X<<1)
#define R(X) (1+(X<<1))
#define mid ((l+r)>>1)
LL Ar( LL a0 , LL nn , LL ad ){
  return ( a0 + a0 + ( nn - 1 ) * ad ) * nn / 2;
}
void push( int no , int l , int r ){
  if( a[ no ] == 0 and d[ no ] == 0 ) return;
  st[ L( no ) ] += Ar( a[ no ] , mid - l + 1 , d[ no ] );
  st[ R( no ) ] += Ar( a[ no ] + ( mid - l + 1 ) * d[ no ] , r - mid , d[ no ] );
  a[ L( no ) ] += a[ no ];
  a[ R( no ) ] += a[ no ] + ( mid - l + 1 ) * d[ no ];
  d[ L( no ) ] += d[ no ];
  d[ R( no ) ] += d[ no ];
  a[ no ] = d[ no ] = 0;
}
void modify( int no , int l , int r , int ql , int qr , LL qa , LL qd ){
  if( l == ql and r == qr ){
    st[ no ] += Ar( qa , r - l + 1 , qd );
    a[ no ] += qa;
    d[ no ] += qd;
    return;
  }
  push( no , l , r );
  if( qr <= mid )
    modify( L( no ) , l , mid , ql , qr , qa , qd );
  else if( mid < ql )
    modify( R( no ) , mid + 1 , r , ql , qr , qa , qd );
  else{
    modify( L( no ) , l , mid , ql , mid , qa , qd );
    modify( R( no ) , mid + 1 , r , mid + 1 , qr , qa + ( mid - ql + 1 ) * qd , qd );
  }
  st[ no ] = st[ L( no ) ] + st[ R( no ) ];
}
LL query( int no , int l , int r , int p ){
  if( l == r ) return st[ no ];
  push( no , l , r );
  if( p <= mid ) return query( L( no ) , l , mid , p );
  return query( R( no ) , mid + 1 , r , p );
}
