LL n , m , aa[ N ];
void init(){
  n = getint();
  m = getint();
  for( int i = 1 ; i <= n ; i ++ )
    aa[ i ] = getint();
}
LL ans;
void go( int from , int to ){
  if( from == to ) return;
  LL tans = to - from;
  if( tans < 0 ) tans += m;
  ans += tans;
  from ++;
  if( from == to ) return;
  if( from > m ) from -= m;
  if( from <= to ){
    modify( 1 , 1 , m , from , to , 0 , 1 );
  }else{
    modify( 1 , 1 , m , from , m , 0 , 1 );
    //printf( "%d %lld + %d %d\n" , from , m , 0 , 1 );
    modify( 1 , 1 , m , 1 , to , m - from + 1 , 1 );
    //printf( "%d %d + %lld %d\n" , 1 , to , m - from + 1 , 1 );
  }
}
void solve(){
  for( int i = 2 ; i <= n ; i ++ )
    go( aa[ i - 1 ] , aa[ i ] );
