  for( int i = 1 ; i <= m ; i ++ ){
    bst = max( bst , query( 1 , 1 , m , i ) );
    //cout << i << " " << query( 1 , 1 , m , i ) << endl;
  }
  printf( "%lld\n" , ans - bst );
}
