using namespace std;

using LL = long long int;

struct BinaryIndexedTree {
    vector<LL> tree;
    BinaryIndexedTree(int capacity) : tree(capacity + 1){

    }

    void update(int index, int diff) {
        for(int i = index; i < tree.size(); i += i & -i) {
            tree[i] += diff;
        }
    }

    LL query(int limit) {
        LL total = 0;
        for(int i = limit; i; i -= i & -i) {
            total += tree[i];
        }
        return total;
    }
};

class Solution {
public:
    LL solve(int n, int m, vector<int> &a) {
        BinaryIndexedTree b1(m<<1), b2(m<<1), c1(m<<1), c2(m<<1);
        LL cost = 0;
        for(int i = 0; i + 1 < a.size(); ++ i) {
            b1.update(a[i], a[i]);
            c1.update(a[i], 1);
            if(a[i] < a[i+1]) {
                b2.update(a[i+1], a[i]);
                c2.update(a[i+1], 1);
                cost += a[i+1] - a[i];
            }
            else {
                b2.update(a[i+1] + m, a[i]);
                c2.update(a[i+1] + m, 1);
                cost += a[i+1] + m - a[i];
            }
        }
        LL reduce = 0;
        for(int i = 1; i <= m; ++ i) {
            for(int k = 0; k < 2; ++ k) {
                LL j = i - 1 + k * m;
                LL t1 = b1.query(j);
                LL k1 = c1.query(j);
                LL t2 = b2.query(j);
                LL k2 = c2.query(j);
                LL r = (k1 - k2)*j - (t1 - t2);
                reduce = max(reduce, r);
            }
        }
        return cost - reduce;
    }
};

