		cost += (b-a+m)%m;
		if (a <= b)
			magic(a+1, b, -a-1); // a < x <= b: x - a - 1
		else
		{
			magic(a+1, m, -a-1); // a < x <= m:  x - a - 1
			magic(1, b, m-a-1);  // 1 <= x <= b: m - a + x - 1
		}
	}
	partial_sum(x, x+m+1, x);
	partial_sum(add, add+m+1, add);
	for (int i=1; i<=m; i++)
		x[i] = x[i]*i + add[i];
	printf("%lld\n", cost - *max_element(x+1, x+1+m));
	return 0;
}

