      0, [](ll a, ll b){return a + b;}, 0, [](ll a, ll b, int c){return a + b * c;}, vector<ll>());
  LazySegmentTreeI segtree = LazySegmentTreeI(m+1, [](int a, int b){return a + b;},
      0, [](int a, int b){return a + b;}, 0, [](int a, int b, int c){return a + b * c;}, vector<int>());
  rep(i, n - 1){
    if(a[i] < a[i+1]){
      segtree.update(a[i]+1, a[i+1]+1, 1);
      seg.update(a[i]+1, a[i+1]+1, a[i]);
    }else{
      segtree.update(a[i]+1, m+1, 1);
      segtree.update(0, a[i+1]+1, 1);
      seg.update(a[i]+1, m+1, a[i]);
      seg.update(0, a[i+1]+1, a[i] - m);
    }
