using namespace std;

typedef long long int llint;

const int N = 1e5 + 500;
const int off = 1<<18;
const int INF = 0x3f3f3f3f;

llint propw[3*off];
llint propc[3*off];
llint tour[3*off];
llint broj[3*off];
llint a[3*off];
llint reg,weird;

int n,m;

llint gauss(int x){
    return x * (x+1) / 2;
}

void refresh(int i,int len){
    tour[i] += propc[i] + propw[i];
    if(i < off){
        propc[2 * i + 1] +=  propc[i] / 2;
        propw[2 * i + 1] += (propw[i] - len/2 * broj[i]) / 2;
        broj[2 * i + 1] += broj[i];
        propc[2 * i] += propc[i] / 2;
        propw[2 * i] += propw[i] - (propw[i] - len/2 * broj[i]) / 2;
        broj[2 * i] += broj[i];
    }
    broj[i] = 0;
    propc[i] = 0;
    propw[i] = 0;

}

void update(int i,int a,int b,int lo,int hi){
    //žprintf("%d %d %d %d %d\n",i,a,b,lo,hi);
    refresh(i ,  b - a + 1);
    if(lo <= a && b <= hi){
        if(reg > -1)
            propc[i] += reg * (b - a + 1);
        if(weird > -1)
            propw[i] += gauss(hi -a + weird ) - gauss(hi - b + weird -1);
        broj[i]++;
        return;
    }
    if(a > hi || b < lo) return;
    update(2 * i,a ,(a+b)/2,lo,hi);
    update(2 * i + 1, (a+b) / 2 + 1 , b,lo,hi);
}



llint query(int i,int a,int b,int lo,int hi){
    refresh(i, b - a + 1);
    if(lo <= a && b <= hi) return tour[i];
    if(a > hi || b < lo) return 0;
    return query(2 * i, a , (a+b)/2, lo, hi) +  query(2 *i + 1, (a+b)/2+1,b,lo,hi);
}

