        if (ar[i] > 1) {
          updateRange(1, 1, M, 2, ar[i], 1);
        }
        updateRange(1, 1, M, ar[i]+1, ar[i]+1, -(startVal+ar[i]-1));
      }
    }
  }
  ll savings = 0;
  for (int i = 1 ; i <= N ; i++) {
    ll tmp = queryRange(1, 1, M, 1, i);
