// ---------------------- template ----------------------


void solve() {
	int N, M; cin >> N >> M;
	vector<int> A(N); for (auto &a : A) a = in() - 1;
	vector<int> imos(2*M+1);
	vector<int> imos2(2*M+1);
	int noSwitch = 0;
	for (int i = 1; i < N; ++i) {
		int a = A[i];
		if(A[i-1] > A[i]){
			a += M;
		}
		noSwitch += a - A[i - 1];
	}
	for (int i = 1; i < N; ++i) {
		if (A[i - 1] < A[i]) {
			imos[A[i-1]+2]++;
			imos[A[i]+1]--;
			imos2[A[i]+1]-=(A[i]-A[i-1]-1);
		}
		else{
			imos[A[i - 1] + 2]++;
			imos[A[i]+M+1]--;
			imos2[A[i]+M+1]-=(A[i]+M - A[i-1]-1);
		}
	}
	vector<int> val(imos.size());
	int inc = 0;
	for (int i = 1; i < imos.size(); ++i) {
		inc += imos[i];
		val[i] = val[i - 1] + inc;
		val[i] += imos2[i];
	}
	for (int i = M; i < val.size(); ++i) {
		val[i - M] += val[i];
	}
	cout << noSwitch - *max_element(ALL(val)) << endl;
}

