LL cnt, ans;
void add(LL l, LL r) {
    rng[++cnt] = make_pair(l, INT_MIN);
    rng[++cnt] = make_pair(r, l-r);
    ans += r-l;
}

int main() {

    //freopen("out.txt", "r", stdin);
    cin >> n >> m;
    for(LL i = 1; i <= n; i++) {
        cin >> a[i];
        if(i > 1) {
            if(a[i-1] < a[i]) 
                add(a[i-1], a[i]), add(a[i-1] + m, a[i] + m), ans -= a[i] - a[i-1];
            else 
                add(a[i-1], a[i] + m);
        }
    }

    sort(rng+1, rng+cnt+1);

    LL dans = 0;
    LL tot = 0, res = 0;
    for(LL j = 1, i = 1; i <= 2*m+1; i++) {
        while(j <= cnt && rng[j].fst == i) {
            if(rng[j].snd == INT_MIN) ++ tot; 
            else {
                chkmax(dans, res - tot);
                -- tot;
                res += rng[j].snd;
            }++ j;
        }
        res += tot;
    }
    printf("%lld\n", ans - dans);
    return 0;
}

