const int maxn = 2e5 + 100;

int n, m, l1, l2;
LL a[maxn], ans, cst[maxn];
pii typ1[maxn], typ2[maxn];
vi in[maxn], out[maxn];

int main()
{
	scf(n, m);
	forn(i, 1, n)
	{
		scf(a[i]);
		if(i == 1) continue;
		if(a[i - 1] != a[i])
		{
			if(a[i - 1] < a[i])
			{
				ans += 1ll * (a[i] - a[i - 1]);
				typ1[l1++] = mp(a[i - 1], a[i]);
			}
			else
			{
				ans += 1ll * (a[i] + m - a[i - 1]);
				typ2[l2++] = mp(a[i - 1], a[i] + m);
			}
		}
	}
	rep(i, l1) if(typ1[i].X != typ1[i].Y) in[typ1[i].X].pb(i), out[typ1[i].Y].pb(i);
	LL cur = 0; int cnt = 0;
	forn(i, 1, m)
	{
		cst[i] += cur + 1ll * cnt * (i - 1);
		for(int j: out[i]) cur += 1ll * typ1[j].X, --cnt;
		for(int j: in[i]) cur -= 1ll * typ1[j].X, ++cnt;
	}
	cur = 0; cnt = 0;
	forn(i, 1, m * 2) in[i].clear(), out[i].clear();
	rep(i, l2) if(typ2[i].X != typ2[i].Y) in[typ2[i].X].pb(i), out[typ2[i].Y].pb(i);
	forn(i, 1, 2 * m)
	{
		cst[i > m ? i - m : i] += cur + 1ll * cnt * (i - 1);
		for(int j: out[i]) cur += 1ll * typ2[j].X, --cnt;
		for(int j: in[i]) cur -= 1ll * typ2[j].X, ++cnt;
	}
	LL mx = -linf;
	forn(i, 1, m) chkmax(mx, cst[i]);
	ans -= mx;
	printf("%lld\n", ans);
	return 0;
}

