    vector<ll> a(n);
    cin >> a;
    WeightedGraph<ll> base(n);
    auto distCalc = [&](ll now, ll next) {
        if (now <= next) return next - now;
        else return (m - now) + next;
    };
    for (int i = 0; i + 1 < n; i++) base[i].emplace_back(i + 1, distCalc(a[i], a[i + 1]));
    auto explore = [&](ll x) {
        WeightedGraph<ll> graph(n);
        copy(base.begin(), base.end(), graph.begin());
        for (int i = 0; i + 1 < n; i++) graph[i].emplace_back(i + 1, distCalc(x, a[i + 1]) + 1);
        auto dist = dijkstra(graph, 0);
        return dist[n - 1];
    };
    ll low = 0, high = m;
    while (high - low > 2) {
        ll lowMiddle = (low * 2 + high) / 3;
        ll highMiddle = (low + high * 2) / 3;
        if (explore(lowMiddle) > explore(highMiddle)) low = lowMiddle;
        else high = highMiddle;
    }
    ll ans = INFLL;
    for (ll i = low; i <= high; i++) ans = min(ans, explore(i));
    cout << ans << endl;
}

