        if((a[i-1] + 2) < a[i] + 1){
            m_num[(a[i-1] + 2) % m]++;
            m_num[(a[i] + 1)]--;
        }
        else if((a[i-1] + 2) % m == (a[i] + 1) % m){
            continue;
        }
        else if((a[i-1] + 2) > (a[i] + 1)){
            m_num[a[i-1] + 2]++;
            m_num[(a[i] + 1)]--;
            m_num[0]++;
      //      cout << i << endl;
        }
    }
