    //cout << 0 << " " << m_num[0] << endl;
    for(int i = 1; i < m; i++){
        //cout << i << " " << m_num[i] << endl;
        m_num[i] += m_num[i-1]; //imos
        //cout << m_num[i] << endl;
        //cout << endl;
    }
    //cout << endl;

    int res = 0;  //m = 0のとき
    for(int i = 1; i < n; i++){
        res += min(dif(a[i-1], a[i]), dif(0, a[i]) + 1);
    }

    int res_tmp = res;
    for(int m_tmp = 1; m_tmp < m; m_tmp++){
        res_tmp += b[m_tmp];
        res_tmp -= m_num[m_tmp];
        res = min(res, res_tmp);
    }

    cout << res << endl;

    return 0;
}

