void upd(int n,int b,int e,int i,int j,double k,double s)
{

    if(lazy[n]) {
        if(b!=e) {
            lazy[lc] = 1;
            lazy[rc] = 1;
            T[lc] += T[n];
            T[rc] += T[n];
