            T[n] = 0;
            P[n] = 0;
        }

    }
    if(b>j||e<i)return;
    if(b>=i&&e<=j){
        T[n] += k;
        P[n] += s;
        lazy[n] = 1;
        return;
    }
    int mid = (b+e)/2;
    upd(lc,b,mid,i,j,k,s);
