            lazy[lc] = 1;
            lazy[rc] = 1;
            T[lc] += T[n];
            T[rc] += T[n];
            P[lc] += P[n];
            P[rc] += P[n];

            lazy[n] = 0;
            T[n] = 0;
            P[n] = 0;
        }

    }
    if(b==e) {
        Ans[b] = P[n] + b * T[n];
        return;
    }
    int mid = (b+e)/2;
    Trv(lc,b,mid);
    Trv(rc,mid+1,e);
}
