    {
        if(a[i]<a[i+1])
        {
            base+=(ll)(a[i+1]-a[i]);
            add(a[i]+1,a[i+1]-1,-1,1);
            add(a[i+1],a[i+1],a[i+1]-a[i]-1,1);
        }
        else
        {
            base+=(ll)(m-a[i]+a[i+1]);
            add(0,0,-(m-a[i]),1);
            add(1,a[i+1]-1,-1,1);
            add(a[i+1],a[i+1],m-a[i]+a[i+1]-1,1);
            add(a[i]+1,m-1,-1,1);
        }
    }
    together(1);
