void update(int l, int r, int a, int d){
	// printf("%d %d %d %d\n", l, r, a, d);
	if(l > r)
		return;
	f[l] += a;
	f[r+1] -= a;
	da[l] -= 1ll*l*d;
	da[r+1] += 1ll*l*d;
	db[l] += d;
	db[r+1] -= d;
}

void compute(){
	d[1] = f[1] + 1ll*db[1] + da[1];
	for(int i = 2 ; i <= m ; i++){
		f[i] = f[i-1] + f[i];
		da[i] = da[i-1] + da[i];
		db[i] = db[i-1] + db[i];
		d[i] = f[i] + 1ll*i*db[i] + da[i]; 
	}
}

