typedef long long ll;
const int maxn = 1e5 + 10;
int n, h, x[maxn];
ll arr[3][maxn], r[maxn];

int prefix_rect(int l, int v){
	arr[1][1] += v;
	arr[1][l + 1] -= v;
	arr[0][l + 1] += v * l;
}

int rect(int l, int r, int v){
	prefix_rect(r, v);
	prefix_rect(l - 1, -v);
}

int prefix_tria(int l, int v){
	arr[2][1] += v;
	arr[2][l + 1] -= v;
	arr[0][l + 1] += (l) * (l + 1) * v / 2;
}

int tria(int l, int r, int v){
	prefix_tria(r, v);
	prefix_tria(l - 1, -v);
	rect(l, r, -l + 1);
}

void flatten(){
	int s0 = 0, s1 = 0, s2 = 0;
	for(int i = 1; i < maxn; i++){
		s0 += arr[0][i], s1 += arr[1][i], s2 += arr[2][i];
		r[i] = ll(s0) + ll(i) * s1 + ll(i) * (i + 1) * s2 / 2;
	}

//	for(int i = 1; i <= h; i++){
//		cout << r[i] - r[i - 1] << ' ';
//	}
//	cout << endl;
}

void process(int i){
	int cut = x[i] - x[i - 1];
	if(cut < 0){
		cut += h;
	}
//	}cout << cut << endl;

	if(cut > x[i]){
		rect(1, h - x[i], x[i]);
		tria(1, cut - x[i], 1);
		rect(cut - x[i] + 1, h - x[i], cut - x[i]);
		tria(h - x[i] + 1, h + 1, 1);
	}else{
//		cout << "yup\n";
		rect(1, h - x[i], cut);
		tria(h - x[i] + 1, h - x[i] + cut, 1);
		rect(h - x[i] + cut + 1, h + 1, cut);
	}
}

