int c1[N], c2[N];
ll t1[N], t2[N];

void add(int v, int val){
  for(; v < N; v += v & -v){
    c1[v] += (val > 0 ? 1 : -1);
    t1[v] += val;
  }
}

void add2(int v, int val){
  for(; v < N; v += v & -v){
    c2[v] += (val > 0 ? 1 : -1);
    t2[v] += val;
  }
}

pair < ll, ll > get1(int v){
  pair < ll, ll > ans;
  for(; v > 0; v -= v & -v){
    ans.first += c1[v];
    ans.second += t1[v];
  }
  return ans;
}

pair < ll, ll > get2(int v){
  pair < ll, ll > ans;
  for(; v > 0; v -= v & -v){
    ans.first += c2[v];
    ans.second += t2[v];
  }
  return ans;
}

main(){
