		if (a[i - 1] < a[i]) e.pb(mp(a[i - 1], a[i])) ;
		else e.pb(mp(a[i - 1] - m, a[i])) ;
		now += (a[i] - a[i - 1] + m) % m ;
	}
	rep(i, 0, n - 1) e.pb(mp(e[i].fi + m,  e[i].se + m)) ;
	sort(all(e)) ;
	pq <pii> Q ;
	int id = 0 ;
	rep(x, 0, m - 1) {
		now -= siz(Q) ;
		while (id < 2 * n - 2 && e[id].fi < x) {
			Q.push(mp(-e[id].se, e[id].se - e[id].fi)) ;
			now += e[id].se - x + 1 ;
			now -= e[id].se - e[id].fi ;
			id++ ;
		}
		chmin(ans, now) ;
		while (!Q.empty() && -Q.top().fi == x) {
			now += Q.top().se - 1 ;
			Q.pop() ;
		}
	}
	printf("%lld\n", ans) ;
	return 0 ;
}

