vector<i64> unroll(i64 m,vector<i64> a){
    vector<i64> res={a.front()};

    i64 s=a.front();
    rep(i,1,a.size()){
        if(a[i]>a[i-1]){
            res.push_back(s+a[i]-a[i-1]);
            s+=a[i]-a[i-1];
        }else{
            res.push_back(s+m-a[i-1]+a[i]);
            s+=m-a[i-1]+a[i];
        }
    }
    return res;
}

void solve(){
    i64 n,m;
    cin >> n >> m;
    vector<i64> a(n);
    rep(i,0,n){
        cin >> a[i];
        --a[i];
    }

    auto a_=unroll(m,a);

    vector<queue<i64>> push(m);
    vector<set<i64>> pop(m);
    vector<i64> d(a_.size()-1);
    rep(i,0,a_.size()-1){
        if(a_[i]<a_[i+1]){
            if(a_[i+1]-a_[i]<=1) continue;
            push[(a_[i]+2)%m].push(i);
            pop[(a_[i+1]+1)%m].insert(i);
            d[i]=a_[i+1]-a_[i]-1;
        }else{
            if(a_[i+1]+m-a_[i]<=1) continue;
            push[(a_[i]+2)%m].push(i);
            pop[(a_[i+1]+1)%m].insert(i);
            d[i]=a_[i+1]+m-a_[i]-1;
        }
    }

    i64 ans=0,s=0;
    rep(i,0,a.size()-1){
        if(a[i]<a[i+1]) s+=a[i+1]-a[i];
        else s+=m-a[i]+a[i+1];
    }
    ans=s;

    set<i64> ids;
    vector<i64> k(m);
    i64 c=0;
    rep(i_,0,2*m){
        i64 i=i_%m;
        while(!push[i].empty()){
            ids.insert(push[i].front());
            push[i].pop();
        }

        set<i64> tmp;
        set_intersection(ids.begin(),ids.end(),pop[i].begin(),pop[i].end(),inserter(tmp,tmp.end()));
        for(auto id:tmp){
            ids.erase(id);
            pop[i].erase(id);
            c-=d[id];
        }

        c+=ids.size();
        k[i]+=c;
        ans=min(ans,s-k[i]);
    }
    cout << ans << endl;
}

