void add(int l,int r,ll s[],int val){
	s[l]+=(ll)val;
	s[r+1]-=(ll)val;
}

void add_ans(int a,int b){
	if(a<b){
		add(1,a,coef,b-a);
		add(a+1,b,cons,-1);
		add(a+1,b,coef,1+b);
		add(b+1,m,coef,b-a);
	}
	else{
		add(a+1,m,coef,1+m+b);
		add(a+1,m,cons,-1);
		add(1,b,coef,1+b);
		add(1,b,cons,-1);
		add(b+1,a,coef,m-a+b);
	}
}

