inline void calc(int a, int b, long long &ans, int m) {
    if (a == b) return ;
    if (a > b)
        b += m;
    ans += b - a;
    if (a + 1 == b)
        return ;

    B[a + 1]++;
    c[b + 1] -= b - a - 1;
    B[b]--;
}

int main() {
    int n, m;
    scanf("%d%d", &n, &m);

