        calc(a[i], a[i + 1], ans, m);

    long long add = 0;
    for (int i = 1; i <= 2 * m; i++) {
        c[i] += c[i - 1] + add;
        add += B[i];

        if (i <= m)
            e[i] += c[i];
        else e[i - m] += c[i];
    }

    long long best = 0;
    for (int i = 1; i <= m; i++)
        if (e[i] > best)
            best = e[i];

    printf("%lld\n", ans - best);

    return 0;
}

