inline void inp( int &n ) {
	n=0; int ch = getcx(); int sign = 1;
	while(ch < '0' || ch > '9') { if(ch == '-') sign=-1; ch = getcx(); }
	while(ch >= '0' && ch <= '9') { n = (n << 3) + (n << 1) + ch - '0', ch = getcx(); }
	n = n * sign;
}

int getDist(int x, int y, int m) {
	if (y >= x) return y - x;
	else return m - x + y;
}

LL calc(vector<int> &A, int n, int fav, int m) {
	LL sum = 0;
	for (int i = 0; i < n - 1; i++) {
		sum += min(getDist(A[i], A[i + 1], m), 1 + getDist(fav, A[i + 1], m));
	}
	return sum;
}

