	REP (i, n) cin >> A[i];
	//cout << calc(A, n, 4, m) << endl;
	int l = 1, r = m;
	LL best = l, bestcst = calc(A, n, 1, m);
	while (r - l > 20) {
		int mid1 = (2 * l + r) / 3;
		int mid2 = (l + 2 * r) / 3;
		LL c1 = calc(A, n, mid1, m);
		LL c2 = calc(A, n, mid2, m);
		if (c1 < c2) {
			r = mid2;
		} else {
			l = mid1;
		}
	}
	for (int i = l; i <= r; i++) {
		LL cst = calc(A, n, i, m);
	//	cout << i << " " << cst << endl;
		bestcst = min(cst, bestcst);
	}
	cout << bestcst << endl;
    return 0;
}

