    cin >> ar[i];
  }
}


void preprocess() {
}


void solve() {
  for (int i = 2 ; i <= N ; i++) {
    if (ar[i-1] < ar[i]-1) {
      updateRange(1, 1, M, ar[i-1]+2, ar[i], 1);
      if (ar[i] != M) {
        updateRange(1, 1, M, ar[i]+1, ar[i]+1, ar[i]-ar[i-1]);
      }
    } else {
      if (!(ar[i-1] == M && ar[i] == 1)) {
        if (ar[i-1] + 2 <= M) {
          updateRange(1, 1, M, ar[i-1]+2, M, 1);
        }
        int startVal = M - ar[i-1];
        updateRange(1, 1, M, 1, 1, startVal);
        if (ar[i] > 1) {
          updateRange(1, 1, M, 2, ar[i], 1);
        }
        updateRange(1, 1, M, ar[i]+1, ar[i]+1, -(startVal+ar[i]-1));
      }
    }
  }
  ll savings = 0;
  for (int i = 1 ; i <= N ; i++) {
    ll tmp = queryRange(1, 1, M, 1, i);
    //cerr << "I = " << i << ", Savings = " << tmp << "\n";
    savings = max(savings, tmp);
  }
  ll ans = -savings;
  for (int i = 2 ; i <= N ; i++) {
    if (ar[i-1] < ar[i]) {
      ans += ar[i]-ar[i-1];
    } else {
      ans += M-ar[i-1]+1+ar[i]-1;
    }
  }
  cout << ans;
}


