void update(int beg,int en,int l,int r,int node,long long xs,long long cs)
{
	if (l>=beg && r<=en)
	{
		lazy[node].first+=xs;
		lazy[node].second+=cs;
		return;
	}
	else if (l>en || r<beg) return;
	int mid=(l+r)/2;
	update(beg,en,l,mid,node*2,xs,cs);
	update(beg,en,mid+1,r,node*2+1,xs,cs);
	int leng=min(en,r)-max(beg,l)+1;
	tree[node].first+=(xs*leng);
	tree[node].second+=(cs*leng);
}
pair<long long,long long> sum(int beg,int en,int l,int r,int node)
{
	if (l>=beg && r<=en)
	{
		return make_pair(lazy[node].first*(r-l+1),lazy[node].second*(r-l+1));
	}
	else if (l>en || r<beg) return make_pair(0,0);
	int leng=min(en,r)-max(beg,l)+1;
	pair<long long,long long> res=make_pair(lazy[node].first*leng,lazy[node].second*leng),res1,res2;
	int mid=(l+r)/2;
	res1=sum(beg,en,l,mid,node*2);
	res2=sum(beg,en,mid+1,r,node*2+1);
	res.first+=(res1.first+res2.first);
	res.second+=(res1.second+res2.second);
	return res;
}
long long query(long long i)
{
	pair<long long,long long> res=sum(i,i,1,m,1);
	return res.first*i+res.second;
}
