    if (a[i-1] < a[i]) {
      if (a[i] - a[i-1] >= 2) {
        fall[(a[i]+1)%m] += a[i] - a[i-1] - 1;
      }
    } else {
      if (a[i] - a[i-1] + m >= 2) {
        fall[(a[i]+1)%m] += a[i] - a[i-1] + m - 1;
