int execute(){
    int n, m;
    if(!~scanf("%d %d", &n, &m))
        return 0;
    vector<int> cnt(m + 1), add(m + 1);
    int last;
    scanf("%d", &last); last --;
    int full = 0;
    for(int e = 1; e < n; e++){
        int nxt; scanf("%d", &nxt); nxt--;
        if(last < nxt){
            // (nxt - x + 1)
            add[last + 1] += nxt + 1;
            add[nxt + 1] += - nxt - 1;

            cnt[last + 1]++;
            cnt[nxt + 1]--;

            add[nxt + 1] += nxt - last;
            add[0] += nxt - last;
            add[last + 1] += - nxt + last;

        } else {
            // (nxt - x + m + 1)
            add[last + 1] += nxt + m + 1;
            cnt[last + 1]++;
            add[0] += nxt + 1;
            add[nxt + 1] += - nxt - 1;
            cnt[0]++;
            cnt[nxt + 1]--;

            add[nxt + 1] += nxt - last + m;
            add[last + 1] += - nxt + last - m;
        }
        full += (nxt - last + m)%m;
        last = nxt;
    }
    for(int e = 1; e < m; e++)
        add[e] += add[e-1], cnt[e] += cnt[e-1];
    for(int e = 0; e < m; e++)
        full = min(full, add[e] - cnt[e] * e);
    printf("%d\n", full);
    return 1;
}
