//BIT 1-origin

ll sum(ll *bit, int i) {
	ll s = 0;
	while(i > 0) {
		s += bit[i];
		i -= i & -i;
	}
	return s;
}

void add(ll *bit, int i, ll x) {
	while(i <= n) {
		bit[i] += x;
		i += i & -i;
	}
}

void range_add(ll *bit0, ll *bit1, int a, int b, ll x) { //[a, b]
	add(bit0, a, -x * (a - 1));
	add(bit1, a, x);
	add(bit0, b + 1, x * b);
	add(bit1, b + 1, -x);
}

ll range_sum(ll *bit0, ll *bit1, int a, int b) { //[a, b]
	return (sum(bit1, b) * b + sum(bit0, b)) 
		- (sum(bit1, a - 1) * (a - 1) + sum(bit0, a - 1));
}

ll bit0[200010], bit1[200010];

