	rep(i, 0, N - 1) {
		if(A[i] < A[i + 1]) {
			range_add(bit0, bit1, A[i] + M + 1, A[i + 1] + M, 1);
			range_add(bit0, bit1, A[i + 1], A[i + 1], -(A[i + 1] - A[i]));
		}
		else {
			range_add(bit0, bit1, A[i] + 1, A[i + 1] + M, 1);
			range_add(bit0, bit1, A[i + 1], A[i + 1], -(A[i + 1] + M - A[i]));
		}
	}
	for(int i = 2 * M; i >= 1; i--) {
		S[i] = range_sum(bit0, bit1, i, i);
		if(i != 2 * M) S[i] += S[i + 1];
	}
	//debug(vec(S + 1, S + 2 * M + 1));
	ll res = inf;
	for(int i = 1; i <= M; i++) {
		MIN(res, S[i] + S[i + M]);
	}
