class Imos {
public:
    const unsigned int N;
    vector<long long> dp;
    Imos(unsigned int N) : N(N) {
        dp = vector<long long>(N + 1);
    }

    // [a, b]にkを加える
    void add(int a, int b, int k) {
        dp[a] += k;
        dp[b + 1] -= k;
    }

    // 円環状で[a, b]にk加える
    void add_circle(int a, int b, int k) {
        if (a <= b) {
            add(a, b, k);
        }
        else {
            add(b, N, k);
            add(0, b, k);
        }
    }

    void build() {
        for (int i = 0; i < dp.size() - 1; ++i) {
            dp[i + 1] += dp[i];
        }
    }

    void print() {
        for (int i = 0; i < dp.size(); ++i) {
            if (i != 0) { cout << " "; }
            cout << dp[i];
        }
        cout << endl;
    }

};


void solve(long long m, vector<long long> &a){
    vector<int> dp(m + 2, 0);

    Imos imos1(m), imos2(m);

    FOR(i, 0, a.size() - 1) {
        int x = a[i];
        int y = a[i + 1];

        if (x<=y){
            imos1.add(1, x, y - x);
            imos1.add(x + 1, y, y + 1);
            imos2.add(x + 1, y, -1);
            imos1.add(y + 1, m, y - x);
        }
        else{
            imos1.add(1, y, y + 1);
            imos2.add(1, y, -1);
            imos1.add(y + 1, x, m - x + y);
            imos1.add(x + 1, m, m + y + 1);
            imos2.add(x + 1, m, -1);
        }
    }

    imos1.build();
    imos2.build();

    LL ans = LONG_LONG_MAX;
    FOR(i, 1, m) {
        ans = min(ans, imos1.dp[i] + i * imos2.dp[i]);
    }

    cout << ans - MAX(dp) << endl;
}

