typedef int SegT;
static const SegT defvalue = 0;
class SegTree{
private:
    vector<SegT> val;
    int n;
public:
    SegTree(int size){
        n=1;
        while(n<size)n<<=1;
        val=vector<SegT>(2*n, defvalue);
    }
    void update(int a,int b,SegT x,int k=0,int l=0,int r=-1){
        if(r==-1)r=n;
        if(r<=a||b<=l) return;
        if(a<=l&&r<=b){
            val[k] += x;
        }
        else{
            update(a,b,x,k*2+1,l,(l+r)/2);
            update(a,b,x,k*2+2,(l+r)/2,r);
        }
        return;
    }
    SegT query(int i){
        i+=n-1;
        SegT ret = val[i];
        while(i>0){
            i=(i-1)/2;
            ret += val[i];
        }
        return ret;
    }
};

