void up(int id,int l,int r,int tl,int tr,int start,int add)
{
    //printf("%d %d %d %d %d\n",l,r,tl,tr,id);
    if(l==tl&&r==tr){
        lazy[id].start+=start;
        lazy[id].add+=add;
        //printf("%d %d %d %d\n",l,r,start,add);
        return;
    }
    int mid=(l+r)>>1;
    if(tr<=mid) up(id<<1,l,mid,tl,tr,start,add);
    else if(tl>mid) up(id<<1|1,mid+1,r,tl,tr,start,add);
    else{
        up(id<<1,l,mid,tl,mid,start,add);
        up(id<<1|1,mid+1,r,mid+1,tr,start+add*(mid-tl+1),add);
    }
}
long long get(int id,int l,int r)
{
    if(l==r){
        //printf("%lld ",lazy[id].start);
        return lazy[id].start;
    }
    int mid=(l+r)>>1;
    lazy[id<<1].start+=lazy[id].start;
    lazy[id<<1].add+=lazy[id].add;
    lazy[id<<1|1].start+=lazy[id].start+lazy[id].add*(mid-l+1);
    lazy[id<<1|1].add+=lazy[id].add;
    lazy[id].start=lazy[id].add=0;
    //get(id<<1,l,mid);
    //get(id<<1|1,mid+1,r);
    return min(get(id<<1,l,mid),get(id<<1|1,mid+1,r));
}
