      while(pque.top().first<i){
        P p=pque.top();
        pque.pop();
        s--;
        int d=p.first-p.second;
        kans-=d+(d<0?m:0);
        //cout<<i<<" out:"<<p.second<<" "<<p.first<<" "<<d+(d<0?m:0)<<endl;
        if(pque.empty()) break;
      }
    }
    cout<<sum-kans<<endl;
    ans=min(ans,sum-kans);
    //cout<<i<<" "<<kans<<" "<<s<<endl;
    pos=npos;
  }
  cout<<ans<<endl;
}

