typedef long long ll;
int N, M;
vector<int> arr;
vector<ll> A, B;

void add(int l, int r, ll a, ll b) {
    if(l > r) return;
    A[l] += a;
    B[l] += b;
    A[r + 1] += -a;
    B[r + 1] += -b;
}

int main() {
    scanf("%d %d", &N, &M);
    arr.resize(N);
    for(int i = 0; i < N; i++) {
        scanf("%d", &arr[i]);
        arr[i]--;
    }

    A = vector<ll>(M + 1, 0);
    B = vector<ll>(M + 1, 0);

    for(int i = 0; i < N - 1; i++) {
        if(arr[i] <= arr[i + 1]) {
            add(arr[i] + 1, arr[i + 1], -1, arr[i + 1] + 1);
            add(0, arr[i], 0, arr[i + 1] - arr[i]);
            add(arr[i + 1] + 1, M - 1, 0, arr[i + 1] - arr[i]);
        }
        else {
            add(0, arr[i + 1], -1, arr[i + 1] + 1);
            add(arr[i] + 1, M - 1, -1, N + arr[i + 1] + 1);
            add(arr[i + 1] + 1, arr[i], 0, M - arr[i] + arr[i + 1]);
        }
    }

    ll mn = 1e18;
    ll suma = 0;
    ll sumb = 0;
    for(int i = 0; i < M; i++) {
        suma += A[i];
        sumb += B[i];

        //cout << suma << ' ' << sumb << endl;

        mn = min(mn, suma*i + sumb);
    }

    printf("%lld", mn);
}

