	for (i=1;i<n;i++)
	{
		if (a[i]<a[i+1])
		{
			c[a[i]].push_back(i);
			d[a[i+1]].push_back(i);
		}
		else 
		{
			e[a[i]].push_back(i);
			f[a[i+1]].push_back(i);
			num++;
			s+=m-a[i]-1;
		}
	}
	int now=0;//how many intervals 
	int sum=0;//current contribution
	for (i=2;i<=m;i++)
	{
