	for(int i = 1;i < n;i++)
	{
		int from = a[i - 1];
		int to = a[i];
		if(from > to) to += m;
		//from < to


		int dist = (to - from)% m;

		sum += dist;

		to = a[i] + 1;
		from =  a[i] - (dist - 1) + 1;

		if(from < 0)
		{
		}
		else
		{

			seg.add_inter(from , to,1);
			seg.add_inter(to,to + 1,-(dist - 1));
		}

		from += m;
		to += m;


		seg.add_inter(from , to,1);
		seg.add_inter(to,to + 1,-(dist - 1));

	}

