const int N = 100003;

ll ans = 0;

namespace SegmentTree {
	ll mx[N << 2];
	ll d[N << 2], a0[N << 2];

	void add(int rt, int l, int r, int L, int R, int sx) {
		if (L <= l && r <= R) {a0[rt] += sx + (l - L); ++d[rt]; return;}
		int mid = (l + r) >> 1;
		if (L <= mid) add(rt << 1, l, mid, L, R, sx);
		if (R > mid) add(rt << 1 | 1, mid + 1, r, L, R, sx);
	}

	void pushdown(int rt, int l, int r) {
		if (l == r) {mx[rt] = a0[rt]; return;}
		int mid = (l + r) >> 1;
		a0[rt << 1] += a0[rt]; d[rt << 1] += d[rt];
		a0[rt << 1 | 1] += a0[rt] + d[rt] * (mid - l + 1); d[rt << 1 | 1] += d[rt];
		pushdown(rt << 1, l, mid);
		pushdown(rt << 1 | 1, mid + 1, r);
		mx[rt] = max(mx[rt << 1], mx[rt << 1 | 1]);
	}
}

