		add(y+1,y+1,y-x-1);
		if(x<1+m&&1+m<=y) tot+=y-(m+1)+1;
		else tot+=y-x;
	}
	ans=tot;
//	printf("%I64d\n",ans);
	for(int i=2;i<=m;i++){
		long long now=query(t,i,i);
