template<class T> class SegmentTreePointAddRangeSum {
	size_t nodeNum; //セグメント木のノードの数
	size_t length;  //セグメント木にのせるvectorの要素の数
	T init;         //各ノードの初期値
	vector<T> node; //ノード

public:
	//vectorで初期化
	SegmentTreePointAddRangeSum(const vector<T> & ar, const T init) : length(ar.size()), init(init) {
		for (nodeNum = 1; nodeNum < length; nodeNum *= 2);
		node.resize(2 * nodeNum - 1, init);
		for (int i = 0; i < length; ++i) node[i + nodeNum - 1] = ar[i];
		for (int i = nodeNum - 2; i >= 0; --i) node[i] = node[2 * i + 1]+node[2 * i + 2];
	}

	//lengthだけで初期化
	SegmentTreePointAddRangeSum(const size_t length, const T init) : length(length), init(init) {
		for (nodeNum = 1; nodeNum < length; nodeNum *= 2);
		node.resize(2 * nodeNum - 1, init);
	}

	void update(size_t idx, const T var) {
		idx += (nodeNum - 1);
		node[idx] += var;
		while (idx > 0) {
			idx = (idx - 1) / 2;
			node[idx] = node[2 * idx + 1]+node[2 * idx + 2];
		}
	}

	T getvar(const int a, const int b, int k = 0, int l = 0, int r = nodeNum) {
		if (r <= a || b <= l) return init;
		if (a <= l && r <= b) return node[k];
		T vl = getvar(a, b, 2 * k + 1, l, (l + r) / 2);
		T vr = getvar(a, b, 2 * k + 2, (l + r) / 2, r);
		return vl+vr;
	}

	void print(){
		cout << "{ " << getvar(0,1);
		for(int i = 1; i < length; ++i) cout << ", " << getvar(i,i+1);
		cout << " }" << endl;
	}
};


int main() {
	ll n,m; cin >> n >> m;
	V<ll> a(n);
	for(int i = 0; i < n; ++i) cin >> a[i];

	SegmentTreePointAddRangeSum<ll> Seg1(2*m+2,0),Seg2(2*m+2,0),Seg3(2*m+2,0),Seg4(2*m+2,0);

	for(int i = 0; i < n-1; ++i) Seg1.update(a[i] - (a[i+1]>a[i]?0:m) + m,1);
	for(int i = 0; i < n-1; ++i) Seg2.update(a[i] - (a[i+1]>a[i]?0:m) + m,a[i] - (a[i+1]>a[i]?0:m));

	ll sum = 0;
	for(int i = 1; i < n; ++i) sum += a[i];
	ll ans = sum;
	for(int i = 0; i < n-1; ++i) ans -= (a[i] - (a[i+1]>a[i]?0:m) );

	V<P<ll,int>> ord;
	for(int i = 1; i < n; ++i) ord.push_back({a[i],i});

	sort(ALL(ord));
	for(auto e:ord){
		ll key = e.first;
		int idx = e.second;
		ll x = Seg1.getvar(0,key+m);
		ll y = Seg3.getvar(0,key);
		ll cnt = sum - (Seg2.getvar(key+m,2*m+2)+(key-1)*x + Seg4.getvar(key-m + m,2*m+2)+(key-m -1)*y);

		chmin(ans,cnt);
		ll z = a[idx-1] - (a[idx]>a[idx-1]?0:m);
		Seg1.update(z + m,-1);
		Seg2.update(z + m,-z);
		Seg3.update(z + m, 1);
		Seg4.update(z + m, z);

	}
	cout << ans << endl;
	return 0;
}

