	void mark(ll l,ll r,ll a,ll b){
		pre[l]+=a;
		add[l]+=b;
		add[r+1]-=b;
		pre[r+1]-=a+(r-l+1)*b;
	}
	void Prepare(){
		scanf("%lld%lld",&N,&M);
		up(i,1,N)scanf("%lld",&a[i]);
	}
	void Solve(){
		up(i,1,N-1){
			ll now=a[i],nxt=a[i+1];
			if(now<nxt){
				mark(now+1,nxt,-1,1);
				ans+=(nxt-now);
			}else{
				if(now+1<=M)mark(now+1,M,-1,1);
				mark(1,nxt,M-now-1,1);
				ans+=(nxt+M-now);
			}
		}
//		up(i,1,M)printf("%lld ",pre[i]);puts("");
//		up(i,1,M)printf("%lld ",add[i]);puts("");
		up(i,1,M){
			add[i]+=add[i-1];
			pre[i]+=pre[i-1]+add[i];
		}
//		up(i,1,M)printf("%lld ",pre[i]);puts("");
		up(i,1,M)cmax(mx,pre[i]);
//		printf("%lld %lld\n",ans,mx);
		printf("%lld\n",ans-mx);
	}
}

int main(){
//	freopen("input.in","r",stdin);
	using namespace solution;
	Prepare();
	Solve();
	return 0;
}

