struct BIT {
    ll t[N];
    BIT() {fill(t, t + N, 0);}
    void Update(int x, int val) {for(; x < N; x += (x & -x)) t[x] += val;}
    ll Get(int x) {ll res = 0; for(; x > 0; x -= (x & -x)) res += t[x]; return res;}
} bit1, bit2;
int n, m, a[N];
ll sum, cur, x, res;

int32_t main() {
    ios_base::sync_with_stdio(0);
    cin.tie(0), cout.tie(0);
