    for(int i = 2; i <= n; ++i) {
        x = a[i];
        if(x < a[i - 1]) x += m;
        sum += x - a[i - 1];
        bit2.Update(a[i - 1] + 1, -a[i - 1]);
        bit2.Update(x + 1, a[i - 1]);
        bit1.Update(a[i - 1] + 1, 1);
        bit1.Update(x + 1, -1);
    }
    res = sum;
    for(int i = 1; i <= m; ++i) {
        x = bit1.Get(i);
        cur = sum - (x * i + bit2.Get(i)) + x;
        x = bit1.Get(i + m);
