int main(){
	int n=ni,m=ni;
	memset(dval,0,sizeof(dval));
	memset(ddval,0,sizeof(ddval));
	int last=ni;
	for(int i=2;i<=n;i++){
		int cur=ni;
		if(last<cur){
			dval[1]+=cur-last;
			ddval[last+2]--;
			ddval[cur+1]++;
			dval[cur+1]+=cur-last-1;
		}else if(cur<last){
			dval[1]+=cur;
			ddval[2]--;
			ddval[cur+1]++;
