    int l = 0;
    for(int i = 1; i <= m; ++i){
        while(l < sz(events) && events[l][0] <= i){
            if(events[l][2] < 0) ++scale_cnt;
            else --scale_cnt;
            scale_sum += events[l][1];
            flat += events[l][2];
            ++l;
        }
        ll cur = flat + scale_sum - scale_cnt*(i-1);
        ans = min(ans,cur);
    }
    print(ans);
}
