struct Segtree{
	static const int Len = 1<<17;
	LL k[Len<<1],b[Len<<1];
	inline void pushdown(const int& p,const int& l,const int& r) {
		if (l==r) return;
		if (k[p]==0 && b[p]==0) return;
		int mid=(l+r)/2;
		k[p*2]+=k[p],k[p*2+1]+=k[p];
		b[p*2]+=b[p],b[p*2+1]+=k[p]*(mid+1-l)+b[p];
		k[p]=0,b[p]=0;
	}
	int K,B,L,R;
	void _add(const int& p,const int& l,const int& r) {
		if (L<=l && r<=R) {
			b[p]+=K*(l-L)+B;
			k[p]+=K;
			return;
		}
		pushdown(p,l,r);
		int mid=(l+r)/2;
		if (L<=mid) _add(p*2,l,mid);
		if (R>mid)  _add(p*2+1,mid+1,r);
	}
	inline void add(const int& k,const int& b,const int& l,const int& r) {
		K=k,B=b,L=l,R=r;
		_add(1,0,Len-1);
	}
	LL query(int x) {
		int p=1,l=0,r=Len-1;
		while (l<r) {
			pushdown(p,l,r);
			int mid=(l+r)/2;
			if (x<=mid) r=mid,p=p*2;
			else l=mid+1,p=p*2+1;
		}
		return b[p];
	}
}s;

inline int dist(int u,int v) {
	if (u<v) return v-u;
	else return v+m-u;
}

int main() {
	scanf("%d%d",&n,&m);
	for (int i=1;i<=n;++i) scanf("%d",a+i);
	LL sum=0;
	for (int i=1;i<n;++i) {
		sum+=dist(a[i],a[i+1]);
		if (a[i]<a[i+1]) {
			if (dist(a[i],a[i+1])<=1) continue;
			s.add(1,1,a[i]+2,a[i+1]);
		} else {
			if (dist(a[i],a[i+1])<=1) continue;
			if (a[i]<n-1) s.add(1,1,a[i]+2,n);
			int b=dist(a[i],1)-1;
			s.add(1,b,1,a[i+1]);
		}
	}
	LL mx=0;
	for (int i=1;i<=n;++i) {
		LL t=s.query(i);
		if (t>mx) mx=t; 
	}
	printf("%I64d\n",sum-mx);
	return 0;

}

