    	}
    }
    i64 ts = 0, si = 0;
    for(int i = 0; i < n - 1; i++){
    	if(ar[i] < ar[i + 1]){
    		// never occurs
    		if(ar[i] < 1 and ar[i + 1] <= 1){
    			si++;
    			ts += 1 - ar[i];
    		}
    	}
    	else{
    		if((ar[i] < 1 and 1 <= ar[i + 1] + m)){
    			// never
    			si++;
    			ts += 1 - ar[i];
    		}
    		else if(ar[i] < 1+m and 1+m <= ar[i + 1] + m){
    			si++;
				ts += m + 1 - ar[i];
    		}
    	}
    }

    //cout << tot << " " << ts << " " << si << endl;
    i64 ans = tot;
    if(ans > tot - ts+si)ans = tot - ts+si;
    if(ar[0] == 1)si++;
    for(int i = 2; i <= m; i++){
    	for(auto v: ars[i - 1]){
    		if(v > 0){
    			if(ar[v] > ar[v - 1])ts -= ar[v] - ar[v - 1];
    			else ts -= ar[v] + m - ar[v - 1];
    		}
    	}
    	if(ar[n - 1] == i - 1)si--;
    	ts += si;
    	if(ans > tot - ts+si)ans = tot - ts+si;
    	//cout << tot << " " << ts << " " << si << endl;
    }
    cout << ans << endl;



}

