    for(int i = 1; i <= n; i++) cin >> a[i];
    for(int i = 2; i <= n; i++){
        int cur = a[i];
        int prev = a[i - 1];
        bad += dist(prev, cur);
        if(cur == prev) continue;
        if(cur >= prev){
            //cout << prev + 1 << " " << cur << " " << 0 << endl;
            update(1, 1, m, prev + 1, cur, 0);
        } else {
            if(prev != m) {
                update(1, 1, m, prev + 1, m, 0);
                //cout << prev + 1 << " " << m << " " << 0 << endl;
            }
            int taken = m - (prev + 1);
            //cout << 1 << " " << cur << " " << taken + 1 << endl;
            update(1, 1, m, 1, cur, taken + 1);
        }
        //for(int i = 1; i <= m; i++) cout << query(1, 1, m, i, i) << " " ;
        //cout << endl;
    }
    long long maxx = 0ll;
    for(int i = 1; i <= m; i++){
        //cout << query(1, 1, m, i, i) << endl;
        maxx = max(maxx, query(1, 1, m, i, i));
    }
