template<typename T> class BIT
{
   private:
      vector<T> bit;
      int len;
   public:
      BIT(int n=0) {
         len = n+1;
         bit.resize(len);
      }
      void add(int i, T x) {
         i += 1;
         while (i < len) {
            bit[i] += x;
            i += i & -i;
         }
      }
      int sum(int i) {
         i += 1;
         T s = 0;
         while (i > 0) {
            s += bit[i];
            i -= i & -i;
         }
         return s;
      }
};
template<typename T> class CircleCumulativeSum
{
   private:
      BIT<T> bit;
   public:
      CircleCumulativeSum(int n) {
         bit = BIT<T>(n);
      }
      void add(int a, int b, int x) {
         // add x in [a, b)
         bit.add(a, x);
         bit.add(b, -x);
         if (a > b) bit.add(0, x);
      }
      int val(int i) {
         return bit.sum(i);
      }
};

