			if (a[i - 1] > a[i])
				sum += m - a[i - 1] + a[i];
			else
				sum += a[i] - a[i - 1];
			sum--;
			if (a[i - 1] >= f)
				heap_open.push(make_pair(-a[i - 1], i));
		}
		sum -= cnt;
		ret = min(ret, sum);
		while (!heap_open.empty() && f - 1 == -heap_open.top().first) {
			pair<int, int> el = heap_open.top();
			heap_open.pop();
			cnt++;
			int i = el.second;
			if (a[i] >= f)
				heap_close.push(make_pair(-a[i], i));
		}
		//cout << sum << endl;
	}
	cout << ret << endl;
	return 0;
}

