void PushUp(long long *s, int v) {
    s[v] = s[v << 1] + s[v << 1 | 1];
}

void PushDown(long long *s, long long *c, int m, int len) {
    if (c[m]) {
        c[m << 1] += c[m];
        s[m << 1] += 1ll * (len - (len >> 1)) * c[m];
        c[m << 1 | 1] += c[m];
        s[m << 1 | 1] += 1ll * (len >> 1) * c[m];
        c[m] = 0;
    }
}

#define lson l, m, v << 1
#define rson m + 1, r, v << 1 | 1

void update(long long *s, long long *c, int L, int R, int val, int l, int r, int v) {
    if (L <= l && r <= R) {
        s[v] += 1ll * (r - l + 1) * val;
        c[v] += 1ll * val;
        return;
    }
    int m = (l + r) >> 1;
    PushDown(s, c, v, r - l + 1);
    if (L <= m) update(s, c, L, R, val, lson);
    if (R >  m) update(s, c, L, R, val, rson);
    PushUp(s, v);
}

long long query(long long *s, long long *c, int L, int R, int l, int r, int v) {
    if (L <= l && r <= R) return s[v];
    int m = (l + r) >> 1;
    PushDown(s, c, v, r - l + 1);
    long long ans = 0;
    if (L <= m) ans += query(s, c, L, R, lson);
    if (R >  m) ans += query(s, c, L, R, rson);
    return ans;
}

int n, m;
int a[maxn];

int main(int argc, char const *argv[]) {

    cin >> n >> m;

    memset(sum, 0, sizeof(sum));
    memset(num, 0, sizeof(num));

    for (int i = 1; i <= n; i ++)
        scanf("%d", a + i);

    for (int i = 2; i <= n; i ++) {
        int s = a[i - 1], t = a[i];

        if (s < t) {
            update(sum, col, 1, s, t - s, 1, m, 1);
            update(sum, col, s + 1, t, t + 1, 1, m, 1);
            update(num, cor, s + 1, t, 1, 1, m, 1);
            if (t + 1 <= m)
                update(sum, col, t + 1, m, t - s, 1, m, 1);
        }
        else if (s > t) {
            swap(s, t);
            update(sum, col, s + 1, t, s + m - t, 1, m, 1);
            update(sum, col, 1, s, s + 1, 1, m, 1);
            update(num, cor, 1, s, 1, 1, m, 1);
            if (t + 1 <= m) {
                update(sum, col, t + 1, m, s + m + 1, 1, m, 1);
                update(num, cor, t + 1, m, 1, 1, m, 1);
            }
        }
    }

    long long ans = 1e18;
    for (int i = 1; i <= m; i ++) {
        long long tmp1 = query(sum, col, i, i, 1, m, 1);
        long long tmp2 = query(num, cor, i, i, 1, m, 1);
        long long res = tmp1 - tmp2 * i;
        // cout << tmp1 << " " << tmp2 << endl;
        ans = min(ans, res);
        // cout << i << " " << res << e1ndl;
    }

    cout << ans << endl;

    return 0;
}

