  rep(i,arr[0]) --cnt[i];
  REP(i,arr[n-1]+1,n-1) --cnt[i];

  rep(i,n-1) {
    ll tmp = 0;

    for (auto &v : pos[i]) {
      if (v != 0) {
        int dif = i - arr[v-1];
        if (dif < 0) dif += m;
        tmp += dif - 1;
      }
    }

    dec[i+1] = dec[i] - tmp + cnt[i] - pos[i].size();
  }

  ll ans = 1LL * cycle * m - arr[0] + arr[n-1] - *max_element(ALL(dec));
  cout << ans << endl;
}


