                                csum[L] += 1;
                                csum[R] -= (R - L + 1);
                                csum[R + 1] += (R - L);
                        }
                }

        }
        FORR(i, 0, m + m){
                csum[i] += csum[i - 1];
        }
        FORR(i, 0, m + m){
                csum[i] += csum[i - 1];
        }
        ll mx = - 1e18;
        FORR(i, 0, m) mx = max(mx, csum[i] + csum[i + m]);
        cout << tmp - mx << endl;

        return 0;

}

