            if(B+1<m)seg.update(B+1,B+2,-(B-A-1));
            sum+=B-A;
        }
        if(A>B){
            if(A+2<m)seg.update(A+2,m,1);
            seg.update(0,B+1,1);
            seg.update(B+1,B+2,-(B+m-A-1));
            sum+=B+m-A;
            now+=m-A-1;
        }
    }
