    lst.resize( unique( lst.begin(), lst.end() ) - lst.begin() );

    long long ans = numeric_limits<long long> :: max() / 2;
    for( int st = 1, dr = (int) lst.size(); ; ){
        if( dr - st <= 5000 ) {
            for( int i = st; i <= dr; i ++ )
                ans = min( ans, solve( n, m, lst[i - 1] ) );
            break;
        }

        int mid1 = st + (dr - st) / 3, mid2 = dr - (dr - st) / 3;

        long long C1 = solve( n, m, lst[mid1 - 1] ),
                  C2 = solve( n, m, lst[mid2 - 1] );

        ans = min( ans, min( C1, C2 ) );

        if( C1 < C2 ) dr = mid2;
        else          st = mid1;
    }
