const int N=1e5+10;
const int Inf=1e9;
typedef long long LL;

int n,m,a[N];

LL f[N<<2],g[N<<2];

void Add(int x,int l,int r,int ql,int qr,LL y)
{
	if(ql>qr) return;
	if(ql==l&&qr==r)
	{
		f[x]+=y;
		return;
	}
	int mid=l+r>>1;
	if(qr<=mid) Add(x<<1,l,mid,ql,qr,y);
	else if(ql>mid) Add(x<<1|1,mid+1,r,ql,qr,y);
	else 
	{
		Add(x<<1,l,mid,ql,mid,y);
		Add(x<<1|1,mid+1,r,mid+1,qr,y-(mid-ql+1));
	}
}

void Add1(int x,int l,int r,int ql,int qr,LL y)
{
	if(ql>qr) return;
	if(ql==l&&qr==r)
	{
		g[x]+=y;
		return;
	}
	int mid=l+r>>1;
	if(qr<=mid) Add(x<<1,l,mid,ql,qr,y);
	else if(ql>mid) Add(x<<1|1,mid+1,r,ql,qr,y);
	else 
	{
		Add(x<<1,l,mid,ql,mid,y);
		Add(x<<1|1,mid+1,r,mid+1,qr,y);
	}
}

LL Ask(int x,int l,int r,int y)
{
	LL S=f[x]+(y-l);
	if(l==r) return S;
	int mid=l+r>>1;
	if(y<=mid) S+=Ask(x<<1,l,mid,y);
	else S+=Ask(x<<1|1,mid+1,r,y);
	return S+g[x];
}


int main()
{
	scanf("%d%d",&n,&m);
	for(int i=1;i<=n;i++) scanf("%d",&a[i]);
	for(int i=1;i<n;i++)
	{
		if(a[i+1]==a[i]) continue;
		if(a[i+1]>a[i])
		{
			int x=a[i+1]-a[i];
			Add(1,1,m,a[i]+1,a[i+1],x);
			Add1(1,1,m,1,a[i],x);
			Add1(1,1,m,a[i+1]+1,m,x);
		}
		else
		{
			Add(1,1,m,a[i]+1,m,m-a[i]+a[i+1]);
			Add1(1,1,m,a[i+1]+1,a[i],m-a[i]+a[i+1]);
			if(a[i+1]>0)
			{
				int l=1,r=a[i+1];
				int	Ans=a[i+1];
				int S=m-a[i]+a[i+1];
				while(l<=r)
				{
					int mid=l+r>>1;
					int now=1+a[i+1]-mid;
					if(now<=S)
					{
						Ans=mid;
						r=mid-1;
					}
					else l=mid+1;
				}
				Add(1,1,m,Ans,a[i+1],1+a[i+1]-Ans);
				if(Ans>1) Add1(1,1,m,1,Ans-1,S);
			}
		}
	}
	LL Ans=Inf;
	for(int i=1;i<=m;i++) Ans=min(Ans,Ask(1,1,m,i));
	cout<<Ans<<endl;
	return 0;
}

