	cin >> n >> m;
	vector<int> a(n);
	for(int i = 0; i < n; ++i){
		cin >> a[i];
		--a[i];
	}
	const int k = n - 1;
	vector<pii> b(k);
	for(int i = 0; i < k; ++i){
		b[i] = pii(a[i], a[i + 1]);
	}
	sort(b.begin(), b.end());
	priority_queue<pii, vector<pii>, greater<pii>> pq;
	ll current = 0;
	for(int i = 0; i < k; ++i){
		if(b[i].second < b[i].first){
			pq.push(pii(b[i].second, i));
			current += b[i].second + 1;
		}else{
			current += b[i].second - b[i].first;
		}
	}
	ll best = current;
	for(int i = 1, j = 0; i < m; ++i){
		while(!pq.empty() && pq.top().first < i){
			const int t = pq.top().second;
			pq.pop();
			current -= 1;
			current += (b[t].second - b[t].first + m) % m;
		}
		current -= pq.size();
		best = min(best, current);
		while(j < n && b[j].first < i){
			const int t = b[j].second < b[j].first
				? b[j].second + m
				: b[j].second;
			pq.push(pii(t, j));
			++j;
		}
	}
	cout << best << endl;
	return 0;
}

