			sum+=m-i.fi+i.se;
			clos[i.se].pb(m-i.fi+i.se-1);
		} else {
			sum+=i.se-i.fi;
			clos[i.se].pb(i.se-i.fi-1);
		}
		open[i.fi]++;
		trace(sum,i.fi,i.se,m,val,inter,clos[i.se].back());
	}
	ll ans=val;
	fr(x,1,m-1) {
		for(int j:clos[x])
			val-=j;
		inter-=clos[x].size();
		val+=inter;
		inter+=open[x];
		trace(inter,val);
		ans=max(ans,val);
	}
	cout<<sum-ans<<endl;
}
