#define MOD 1000000007
#define INF 1000000000
#define MAX_N 100005

ll n, m;
ll A[MAX_N];

ll process(ll fav_pos) {
    ll ret = 0;
    for(int i = 1; i < n; ++i) {
        ll cur = A[i - 1];
        ll nofav = 0;
        ll yesfav = 1;
        if(cur == A[i]) { continue; }
        // お気にを使わない場合
        if(cur < A[i]) { nofav = A[i] - cur; }
        else { nofav = m - cur + A[i]; }
        // お気にを使う場合
        cur = fav_pos;
        if(cur == A[i]) {}
        else if(cur < A[i]) { yesfav += A[i] - cur; }
        else { yesfav += m - cur + A[i]; }
        // 使う場合と使わない場合の小さいほうを加算
        ret += min(yesfav, nofav);
    }
    return ret;
}

int main()
{
    cin >> n >> m;
    REP(i, n) {
        cin >> A[i];
    }

    ll middle = m / 2 + 1;
    ll left = 1;
    ll right = m;
    ll ans;
    while(1) {
        //printf("pos l: %lld mid: %lld r: %lld\n", left, middle, right);
        // それぞれに何手かかるか計算
        ll middle_ret = process(middle);
        ll left_ret = process(left);
        ll right_ret = process(right);
        //printf("  ret l: %lld mid: %lld r: %lld\n", left_ret, middle_ret, right_ret);
        ll next_left, next_right, next_middle;
        if(middle_ret < left_ret && middle_ret < right_ret) {
            next_left = (middle - left) / 2 + left;
            next_right = (right - middle) / 2 + middle;
            next_middle = middle;
            if(next_left == left && next_right == right) {
                ans = min(middle_ret, min(right_ret, left_ret));
                break;
            }
        }
        else if(right_ret < left_ret && right_ret < middle_ret) {
            next_left = middle + 1;
            next_middle = (right - middle) / 2 + middle;
            next_right = right;
            if(next_left >= right && next_middle == middle) {
                ans = min(middle_ret, min(right_ret, left_ret));
                break;
            }
        }
        else if(left_ret < right_ret && left_ret < middle_ret) {
            next_right = middle - 1;
            next_middle = left / 2;
            next_left = left;
            if(next_right <= left && next_middle == middle) {
                ans = min(middle_ret, min(right_ret, left_ret));
                break;
            }
        }
        else {
            ans = min(middle_ret, min(right_ret, left_ret));
            break;
        }
        left = next_left;
        middle = next_middle;
        right = next_right;
    }
    printf("%lld\n", ans);
    return 0;
}

