  /// 1 + a[i + 1] - fav - a[i + 1] + a[i]
  /// 1 - fav + a[i]
  /// a[i] > a[i + 1] && fav <= a[i + 1]
  /// 1 + a[i + 1] - fav - a[i + 1] + a[i] - m
  /// 1 - fav + a[i] - m
  for(int i = 1; i < n; ++i){
    if(a[i] < a[i + 1]){
      dist[i] = a[i + 1] - a[i];
      add(a[i] + 1, a[i]);
      add(a[i + 1] + 1, -a[i]);
    } else{
      dist[i] = a[i + 1] - a[i] + m;
      add2(1, a[i]);
      add2(a[i + 1] + 1, -a[i]);
    }
    sum += dist[i];
  }
  for(int i = 1; i <= m; ++i){
    pair < ll, ll > e = get1(i);
    ans[i] = e.first - e.first * i + e.second;
    e = get2(i);
    ans[i] += e.first - e.first * i + e.second - m * 1ll * e.first;
  }
  ll wow = sum;
  wow = min(wow, *min_element(ans + 1, ans + 1 + m) + sum);
  printf("%lld", wow);
  return 0;
}

