        int nto = to % m + 1;
        addDelta(nto, from, dist);
        addDelta(nfrom, to, 1);
        if (nfrom <= to) {
            addDelta(nfrom, to, +to);
            f[nfrom] -= 1;
            f[to + 1] += 1;
        }
        else {
            addDelta(nfrom, m, to + m);
            f[nfrom] -= 1;
