template <typename T> struct LinearImos1D{
  vector<T> vec_a, vec_a_end, vec_b, vec;
  int n;

  LinearImos1D(int n): vec_a(n+1), vec_a_end(n+1), vec_b(n+1), vec(n+1), n(n){}

  void add(int s, int t, const T &a, const T &b){ // x∈[s,t)にax+bを加算する。
    vec_a[s+1] += a;
    vec_a[t] -= a;

    vec_a_end[t] -= a*(t-s-1);

    vec_b[s] += a*s+b;
    vec_b[t] -= a*s+b;
  }

  void calc(){
    REP(i,n) vec_a[i+1] += vec_a[i];
    REPE(i,n) vec_a[i] += vec_a_end[i];
    REP(i,n) vec_a[i+1] += vec_a[i];

    REP(i,n) vec_b[i+1] += vec_b[i];

    REPE(i,n) vec[i] = vec_a[i] + vec_b[i];
  }

  inline const T operator[](size_t i) const {return vec[i];}
};

int main(){
  cin.tie(0);
  ios::sync_with_stdio(false);

  int n,m;
  while(cin >> n >> m){
    vector<LLI> a(n); cin >> a;
    for(auto &x : a) --x;

    LinearImos1D<LLI> imos(2*m);

    REP(i,n-1){
      if(a[i] < a[i+1]){
        imos.add(a[i]+1,a[i+1]+1,1,-(a[i]+1));
      }else{
        imos.add(a[i]+1,a[i+1]+1+m,1,-(a[i]+1));
      }
    }

    imos.calc();

    LLI b = 0;
    REP(i,n-1){
      if(a[i] < a[i+1]) b += a[i+1]-a[i];
      else b += a[i+1]+1+(m-a[i]-1);
    }

    LLI ans = LLONG_MAX;
    REP(i,m){
      chmin(ans, b-imos[i]-imos[i+m]);
    }

    cout << ans << endl;
  }

  return 0;
}

