ll g(ll M, ll pv, ll v) {
	if(pv==v) return 0;
	ll a = pv <= v ? v-pv : v+M-pv;
	return a;
}

ll f(ll M, ll m, ll pv, ll v) {
	if(pv==v) return 0;
	ll a = g(M, pv, v);
	ll b = 1 + (m <= v ? v-m : v+M-m);
	ll rv = min(a, b);
//	DD(m);
//	DD(pv);
//	DD(v);
//	DD(rv);
	return rv;
}

