ll solve2(ll N, ll M, const VI& w) {
	// Am+B
	VI A(M*2), B(M*2);
	auto plus = [&](int l, int r, int a, int b) {
		A[l] += a;
		A[r+1] -= a;
		B[l] += b;
		B[r+1] -= b;
	};
	RANGE(i, 1, N) {
		ll pv = w[i-1];
		ll cv = w[i];
		if(pv < cv) {
			// x in [1, pv] -> +cv-pv
			plus(1, pv, 0, cv-pv);
			// x in [pv+1, cv] -> +1+cv-x
			plus(pv+1, cv, -1, 1+cv);
			// x in [cv+1, M] -> +cv-pv
			plus(cv+1, M, 0, cv-pv);
		} else if(cv < pv) {
			// x in [1, cv] -> +1+cv-x
			plus(1, cv, -1, 1+cv);
			// x in [cv+1, pv] -> +cv+M-pv
			plus(cv+1, pv, 0, cv+M-pv);
			// x in [pv+1, M] -> +1+cv+M-x
			plus(pv+1, M, -1, 1+cv+M);
		}
	}
//	DD(A);
//	DD(B);
	VI vs(M+1);
	ll ans = 1LL<<60;
	ll a=0, b=0;
	RANGE(i, 1, M+1) {
		a += A[i];
		b += B[i];
		ll v = a * i + b;
		vs[i] = v;
		ans = min(ans, v);
	}
//	DD(vs);
	return ans;
}


