int main(){
  cin >> N >> M;
  int pr; cin >> pr; --pr;

  ll all = 0LL;
  for(int i=1;i<N;i++) {
    int a;
    cin >> a;
    --a;
    if( a == pr ) continue;
    A[a].emplace_back(pr);
    B[pr].emplace_back(a);
    if (pr < a) all += a - pr;
    else all += a + M - pr;
    pr = a;
  }

  ll sum = 0LL;
  ll cnt = 0LL;
  for( auto x : A ){
    int xs = x.first;
    pr = xs;
    for( auto y : A ){
      int r = y.first;
      for( auto l : y.second ){
        if( l == r ) continue;
        if( l < r && l < xs && xs <= r) {
          sum += xs-l;
          cnt++;
        }
        if( l > r ){
          if(l < xs) {
            sum += xs - l;
            cnt++;
          }
          if(xs <= r) {
            sum += M - l + xs;
            cnt++;
          }
        }
      }
    }
    break;
  }

  ll res = all - sum + cnt;
 // cout << sum << " " << cnt << " "<< res << endl;

  for( auto it = --A.end(); it != A.begin(); it-- ){
    int xs = it->first;

    ll dis = xs<pr?pr-xs:pr+M-xs;
    sum -= dis*cnt;
    cnt -= B[xs].size();


    for( auto l : it->second ){
      sum += (l<xs)?xs-l:xs+M-l;
      cnt++;
    }
    res = min( res, all-sum+cnt);
   // cout << sum << " " << cnt << " "<< res << endl;
    pr = xs;
  }

  cout << res << endl;
}

