		} else if (ary[i] > ary[i + 1]) {
			if (ary[i] != m) Tree.add(1, ary[i] + 1, m, 0, m - ary[i] - 1);
			Tree.add(1, 1, ary[i + 1], m - ary[i], m - ary[i] + ary[i + 1] - 1);
		}
	}
