      favor++;
      dist[i] = dist[i-1] + loss - gain + startcount;
      loss = end[i] - endcount[i];
      gain = gain - endcount[i] + start[i];
      startcount = start[i];
      out = (dist[i] < out) ? dist[i] : out;
      //cout << dist[i-1] << "\n";
  }
  cout << out << "\n";
  return 0;
}

