template<class T>
struct FenwichTree{
	struct range{
		int l,r;
	};
	vector<T> data;

	FenwichTree (int n){
		data.assign(n+5,0);
	}
	//point-query
	T get(int t){
		T ret(0);
		for(int x=t+1;x<data.size();x+=x&-x)ret+=data[x];
		return ret;
	}
	T range_add(int a,int d){
		for(int x=a+1;x>0;x-=x&-x){
			data[x]+=d;
		}
	}
	//range-query
	void range_add(const range &p, int d){
		if(p.l>=p.r)return;
		range_add(p.r-1,d);
		range_add(p.l-1,-d);
	}
};

void solve(int n, int m, vector<int> a){
	FenwichTree<Int> fval(m*2), fct(m*2);
	Int sum = 0;
	REP(i,n)a[i]--;
	REP(i,n-1){
		int s = a[i],t = a[i+1];
		if(a[i]>a[i+1]){
			t += m;
		}
		sum+=t-s;
		fval.range_add({s+1,t+1},s+1);
		fct.range_add({s+1,t+1},1);
	}
	Int mini = 1e+18;
	for(int x=0;x<m;x++){
		auto p00 = fval.get(x), p01 = fct.get(x);
		auto p10 = fval.get(x+m), p11 = fct.get(x+m);
		Int result = p00-p01*x+p10-p11*(x+m);
		mini = min(result,mini);
	}
	cout<<sum+mini<<endl;
}

