        }
        sum[a[i+1]+1] += dif-1;  // a[i+1]+1にしたときの増加分
        sum[1] += min(dif, a[i+1]);  // 1のとき
    }
    for(int i=0;i<m*2;i++){
        imos[i+1] += imos[i];
    }
    for(int i=2;i<=m;i++){
        sum[i] += sum[i-1] - (imos[i]+imos[i+m]);
    }

    ll ans = LLINF;
    for(int i=1;i<=m;i++){
        ans = min(ans, sum[i]);
    }
    cout << ans << endl;
    return 0;
}

