    rep(i, 1, N) t += (A[i] - A[i - 1] + M) % M;

    RangeAddRangeSumQuery rars;
    rars.build(M);
    rep(i, 1, N) {
        if (A[i - 1] == A[i]) continue;
        else if (A[i - 1] < A[i]) {
            rars.range_add(A[i - 1] + 2, A[i] + 1, 1LL);
            rars.range_add(A[i] + 1, A[i] + 2, (ll)-(A[i] - A[i - 1] - 1));
        }
