namespace lib
{
	template<class T>class binary_indexed_tree
	{
		std::vector<T> ar;
		std::size_t size;
	public:
		binary_indexed_tree(std::size_t size_):ar(size_), size(size_)
		{

		}
		void add(T val, int index)
		{
			++index;
			while (index <= size)
			{
				ar[index - 1] += val;
				index += index & -index;
			}
		}
		auto get(int index)
		{
			++index;
			T ret{};
			while (index != 0)
			{
				ret += ar[index - 1];
				index -= index & -index;
			}
			return ret;
		}
	};
}

void Main()
{
	int N;
	std::int64_t M;
	std::cin >> N >> M;
	lib::binary_indexed_tree<int> counts(M + 1);
	std::vector<std::int64_t> sizes(M);
	std::vector<std::int64_t> vec(N);
	std::cin >> vec[0];
	--vec[0];
	std::int64_t now = 0;
	for (int i : boost::irange(0, N - 1))
	{
		std::cin >> vec[i + 1];
		--vec[i + 1];
		auto prev = vec[i];
		auto v = vec[i + 1];
		auto len = (v + M - prev) % M;
		auto s = (v + 1) % M;
		auto s2 = (s + M - (len - 1)) % M;
		sizes[s] = len;
		if (s2 < s)
		{
			counts.add(1, s2);
			counts.add(-1, s + 1);
		}
		else
		{
			counts.add(1, 0);
			counts.add(-1, s + 1);
			counts.add(1, s2);
		}
		now += std::min(len, v + 1);
	}
	auto min = now;
	for (int i : boost::irange<std::int64_t>(1, M))
	{
		now -= counts.get(i);
		now += sizes[i];
		min = std::min(min, now);
	}
	out::write_line(min);
}

