            c[a[i-1]+1]++;
            c[a[i]+1]--;
        }
    }
    for(int i=1; i<=m; ++i) {
        c[i]+=c[i-1];
        b[i]+=b[i-1];
    }
    int ma=0;
    for(int x=1; x<=m; ++x) {
        if(c[x]) {
            ma=max(ma,x*c[x]-b[x]);
        }
    }
    printf("%d\n",sum-ma);
    return 0;
}

