				debug(1, a[i], without);

				//a[i]+1, a[i+1]
				//1 + (a[i+1] - x) = 1 + a[i+1] - x

				data[a[i]+1] += 1 + a[i+1];
				data[a[i+1]+1] -= 1 + a[i+1];

				countdata[a[i]+1] += 1;
				countdata[a[i+1]+1] -= 1;		

				debug(a[i]+1, a[i+1], 1 + a[i+1], "- x");

				//a[i+1] + 1, m is useless

				data[a[i+1] + 1] += without;
				data[m+1] -= without;

				debug(a[i+1] + 1, m, without);

			}
			else
			{
				int without = m - a[i] + a[i+1];

				//1, a[i+1]
				//a[i+1] - x + 1 = a[i+1] + 1 - x

				data[1] += a[i+1] + 1;
				data[a[i+1]+1] -= a[i+1] + 1;

				countdata[1] += 1;
				countdata[a[i+1]+1] -= 1;

				debug(1, a[i+1], a[i+1] + 1, "- x");

				//a[i+1]+1, a[i] is useless

				data[a[i+1] + 1] += without;
				data[a[i]+1] -= without;

				debug(a[i+1]+1, a[i], without);

				//a[i]+1, m
				//(m - x) + a[i+1] + 1 = a[i+1] + m - x + 1

				data[a[i]+1] += a[i+1] + m + 1;
				data[m+1] -= a[i+1] + m + 1;

				countdata[a[i]+1] += 1;
				countdata[m+1] -= 1;

				debug(a[i]+1, m, a[i+1] + m + 1,  "- x");

			}
		}
	}

	slong ans = LONG_INFINITY;

	for (i = 1; i <= m; i++)
	{
		countdata[i] += countdata[i-1];
		data[i] += data[i-1];

		slong val = data[i] - countdata[i]*i;

		debug(i, val);

		ans = min(ans, val);
	}

	cout << ans;

	clock_t end = clock();
	double elapsed_secs = double(end - begin) / CLOCKS_PER_SEC;

	cerr << elapsed_secs;

	return 0;
}

