ll mod_pow(ll a, ll n, ll mod) {
	ll ret = 1;
	ll p = a % mod;
	while (n) {
		if (n & 1) ret = ret * p % mod;
		p = p * p % mod;
		n >>= 1;
	}
	return ret;
}
template<class T> T extgcd(T a, T b, T& x, T& y) { for (T u = y = 1, v = x = 0; a;) { T q = b / a; swap(x -= q * u, u); swap(y -= q * v, v); swap(b -= q * a, a); } return b; }
template<class T> T mod_inv(T a, T m) { T x, y; extgcd(a, m, x, y); return (m + x % m) % m; }
template<class T> T CRT(T m1, T r1, T m2, T r2) { T a1, a2; extgcd(m1, m2, a1, a2); T ret = (m1*a1*r2 + m2*a2*r1) % (m1*m2); return ret < 0 ? ret + m1 * m2 : ret; }

ll memo[ten(5) + 10];
ll mns[ten(5) + 10];

int main() {
	int n, m; reader(n, m);
	vector<int> a(n);
	FOR(i, n) {
		reader(a[i]);
		a[i]--;
	}
	FOR(i, n - 1) {
		int fm = a[i], to = a[i + 1];
		int dist = to - fm;
		if (dist < 0) dist += m;
		memo[0] += dist;
		memo[m] -= dist;
		if (fm < to) {
			int additional = to + 1;
			memo[fm + 1] -= dist;
			memo[to + 1] += dist;
			memo[fm + 1] += additional;
			memo[to + 1] -= additional;
			mns[fm + 1]++;
			mns[to + 1]--;
		} else {
			int add1 = fm + dist + 1;
			memo[fm + 1] -= dist;
			memo[m] += dist;
			memo[fm + 1] += add1;
			memo[m] -= add1;
			mns[fm + 1]++;
			mns[m]--;

			int add2 = to + 1;
			memo[0] -= dist;
			memo[to + 1] += dist;
			memo[0] += add2;
			memo[to + 1] -= add2;
			mns[0]++;
			mns[to + 1]--;
		}
	}

	static ll sm[ten(5) + 10];
	FOR(i, m) {
		memo[i + 1] += memo[i];
		mns[i + 1] += mns[i];
	}
	FOR(i, m) {
		sm[i] = memo[i] - mns[i] * i;
	}

	ll ans = *min_element(memo, memo+m);
	writerLn(ans);

	return 0;
}

