void lazy(int p,int u,int node)
{
    const ll shit1 = lz[node].x;
    const ll shit2 = lz[node].y;
    if (p == u)
        t[node] += shit1;
    else
    {
        int m = (p + u) / 2;
        lz[node << 1].x += shit1;
        lz[node << 1].y += shit2;
        lz[node << 1 | 1].x += shit1 + (m - p + 1) * shit2;
        lz[node << 1 | 1].y += shit2;
    }
    lz[node] = mp(0ll,0ll);
};
void update(int p,int u,int l,int r,ll v1,ll v2,int node)
{
    if (l > r) return;
    lazy(p,u,node);
    if (l <= p && u <= r)
        lz[node].x += v1 + (p - l) * v2,lz[node].y += v2,lazy(p,u,node);
    else
    {
        int m = (p + u) / 2;
        if (l <= m)
            update(p,m,l,r,v1,v2,node << 1);
        if (m+1<=r)
            update(m+1,u,l,r,v1,v2,node << 1 | 1);
    }
}
ll query(int p,int u,int node)
{
    lazy(p,u,node);
    if (p == u)
        return t[node];
    else
    {
        int m = (p + u) / 2;
        return min(query(p,m,node << 1),query(m+1,u,node << 1 | 1));
    }
}
