void upd(int n,int b,int e,int i,int j,double k,double s)
{

    if(lazy[n]) {
        if(b!=e) {
            lazy[lc] = 1;
            lazy[rc] = 1;
            T[lc] += T[n];
            T[rc] += T[n];
            P[lc] += P[n];
            P[rc] += P[n];

            lazy[n] = 0;
            T[n] = 0;
            P[n] = 0;
        }

    }
    if(b>j||e<i)return;
    if(b>=i&&e<=j){
        T[n] += k;
        P[n] += s;
        lazy[n] = 1;
        return;
    }
    int mid = (b+e)/2;
    upd(lc,b,mid,i,j,k,s);
    upd(rc,mid+1,e,i,j,k,s);


