inline void push1(int i) {
    if (mod1[i] != 0) {
        d1[i] += mod1[i];
        if (i < ss) {
            mod1[i * 2] += mod1[i];
            mod1[i * 2 + 1] += mod1[i];
        }
        mod1[i] = 0;
    }
}


void add1(int v, int vl, int vr, int l, int r, int x) {
    push1(v);
    if (l > vr || vl > r) {
        return;
    }
    if (l <= vl && vr <= r) {
        mod1[v] += x;
     //   cout << vl << ' ' << vr << ' ' << x << endl;
        push1(v);
        return;
    }
    add1(v * 2, vl, (vl + vr) / 2, l, r, x);
    add1(v * 2 + 1, (vl + vr) / 2 + 1, vr, l, r, x);
    d1[v] = max(d1[v * 2], d1[v * 2 + 1]);
}


long long rmq1(int v, int vl, int vr, int l, int r) {
    push1(v);
    if (l > vr || vl > r) {
        return -1e18;
    }
    if (l <= vl && vr <= r) {
        return d1[v];
    }
    return max(rmq1(v * 2, vl, (vl + vr) / 2, l, r), rmq1(v * 2 + 1, (vl + vr) / 2 + 1, vr, l, r));
}


