vector<LL> G[100001];
LL decreasing;
LL W;
LL ans;
int main() {
	cin >> N >> M;
	REP(i, 0, N) {
		cin >> A[i];
		if (i != N - 1) ++S[A[i]];
		if (i != 0) G[A[i]].push_back(i);
	}
	REP(i, 0, N - 1) {
		B[i] = M * (A[i] > A[i + 1]) + A[i + 1] - A[i];
	}

	REP(i, 0, N - 1) {
		W += min(B[i], A[i + 1]);
		if(B[i] > A[i + 1]) ++decreasing;
	}

	ans = W;
	REP(k, 2, M + 1) {
		for (int a : G[k - 1]) {
			W += B[a - 1] - 1;
		}
		decreasing -= G[k - 1].size();
		W -= decreasing;
		decreasing += S[k - 1];
		ans = min(ans, W);
	}
	cout << ans << endl;
	return 0;
}

