	for (int i = 1; i <= n; i++) cin >> a[i], a[i]--;
	for (int i = 1; i <= n; i++) {
		if (a[i] < a[i - 1]) {
			ll need = (a[i - 1] - a[i] + m - 1) / m;
			a[i] += need * m;
		}
		if (i > 1) {
			int l = (a[i - 1] + 1) % m;
			int r = a[i] % m;
			int c = (a[i - 1] + 1) / m;
			if (l > r) {
				upd(0, l, a[i - 1] + 1);
				upd(1, l, 1);
				upd(2, l, c * m);
				l = 0;
				c++;
			}
			upd(0, l, a[i - 1] + 1);
			upd(1, l, 1);
			upd(2, l, c * m);
			upd(0, r + 1, -(a[i - 1] + 1));
			upd(1, r + 1, -1);
			upd(2, r + 1, -c * m);
		}
	}
	ll res = 1e18;
	for (int i = 0; i < m; i++) {
		ll s = get(0, i);
		ll num = get(1, i);
		ll c = get(2, i);
		res = min(res, (a[n] - a[1]) - (c + num * i - s));
	}
	cout << res;
}

