int N, M, a[MAXN];
struct event {
  int y, type, dir, save; // type 0: enter, type 1: exit, dir 1: up, dir -1: down
  event(int _y, int _type, int _dir, int _save): y(_y), type(_type), dir(_dir), save(_save) {}
  bool operator < (const event &ano) const {
    if (type != ano.type) return type < ano.type;
    return y < ano.y;
  }
};
int main() {
  cin >> N >> M;
  ll totCost = 0;
  vector<event> es;
  ll ans = INF, uping=0, downing=0, saving=0;
  REP(i,0,N) {
    scanf("%d", a+i); a[i]--;
    if (i) {
      if (a[i] > a[i-1]) {
        totCost += a[i] - a[i-1];
        es.push_back(event(a[i-1], 0, 1, 0));
        es.push_back(event(a[i], 1, 1, a[i]-a[i-1]));
      } else if (a[i] < a[i-1]) {
        totCost += M - a[i-1] + a[i];
        es.push_back(event(a[i], 1, -1, M-a[i-1]+a[i]));
        downing++;
        saving += M - a[i-1];
      }
    }
  }
  sort(es.begin(), es.end());
  int ei = 0;
  REP(m,0,M) {
    ll sol = totCost - saving + uping + downing;
    ans = min(ans, sol);
    while (ei < es.size() && es[ei].y == m && es[ei].type == 0) {
      uping++; ei++;
    }
    while (ei < es.size() && es[ei].y == m && es[ei].type == 1) {
      if (es[ei].dir == 1) uping--;
      else downing--;
      saving -= es[ei].save;
      ei++;
    }
    saving += uping + downing;
  }
  cout << ans << endl;
  return 0;
}

