void solve() {
  int n, m;
  cin >> n >> m;
  vi32 a(n);
  cin >> a;
  rep(i, n) a[i]--;
  i64 all = 0;
  vi32 cnts(m * 2 + 1);
  vi64 sums(m * 2 + 1);
  vi64 imos(m * 2 + 1);
  using T = tuple<int, int>;
  vector<vector<T>> events(m * 2 + 1);
  rep(i, n - 1) {
    int l = a[i];
    int r = a[i + 1];
    if (l > r) r += m;
    sums[l + 1] += r - l;
    sums[r + 1] -= r - l;
    cnts[l + 1] += 1;
    cnts[r + 1] -= 1;
    all += r - l;
    events[l + 1].emplace_back(0, r - l - 1);
    events[r].emplace_back(1, 0);
  }
  i64 acc = 0;
  int cnt = 0;
  repc(i, m * 2) {
    for (auto p : events[i]) {
      int kind, diff;
      tie(kind, diff) = p;
      if (kind == 0) {
        acc += diff;
        cnt += 1;
      } else {
        cnt -= 1;
      }
    }
    imos[i] = acc;
    acc -= cnt;
  }
  rep(i, m * 2 - 1) {
    sums[i + 1] += sums[i];
    cnts[i + 1] += cnts[i];
  }
  i64 ans = 1e18;
  rep(chan, m) {
    i64 sum = all;
    sum -= sums[chan] + sums[chan + m];
    sum += cnts[chan] + cnts[chan + m];
    sum += imos[chan] + imos[chan + m];
    amin(ans, sum);
  }
  cout << ans << endl;
}

