int main() {
	ll N, M;
	ll A[100005];
	vector<Pl> sorted(100005);
	ll cost = 0;
	ll num = 0;
	cin >> N >> M;
	for (int i = 0; i < N; i++) {
		cin >> A[i]; --A[i];
		sorted[i] = Pl(A[i], i);
		if (i) {
			if (A[i - 1] <= A[i]) cost += A[i] - A[i - 1];
			else cost += A[i] + 1, num++;
		}
	}
	sort(rbegin(sorted), rend(sorted));

	ll minv = cost;
	//cout << " " << cost << endl;
	ll i = 0;
	ll plus = 0;

	while (i < N) {
		ll val = sorted[i].first; 
		ll cnt = 0;
		ll mae, ushiro;
		mae = ushiro = 0;

		ll d = val + plus;
		while (i < N && sorted[i].first == val) {
			ll idx = sorted[i].second;
			if (idx == 0) mae = -1;
			if (idx == N - 1) ushiro = 1;
			if (idx > 0) cost -= d - (A[idx - 1] + plus) % M;
			i++, cnt++;
		}
		cost += num * (M - d);
		cost += mae + ushiro;
		//cout << " " << cost << endl;
		num += mae + ushiro;

		plus += (M - d);
		minv = min(minv, cost);
	}

