void put(int c, int x, int y) {
    for ( ; x <= m ; x += x & (- x)) {
        bit[c][x] += y ;
    }
}

ll get(int c, int x) {
    ll ret = 0 ;
    for ( ; x ; x -= x & (- x)) {
        ret += bit[c][x] ;
    }
    return ret ;
}

void solve(int l, int r, int ave) {
    put(0, l, 1) ;
    put(1, l, ave) ;
    put(0, r + 1, - 1) ;
    put(1, r + 1, - ave) ;
}

