        if (x == y) continue ;
        if (x < y) {
            ans += y - x ;
            solve(x + 1, y, - x - 1) ;
        } else {
            ans += m - x + y ;
            if (x < m) {
                solve(x + 1, m, - x - 1) ;
            }
            solve(1, y, m - x - 1) ;
        }
    }
    ll mx = 0 ;
    rep(i, 1, m) {
        mx = max(mx, get(0, i) * i + get(1, i)) ;
    }
    printf("%lld\n", ans - mx) ;
