void solve() {
	int n, m; cin >> n >> m;
    vector<int> a(n);
    rep(i, n) {
        cin >> a[i];
    }
    int res = 0;
    rep(i, n - 1) {
        int x = a[i], y = (a[i] <= a[i + 1] ? a[i + 1] : a[i + 1] + m);
        if(x < m && m <= y) {
            res += 1 + (y - m);
        } else {
            res += (y - x);
        }
    }
    int ans = res;
    vector<int> cnt(3 * m, 0);
    map<int, int> mp;
    rep(i, n - 1) {
        int x = a[i], y = (a[i] < a[i + 1] ? a[i + 1] : a[i + 1] + m);
        mp[(a[i + 1] + 1) % m] += (y - x - 1);
        if(x + 2 <= y) cnt[x + 2] --;
        cnt[y + 1] ++;
    }
    rep(i, 2 * m - 1) {
        cnt[i + 1] += cnt[i];
    }
    rep(i, m) {
        cnt[i] += cnt[i + m];
    }
    for(int k = 1; k < m; ++k) {
        res += mp[k];
        res += cnt[k];
        chmin(ans, res);
    }
    cout << ans << endl;
}

