template<typename T> bool chkmin(T&a, T b) { return a > b ? a = b, 1 : 0; }
template<typename T> bool chkmax(T&a, T b) { return a < b ? a = b, 1 : 0; }

LL n, m;
LL a[100010];
pair<LL, LL> rng[800010];

LL cnt, ans;
void add(LL l, LL r) {
    rng[++cnt] = make_pair(l, LLONG_MIN);
    rng[++cnt] = make_pair(r, l-r);
    ans += r-l;
}

int main() {

    //freopen("out.txt", "r", stdin);
    cin >> n >> m;
    for(LL i = 1; i <= n; i++) {
        cin >> a[i];
        if(i > 1) {
            if(a[i-1] < a[i]) 
                add(a[i-1], a[i]), add(a[i-1] + m, a[i] + m), ans -= a[i] - a[i-1];
            else 
                add(a[i-1], a[i] + m);
        }
    }

    sort(rng+1, rng+cnt+1);

    LL dans = 0;
    LL tot = 0, res = 0;
    for(LL j = 1, i = 1; i <= 2*m; i++) {

        res += tot;
        chkmax(dans, res - tot);

        while(j <= cnt && rng[j].fst == i) {
            if(rng[j].snd == LLONG_MIN) ++ tot; 
            else break;
            ++ j;
        }
        while(j <= cnt && rng[j].fst == i) {
            -- tot, res += rng[j].snd;
            ++ j;
        }
    }
    printf("%lld\n", ans - dans);
    return 0;
}

