#define ll long long

using namespace std;

const ll inf = 1e18;
const ll mod = 1e9 + 7;

const ll MAXN = 1e5 + 100;

ll t[MAXN * 4];
ll cnt[MAXN * 4];

void update(ll v, ll tl, ll tr, ll l, ll r, ll val) {
    if (l > r)
        return;
    if (tl == l && tr == r) {
        t[v] += val;
        ++cnt[v];
    } else {
        ll tm = (tl + tr) / 2;
        update(v * 2, tl, tm, l, min(r, tm), val);
        update(v * 2 + 1, tm + 1, tr, max(l, tm + 1), r, val);
    }
}

pair<ll, ll> get(ll v, ll tl, ll tr, ll pos) {
    if (tl == tr)
        return {t[v], cnt[v]};
    ll tm = (tl + tr) / 2;
    pair<ll, ll> res;
    if (pos <= tm)
        res = get(v * 2, tl, tm, pos);
    else
        res = get(v * 2 + 1, tm + 1, tr, pos);
    return {res.first + t[v], res.second + cnt[v]};
}

