    for (ll i = 0; i < n; ++i) {
        scanf("%lld", &a[i]);
    }
    ll all = 0;
    for (ll i = 0; i + 1 < n; ++i) {
        if (a[i + 1] >= a[i]) {
            all += a[i + 1] - a[i];
            update(1, 0, MAXN - 1, a[i] + 1, a[i + 1], a[i]);
        }
        else {
            all += a[i + 1] + m - a[i];
            update(1, 0, MAXN - 1, a[i] + 1, m, a[i]);
            update(1, 0, MAXN - 1, 1, a[i + 1], a[i] - m);
        }
    }
    // cerr << "a " << all << endl;
    ll ans = inf;
    for (ll i = 1; i <= m; ++i) {
        pair<ll, ll> g = get(1, 0, MAXN - 1, i);
        ll cur = all - g.second * (i - 1) + g.first;
        ans = min(ans, cur);
        cerr << cur << endl;
    }
    printf("%lld", ans);

    return 0;
}

