ll calc_total(const V<ll> &alist, ll n, ll m)
{
    ll total = 0LL;

    rep (i, n-1) {
        ll a1 = alist[i];
        ll a2 = alist[i+1];

        if (a1 < a2) {
            total += a2 - a1;
            continue;
        }

        total += m - a1;
        total += a2;
    }

    debug_printf("---- total=%lld\n", total);
    return total;
}

ll calc_bonus(const V<ll> &alist, ll n, ll m)
{
    ll bonus = 0LL;

    // calc bonus when x == 1
    rep (i, n-1) {
        ll a1 = alist[i];
        ll a2 = alist[i+1];
        if (a1 < a2) continue;
        bonus += m - a1;
    }

    S ll cnt1[100005];
    S ll cnt2[100005];
    S ll decr2[100005];
    memset(cnt1, 0, sizeof(cnt1));
    memset(cnt2, 0, sizeof(cnt2));
    memset(decr2, 0, sizeof(decr2));
    ll inrange = 0LL;

    rep (i, n-1) {
        ll a1 = alist[i];
        ll a2 = alist[i+1];
        a1 = ((a1 == m) ? 1LL : (a1 + 1LL));
        cnt1[a1]++;
        cnt2[a2]++;
        ll decr = a2 - a1;
        if (decr < 0LL) {
            decr = m - a1 + a2;
            inrange++;
        }
        decr2[a2] += decr;
    }

    ll now = bonus;

    srep (x, 1, m+1) {
        debug_printf("-------- x=%lld bonus=%lld inrange=%lld\n",
                     x, now, inrange);
        bonus = max(bonus, now);
        inrange += cnt1[x];
        inrange -= cnt2[x];
        now += inrange;
        now -= decr2[x];
    }

    debug_printf("---- bonus=%lld\n", bonus);
    return bonus;
}

