//it
void build(int x,int l,int r)
{
    low[x]= l; high[x]= r; it[x]= f[x]= v[x]= 0;
    if (l==r) return;
    int m= (l+r)/2;
    build(2*x,l,m); build(2*x+1,m+1,r);
}
long sum(long f,long v,long sz)
{
    return f*sz+ (sz-1)*sz/2* v;
}
void downlazy(int x)
{
    it[2*x]+= sum(f[x],v[x],high[2*x]- low[2*x]+1);
    f[2*x]+= f[x]; v[2*x]+= v[x];
    it[2*x+1]+= sum(f[x]+(high[2*x]-low[2*x]+1)*v[x], v[x], high[2*x+1]- low[2*x+1]+1 );
    f[2*x+1]+= f[x]+(high[2*x]-low[2*x]+1)*v[x]; v[2*x+1]+= v[x];
    f[x]= v[x]= 0;
}
void update(int x,int l,int r,long newf,long newv)
{
    if (l> high[x] or r< low[x]) return;
    if (low[x]>= l and high[x]<= r)
    {
    	long sz= high[x]- low[x]+1;
        it[x]+= sum(newf+ (low[x]-l)* newv,newv,sz);
        f[x]+= newf+ (low[x]-l)* newv; v[x]+= newv;
        return;
    }
    downlazy(x);
    update(2*x,l,r,newf,newv); update(2*x+1,l,r,newf,newv);
    it[x]= it[2*x]+ it[2*x+1];
}
long query(int x,int l)
{
     if (l> high[x] or l< low[x]) return 0;
     if (low[x]== high[x]) return it[x];
     downlazy(x);
     return query(2*x,l)+ query(2*x+1,l);
}
