void solve()
{
    build(1,1,m);
    up(i,1,n-1)
    {
        if (a[i]< a[i+1]) update(1,a[i]+1,a[i+1],0,1);
        else if (a[i]> a[i+1])
		{
			update(1,a[i]+1,m,0,1);
			update(1,1,a[i+1],m-a[i],1);
		}
    }
    long savemax= 0;
    up(i,1,m)
    {
        savemax= max(savemax, query(1,i));
