class BIT
{
public:
    vector<int> bit;
    int M;

    BIT(int M):
        bit(vector<int>(M+1, 0)), M(M) {}

    int sum(int i) {
        if (!i) return 0;
        return bit[i] + sum(i-(i&-i));
    }

    void add(int i, int x) {
        if (i > M) return;
        bit[i] += x;
        add(i+(i&-i), x);
    }
};

void add_b(int l, int r, BIT &b0, BIT &b1, int n){
    b1.add(l, 1);
    b1.add(r + 1, -1);
    b0.add(l, n - l);
    b0.add(r + 1, l - n);
}

