class BIT{
	#define lowbit(x) ((x)&(-(x)))
	private:
		lld arr[N];
		int size;
	public:
		//1-base (l, r]
		void init(int n){
			size=n;
			//arr=new lld[n];
			fill(arr,arr+n,0);
		}
		void add(int l, int r, lld v){
			add(r, v);
			add(l, -v);
		}
		void add(int r, lld v){
			while(r){
				arr[r]+=v;
				r-=lowbit(r);
			}
		}
		lld query(int x){
			lld sm=0;
			while(x<size){
				sm+=arr[x];
				x+=lowbit(x);
			}
			return sm;
		}
	#undef lowbit
};

