void solve() {
  int n, m; cin >> n >> m;
  vi arr(n); cin >> arr;

  Graph<int> pos(m);
  rep(i,n) {
    pos[--arr[i]].emplace_back(i);
  }

  int cycle = 0;

  vl dec(m);
  dec[0] = 0;

  rep1(i,n) {
    if (arr[i-1] > arr[i]) {
      ++cycle;
      dec[0] += m - arr[i-1] - 1;
    }
  }

  vi cnt(m, cycle + 1);
  repeq(i,arr[0]) --cnt[i];
  REP(i,arr[n-1]+1,m-1) --cnt[i];

  rep(i,m-1) {
    ll tmp = 0;

    for (auto &v : pos[i]) {
      if (v != 0) {
        int dif = i - arr[v-1];
        if (dif < 0) dif += m;
        tmp += dif - 1;
      }
    }

    dec[i+1] = dec[i] - tmp + cnt[i+1] - pos[i].size();
  }

  ll ans = 1LL * cycle * m - arr[0] + arr[n-1] - *max_element(ALL(dec));
  cout << ans << endl;
}


