	ll ans = 0;
	while(n > 0){
		ans += bit[n];
		n -= n&(-n);
	}
	return ans;
}

void add(vector<ll> &bitn, vector<ll> &bitc, ll x, int l, int r){
	add(bitn, x, l);
	add(bitc, (-l+1)*x, l);
	add(bitn, -x, r+1);
	add(bitc, r*x, r+1);
}

ll sum(vector<ll> &bitn, vector<ll> &bitc, int n){
	return sum(bitn, n)*n+sum(bitc, n);
}

