void updateCnt(int l, int r, ll x) {
    assert(l <= r);
    cnt[l] += x, cnt[r + 1] -= x;
}

void updateSum(int l, int r, ll x) {
    assert(l <= r);
    sum[l] += x, sum[r + 1] -= x;
}

int dist(int x, int y) {
    return (y - x + m) % m;
}

void out() {
    ll f = 0, s = 0;
    for (int i = 0; i < m; i++) {
        f += cnt[i], s += sum[i];
        cout << now + f * 1ll * i + s << ' ';
    }
    cout << endl;
}

void updateLeft(int x, int sub, ll val) {
//    cout << "updateLeft " << x << ' ' << sub << " with " << val << endl;

    int l = (x - sub + m) % m, r = x;
    if (l <= r) {
        updateCnt(l, r, -1);
        updateSum(l, r, val + r);
    } else {
        updateCnt(0, r, -1);
        updateSum(0, r, val + r);

        updateCnt(l, m - 1, -1);
        updateSum(l, m - 1, val + m + r);
    }
}

void updateRight(int x, int add, ll val) {

//    cout << "updateRight " << x << ' ' << add << " with " << val << endl;


    int l = x, r = (x + add) % m;
    if (l <= r) {
        updateCnt(l, r, 1);
        updateSum(l, r, val - l);
    } else {
        updateCnt(l, m - 1, 1);
        updateSum(l, m - 1, val - l);

        updateCnt(0, r, 1);
        updateSum(0, r, val + m - l);
    }
}

