const int MAXN = 100005;

int n, m, a[MAXN], k[MAXN];
LL b[MAXN];

inline void Solve(int l, int r)
{
	if (l < r)
	{
		b[1] += r - l;
		b[l + 1] -= r - l;
		b[r + 1] += r - l;
		k[l + 1] --;
		k[r + 1] ++;
		b[l + 1] += r + 1;
		b[r + 1] -= r + 1;
	}
	else
	{
		b[r + 1] += m + r - l;
		b[l + 1] -= m + r - l;
		k[1] --;
		k[r + 1] ++;
		b[1] += r + 1;
		b[r + 1] -= r + 1;
		k[l + 1] --;
		b[l + 1] += r + m + 1;
	}
}

