int main()
{
    scanf("%d%d",&N,&M);
    for(int i = 0; i < N; i++)scanf("%d",&A[i]);
    for(int i = 1; i < N; i++)
    {
        int length,l = A[i - 1],r = A[i];
        if(l <= r)length = r - l;
        else length = M + (r - l);
        ans += length;
        if(length < 2)continue;
        int s = l + 1;
        num[s + length - 1] += length - 1;
        app[s]++;
        dis[s + length - 1]--;
    }
    int now = 0,dif = 0;
    for(int i = 0; i < M * 2 + 10; i++)
    {
        neg[i] = now;
        now -= num[i];
        dif += app[i];
        dif += dis[i];
        now += dif;
    }
    int sum = 0;
    for(int i = 1; i < M + 1; i++)
    {//printf("%d %d\n",i,neg[i] + neg[i + M]);
        sum = max(sum,neg[i] + neg[i + M]);
    }
    printf("%d\n",ans - sum);
    return 0;
}

