ll simulate(ll fav) {
    //printf("begin FAV:%d\n",fav);
    ll count = 0;
    ll a = aa[0];
    iterate(1, n) {
        ll b = aa[cnt];
        ll v = b - a;
        if (v < 0) v = b - (a - m);
        ll w = b - fav;
        if (w < 0) w = b - (fav - m);

        ++w; // favボタンを押した

        count += min(v, w);

        //printf("%d -> %d; ctrl:%d <= %d vs %d\n",a,b,min(v, w),v,w);
        a = b;
    }
    //printf("fin\n");
    return count;
}

