		else if (a[i + 1] < a[i] && (a[i] + 1 % m) != a[i + 1]) {
			dc[(a[i] + 1) % m]++;
			dc[a[i + 1]]--;
			dt[a[i + 1] + 1] += a[i + 1] - a[i] + m - 1;
			if (a[i + 1] > 1) {
				c++;
			}
		}
	}
	int x = 1;
	ll t = 0;
	FOR(i, 0, n - 1) {
		t += min((a[i + 1] - a[i] + m) % m, (a[i + 1] - x + m) % m + 1);
	}
	ll ans = t;
	FOR(i, 2, m + 1) {
		t -= c;
		c += dc[i];
		t += dt[i];
		ans = min(ans, t);
	}
	cout << ans << endl;
}

