	cin>>n>>m;
	vc<int> a(n);
	f(i,n) cin>>a[i],a[i]--;
	vc<Step> steps(n-1);
	f(i,n-1) steps[i]=Step(i,a[i],a[i+1]);
	vc<Event> events;
	f(i,n-1) for(auto e:steps[i].getEvents()) events.pb(e);
	sort(all(events));
	auto lf=Linfun(0,0);
	f(i,n-1) lf+=steps[i].cost(0);
	int j=0;
	while(events[j].x==0) j++;
	int best=2e9;
	f(x,m){
		for(;j<sz(events)&&events[j].x==x;j++){
			int i=events[j].i;
			lf-=steps[i].cost(x-1);
			lf+=steps[i].cost(x);
		}
		int cand=lf.eval(x);
		if(cand<best) best=cand;
	}
	cout<<best<<'\n';
}


