int get_ans(int node, int l, int r)
{
	diffuse(node, l, r);
	if (l == r)
		return Seg[node].val;
	int mi = (l + r) /2;
	return min(get_ans(node * 2, l, mi), get_ans(node * 2 + 1, mi + 1, r));
}

