	for (int i=2;i<=n;i++){
		if (num[i]>=num[i-1]) update(1,1,2*m,num[i-1]+1,num[i],num[i-1]),update(1,1,2*m,num[i-1]+m,num[i]+m,num[i-1]+m),cnt+=num[i]-num[i-1];
			else update(1,1,2*m,num[i-1]+1,num[i]+m,num[i-1]),cnt+=num[i]+m-num[i-1];
	}
	ll ans=inf;
	for (int i=1;i<=2*m;i++){
		sum1=sum2=0;
		query(1,1,2*m,i);
		ans=min(ans,cnt-sum2*i+sum2+sum1);
	}
	printf("%lld\n",ans);
}
