const int BIT_MAX = 100010;

template <class T> class BIT{
	T x[BIT_MAX + 1];

public:

	BIT(){
		fill(x,x+BIT_MAX+1,0);
	}

	void add(int a , T b){
		++a;
		for(; a <= BIT_MAX ; a += a & -a) x[a] += b;
	}

	T get(int a){
		++a;
		T b = 0;
		for(; a > 0 ; a -= a & -a) b += x[a];
		return b;
	}
};

