    for (int i = 0; i < n; ++i) {
        cin >> a[i];
        if (i && a[i] < a[i - 1]) {
            ll t = (a[i - 1] - a[i] + m - 1) / m;
            a[i] += t * m;
        }
    }
    ll s = a[n - 1] - a[0];
    for (int i = 0; i + 1 < n; ++i) {
        if (a[i + 1] - a[i] < 2) {
            continue;
        }
        ll l = (a[i] + 2) % m;
        ll r = (a[i + 1]) % m;
        if (!l) {
            l += m;
        }
        if (!r) {
            r += m;
        }
        if (l > r) {
            update(l, m);
            update(1, r, m - l + 2);
        } else {
            update(l, r);
        }
    }
    ll ans = s;
    for (int i = 1; i <= m; ++i) {
        ans = min(ans, s - query(i, i));
