int solve(int n, int m, vi a) {
//    cin >> n >> m;
//    addn(a, n);
    vi rui(k5 * 3);
    int su = 0;
    vi ato(k5 * 3);
    rep(i, n - 1) {
        int f = a[i];
        int t = a[i + 1];
        if (f > t) {
            t += m;
        }
        su += t - f;
        rui[f + 2]--;
        rui[t + 1]++;
        ato[t + 1] += t - f - 1;//1 - d-1まで入っている
    }
    imo(rui);
    rep(i, k5 * 3)rui[i] += ato[i];
    imo(rui);
    vi res(m + 1);
    rep(i, 1, m + 1)res[i] = su + rui[i] + rui[i + m];
    return min(res, 1, inf);
}
