using namespace std;
typedef long long LL;
const int SIZEN = 100010;
int N,M;
LL f[SIZEN]={0},ans = 0;
int a[SIZEN]={0};
int sum[SIZEN]={0};
int tmp1[SIZEN] = {0};
int tmp2[SIZEN]={0};
int main(){
	scanf("%d%d",&N,&M);
	for(int i = 1;i <= N;i++)scanf("%d",&a[i]);
	for(int i = 2;i <= N;i++){
		int x,y;
		if(a[i-1] < a[i]){
			x = a[i-1];y = a[i];
			ans += y-x;
			f[x+1] += (-x-1);
			f[y+1] -= (-x-1);
			sum[x+1]++;sum[y+1]--;
		}	
		else{
			ans += M-a[i-1];
			ans += a[i];
			x = a[i-1];y = M;
			if(x+1 <= y){
				f[x+1] += (-x-1);
				f[y+1] -= (-x-1);
				sum[x+1]++;sum[y+1]--;
			}
			x = 1;y = a[i];
			f[x] += (M-a[i-1]-1);
			f[y+1] -= (M-a[i-1]-1);
			sum[x]++;sum[y+1]--;	
		}
	}
	LL mx = 0;
	for(int i = 1;i <= M;i++){
		sum[i] += sum[i-1];
		f[i] += f[i-1];
		mx = max(mx,f[i]+sum[i]*i);
	}
	printf("%lld\n",ans-mx);
	getchar();getchar();
	return 0;
}

#include <iostream>
#define ll long long
using namespace std;
ll N,M;
ll A[100005];
ll dist(ll x,ll y)
{
    if(x<=y)return y-x;
    return M-x+y;
}
ll cost(ll x)
{
    ll rez=0;
    for(ll i=2;i<=N;i++)
        rez+=min(1+dist(x,A[i]),dist(A[i-1],A[i]));
    return rez;
}
int main()
{
    cin>>N>>M;
    for(ll i=1;i<=N;i++)
        cin>>A[i];
    ll rez=1;
    ll minim=cost(rez);
    for(ll pas=1<<20;pas;pas>>=1)
    {
        ll j,k;j=k=1LL<<60;
        if(rez+pas<=M&&cost(rez+pas)<minim)j=cost(rez+pas);
        if(rez-pas>0&&cost(rez-pas)<minim)k=cost(rez-pas);
        if(j<k&&j<minim){minim=j;rez+=pas;}
        else if(k<=j&&k<minim){minim=k;rez-=pas;}
    }
    cout<<minim;
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

typedef long long ll;

ll N, M;
vector<ll> A;
ll Base, Skip, DSkip;
vector<ll> XSkip, XDSkip;
ll R = 1ll << 60;

int main() {
  cin >> N >> M;
  for (ll i = 0; i < N; ++i) {
    ll a;
    cin >> a;
    --a;
    A.push_back(a);
  }
  for (ll i = 0; i < N - 1; ++i) {
    ll d = A[i + 1] - A[i];
    if (d < 0) d += M;
    Base += d;
    if (A[i] > A[i + 1]) {
      Skip += M - A[i] - 1;
      ++DSkip;
    }
  }
  XSkip.resize(M);
  XDSkip.resize(M);
  for (ll i = 0; i < N - 1; ++i) {
    ll d = A[i + 1] - A[i];
    if (d < 0) d += M;
    XSkip[A[i + 1]] += d - 1 + 1;
  }
  ++XDSkip[A[0]];
  --XDSkip[A[N - 1]];
  for (ll x = 0; x < M; ++x) {
    R = min(R, Base - Skip);
    Skip += DSkip;
    Skip -= XSkip[x];
    DSkip += XDSkip[x];
  }
  cout << R << endl;
  return 0;
}

