#define _int64 long long

int a[110000];
_int64 d[510000];

void doit(int x,int l,int r,int ll,int rr,int v)
{
  int mid;
  if (r<ll) return;
  if (rr<l) return;
  if ((ll<=l)&&(r<=rr))
  {
    d[x]+=v;
    return;
  }
  mid=(l+r)/2;
  doit(x+x+1,l,mid,ll,rr,v);
  doit(x+x+2,mid+1,r,ll,rr,v);
}

_int64 get1(int x,int l,int r,int p)
{
  _int64 ret;
  int mid;
  if (p<l) return 0;
  if (r<p) return 0;
  ret=d[x];
  mid=(l+r)/2;
  if (r>l)
  {
    ret+=get1(x+x+1,l,mid,p);
    ret+=get1(x+x+2,mid+1,r,p);
  }
  return ret;
}

int main()
{
  int i,j,m,n,tmp,tmp1;
  _int64 tot,best;
  scanf("%d%d",&n,&m);
  for (i=0;i<n;i++)
  {
    scanf("%d",&a[i]);
    a[i]--;
  }
  memset(d,0,sizeof(d));
  for (i=0;i+1<n;i++)
  {
    tmp=a[i];
    if (tmp==a[i+1]) continue;
    tmp++;
    if (tmp==m) tmp=0;
    if (tmp==a[i+1]) continue;
    tmp++;
    if (tmp==m) tmp=0;
    tmp1=a[i+1];
    tmp1++;
    if (tmp1==m) tmp1=0;
    if (tmp<=a[i+1])
    {
      //cout<<"a:"<<tmp<<" "<<a[i+1]<<endl;
      doit(0,0,m-1,tmp,a[i+1],-1);
      doit(0,0,m-1,tmp1,tmp1,a[i+1]-tmp+1);
    }
    else
    {
      //cout<<"a:"<<tmp<<" "<<m-1<<endl;
      //cout<<"a:"<<0<<" "<<a[i+1]<<endl;
      doit(0,0,m-1,tmp,m-1,-1);
      doit(0,0,m-1,0,a[i+1],-1);
      doit(0,0,m-1,tmp1,tmp1,m-tmp+a[i+1]+1);
    }
  }
  tot=0;
