  {
    tmp=a[i+1]-a[i];
    if (tmp<0) tmp+=m;
    tmp1=a[i+1]+1;
    if (tmp1<tmp) tmp=tmp1;
    tot+=tmp;
  }
  best=tot;
  for (i=1;i<m;i++)
  {
    //cout<<tot<<endl;
    tot+=get1(0,0,m-1,i);
    if (tot<best) best=tot;
  }
  //cout<<tot<<endl;
  printf("%lld\n",best);
  return 0;
}

