#define N 200010
using namespace std;
long long lz1[N * 4], lz2[N * 4];
int a[N];
void build(int node, int l, int r)
{
	if(l == r) return ;
	int mid = (l + r) / 2;
	build(node << 1, l, mid);
	build(node << 1, mid + 1, r);
}
void Push_down(int node, int l, int r)
{
	if(!lz1[node] && !lz2[node]) return ;
	long long d = (lz2[node] - lz1[node]) / (r - l);
	int mid = (l + r) / 2;
	lz1[node << 1] += lz1[node];
	lz2[node << 1] += lz1[node] + d * (mid - l);
	lz1[node << 1 | 1] = lz1[node] + d * (mid - l + 1);
	lz2[node << 1 | 1] = lz2[node];
	lz1[node] = lz2[node] = 0;
}
void update(int node, int l, int r, int left, int right, int d1, int d2)
{
	if(l >= left && r <= right)
	{
		long long d = (d2 - d1) / (right - left);
		long long t1 = 1LL * d1 + d * (l - left), t2 = 1LL * d1 + d * (r - left);
		lz1[node] += t1;
		lz2[node] += t2;
		return ;
	}
	int mid = (l + r) / 2;
	Push_down(node, l, r);
	if(left <= mid) update(node << 1, l, mid, left, right, d1, d2);
	if(right > mid) update(node << 1 | 1, mid + 1, r, left, right, d1, d2);
}
long long query(int node, int l, int r, int k)
{
    if(l == r)
        return lz1[node];
    int mid = (l + r) / 2;
    Push_down(node, l, r);
    if(mid >=k)
        return query(node << 1, l, mid, k);
    else
        return query(node << 1 | 1, mid + 1, r, k);
}
int main()
{
	int n, m, i;
	long long t = 0;
	scanf("%d%d", &n, &m);
	build(1, 1, 2 * m);
	for(i = 1; i <= n; ++i) scanf("%d", &a[i]);
	for(i = 2; i <= n; ++i)
	{
		if(a[i - 1] < a[i])
		{
		    t += a[i] - a[i - 1];
			update(1, 1, m * 2, a[i - 1] + 1, a[i], 0, a[i] - a[i - 1] - 1);
		}else
		{
		    t += a[i] - a[i - 1] + m;
			update(1, 1, m * 2, a[i - 1] + 1, a[i] + m, 0, a[i] + m - a[i - 1] - 1);
		}
	}
	long long maxn = 0;
	for(i = 1; i <= m; ++i) maxn = max(maxn, query(1, 1, 2 * m, i) + query(1, 1, 2 * m, i + m));
    printf("%lld\n", t - maxn);
	return 0;
}

