                //cout << prev + 1 << " " << m << " " << 0 << endl;
            }
            int taken = m - (prev + 1);
            //cout << 1 << " " << cur << " " << taken + 1 << endl;
            update(1, 1, m, 1, cur, taken + 1);
        }
        //for(int i = 1; i <= m; i++) cout << query(1, 1, m, i, i) << " " ;
        //cout << endl;
    }
    //for(int i = 1; i <= m; i++) cout << query(1, 1, m, i, i) << " " ;
