  for(int i = 1; i <= n; ++i){
    scanf("%d", &a[i]);
  }
  for(int i = 1; i < n; ++i){
    int l = a[i], r = a[i + 1];
    if(r > l){
      add[m] += r - l;
      add[r] -= r - l;
      add[l] += r - l;
      add[r] += r + 1;
      add[l] -= r + 1;
      del[r] += 1;
      del[l] -= 1;
    }
    else{
      swap(l, r);
      add[r] += m - r + l;
      add[l] -= m - r + l;
      add[m] += m + l + 1;
      add[r] -= m + l + 1;
      del[m] += 1;
      del[r] -= 1;
      add[l] += l + 1;
      del[l] += 1; 
    }
  }
  for(int i = m - 1; i > 0; --i){
    add[i] += add[i + 1];
    del[i] += del[i + 1];
  }
  long long res = 1LL << 62;
  for(int i = 1; i <= m; ++i){
    add[i] -= 1LL *del[i] * i;
    res = min(res, add[i]);
  } 
