inline void read(int &x){
	static int ch; static bool flag;
	for(flag=0,ch=getchar(); ch<'0'||ch>'9'; ch=getchar()) flag |= ch=='-';
	for(x=0; ch>='0'&&ch<='9'; ch=getchar()) x = (x<<1) + (x<<3) + ch-48;
	x = flag ? -x : x;
}

int N,M,Ans,Sum,A[Maxn],B[Maxn],C[Maxn];

int main()
{
	read(N),read(M);
	for(R int i=1;i<=N;++i) read(A[i]);
	for(R int i=1;i<N;++i){
		R int l=A[i], r=A[i+1];
		if(l==r) continue;
		if(l>r) r+=M;
		B[l+1]++, B[r+1]--, C[r+1]-=r-l;		
	}
	for(R int i=1;i<=M*2;++i) 
		B[i]+=B[i-1], C[i]+=C[i-1]+B[i];
	for(R int i=1;i<=M;++i) 
		B[i]+=B[i+M], C[i]+=C[i+M], Sum+=B[i];
	Ans=Sum;
	for(R int i=1;i<=M;++i) 
		Ans=min(Ans,Sum+B[i]-C[i]);
	printf("%d\n",Ans);
	return 0;
}

