template <typename T>
constexpr T INF = numeric_limits<T>::max() / 100;

int main()
{
    ll n, m;
    cin >> n >> m;
    vector<ll> pos(n, 0);
    for (ll i = 0; i < n; i++) {
        ll p;
        cin >> p;
        pos.at(i) = p;
    }

    vector<ll> count(m + 1, 0);
    vector<ll> imos(m + 1, 0);
    for (ll i = 1; i < n; i++) {
        const ll from = pos[i - 1];
        const ll to = pos[i];
        count[to] += (to - from + m) % m - 1;

        if (from < to) {
            imos[from + 1]++;
            imos[to]--;
        } else if (from < m) {
            imos[from + 1]++;
            imos[1]++;
            imos[to]--;
        } else {
            imos[1]++;
            imos[to]--;
        }
    }
    vector<ll> cnt(m + 1, 0);
    for (ll i = 1; i <= m; i++) {
        cnt[i] = cnt[i - 1] + imos[i];
    }
    //    show(cnt);

    vector<ll> ans(m + 1, 0);
    for (ll i = 1; i <= m; i++) {
        if (i == 1) {
            ll sum = 0;
            for (ll j = 1; j < n; j++) {
                const ll from = pos[j - 1];
                const ll to = pos[j];
                const ll move = (1 - from + m) % m;
                if (0 < move and move <= (to - from + m) % m) {
                    sum += (to - 1 + m) % m + 1;
                } else {
                    sum += (to - from + m) % m;
                }
            }
            ans[1] = sum;
        } else {
            ans[i] = ans[i - 1] + count[i - 1] - cnt[i - 1];
        }
    }
    ll mini = INF<ll>;
    for (ll i = 1; i <= m; i++) {
        if (mini > ans[i]) {
            mini = ans[i];
        }
    }
    cout << mini << endl;

    return 0;
}

