int seg[262144];
void add(int id,int il,int ir,int l,int r,int val)
{
	if (l>=r)
		return;
	if (il>=l&&ir<=r)
		seg[id]+=val;
	else if ((l>=il&&l<ir)||(r>il&&r<=ir))
	{
		add(id<<1,il,(il+ir)>>1,l,r,val);
		add((id<<1)^1,(il+ir)>>1,ir,l,r,val);
	}
}
int query(int id)
{
	id+=131072;
	int ret=0;
	while (id>0)
	{
		ret+=seg[id];
		id>>=1;
	}
	return ret;
}
int n,m,ttl[100001],a[100001];
int dist(int a,int b)
{
	return (b+m-a)%m;
}
