	{
		if (a[i+1]>a[i])
		{
			add(1,0,131072,a[i]+2,a[i+1]+1,1);
			ttl[a[i+1]%m+1]-=a[i+1]-a[i]-1;
		}
		else
		{
			add(1,0,131072,a[i]+2,m+1,1);
			ttl[1]+=m-a[i+1];
			add(1,0,131072,1,a[i+1]+1,1);
			ttl[a[i+1]+1]-=m-a[i]+a[i+1]-1;
		}
	}
	long long mx=0,cur=0,idx;
	for (int i=1;i<=m;++i)
	{
		cur+=query(i)+ttl[i];
