using namespace std;
const int maxn=1e5+5; 
const int TNF=0x3f3f3f3f; 
int a[maxn],n,m;
bool vis[maxn]; 
struct node
{
	int p,step; 
}; 
int bfs(int x,int y,int c)
{
	int ans=0; 
	memset(vis,false,sizeof(vis));
	queue<node>q;
	node s;
	s.p=x;s.step=0;
	q.push(s);
	while(!q.empty()) 
	{
		node next; 
		s=q.front();
		if(s.p==y)
		{
			ans=s.step;break; 
		} 
		q.pop();
		next=s;
		for(int i=0;i<2;i++)
		{
			if(i==0)	
			{
				next.p=s.p+1;
				next.p%=m; 
				next.step++; 
			} 
			else
			{
				next.p=c;
				next.step++; 
			} 
			if(!vis[next.p]) 
			{
				q.push(next);
				vis[next.p]=true; 
			} 
		} 

	} 

	 return ans; 
} 
int main() 
{
