	{	
		int tmp=0; 
		for(int i=0;i<n-1;i++)
		{
			 tmp+=bfs(a[i],a[i+1],f); 
		}
		ans=ans>tmp?tmp:ans; 
	//	break; 
	} 
	cout<<ans<<endl; 
}

