                ans = min( ans, solve( n, m, lst[i - 1] ) );
            break;
        }

        int mid1 = st + (dr - st) / 3, mid2 = dr - (dr - st) / 3;

        long long C1 = solve( n, m, lst[mid1 - 1] ),
                  C2 = solve( n, m, lst[mid2 - 1] );

        ans = min( ans, min( C1, C2 ) );

        if( C1 < C2 ) dr = mid2;
        else          st = mid1;
    }
    cout << ans;
    return 0;
}

