void add(int a,int b,int r,int l,int k,ll x){
    if(a<=r&&l<=b)seg[k]+=x;
    else if(r<=b&&a<=l){
        add(a,b,r,(r+l-1)/2,k*2+1,x);
        add(a,b,(r+l+1)/2,l,k*2+2,x);
    }
}
void ini(int k,int r,int l){
    if(l-r>0){
        seg[k*2+1]+=seg[k];
        seg[k*2+2]+=seg[k];
        ini(k*2+1,r,(r+l-1)/2);
        ini(k*2+2,(r+l+1)/2,l);
    }
}
