	for (int i = 0; i < n; i++) {
		cin >> a[i];
		pos[a[i]].push_back(i);
	}

	ll ans = 0, cur = 0;
	int shortcut = 0;
	for (int i = 1; i < n; i++) {
		if (((m + a[i] - a[i - 1]) % m) >= ((m + a[i] - 1) % m) + 1 && a[i] != 1) {
			//次のステップでshortcutから外れないものの個数を数え上げる。
			shortcut++;
			ans += ((m + a[i] - 1) % m) + 1;
		}
		else ans += ((m + a[i] - a[i - 1]) % m);
	}
	cur = ans;
	for (int x = 2; x <= m; x++) {
		cur -= shortcut;
		ans = min(ans, cur);

		//終点がxのものは、shortcutから外して固定の移動距離になる。
		for (int i = 0; i < pos[x].size(); i++) {
			int idx = pos[x][i];
			if (idx != 0) {//0番目ならば、終点にはなりえない。
