typedef long long LL;
const int MAX_N = 1e5 + 6;

struct Node {
    Node *lc,*rc;
    LL sum,tag;
    Node():lc(NULL),rc(NULL),sum(0),tag(0){};
    void pull() {
        sum = lc->sum + rc->sum;
    }
};

void push(Node* node,int L,int R) {
    if (L==R) node->tag =0 ;
    if (node->tag ==0) return;
    int mid=(L+R)>>1;
    node->lc->tag += node->tag;
    node->rc->tag += node->tag;
    node->lc->sum += node->tag * (mid-L+1);
    node->rc->sum += node->tag * (R-mid);
    node->tag = 0;
    return;
}

Node* Build(int L,int R) {
    Node* node = new Node();
    if (L==R) return node;
    int mid=(L+R)>>1;
    node->lc=Build(L,mid);
    node->rc=Build(mid+1,R);
    return node;
}

void modify(Node* node,int L,int R,int l,int r,LL val) {
    if (l>R || L>r) return;
    else if (l<=L && R<=r) {
        node->tag += val;
        node->sum += (R-L+1)*val;
        return;
    }
    push(node,L,R);
    int mid=(L+R)>>1;
    modify(node->lc,L,mid,l,r,val);
    modify(node->rc,mid+1,R,l,r,val);
    node->pull();
    return;
}

LL cha[MAX_N];
LL val[MAX_N];

void visit(Node* node,int L,int R) {
    if (L==R) {
        cha[L] = node->sum;
        return;
    }
    push(node,L,R);
    int mid=(L+R)>>1;
    visit(node->lc,L,mid);
    visit(node->rc,mid+1,R);
    return;
}

