void forward() {
	for(int i = 2; i <= n; i++) {
		if(a[i-1] <= a[i]) {
			sum[a[i-1] + 1] += a[i-1];
			sum[a[i] + 1] -= a[i-1];
			cnt[a[i-1] + 1] += 1;
			cnt[a[i] + 1] -= 1;
		}
	}
	long long cursum = 0;
	int cunt = 0;
	for(int i = 1; i <= m; i++) {
		cursum += sum[i];
		cunt += cnt[i];
		P[i] = 1LL * i * cunt - cursum;
		P[i] -= cunt;
	}
}
void backward() {
	memset(sum, 0, sizeof sum);
	memset(cnt, 0, sizeof cnt);

	for(int i = 2; i <= n; i++) {
		if(a[i-1] > a[i]) {
			sum[a[i]] += m - a[i-1];
			cnt[a[i]] += 1;
		}
	}
	long long cursum = 0;
	int cunt = 0;
	for(int i = m; i >= 1; i--) {
		cursum += sum[i];
		cunt += cnt[i];
		Q[i] = 1LL * i * cunt + cursum;
		Q[i] -= cunt;
	}

	memset(sum, 0, sizeof sum);
	memset(cnt, 0, sizeof cnt);
	for(int i = 2; i <= n; i++) {
		if(a[i-1] > a[i]) {
			sum[a[i - 1] + 1] += a[i - 1];
			cnt[a[i - 1] + 1] += 1;
		}
	}
	cursum = 0;
	cunt = 0;
	for(int i = 1; i <= m; i++) {
		cursum += sum[i];
		cunt += cnt[i];
		R[i] = 1LL * i * cunt - cursum;
		R[i] -= cunt;
	}
}
