        if (first) first = 0;
        else printf("\n");

        vector<int> a(n);
        for (int i = 0; i < n; i++) {
            scanf("%d", &a[i]);
            a[i]--;
        }

        vector<vector<ll> > b(3, vector<ll>(m));

        for (int i = 0; i < n - 1; i++) {
            int x = a[i];
            int y = a[i + 1];

            int len;
            if (x < y) len = y - x;
            else len = (m - x) + y;

            b[1][0] += len;
            if (x < y) {
                if (x + 1 < y) {
                    b[2][x + 2]--;
                    if (y < m - 1) {
                        b[2][y + 1]++;
                        b[1][y + 1] += len - 1;
                        b[0][y + 1] += 1LL * (len - 1) * len / 2;
                    }
                }
            } else {
                int tail = m - (x + 2);
                if (x + 2 < m) {
                    b[2][x + 2]--;
                }
                int st = tail == -1 ? 1 : 0;
                tail = max(0, tail);

                b[1][st] -= tail;
                b[2][st]--;

                b[2][y + 1]++;
                b[1][y + 1] += len - 1;
                b[0][y + 1] += 1LL * (len - 1) * len / 2;
            }
        }
        for (int i = 2; i; i--) {
            for (int j = 0; j < m; j++) {
                if (j) b[i][j] += b[i][j - 1];
                b[i - 1][j] += b[i][j];
            }
        }
        ll mn = 1e18;
        for (int i = 0; i < m; i++) mn = min(mn, b[0][i]);
        cout << mn << endl;
    }

#ifdef HOME
    cerr << clock() / (double)CLOCKS_PER_SEC << endl;
#endif
    return 0;
}

