            sum+=a[i]-a[i-1];
            b[a[i-1]+1]+=a[i-1]+1;
            b[a[i]+1]-=a[i-1]+1;
            c[a[i-1]+1]++;
            c[a[i]+1]--;
        } else {
            sum += m-a[i-1]+a[i];
            b[a[i-1]+1] += a[i-1]+1;
            b[a[i]+1] += m-a[i-1]-1;
            b[1] -= m-a[i-1]-1;
            c[1]++;
            c[a[i-1]+1]++;
            c[a[i]+1]--;
        }
    }
    for(int i=1; i<=m; ++i) {
        c[i]+=c[i-1];
        b[i]+=b[i-1];
    }
    long long  ma=0;
    for(int x=1; x<=m; ++x) {
        if(c[x]) {
            ma=max(ma,(long long )(x*c[x]-b[x]));
        }
    }
    printf("%lld\n",sum-ma);
    return 0;
