const int N = 1e5 + 11;
#define LL long long
LL ans, now;
int n, m, a[N], cha[N];
int tag[N], add, tong[N];
int main(){
    //freopen("arc077e.in", "r", stdin);
    //freopen("arc077e.out", "w", stdout);
    cin>>n>>m;
    for(int i = 1;i <= n; i++){
        scanf("%d", &a[i]);
        if(i > 1){
            cha[i] = a[i] - a[i-1] + (a[i] - a[i-1] < 0 ? m : 0);
            int x = (a[i] + 2 - cha[i] + m) % m;
            if(x == 0)x += m;
            int y = (a[i] + 1) % m;
            if(y == 0)y += m;
            if(a[i] < cha[i] - 1){
                tag[1]--;
                tong[1] += a[i] - cha[i];
                if(y > 1){
                    tong[y] += cha[i];
                    tag[y]++;
                }
                tong[x]--;
                tag[x]--;
            }
            else{
                tong[x]--;
                tag[x]--;
                if(y > x)tong[y] += cha[i], tag[y]++;
            }
        }
        ans += cha[i];
    }
    now = ans;
    for(int i = 1;i <= m; i++){
        now += add + tong[i];
        add += tag[i];
        ans = min(ans, now);
    }
    cout<<ans<<endl;
    return 0;
}

