      return s.cost;
    }
    if(mincost[s.idx][s.now] < s.cost) continue;
    for(edge& e : graph[s.now]) {
      int cost = e.cost + s.cost;
      int idx = (e.to == a[s.idx] ? s.idx+1 : s.idx);
      if(cost < mincost[idx][e.to]) {
	que.emplace(e.to, cost, idx);
	mincost[idx][e.to] = cost;
      }
    }
  }

}

