template<typename T>
class BIT {
	int n;
	T* bit;
public:
	BIT(int n) :n(n) {
		bit = new T[n];
		fill(bit, bit + n, T());
	}
	void add(int a, T x) {
		while (a < n) {
			bit[a] += x;
			a += a & -a;
		}
	}
	T query(int a) {
		int cnt = 0;
		while (a > 0) {
			cnt += bit[a];
			a -= a & -a;
		}
		return cnt;
	}
};
template<typename T>
class Matrix {
	int n;
	T zero, e;
	vector<vector<T>> vec;
	void letmeasure() {
		rep(i, n) {
			rep(j, n) {
				if (i != j)vec[i][j] = zero;
				else vec[i][j] = e;
			}
		}
	}
public:
	Matrix(int n, T zero, T e) :n(n), zero(zero), e(e) {
		vec.resize(n, vector<T>(n));
	}
	Matrix(int n, T zero, T e, vector<int> vec) :n(n), zero(zero), e(e) {
		if (vec.size() != n * n) {
			cerr << "Invalid construct of matrix" << endl;
			exit(1);
		}
		this->vec.resize(n, vector<T>(n));
		rep(i, n) {
			rep(j, n)this->vec[i][j] = vec[i * n + j];
		}
	}
	T& operator[](int a) {
		return vec[a / n][a % n];
	}
	unsigned int size() { return n; }
	Matrix operator*(const Matrix a) {
		if (this->n != a.n) {
			cerr << "Invalid multiply of matrix" << endl;
			exit(1);
		}
		vector<T> memo(n);
		rep(i, n) {
			rep(j, n) {
				rep(k, n) {
					memo[j] += vec[i][k] * a.vec[k][j];
				}
			}
			vec[i] = memo;
			memo.clear();
			memo.resize(n);
		}
		return *this;
	}
	static Matrix<T> measure(int n, T zero, T e) {
		Matrix<T> res(n, zero, e);
		res.letmeasure();
		return res;
	}
};

class mycomplex {
	double realvalue, imagvalue;
public:
	mycomplex() :realvalue(0), imagvalue(0) {}
	mycomplex(double realvalue, double imagvalue) : realvalue(realvalue), imagvalue(imagvalue) {}
	mycomplex(double realvalue) : realvalue(realvalue), imagvalue(0) {}
	mycomplex(complex<double> c) :realvalue(c.real()), imagvalue(c.imag()) {}
	mycomplex(const mycomplex& rhs) :realvalue(rhs.realvalue), imagvalue(rhs.imagvalue) {}
	double real()const { return this->realvalue; }
	double imag()const { return this->imagvalue; }
	double abs() { return hypot(realvalue, imagvalue); }
	mycomplex& operator=(const mycomplex& obj) {
		if (this != &obj) {
			this->realvalue = obj.realvalue;
			this->imagvalue = obj.imagvalue;
		}
		return *this;
	}
	mycomplex& operator=(mycomplex&& obj)noexcept {
		if (this != &obj) {
			this->realvalue = exchange(obj.realvalue, 0);
			this->imagvalue = exchange(obj.imagvalue, 0);
		}
		return *this;
	}
	mycomplex& operator+=(const mycomplex& rhs) {
		this->realvalue += rhs.realvalue;
		this->imagvalue += rhs.imagvalue;
		return *this;
	}
	friend mycomplex operator+(mycomplex lhs, const mycomplex& rhs) {
		lhs += rhs;
		return lhs;
	}
	mycomplex& operator-=(const mycomplex& rhs) {
		this->realvalue -= rhs.realvalue;
		this->imagvalue -= rhs.imagvalue;
		return *this;
	}
	mycomplex& operator-=(const double& rhs) {
		this->realvalue -= rhs;
		return *this;
	}
	friend mycomplex operator-(mycomplex lhs, const mycomplex& rhs) {
		lhs -= rhs;
		return lhs;
	}
	mycomplex& operator*=(const mycomplex& rhs) {
		double pastreal = this->realvalue;
		this->realvalue = this->realvalue * rhs.realvalue - this->imagvalue * rhs.imagvalue;
		this->imagvalue = pastreal * rhs.imagvalue + rhs.realvalue * this->imagvalue;
		return *this;
	}
	friend mycomplex operator*(mycomplex lhs, const mycomplex& rhs) {
		lhs *= rhs;
		return lhs;
	}
	mycomplex& operator/=(const mycomplex& rhs) {
		*this *= mycomplex(rhs.real(), -rhs.imag());
		double dnm = rhs.real() * rhs.real() - rhs.imag() * rhs.imag();
		this->realvalue /= dnm;
		this->imagvalue /= dnm;
		return *this;
	}
	friend mycomplex operator/(mycomplex lhs, const mycomplex& rhs) {
		lhs /= rhs;
		return lhs;
	}
};
class FastFourierTransform {
private:
	static void dft(vector<mycomplex>& func, int inverse) {
		int sz = func.size();
		if (sz == 1)return;
		vector<mycomplex> veca, vecb;
		rep(i, sz / 2) {
			veca.push_back(func[2 * i]);
			vecb.push_back(func[2 * i + 1]);
		}
		dft(veca, inverse); dft(vecb, inverse);
		mycomplex now = 1, zeta = polar(1.0, inverse * 2.0 * acos(-1) / sz);
		rep(i, sz) {
			func[i] = veca[i % (sz / 2)] + now * vecb[i % (sz / 2)];
			now *= zeta;
		}
	}
public:
	template<typename T>
	static vector<double> multiply(vector<T> f, vector<T> g) {
		vector<mycomplex> nf, ng;
		int sz = 1;
		while (sz < f.size() + g.size())sz *= 2;
		nf.resize(sz); ng.resize(sz);
		rep(i, f.size()) {
			nf[i] = f[i];
			ng[i] = g[i];
		}
		dft(nf, 1);
		dft(ng, 1);
		rep(i, sz)nf[i] *= ng[i];
		dft(nf, -1);
		vector<double> res;
		rep(i, sz)res.push_back(nf[i].real() / sz);
		return res;
	}
};
int n, m, a[100010];
signed main() {
	cin >> n >> m;
	rep(i, n) {
		cin >> a[i];
		a[i]--;
	}
	RAQRMaQ<int> st(m);
	rep(i, n - 1) {
		if (a[i] > a[i + 1])a[i + 1] += m;
		if (a[i + 1] - a[i] == 1) {
			if (a[i + 1] >= m)a[i + 1] -= m;
			continue;
		}
		if (a[i + 1] < m) {
			st.update(a[i] + 2, a[i + 1] + 1, 1);
			if (a[i + 1] != m - 1) {
				st.update(a[i + 1] + 1, a[i + 1] + 2, -(a[i + 1] - a[i] - 1));
			}
		}
		else {
			if (a[i] + 2 < m) {
				st.update(a[i] + 2, m, 1);
				st.update(0, a[i + 1] + 1 - m, 1);
				st.update(0, 1, m - 1 - a[i] - 1);
				if (a[i + 1] != m + m - 1) {
					st.update(a[i + 1] - m + 1, a[i + 1] - m + 2, -(a[i + 1] - a[i] - 1));
				}
			}
			else {
				st.update(a[i] + 2 - m, a[i + 1] + 1 - m, 1);
				if (a[i + 1] != m + m - 1) {
					st.update(a[i + 1] - m + 1, a[i + 1] - m + 2, -(a[i + 1] - a[i] - 1));
				}
			}
		}
		if (a[i + 1] >= m)a[i + 1] -= m;
	}
	REP(i, m - 1)st.update(i, i + 1, st.query(i - 1, i));
	int ans = 0;
	rep(i, n - 1) {
		if (a[i] < a[i + 1])ans += a[i + 1] - a[i];
		else ans += a[i + 1] + m - a[i];
	}
	cout << ans - st.query(0, m) << endl;
	return 0;
}

#include <bits/stdc++.h>
using namespace std;

typedef long long lint;
typedef pair<int, int> pii;
typedef priority_queue<int, vector<int>, greater<int>> PQ;

const int INF = 2e9;
const int MOD = 1e9+7;
const int MAX = 1e5+10;
const lint LNF = 2e18;

int n, m, A[MAX];
lint now, ans=LNF;
lint P[MAX], Q[MAX];

int dist(int a, int b){
	return (b>=a) ? b-a : b+m-a;
}

int main(){
	ios::sync_with_stdio(0); cin.tie(0);

	cin>>n>>m;
	for(int i=1; i<=n; i++) cin>>A[i];

	for(int i=2; i<=n; i++){
		now += min(dist(A[i-1], A[i]), 1+dist(1, A[i]));
	}

	for(int i=2; i<=n; i++){
		int l = A[i-1]%m+1, r = A[i];
		P[l]--, P[r]++;
		if(l>r) P[m]++, P[1]--;
		Q[r] += dist(A[i-1], A[i])-1;
	}

	lint sum1=0, sum2=0;
	for(int i=1; i<=m; i++){
		now += sum1 + sum2; sum2=0;
		ans = min(ans, now);
		sum1+=P[i], sum2+=Q[i];
	}

	cout<<ans<<'\n';

	return 0;
}

