	for(auto v : p)
	{
		if(v.second > 0) 
		{
			++cnt;
			tmp += v.first;
		}
		else
		{
			ans = max(ans, 1ll * (v.first - 1) * cnt - tmp);
			tmp -= b[-(v.second + 1)].first;
			--cnt;
		}

