int main() {
    //freopen(".in", "r", stdin);
    int n,m;
    scanf("%d%d",&n,&m);
    for(int i=1;i<=n;i++)scanf("%lld",&num[i]),edge[num[i]].push_back(i);
    ll mmax=0;
    num[0]=num[1];
    for(int i=1;i<=n;i++){
        if(ss.size()==0){
            ss.push(num[i]);
            sum[1]+=1;
        }
        else if(num[i]<ss.top()){
            sum[ss.top()+1]--;
            mmax=max(mmax,ss.top()+1);
            while(ss.size())ss.pop();
            ss.push(num[i]);
            sum[1]+=1;
        }
        else ss.push(num[i]);
    }
    /*
    4 6
    1 5 1 4
    i = 1 cor[i] = 2
    i = 2 cor[i] = 2
    i = 3 cor[i] = 2
    i = 4 cor[i] = 2
    i = 5 cor[i] = 1
    i = 6 cor[i] = 0
    8
    i = 2 cnt = 11
    i = 3 cnt = 9
    i = 4 cnt = 7
    i = 5 cnt = 9
    i = 6 cnt = 13
    7
    */
    sum[ss.top()+1]--;
    mmax=max(mmax,ss.top()+1);
    while(ss.size())ss.pop();
    for(int i=1;i<=mmax;i++){
        cor[i]=cor[i-1]+sum[i];
       // dbg2(i,cor[i]);
    }
    ll cnt=0;
    for(int i=2;i<=n;i++){
        if(num[i]>=num[i-1])cnt+=num[i]-num[i-1];
        else cnt+=num[i];
    }
    ll ans=cnt;
    for(int i=2;i<=m;i++)   {
        cnt-=cor[i-1];
        int sz=edge[i-1].size();
        cnt+=sz;
        for(int j=0;j<edge[i-1].size();j++){
            ll loc=edge[i-1][j];
            if(num[loc-1]>num[loc]) cnt+=m-num[loc-1]+num[loc];
            else if(num[loc]-num[loc-1]-1>=0) cnt+=num[loc]-num[loc-1]-1;
        }
        ans=min(ans,cnt);
    }
    printf("%lld\n",ans);
    return 0;
}

