ll n, m, a[100000], r[100000], sum, msum, mcounter, ans;

int main() {
  scanf("%lld%lld", &n, &m);
  for (ll i = 0; i < n; i++) scanf("%lld", &a[i]), a[i]--;
  ll now = a[0];
  for (ll i = 1; i < n; i++) {
    ll plus = a[i] - a[i-1];
    if (a[i-1] > a[i]) plus += m, msum += m-a[i-1]-1, mcounter++;
    sum += plus, r[a[i]] += plus - 1;
  }
  ans = sum - msum;
  for (ll i = 1; i < m; i++) {
    if (a[n-1] == i-1) mcounter--;
    msum += mcounter - r[i-1];
    if (a[0] == i-2) mcounter++;
    ans = min(ans, sum - msum);
  }
  printf("%lld\n", ans);
}

