const LL MOD = 1e9+7;
const auto INF  = 0x3f3f3f3f;
const int N = 1e5+5;

int a[N], n, m;

int get(int x, int y) {
    int ans = 0;
    if(x <= y) {
        ans = y - x;
    } else
        ans = m - x + y;
    return ans;
}

int solve(int x) {
    int ans = 0;
    for(int i=2; i<=n; i++) {
        int temp = get(a[i-1], a[i]);
        temp = min(temp,1 + get(x, a[i]));
        ans += temp;
    }
    return ans;
}

int main() {
    scanf("%d%d", &n, &m);
    for(int i=1; i<=n; i++) {
        scanf("%d", &a[i]);
    }
    int L = 1, R = m;
    int answer = INF;
    while(L <= R) {
        int mid = (L+R)>>1;
        int ans = solve(mid);
//        if(ans < answer) {
//            printf("ans=%d answer=%d mid=%d\n", ans, answer, mid);
//        }
        answer = min(answer, ans);
        if(mid == 1) {
            int ansL = solve(mid+1);
            if(ansL > ans)
                break;
            else
                L = mid+1;
        } else if(mid == m) {
            int ansL = solve(mid-1);
            if(ansL > ans)
                break;
            else
                R = mid-1;
        } else {
            int ansL = solve(mid-1);
            if(ansL < ans)
                R = mid-1;
            else
                L = mid+1;
        }
    }
    printf("%d\n", answer);
}

