int n, m;
vector<LL>a;

vector<LL>accum(const vector<LL>&imos)
{
	vector<LL>ret;
	LL tot = 0;
	for (int i = 0; i < m; ++i)
	{
		tot += imos[i];
		ret.push_back(tot);
	}
	return ret;
}

int main(void)
{
	cin >> n >> m;
	for (int i = 0; i < n; ++i)
	{
		LL aa;
		cin >> aa;
		--aa;
		a.push_back(aa);
	}
	vector<LL>imos(m + 2, 0);//最後の2つの要素は番兵＝処理を行わない
	for (int i = 1; i < n; ++i)
	{
		int S = a[i - 1];
		int T = a[i];
		int dif = T - S;
		if (dif < 0)
		{
			dif += m;
			if (dif == 1)
			{
				imos[0]++;
				continue;
			}
			imos[0] += (T + 1);
			imos[1] -= (T + 2);
			imos[T + 1] += dif;
			imos[T + 2] -= (dif - 1);
			imos[S + 2]--;
		}
		else
		{
			if (dif == 1)
			{
				imos[0]++;
				continue;
			}
			imos[0] += dif;
			imos[1] -= dif;
			imos[S + 2]--;
			imos[T + 1] += dif;
			imos[T + 2] -= (dif - 1);
		}
	}
	imos = accum(imos);
	imos = accum(imos);
	LL ans = LLONG_MAX;
	for (int i = 0; i < m; ++i)
	{
		ans = min(ans, imos[i]);
	}
	cout << ans << endl;
	return 0;
}

