int main() {
    int n, m;
    scanf("%d%d", &n, &m);
    vector<int> a(n);
    for (int i = 0; i < n; i++) {
        scanf("%d", &a[i]);
    }
    vector<pair<int, pair<int, int>>> evs;
    long long tot = 0;
    for (int i = 0; i + 1 < n; i++) {
        if (a[i] < a[i + 1]) {
            evs.push_back({a[i], {1, 0}});
            evs.push_back({a[i + 1], {-1, a[i + 1] - a[i]}});
        } else {
            evs.push_back({a[i], {1, 0}});
            evs.push_back({m + 1, {-1, m + 1 - a[i]}});
            evs.push_back({1, {1, 0}});
            evs.push_back({a[i + 1], {-1, a[i + 1] - 1}});
        }
        tot += (a[i + 1] - a[i] + m) % m;
    }
    sort(evs.begin(), evs.end());
    int cnt = 0;
    long long dst = 0;
    long long mx = 0;
    for (int i = 0; i < evs.size(); i++) {
        if (i > 0) {
            dst += cnt * (evs[i].first - evs[i - 1].first);
        }
        mx = max(mx, dst - cnt);
        cnt += evs[i].second.first;
        if (evs[i].second.first == -1) {
            dst -= evs[i].second.second;
        }
    }

    cout << tot - mx << endl;

    return 0;
}

