vi removal[(int)3e5];
signed main(){
    ios_base::sync_with_stdio(false);cin.tie(NULL);

    int n, m;cin >> n >> m;
    vi vals(n);
    FOR(i, n)cin >> vals[i];
    int cost = 0;
    vi updates(2*m);
    int begin = 0;
    FOR(i, n - 1){

        int nex = vals[i+1];
        int cur = vals[i];
        if(cur <= nex){
            if(nex- cur == 0)continue;
            cost += nex -cur;
            updates[cur+2]++;
            updates[nex + 1]--;
            removal[nex +1].pb(nex- cur- 1);
        }else{
            cost += (m - nex) + (cur - 1) + 1; 
            // no need to remove this last update
            // it will last till the end
            updates[cur+2]++;
            updates[1]++;
            begin += (m - nex) - 1;
            updates[cur + 1]--;
            removal[cur + 1].pb((m - nex) + (cur - 1) +1 -1);
        }

    }
    begin = -begin;
    int points = 0;
    int mn = 0;
    FOR1(i, m){
        points += updates[i]; 
        for(int r: removal[i])begin += r;
        begin -= points;
        mn = min(begin, mn);
    }
    cout<< cost +  mn << endl;
}

