const int DIM = 1e5 + 5;

int arr[DIM];

inline int f( int x, int y, int m ) {
    if( x <= y ) return y - x;
    else         return m - x + y;
}

inline long long solve( int n, int m, int k ) {
    long long cst = 0;

    for( int i = 2; i <= n; i ++ ) {
        cst += min( f( arr[i - 1], arr[i], m ),
                    f( k, arr[i], m ) + 1 );
    }

    return cst;
}

int main() {

    int n, m;
    cin >> n >> m;

    for( int i = 1; i <= n; i ++ )
        cin >> arr[i];
    sort( arr + 1, arr + n + 1 );

    long long ans = numeric_limits<long long> :: max() / 2;
    for( int st = 1, dr = n; ; ){
        if( dr - st <= n ) {
            for( int i = st; i <= dr; i ++ )
                ans = min( ans, solve( n, m, arr[i] ) );
            break;
        }

        int mid1 = st + (dr - st) / 3, mid2 = dr - (dr - st) / 3;

        long long C1 = solve( n, m, arr[mid1] ),
                  C2 = solve( n, m, arr[mid2] );

        ans = min( ans, min( C1, C2 ) );

        if( C1 < C2 ) dr = mid2;
        else          st = mid1;
    }
    cout << ans;
    return 0;
}

