void solve(long long n, long long m, std::vector<long long> a){
    rep(i,n)a[i]--;
    vl sum1(2*m+5),sumM(2*m+5);
    rep(i,n-1){
        ll from=a[i],to=a[i+1];
        if(a[i]>a[i+1])to+=m;
        sum1[from+2]++;
        sum1[to+1]--;
        sumM[to+1]-=to-from-1;
    }

    rep(i,2*m)sum1[i+1]+=sum1[i];
    rep(i,2*m)sum1[i]+=sumM[i];
    rep(i,2*m)sum1[i+1]+=sum1[i];

