#define MAX_N 100005

ll n, m;
ll A[MAX_N];

ll process(ll fav_pos) {
    ll ret = 0;
    for(int i = 1; i < n; ++i) {
        ll cur = A[i - 1];
        ll nofav = 0;
        ll yesfav = 1;
        if(cur == A[i]) { continue; }
        // お気にを使わない場合
        if(cur < A[i]) { nofav = A[i] - cur; }
        else { nofav = m - cur + A[i]; }
        // お気にを使う場合
        cur = fav_pos;
        if(cur == A[i]) {}
        else if(cur < A[i]) { yesfav += A[i] - cur; }
        else { yesfav += m - cur + A[i]; }
        // 使う場合と使わない場合の小さいほうを加算
        ret += min(yesfav, nofav);
    }
    return ret;
}

int main()
{
    cin >> n >> m;
    REP(i, n) {
        cin >> A[i];
    }

    ll middle = m / 2 + 1;
    while(1) {
        ll left = (middle > 1) ? middle - 1 : 1;
        ll right = (middle < m) ? middle + 1 : m;
        //printf("pos l: %lld mid: %lld r: %lld\n", left, middle, right);
        // それぞれに何手かかるか計算
        ll middle_ret = process(middle);
        ll left_ret = process(left);
        ll right_ret = process(right);
        //printf("ret l: %lld mid: %lld r: %lld\n", left_ret, middle_ret, right_ret);
        ll next_middle = 1;
        if(middle_ret <= left_ret && middle_ret <= right_ret) {
            printf("%lld\n", middle_ret);
            return 0;
        }
        else if(right_ret < left_ret && right_ret < middle_ret) {
            next_middle = (m - right) / 2 + 1 + right;
            if(next_middle > m) { next_middle = m; }
        }
        else if(left_ret < right_ret && left_ret < middle_ret) {
            next_middle = left / 2 + 1;
            if(next_middle < 1) { next_middle = 1; }
        }
        if(next_middle == middle) {
            ll ans = min(middle_ret, min(right_ret, left_ret));
            printf("%lld\n", ans);
            return 0;
        }
        middle = next_middle;
        //printf("next: %lld\n", middle);
    }
    assert(true);
    return 0;
}

