long long lazy[5*N], T[5*N], P[5*N], Ans[N];
void upd(int n,int b,int e,int i,int j,double k,double s)
{

    if(lazy[n]) {
        if(b!=e) {
            lazy[lc] = 1;
            lazy[rc] = 1;
            T[lc] += T[n];
            T[rc] += T[n];
            P[lc] += P[n];
            P[rc] += P[n];

            lazy[n] = 0;
            T[n] = 0;
            P[n] = 0;
        }

    }
    if(b>j||e<i)return;
    if(b>=i&&e<=j){
        T[n] += k;
        P[n] += s;
        lazy[n] = 1;
        return;
    }
    int mid = (b+e)/2;
    upd(lc,b,mid,i,j,k,s);
    upd(rc,mid+1,e,i,j,k,s);


}


void Trv(int n,int b,int e)
{
    if(lazy[n]) {
        if(b!=e) {
            lazy[lc] = 1;
            lazy[rc] = 1;
            T[lc] += T[n];
            T[rc] += T[n];
            P[lc] += P[n];
            P[rc] += P[n];

            lazy[n] = 0;
            T[n] = 0;
            P[n] = 0;
        }

    }
    if(b==e) {
        Ans[b] = P[n] + b * T[n];
        return;
    }
    int mid = (b+e)/2;
    Trv(lc,b,mid);
    Trv(rc,mid+1,e);
}
