using i64=int64_t;

//10 1 2 3 4 5 6 7 8 9

vector<i64> unroll(i64 m,vector<i64> a){
    vector<i64> res={a.front()};

    i64 s=a.front();
    rep(i,1,a.size()){
        if(a[i]>a[i-1]){
            res.push_back(s+a[i]-a[i-1]);
            s+=a[i]-a[i-1];
        }else{
            res.push_back(s+m-a[i-1]+a[i]);
            s+=m-a[i-1]+a[i];
        }
    }
    return res;
}

void solve(){
    i64 n,m;
    cin >> n >> m;
    vector<i64> a(n);
    rep(i,0,n){
        cin >> a[i];
        --a[i];
    }

    auto a_=unroll(m,a);

    vector<bool> f(a_.back()+3);
    rep(i,0,a_.size()-1) f[a_[i]+2]=true;

    vector<i64> b(a_.back()+1),c(m);
    for(i64 i=a_.front()+2; i<=a_.back(); ++i){
        if(f[i]) b[i]=1;
        else if(b[i-1] and !f[i+1]) b[i]=b[i-1]+1;
        c[i%m]+=b[i];
    }

    i64 s=0;
    rep(i,0,a.size()-1){
        if(a[i]<a[i+1]) s+=a[i+1]-a[i];
        else s+=m-a[i]+a[i+1];
    }

    i64 ans=s;
    rep(i,0,m) ans=min(ans,s-c[i]);

    cout << ans << endl;
}

int main(){
    std::cin.tie(0);
    std::ios::sync_with_stdio(false);
    cout.setf(ios::fixed);
    cout.precision(16);
    solve();
    return 0;
}

