vector<LL>accum(const vector<LL>&imos)
{
	vector<LL>ret;
	LL tot = 0;
	for (int i = 0; i < imos.size(); ++i)
	{
		tot += imos[i];
		ret.push_back(tot);
	}
	return ret;
}

int main(void)
{
