	for (int i = 1; i < n; ++i)
	{
		LL S = a[i - 1];
		LL T = a[i];
		LL dif = T - S;
		if (dif < 0)
		{
			dif += m;
			if (dif == 1)
			{
				imos[0]++;
				continue;
			}
			imos[0] += (T + 1);
			imos[1] -= (T + 2);
			imos[T + 1] += dif;
			imos[T + 2] -= (dif - 1);
			imos[S + 2]--;
		}
		else
		{
			if (dif == 1)
			{
				imos[0]++;
				continue;
			}
			imos[0] += dif;
			imos[1] -= dif;
			imos[S + 2]--;
			imos[T + 1] += dif;
			imos[T + 2] -= (dif - 1);
		}
	}
	imos = accum(imos);
	imos = accum(imos);
