   s1[a] += val; s1[b_inc +1] -= val;
}
void add_region2(int a, int b_inc, int val, int one=1){
   if (a > b_inc) return;
   cnt[a] +=one; cnt[b_inc +1] -= one;
   add_region(a, b_inc, val*one);
}
