            add_region(1, ar[i], ar[i + 1] - ar[i]);
            add_region(ar[i+1] + 1, m, ar[i + 1] - ar[i]);
            //good ar[i]+1 .. ar[i+1]
            add_region2(ar[i]+1, ar[i+1], ar[i + 1] + 1);
         }else {
