	rep(i, n) --a[i];


	// O(nm)なら余裕

	// すげー
	// x = i のときがわかったら x = i + 1 のときも簡単に計算できる
	ll tmp = 0;
	rep(i, n - 1) {
		int normal = (a[i + 1] - a[i] + m) % m;
		int warp = (a[i + 1] - 0 + m) % m + 1;
		tmp += min(normal, warp);
	}

	// これをもとに x = 1, 2, 3, ... のときも求める
	// imos法でxがa[i]とa[i + 1]の間(両端覗く)にあるか求める
	vector<int> num(m, 0);
	rep(i, n - 1) {
		// 隣り合っているときはなにもいない これいらなそう
		if ((a[i + 1] - a[i] + m) % m == 1) continue;

		int from = (a[i] + 1) % m;
		int to = a[i + 1];

		if (to > from) {
			// 0をまたがっていないとき
			++num[from];
			--num[to];
		}
		else {
			++num[0];
			++num[from];
			--num[to];
		}
	}

	size_t s = (a[0] + 1) % m;
	CCout(num);
	rep(i, m - 1) {
		num[i + 1] += num[i];
	}
	vector<vector<int>> point(m, vector<int>());
	Rep(i, 1, n) {
		point[a[i]].emplace_back(i); // インデックスを保存
	}

	CCout(num);

	ll ans = tmp;

	Rep(x, 1, m) {
		ll tmp_ans = tmp;
		rep(i, point[x - 1].size()) {
			// x - 1 と目的地が被っていたインデックス
			// ワープ使わんほうがはやくなる
			int j = point[x - 1][i];
			tmp_ans += (a[j] - a[j - 1] + m) % m - 1;
		}
		// xがa[i]とa[i + 1]の間にある分だけ引く
		tmp_ans -= num[x - 1];

		cerr << x << " " << tmp_ans << endl;
		chmin(ans, tmp_ans);
		tmp = tmp_ans;
	}

	Cout(ans);

	// 神！ きたでしょ

	return 0;
}

