template<typename T> class BIT {
   private:
      vector<T> bit;
      int len;
   public:
      BIT(int n) : len(n+1), bit(n+1) {}
      void add(int i, T x) {
         i += 1;
         while (i < len) {
            bit[i] += x;
            i += i & -i;
         }
      }
      T sum(int i) {
         i += 1;
         T s = 0;
         while (i > 0) {
            s += bit[i];
            i -= i & -i;
         }
         return s;
      }
};
template<typename T> class CircleRAQ {
   private:
      BIT<T> bit;
      int mod;
   public:
      CircleRAQ(int n, int mod_n=MOD_N) : bit(n), mod(mod_n) {}
      void add(int l, int r, int x) {
         bit.add(l, x);
         bit.add((r+1) % mod, -x);
         if (l > (r+1) % mod) bit.add(0, x);
      }
      T val(int i) {
         return bit.sum(i);
      }
};

signed main()
{
   int n, m; cin >> n >> m;
   V<int> a(n);
   REP(j, n) {
      cin >> a[j]; a[j]--;
   }
   int mod = m;

   V<int> dist(n-1);
   REP(j, n-1) {
      dist[j] = (((a[j+1] - a[j]) % mod) + mod) % mod;
   }
   DUMP(dist)

   V<int> cost(m);
   REP(j, n-1) {
      int d = (((0 - a[j]) % mod) + mod) % mod;      // distance to the favorite point 0
      if (d == 0 || dist[j] < d) {
         cost[0] += dist[j];
      } else {
         cost[0] += dist[j] - d + 1;
      }
   }

   CircleRAQ<int> diff(m);
   REP(j, n-1) {
      if (dist[j] == 0) continue;

      diff.add(a[j+1], a[j+1], dist[j]-1);
      diff.add((a[j]+1) % mod, (((a[j+1]-1) % mod) + mod) % mod, -1);
   }


   REP(i, m-1) {
      cost[i+1] = cost[i] + diff.val(i);
   }
   DUMP(cost)
   SORT(cost);
   cout << cost[0] << endl;

   return 0;
}

