ll solve(int x){
    ll ret = 0;
    lp(i,2,n){
        if(a[i] >= a[i-1]){
            if(x > a[i-1] and x <= a[i]) ret += 1 + a[i] - x;
            else ret += a[i] - a[i-1];
        }
        else{
            if(x > a[i-1]) ret += 1 + m - x + a[i];
            else if(x <= a[i]) ret += 1 + a[i] - x;
            else ret += m - a[i-1] + a[i];
        }
    }
    return ret;
}

