class BinaryIndexedTree
{
public:
    LL aib[100005];

    void U(int pos, LL val)
    {
        for(; pos <= M; pos += (pos & (-pos)))
            aib[pos] += val;
    }

    void update(int st, int dr, LL val)
    {
        if(st > dr) return;
        U(st, val);
        U(dr + 1, -val);
    }

    LL Q(LL pos)
    {
        LL ans = 0;
        for(; pos > 0; pos -= (pos &(-pos)))
            ans += aib[pos];
        return ans;
    }
}A, B;

int main()
{
