    {
        int p1 = v[u];
        int p2 = v[u + 1];

        if(p1 < p2)
        {
            B.update(1, p1, p2 - p1);

            A.update(p1 + 1, p2, -1);
            B.update(p1 + 1, p2, p2 + 1);

            B.update(p2 + 1, M, p2 - p1);
        }
        else
        {
            A.update(1, p2, -1);
            B.update(1, p2, p2 + 1);

            B.update(p2 + 1, p1, M - p1 + p2);

            A.update(p1 + 1, M, -1);
