const int INF=1e9;
const ll INFF=1e17;
const double EPS=1e-9;
const ll MOD=1e9+7;
const int MAXN=1e5+10;
int tree[4*MAXN],lazy[4*MAXN];
void updateRange(int node,int start,int end,int l,int r,int val){
	if(lazy[node]!=0){
		tree[node]+=(end-start+1)*lazy[node];
		if(start!=end){
			lazy[node*2]+=lazy[node];
			lazy[node*2+1]+=lazy[node];
		}
		lazy[node]=0;
	}
	if(start>end || start>r || end<l)return;
	if(start>=l && end<=r){
		tree[node]+=(end-start+1)*val;
		if(start!=end){
			lazy[node*2]+=val;
			lazy[node*2+1]+=val;
		}
		return;
	}
	int mid=(start+end)/2;
	updateRange(node*2,start,mid,l,r,val);
	updateRange(node*2+1,mid+1,end,l,r,val);
	tree[node]=tree[node*2]+tree[node*2+1];
}
int queryRange(int node,int start,int end,int l,int r){
	if(start>end || start>r || end<l)return 0;
	if(lazy[node]!=0){
		tree[node]+=(end-start+1)*lazy[node];
		if(start!=end){
			lazy[node*2]+=lazy[node];
			lazy[node*2+1]+=lazy[node];
		}
		lazy[node]=0;
	}
	if(start>=l && end<=r)return tree[node];
	int mid=(start+end)/2;
	int p1=queryRange(node*2,start,mid,l,r);
	int p2=queryRange(node*2+1,mid+1,end,l,r);
	return p1+p2;
}
int main(){
	ios_base::sync_with_stdio(false);
	cin.tie(NULL);
	int n,m,a[MAXN],mov[MAXN],ans[MAXN],ans1=INF;
	cin >> n >> m;
	REP(i,n)cin >> a[i];
	REP(i,n)--a[i];
	REP(i,n-1){
		if(a[i]<=a[i+1])updateRange(1,0,m-1,a[i]+2,a[i+1],1);
		else updateRange(1,0,m-1,a[i]+2,m-1,1),updateRange(1,0,m-1,0,a[i+1],1);
	}
	ans[0]=0;
	REP(i,n-1)ans[0]+=min(1+((a[i+1]+m)%m),(a[i+1]+m-a[i])%m);
	ans1=min(ans1,ans[0]);
	FOR(i,1,n){
		if((a[i]+1)<m)mov[a[i]+1]+=((a[i]+m-a[i-1])%m-1);
	}
	FOR(i,1,m){
		ans[i]=ans[i-1];
		ans[i]-=queryRange(1,0,m-1,i,i);
		ans[i]+=mov[i];
		ans1=min(ans1,ans[i]);
	}
	cout << ans1 << '\n';
	return 0;
}

