void solve_inc(LIST Q[], vector<int> X[], vector<int> Y[], int N) {
	int HN = 0;
	ll tot = 0;
	FOR(i, 1, N) tot += Q[i].y - Q[i].x;
	int cnt = 0;
	FOR(i, 1, m) {
		for (auto &idx: X[i - 1]){
			tot -= Q[idx].y - Q[idx].x;
			tot += Q[idx].y;
			cnt++;
		}
		ans[i] += tot - (ll)cnt * (i - 1);
		for (auto &idx:Y[i]){
			tot -= Q[idx].y;
			tot += Q[idx].y - Q[idx].x;
			cnt--;
		}
	}
}
void solve_dec(LIST Q[], vector<int> X[], vector<int> Y[], int N) {
	ll tot = 0, cnt = N;
	FOR(i, 1, N) tot += Q[i].x;
	ans[1] += tot;
	FOR(i, 2, m) {
		for (auto &idx : X[i - 1]) {
			tot -= Q[idx].x;
			tot += (m - Q[idx].y) + Q[idx].x;
			cnt--;
		}
		ans[i] += tot + cnt * (1 - i);
		for (auto &idx : Y[i]) {
			tot -= (m - Q[idx].y) + Q[idx].x;
			tot += m + Q[idx].x;
			cnt++;
		}
	}
}
