#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

ll fastsolve(int n, int m, vector<int> a) {
    vector<vector<ll> > b(3, vector<ll>(m));

    for (int i = 0; i < n - 1; i++) {
        int x = a[i];
        int y = a[i + 1];

        int len;
        if (x < y) len = y - x;
        else len = (m - x) + y;

        b[1][0] += len;
        if (len <= 1) continue;

        if (x < y) {
            b[2][x + 2]--;
        } else {
            if (x + 1 == m) {
                b[2][1]--;
            } else {
                if (x + 2 < m) b[2][x + 2]--;
                b[2][0]--;
                b[1][0] -= m - (x + 2);
            }
        }
        if (y < m - 1) {
            b[2][y + 1]++;
            b[1][y + 1] += len - 1;
        }
    }
    for (int i = 2; i >= 1; i--) {
        for (int j = 0; j < m; j++) {
            if (j) b[i][j] += b[i][j - 1];
            if (i) b[i - 1][j] += b[i][j];
        }
    }
    ll mn = 1e18;
    for (int i = 0; i < m; i++) mn = min(mn, b[0][i]);
    return mn;
}

ll slowsolve(int n, int m, vector<int> a) {
    ll res = 1e18;
    for (int c = 0; c < m; c++) {
        ll cur = 0;
        for (int i = 0; i < n - 1; i++) {
            int x = a[i];
            int y = a[i + 1];
            if (x < y) {
                if (x < c && c <= y) cur += 1 + y - c;
                else cur += y - x;
            } else {
                if (x < c) cur += 1 + m - c + y;
                else if (c <= y) cur += 1 + y - c;
                else cur += m - x + y;
            }
        }
        res = min(res, cur);
    }
    return res;
}

void stress() {
    for (int it = 316;; it++) {
        cerr << it << endl;
        srand(it);

        int n = rand() % 10 + 1;
        int m = rand() % 10 + 2;
        vector<int> a(n);
        a[0] = rand() % m;
        for (int i = 1; i < n; i++) {
            a[i] = a[i - 1];
            while (a[i] == a[i - 1]) a[i] = rand() % m;
        }
        ll ans1 = fastsolve(n, m, a);
        ll ans2 = slowsolve(n, m, a);
        if (ans1 != ans2) {
            cerr << ans1 << " instead of " << ans2 << endl;
            cerr << n << " " << m << endl;
            for (int x : a) cerr << x << " ";
            cerr << endl;
            slowsolve(n, m, a);
            fastsolve(n, m, a);
            exit(0);
        }
    }
}

