inline int f( int x, int y, int m ) {
    if( x <= y ) return y - x;
    else         return m - x + y;
}

inline long long solve( int n, int m, int k ) {
    long long cst = 0;

    for( int i = 2; i <= n; i ++ ) {
        cst += min( f( arr[i - 1], arr[i], m ),
                    f( k, arr[i], m ) + 1 );
    }

    return cst;
}

int main() {

    int n, m;
