int main() {
	int n = ri(), m = ri();
	int a[n];
	for (int i = 0; i < n; i++) a[i] = ri() - 1;

	int64_t base = 0; // always/out
	int64_t cost = 0; // in
	std::set<int> in;
	std::vector<int> diffs;
	std::vector<std::vector<int> > lower(m);
	std::vector<std::vector<int> > upper(m);
	for (int i = 0; i + 1 < n; i++) {
		int diff = (a[i + 1] + m - a[i]) % m;
		diffs.push_back(diff);
		if (diff > 1) {
			int high, low;
			if (a[i + 1] > a[i]) high = (a[i + 1] + 1) % m, low = (a[i] + 1) % m;
			else high = (a[i + 1] + m + 1) % m, low = (a[i] + 1) % m;
			upper[high].push_back(i);
			lower[low].push_back(i);
			assert(high != low);
			// std::cerr << "i:" << i << " (" << low << "," << high << ")" << std::endl;
			if (high < low) in.insert(i), cost += high;
			else base += diff;
		} else base += diff;
	}
	/*
	std::cerr << "cost:" << cost << std::endl;
	std::cerr << "base:" << base << std::endl;*/
	int64_t res = 100000000000;
	for (int i = 0; i < m; i++) {
		for (auto j : upper[i]) assert(in.count(j)), in.erase(j), base += diffs[j];
		cost -= in.size();
		for (auto j : lower[i]) assert(!in.count(j)), in.insert(j), cost += diffs[j] - 1, base -= diffs[j];
		// std::cerr << cost + base + in.size() << std::endl;
		res = std::min<int64_t>(res, cost + base + in.size());
	}
	std::cout << res << std::endl;
	return 0;
}

