    F0R(i,n-1) process(i);
    ll ans = INF;
    FOR(i,1,m+1) {
        cum[i] += cum[i-1];
        cumX[i] += cumX[i-1];
        ans = min(ans,cumX[i]*i+cum[i]);
    }
    cout << ans;
}

