LL N,M;
int a[100005];
LL ans = 0LL;

LL f(LL x) {
	//cout << "------------------" << endl;
	LL ret = 0;
	//debug(x);
	FOR(i, 0, N-1) {
		LL c = LINF, d = LINF;
		c=((2 * M - x + 1 + a[i + 1]) % M)==0?M-1:((2 * M - x + 1 + a[i + 1]) % M);
		d = ((2 * M + a[i + 1] - a[i]) % M);
		ret += min( c  , d );
		//debug(c);
		//debug(d);
	}
	return ret;
}

int main() {
