	FOR(_i, 0, 50) {
		LL z1 = (2*L+R) / 3;
		LL z2 = (L + 2 * R) / 3;
		if (f(z1) < f(z2)) {
			R = z2;
		}
		else {
			L = z1;
		}
	}
	ans = LINF;
	FOR(i, max(0LL, L - 5), min(M, L + 5)) {
		ans = min(ans, f(i));
	}
	//FOR(i, 1, M + 1) {
