using namespace std;
typedef long long LL;
const int maxn = 100005;
const int N = maxn * 60;
vector<int> v[maxn];
int n, m, root1[maxn], root2[maxn], lc[N], rc[N], a[maxn], tot;
LL siz[N], nxt[N], cur[N], qsiz, qnxt, qcur;
void change(int &x, int y, int l, int r, LL c, LL n) {
    x = ++tot;
    lc[x] = lc[y];
    rc[x] = rc[y];
    siz[x] = siz[y] + 1;
    nxt[x] = nxt[y] + n;
    cur[x] = cur[y] + c;
    if (l == r) return;
    else {
        int mid = (l + r) >> 1;
        if (n <= mid) change(lc[x], lc[y], l, mid, c, n);
        else change(rc[x], rc[y], mid + 1, r, c, n);
    }
}
void query(int x, int y, int l, int r, int ll, int rr) {
    if (ll <= l && r <= rr) {
        qsiz += siz[y] - siz[x];
        qnxt += nxt[y] - nxt[x];
        qcur += cur[y] - cur[x];
    }
    else {
        int mid = (l + r) >> 1;
        if (ll <= mid) query(lc[x], lc[y], l, mid, ll, rr);
        if (rr > mid) query(rc[x], rc[y], mid + 1, r, ll, rr);
    }
}
void query(int *root, int l1, int r1, int l2, int r2) {
    qsiz = qnxt = qcur = 0;
    if (l1 > r1 || l2 > r2) return;
    query(root[l1 - 1], root[r1], 1, m, l2, r2);
}
int main() {
    scanf("%d %d", &n, &m);
    for (int i = 1; i <= n; ++i)
        scanf("%d", &a[i]);
    for (int i = 1; i < n; ++i)
        v[a[i]].push_back(a[i+1]);
    for (int i = 1; i <= m; ++i) {
        root1[i] = root1[i-1];
        root2[i] = root2[i-1];
        for (auto &x : v[i]) {
            if (x < i) change(root1[i], root1[i], 1, m, i, x);
            else change(root2[i], root2[i], 1, m, i, x);
        }
    }
    LL tmp, ans = 1e16;
    for (int i = 1; i <= m; ++i) {
        tmp = 0;
        query(root1, 1, i - 1, 1, m);
        tmp += qnxt + qsiz * (n - i + 1);
        query(root2, 1, i - 1, i, m);
        tmp += qnxt + qsiz * (1 - i);
        query(root2, 1, i - 1, 1, i - 1);
        tmp += qnxt - qcur;
        query(root1, i, m, i, m);
        tmp += qnxt + qsiz * (1 - i);
        query(root1, i, m, 1, i - 1);
        tmp += qnxt + qsiz * m - qcur;
        query(root2, i, m, 1, m);
        tmp += qnxt - qcur;
        ans = min(ans, tmp);
    }
    printf("%lld\n", ans);
}

