int func(int s, int t, int x) {
	int cnt;
	if (t >= s) {
		if (s < x && x <= t)
			cnt = 1 + (t - x);
		else
			cnt = t - s;
	}
	else {
		if (1 <= x && x <= t)
			cnt = 1 + (t - x);
		else
			cnt = (M - s) + t;
	}
	return cnt;
}

