		for (int i = 2; i <= N; ++i) {
			int cnt = func(A[i - 1], A[i], x);
			C[i] = C[i - 1] + (ll)cnt;
		}
		ans = min(ans, C[N]);
	}

	cout << ans << '\n';
	return 0;
}

