struct yes_no : numpunct<char> {
  string_type do_truename()  const { return "YES"; }
  string_type do_falsename() const { return "NO"; }
};

void solve(ll n, ll m, vector<ll> a) {
  for (ll &i: a) --i;
  vector<int> from(n-1), to(n-1), diff(n-1);
  vector<vector<int>> pos_from(m);
  vector<vector<int>> pos_to(m);
  REP(i,n-1) {
    from[i] = a[i];
    to[i] = a[i + 1];
    diff[i] = to[i] - from[i];
    if (diff[i] < 0) diff[i] += m;
    pos_from[a[i]].push_back(i);
    pos_to[a[i + 1]].push_back(i);
  }
  ll sum = 0;
  int cnt = 0;
  REP(i,n-1) {
    if (from[i] <= to[i]) sum += to[i] - from[i];
    else { sum += to[i]; ++cnt; }
  }
  ll res = sum + cnt;

  REP(i,m-1) {
    for (int j: pos_to[i]) {
      --cnt;
      sum += diff[j];
    }
    for (int j: pos_from[i]) {
      ++cnt;
    }
    sum -= cnt;
    chmin(res, sum + cnt);
  }
  cout << res << endl;
}

