int main() {
	cin >> n >> m;
	REP(i, n) scanf("%d", a + i);

	REP(i, n - 1) {
		if (a[i] < a[i + 1]) {
			aic[a[i] + 1]++;
			adc[0][a[i + 1]]++;

			dc[0][a[i + 1]] += a[i + 1] - a[i] - 1;
		}
		else {
			aic[a[i] + 1]++;
			adc[1][a[i + 1]]++;

			dc[1][a[i + 1]] += m - a[i] + a[i + 1] - 1;
		}
	}

	ll now = 0, aa = 0, p = 1;

	REP(i, 2 * m) {
