struct Linfun{
	int a,b;
	Linfun(int a,int b):a(a),b(b){}
	int eval(int x){ return a*x+b; }
	void operator+=(Linfun r){
		a+=r.a;
		b+=r.b;
	}
	void operator-=(Linfun r){
		a-=r.a;
		b-=r.b;
	}
};

struct Event{
	int i,x;
	Event(int i,int x):i(i),x(x){}
	bool operator<(Event r)const{
		return x<r.x;
	}
};

struct Step{
	int i;
	int a,b;
	int dist;
	Step(){}
	Step(int i,int a,int b):i(i),a(a),b(b){
		dist = a<=b?b-a:m-a+b;
	}
	bool operator<(Step r)const{
		return b<r.b;
	}
	vc<Event> getEvents(){
		vc<Event> r;
		if(1+b-dist>=0) r.pb(Event(i,1+b-dist));
		r.pb(Event(i,b+1));
		r.pb(Event(i,max(b,m-dist+b)+1));
		return r;
	}
	Linfun cost(int x){
		//int odist = x<=b?1+b-x:1+m-x+b;
		// odist <= dist:
		// (x<=b?1+b-x:1+m-x+b)<=dist
		// (x<=b && 1+b-x <= dist || x>b && 1+m-x+b<=dist
		// 1+b-dist <= x && x<=b || max(1+b,1+m-dist+b) <= x
		// r = 1+b-dist <= x && x<b+1 ? 1+b-x : max(b,m-dist+b)+1 <= x ? 1+m-x+b : dist
		//return min(dist,odist);
		return 1+b-dist <= x && x<b+1 ? Linfun(-1,1+b) : max(b,m-dist+b)+1 <= x ? Linfun(-1,1+m+b) : Linfun(0,dist);
	}
};

main(){
	ios::sync_with_stdio(0),cin.tie(0);
	cin>>n>>m;
	vc<int> a(n);
	f(i,n) cin>>a[i],a[i]--;
	vc<Step> steps(n-1);
	f(i,n-1) steps[i]=Step(i,a[i],a[i+1]);
	vc<Event> events;
	f(i,n-1) for(auto e:steps[i].getEvents()) events.pb(e);
	sort(all(events));
	auto lf=Linfun(0,0);
	f(i,n-1) lf+=steps[i].cost(0);
	int j=0;
	while(events[j].x==0) j++;
	int best=2e18;
	f(x,m){
		for(;j<sz(events)&&events[j].x==x;j++){
			int i=events[j].i;
			lf-=steps[i].cost(x-1);
			lf+=steps[i].cost(x);
		}
		int cand=lf.eval(x);
		if(cand<best) best=cand;
	}
	cout<<best<<'\n';
}


