			res_best[x[j + 1]] += m - x[j] + 1;;
			res_cnt[x[j + 1]]++;
			x[j] = 1;
			if (x[j + 1] == 1)
				continue;
		}

		end_left[x[j + 1]] += x[j + 1] - x[j];
		to_right.push_back({ x[j], x[j + 1] });
		center.push_back({ x[j] + 1, x[j + 1] });
	}

	sort(center.begin(), center.end(), [&](pair<int, int>& a, pair<int, int>& b) {
		return a.first < b.first;
		});

