const int inf = (int)1e15;


void addc(int c, int l, int r){
    if(l > r)return;
    add1[l] += c;
    add1[r + 1] -= c;
}

void addp(int s, int d, int l, int r){
    if(l > r)return;
    if(l == r){
        addc(s, l, r);
        return;
    }
    add1[l] += s;
    add2[l + 1] += d;
    add2[r + 1] -= d;
    add1[r + 1] += -(s + d * (r - l));
}





