struct node{
	node *l = NULL, *r = NULL;
	int sz;
	bool pu = false;
	lint a = 0;
	lint d = 0;
};

void push(node * v){
	if(!v || !v->pu)ret;
	if(!v->l)ret;
	v->l->a += v->a;
	v->l->d += v->d;
	v->r->a += v->a + v->d * 1ll * v->l->sz;
	v->r->d += v->d;
	v->l->pu = v->r->pu = true;
	v->a = 0; v->d = 0; v->pu = false;
}

node * build(int l, int r){
	node * v = new node;
	v->sz = r - l + 1;
	if(l == r)ret v;
	int mid = (l + r) >> 1;
	v->l = build(l, mid);
	v->r = build(mid + 1, r);
	ret v;
}

void upd(node * v, int l, int r, int ul, int ur, lint a, lint d){
	if(ul > ur)ret;
	push(v);
	if(l == ul && r == ur){
		v->pu = true;
		if(v->a == -1)v->a = 0;
		v->a += a; v->d += d;
		ret;
	}
	int mid = (l + r) >> 1;
	upd(v->l, l, mid, ul, min(ur, mid), a, d);
	upd(v->r, mid + 1, r, max(ul, mid + 1), ur, a + d * max(0, mid - ul + 1), d);
}

lint calc(node * v, int l, int r){
	if(l == r)ret v->a;
	push(v);
	int mid = (l + r) >> 1;
	ret min(calc(v->l, l, mid), calc(v->r, mid + 1, r));
}

