struct Node {
	int st,ed,lazy;
	Node *l,*r;
}*root,pool[404040];
inline void buildt (Node *&now,int st,int ed) {
	now = &pool[++tot];
	now->st = st;
	now->ed = ed;
	now->lazy = 0;
	if (st == ed)
		return ;
	buildt(now->l,st,(st+ed)/2);
	buildt(now->r,(st+ed)/2+1,ed);
}
inline void down(Node *now) {
	if (now->st == now->ed)
		return ;
	if (!now->lazy)
		return ;
	now->l->lazy += now->l->ed+now->lazy-now->ed;
	now->r->lazy += now->lazy;
	now->lazy = 0;
}
inline void Add(Node *now,int pos,int v) {
	if (now->st > pos || now->ed <= pos-v)
		return ;
	if (now->st > pos-v && now->ed <= pos) {
		now->lazy += v+now->ed-pos;
		return ;
	}
	down(now);
	Add(now->l,pos,v);
	Add(now->r,pos,v);
}
inline int getmax(Node *now) {
	if (now->st == now->ed)
		return now->lazy;
	down(now);
	return max(getmax(now->l),getmax(now->r));
}
