	for (int i = 1;i < n; i++) {
		dis = a[i+1]-a[i];
		if (dis < 0)
			dis += m;
		ans += dis;
		dis--;
		Add(root,a[i+1],dis);
		if (dis > a[i+1])
			Add(root,m,dis-a[i+1]);
	}	
	ans -= getmax(root);
	printf("%d",ans);
	return 0;
}

