		if (x==y) continue;
		if (x<y){
			change(1,x,y-x);
			change(y+1,m,y-x);
			change(x+1,y,y+1);
			modify(x+1,y,-1);
		}
		else{
			change(y+1,x,y+m-x);
			change(x+1,m,y+m+1);
			modify(x+1,m,-1);
			change(1,y,y+1);
			modify(1,y,-1);
		}
	}
	ans=100000000000000;
	fo(i,1,m){
		sum[i]+=sum[i-1];
		num[i]+=num[i-1];
		wdc=sum[i]+(ll)num[i]*i;
		ans=min(ans,wdc);
	}
	printf("%lld\n",ans);
}

