struct SegTree{
	#define SIZE 131072
	int f[SIZE<<1]={},lazy[SIZE<<1]={};
	inline int func(int x,int y){return x<y?x:y;}
	void set(int pos,int v){
		pos+=SIZE-1;
		f[pos]=v;
		while(pos){
			pos=pos-1>>1;
			f[pos]=func(f[pos+pos+1],f[pos+pos+2]);
		}
	}
	int query(int l,int r,int l1=0,int r1=SIZE-1,int k=0){
		if(l<=l1&&r1<=r)return f[k]+lazy[k];
		if(r<l1||r1<l)return (ll)1e18;
		lazy[k+k+1]+=lazy[k];lazy[k+k+2]+=lazy[k];lazy[k]=0;
		int mid=l1+r1>>1;
		int vl=query(l,r,l1,mid,k+k+1);
		int vr=query(l,r,mid+1,r1,k+k+2);
		f[k]=func(f[k+k+1]+lazy[k+k+1],f[k+k+2]+lazy[k+k+2]);
		return func(vl,vr);
	}
	void add(int l,int r,int v,int l1=0,int r1=SIZE-1,int k=0){
		if(l<=l1&&r1<=r){
			lazy[k]+=v;
			return;
		}
		if(l1>r||r1<l)return;
		lazy[k+k+1]+=lazy[k];lazy[k+k+2]+=lazy[k];lazy[k]=0;
		int mid=l1+r1>>1;
		add(l,r,v,l1,mid,k+k+1);
		add(l,r,v,mid+1,r1,k+k+2);
		f[k]=func(f[k+k+1]+lazy[k+k+1],f[k+k+2]+lazy[k+k+2]);
		return;
	}
