void solve(istream& cin, ostream& cout) {
  l n, m;
  while (cin >> n >> m) {
    vll events;
    l last; cin >> last;
    l worst = 0;
    F(i, 0, n - 1) {
      l x; cin >> x;
      l to = x;
      if (to < last) to += m;
      worst += to - last;
      if (to - last > 1) {
        events.emplace_back(last + 1, 0); // add to active
        events.emplace_back(to, to - last - 1); // how much to remove
        events.emplace_back(last + 1 + m, 0); // add to active
        events.emplace_back(to + m, to - last - 1); // how much to remove
      }
      last = x;
    }
    sort(all(events));
    l active = 0;
    l bonus = 0;
    l answer = worst;
    l j = 0;
    l p = 0;
    while (j < events.size()) {
      l x = events[j].first;
      bonus += active * (x - p);
      answer = min(answer, worst - bonus);
      p = x;
      while (j < events.size() and events[j].first == x) {
        if (events[j].second) {
          bonus -= events[j].second;
          active--;
        } else {
          active++;
        }
        j++;
      }
    }
    cout << answer << lf;
  }
}

