			tot -= Q[last].y - Q[last].x;
			tot += Q[last].y;
			cnt++; last++;
		}
		ans[i] += tot - (ll)cnt * (i - 1);
		for (auto &idx:Y[i]){
			tot -= Q[idx].y;
			tot += Q[idx].y - Q[idx].x;
			cnt--;
		}
	}
