	}
	for(int i=2;i<=n;i++){
		int l=a[i-1],r=a[i];
		if(l>r){
			r+=m;
		}
		l+=2;
		if(l<=r){
			p[l]+=1;
			p[r+1]-=r-l+2;
			p[r+2]+=r-l+1;
		}
	}
	for(int i=2;i<=2*m+2;i++){
		p[i]+=p[i-1];
	}
	for(int i=2;i<=2*m+2;i++){
		p[i]+=p[i-1];
	}
	maxp=p[1]+p[1+m];
	for(int i=2;i<=m;i++){
		if(p[i]+p[i+m]>maxp){
			maxp=p[i]+p[i+m];
		}
	}
	cout<<all-maxp<<endl;
	return 0; 
}

