template<class T>struct imos {
	const int N;
	vector<T> table;
	imos(int _n) :N(_n), table(_n + 1) {}
	// [l, r) に v を加算
	void add(int l, int r, T v = 1) {
		table[l] += v;
		table[r] -= v;
	}
	void build() {
		for (int i = 1; i <= N; ++i) {
			table[i] += table[i - 1];
		}
	}
	T operator[](int i)const { return table[i]; }
};

