template<class T>bool amax(T&a,const T&b){return a<b?a=b,1:0;}
template<class T>bool amin(T&a,const T&b){return a>b?a=b,1:0;}
ll ri(){ll l;cin>>l;return l;} string rs(){string s;cin>>s;return s;}

ll solve() {
  int n = ri();
  int m = ri();

  vector<int> A(n);
  rep(i, n) A[i] = ri();

  vl ans_u(m+1, 1e18);
  {
    ll sum = 0;
    vpii U;

    rep(i, 1, n) {
      int x = A[i-1];
      int y = A[i];
      if (y > x) {
        sum += y - x;
        U.emplace_back(x, y);
      }
    }
    sort(all(U));
    out(U);
    out(sum);

    priority_queue<pii, vector<pii>, greater<pii> > q;
    int idx = 0;
    ll efe = 0;

    rep(f, 1, m+1) {
      while (idx < sz(U) && U[idx].fst < f) {
        // 効果ありになる
        int x = U[idx].fst;
        int y = U[idx].snd;
        q.emplace(y, x);
        idx++;
      }
      while (!q.empty() && q.top().fst < f) {
        // 効果なくなる
        int x = q.top().snd;
        q.pop();
        efe -= f - x - 1;
      }
      efe += sz(q);
      out(f, sum, efe, sz(q));
      ans_u[f] = sum - efe + sz(q);
    }
  }
  out(ans_u);

  vl ans_d(m+1, 1e18);
  {
    ll sum = 0;
    vpii D;
    ll efe = 0;

    rep(i, 1, n) {
      int x = A[i-1];
      int y = A[i];
      if (y < x) {
        sum += m-x+y;
        D.emplace_back(y, x);
        efe += m-x;
      }
    }
    sort(all(D));
    out(D);
    out(sum);

    int idx = 0;
    priority_queue<pii, vector<pii>, greater<pii> > q;
    int cnt = sz(D);  // 効果ありのcnt

    rep(f, 1, m+1) {
      while (idx < sz(D) && D[idx].fst < f) {
        // 効果なしになる
        int y = D[idx].fst;
        int x = D[idx].snd;
        out(y, x);
        q.emplace(x, y);
        idx++;
        cnt--;
        // y まで1だったのが、普通に処理しないといけない
        efe -= (m-x+y);
      }
      while (!q.empty() && q.top().fst < f) {
        // 効果ありに戻る
        int x = q.top().fst;
        out(q.top());
        q.pop();
        cnt++;
        efe += f - x - 1;
      }
      efe += cnt;
      out(f, sum, efe, cnt);
      ans_d[f] = sum - efe + cnt;
    }
  }
  out(ans_d);

  ll ans = 1e18;
  rep(f, 1, m+1) {
    amin(ans, ans_u[f]+ans_d[f]);
  }

  return ans;
}

void Main() {
  cout << solve() << endl;
}

