using namespace std;

typedef long long ll;
ll n, m, A[100050];
ll cycd(ll a, ll b){
	if(b<a) b+=m;
	return b-a;
}

struct node{
	ll s,e,m,v,lazy;
	node *l, *r;
	node(ll ss, ll ee){
		s = ss, e = ee;
		m = (s+e)/2;
		v = lazy = 0;
		if(s == e) return;
		l = new node(s,m);
		r = new node(m+1,e);
	}
	ll value(){
		v += lazy*(e-s+1);
		if(s != e){
			l->lazy += lazy;
			r->lazy += lazy;
		}
		lazy = 0;
		return v;
	}
	void add(ll x, ll y, ll val){
		value();
		if(s == x and e == y){
			lazy += val;
			return;
		}
		if(y <= m) l->add(x,y,val);
		else if(x > m) r->add(x,y,val);
		else l->add(x,m,val), r->add(m+1,y,val);
		v = l->value() + r->value();
	}
	ll sum(ll x, ll y){
		value();
		if(s == x and e == y) return value();
		if(y <= m) return l->sum(x,y);
		else if(x > m) return r->sum(x,y);
		else return l->sum(x,m) + r->sum(m+1,y);
	}
}*root;
void print(){
	for(ll i = 1; i<=m; i++) printf("%d ", root->sum(1,i)); printf("\n");
}
void add(ll s, ll e, ll val){
	if(s > m) s-=m;
	if(e > m) e-=m;
	if(s > e){
		root->add(s,m,val);
		root->add(1,1,(m-s+1)*val);
		root->add(1,e,val);
		root->add(e+1,e+1,-(m-s+1+e)*val);
	}else{
		root->add(s,e,val);
		if(e+1 <= m) root->add(e+1,e+1,-(e-s+1)*val);
	}
}
int main(){
//	freopen("mx0.txt","r",stdin);
	cin >> n >> m;
	root = new node(0,m);
	for(ll i = 0; i<n; i++){
		cin >> A[i];
		if(i > 0){
			root->add(1,1,cycd(A[i-1],A[i]));
			if(cycd(A[i-1],A[i]) >= 2) add(A[i-1]+2,A[i],-1);
		}
	}
	ll ans = 1000000000000;
	for(ll i = 1; i<=m; i++){
		ans = min(root->sum(1,i),ans);
	}
	cout << ans;
}

