const int M=(int)2e5+5;
int n,m;
int A[M];
ll add[M],val[M],V[M];
int dist(int a,int b){
	if(b>=a)return b-a;
	else return b+m-a;
}
void Add(int x,int v){
	if(!v)return;
	int l=x-(v-1);
	if(l<=0)l+=m,x+=m;
	add[l]++;
	add[x+1]--;
	val[x+1]-=v;
}
int main(){
	Rd(n),Rd(m);
	for(int i=1;i<=n;i++)Rd(A[i]);
	for(int i=2;i<=n;i++){
		int d=dist(A[i-1],A[i])-1;
		//+1 +2 +3 +4...+d
		Add(A[i],d);
	}
	ll a=0,v=0;
	for(int i=1;i<=m*2;i++){
		a+=add[i];
		v+=val[i];
		v+=a;
		V[i]=v;
	}
	for(int i=1;i<=m;i++)
		V[i]+=V[i+m];
	int pos;ll mx=-1;
	for(int i=1;i<=m;i++)
		if(V[i]>mx)mx=V[i],pos=i;
	ll ans=0;
	for(int i=2;i<=n;i++)
		ans+=min(dist(pos,A[i])+1,dist(A[i-1],A[i]));
	cout<<ans<<endl;
	return 0;
}

