int n,m;
ll val[maxn],b[maxn],c[maxn];
ll ans;

void solve()
{
	ans=0;
	scanf("%d%d",&n,&m);
	repp(i,1,n)
	{
		scanf("%lld",&val[i]);
	}
	repp(i,2,n)
	{
		if(val[i-1]<val[i])
		{
			ans+=val[i]-val[i-1];

			b[val[i-1]+1]+=val[i-1]+1;
			b[val[i]+1]-=val[i-1]+1;
			++c[val[i-1]+1];
			--c[val[i]+1];
		}
		else
		{
			ans += m+val[i]-val[i-1];

			b[1]-=m-val[i-1]-1;
			b[val[i]+1]+=m-val[i-1]-1;
			b[val[i-1]+1]+=val[i-1]+1;

			c[1]++;
			c[val[i]+1]--;
			c[val[i-1]+1]++;
		}
	}
	for(int i=1;i<=m;i++)
	{
		b[i]+=b[i-1];
		c[i]+=c[i-1];
	}
	ll cnt=0;
	for(int i=1;i<=m;i++)
	{
		cnt=max(cnt,1LL*i*c[i]-b[i]);

	}
	//DE(cnt)

	printf("%lld\n", ans-cnt);
}

int main()
{

	solve();
	//system("pause");
