    b[a[i]].push_back(a[i+1]);
  }
  for(int i=1;i<n;i++){
    c[a[i]].push_back(a[i-1]);
  }
  priority_queue<int,vector<int>,greater<int> > q;
  int tmp=0;
  for(int i=0;i<n-1;i++){
    if(a[i]<a[i+1]) tmp+=a[i+1]-a[i];
    else{
      tmp+=a[i+1];
      q.push(a[i+1]);
    }
  }
  //cout<<tmp<<endl;
  int ans=tmp;
  for(int i=1;i<=m;i++){

    for(int j=0;j<(int)c[i].size();j++){
      //cout<<i<<":"<<c[i][j]<<endl;
      if(i>c[i][j]) tmp+=(i-c[i][j])-1;
      else tmp+=((m-c[i][j])+i)-1;
    }

    while(!q.empty()&&q.top()<=i) q.pop();
    tmp-=q.size();
    //cout<<"qs:"<<q.size()<<endl;

    for(int j=0;j<(int)b[i].size();j++){
      if(i<b[i][j]) q.push(b[i][j]);
      else q.push(b[i][j]+m);
    }

    //cout<<tmp<<endl;
    ans=min(ans,tmp);
  }
  cout<<ans<<endl;
