    REP(i,n-1){
        if(a[i]<a[i+1]) e[a[i+1]] += a[i+1]-a[i]-1;
        else{
            e[a[i+1]] += m-a[i];
            e[a[i+1]] += a[i+1]-1;
        }
    }

    VL p(m+1,0), q(m+1,0);
    REP(i,n-1){
        if(a[i]<m && a[i+1]<a[i]) p[m]++;
        if(a[i+1] == m) q[m] += e[m];
    }
    RFOR(i,m,1){
        p[i] = p[i+1] + s[i+1];
        if(i == a[n-1]-1) p[i]++;
        if(i == a[0]-1) p[i]--;
        p[i] -= s[i];
        q[i] = e[i];
    }

    ll ans = 0;
    REP(i,n-1){
        if(a[i+1] == m) ans += 1;
        else if(a[i]<a[i+1]) ans += a[i+1]-a[i];
        else if(i==0 && a[i]==m) ans += a[i+1];
        else ans += a[i+1]+1;
    }

    ll tmp = ans;
    REP(i,m-1){
        tmp += p[m-1-i];
        tmp -= q[m-1-i];
        chmin(ans, tmp);
    }

    cout << ans << en;
    return;
}

