	for (int i = 0; i < n; ++i) {
		cin >> arr[i];
	}

	Segment tree(m + 1);
	for (int i = 1; i < n; ++i) {
		if (arr[i] > arr[i - 1]) {
			sum += arr[i] - arr[i - 1];
			tree.update(1, 0, m , arr[i - 1] + 1, arr[i]);
		}
		else {
			sum += m - arr[i - 1] + arr[i];
			tree.update(1, 0, m, arr[i - 1] + 1, m);
			tree.update(1, 0, m, 1, arr[i], m - arr[i - 1]);
		}
		/*for (int j = 0; j <= m; ++j) {
			cout << tree.get(1, 0, m, j) << " ";
		}
		cout << endl;*/
	}

	ll maxVal = 0;
