#define ll long long
#define M 100005
int n,m,A[M];
ll sum,ans,cnt1[M],cnt2[M];
int dis(int a,int b){
	if(a<=b)return b-a;
	return m-a+b;
}
int nxt(int a,int b=1){
	return (a+b-1)%m+1;
}
int main(){
	scanf("%d%d",&n,&m);
	for(int i=1;i<=n;i++)scanf("%d",&A[i]);
	for(int i=1;i<n;i++)sum+=dis(A[i],A[i+1]);
	for(int i=1;i<n;i++){
		if(nxt(A[i])==A[i+1])continue;
		int s=nxt(A[i],2),t=A[i+1];
		cnt1[s]++;
		if(s<=t){
			if(t!=m)cnt1[nxt(t)]--,cnt2[nxt(t)]-=dis(s,t)+1;
		}
		else{
			cnt1[1]++;
			cnt2[1]+=dis(s,1);
			cnt1[nxt(t)]--;
			cnt2[nxt(t)]-=dis(s,t)+1;
		}
	}
	ll t=0,res=0;
	for(int i=1;i<=m;i++){
		t+=cnt1[i];
		res+=t+cnt2[i];
		ans=max(ans,res);
	}
	cout<<sum-ans<<endl;
	return 0;
}

