		if (i != 0)
		{
			if (d[i - 1] < d[i])now += d[i] - d[i - 1];
			else
			{
				now += d[i] + 1;
				cnt++;
				qs[d[i]].push_back(i);
			}
		}
	}
	ll mini = now;
	for (int i = 0; i < gen; i++)
	{
		mini = min(mini, now);
