                        startlist[alist[i]+1LL].pb(0LL);
                        endlist[alist[i+1LL]].pb(alist[i+1LL] - alist[i] - 1LL);
                }
                if (alist[i] == alist[i+1LL]) {
                        continue;
                }
                if (alist[i] + 1LL == alist[i+1LL]) {
                        continue;
                }
                if (alist[i] == m && alist[i+1LL] == 1LL) {
                        continue;
                }
                if (alist[i+1LL] < alist[i]) {
                        startlist[1LL].pb(m - alist[i]);
                        endlist[alist[i+1LL]].pb(m - alist[i] + alist[i+1LL] - 1LL);
                        startlist[alist[i]+1LL].pb(0LL);
                }
        }

        ll max_x;
        ll max_bonus = -1LL;
        ll now_bonus = 0LL;
        ll bonus_count = 0LL;

        rep (x0, m) {
                ll x = x0 + 1LL;

                now_bonus += bonus_count;

                for (auto bonus_start : startlist[x]) {
                        now_bonus += bonus_start;
                        bonus_count++;
                }

                if (now_bonus > max_bonus) {
                        max_x = x;
                        max_bonus = now_bonus;
                }

                for (auto bonus_end : endlist[x]) {
                        now_bonus -= bonus_end;
                        bonus_count--;
                }
        }

        ll ans = 0LL;

        rep (i, n-1LL) {
                ll now = alist[i];
                ll next = alist[i+1LL];
                if (now <= next) ans += (next - now);
                else ans += (m - now + next);
        }

