    rev_priority_queue<pair<i64, int>> q;
    for(int i = 0; i < N; i++) {
        cin >> A[i];
        A[i]--;
    }
    set<int> shortcut, inv_range;
    i64 L = 0;
    for(int i = 0; i < N - 1; i++) {
        S += (A[i + 1] - A[i] + M) % M;
        if(A[i] < A[i + 1]) { // 向きが同じ
            q.push({A[i], i});
            q.push({A[i + 1], i});
        } else { //
            q.push({A[i + 1], i});
            q.push({A[i], i});
            inv_range.insert(i);
            shortcut.insert(i);
            L += A[i];
        }
    }
    i64 ans = INF;

    for(int x = 0; x < M; x++) {
        i64 cand = 0;
        cand = S;
        cand -= x * shortcut.size() - L + inv_range.size() * M;
        cand += shortcut.size();
        ans = min(ans, cand);
        while(q.size() && x >= q.top().first) {
            i64 a; int i;
            tie(a, i) = q.top();
            inv_range.erase(i);
            if(shortcut.count(i)) {
                shortcut.erase(i);
                L -= A[i];
            } else {
                shortcut.insert(i);
                L += A[i];
            }
            q.pop();
        }
    }
    cout << ans << endl;
    return 0;
