#include <bits/stdc++.h>
using namespace std;

using LL = long long int;

struct BinaryIndexedTree {
    vector<int> tree;
    BinaryIndexedTree(int capacity) : tree(capacity + 1){

    }

    void update(int index, int diff) {
        for(int i = index; i < tree.size(); i += i & -i) {
            tree[i] += diff;
        }
    }

    int query(int limit) {
        int total = 0;
        for(int i = limit; i; i -= i & -i) {
            total += tree[i];
        }
        return total;
    }
};

class Solution {
public:
    int solve(int n, int m, vector<int> &a) {
        BinaryIndexedTree b1(m<<1), b2(m<<1), c1(m<<1), c2(m<<1);
        int cost = 0;
        for(int i = 0; i + 1 < a.size(); ++ i) {
            b1.update(a[i], a[i]);
            c1.update(a[i], 1);
            if(a[i] < a[i+1]) {
                b2.update(a[i+1], a[i]);
                c2.update(a[i+1], 1);
                cost += a[i+1] - a[i];
            }
            else {
                b2.update(a[i+1] + m, a[i]);
                c2.update(a[i+1] + m, 1);
                cost += a[i+1] + m - a[i];
            }
        }
        int reduce = 0;
        for(int i = 1; i <= m; ++ i) {
            for(int k = 0; k < 2; ++ k) {
                int j = i - 1 + k * m;
                int t1 = b1.query(j);
                int k1 = c1.query(j);
                int t2 = b2.query(j);
                int k2 = c2.query(j);
                int r = (k1 - k2)*j - (t1 - t2);
                reduce = max(reduce, r);
            }
        }
        return cost - reduce;
    }
};

int main() {
    Solution s;
    int n, m;
    cin >> n >> m;
    vector<int> a(n);
    for(auto &ai : a) {
        cin >> ai;
    }
    cout << s.solve(n, m, a) << endl;
    return 0;
}

