char buf[1000000], *p1 = buf, *p2 = buf;
inline char gc() {
  if (p1 == p2) p2 = (p1 = buf) + fread(buf, 1, 1000000, stdin);
  return p1 == p2 ? EOF : *(p1++);
}
template <class T> inline void read(T &n) {
  n = 0; RI ch = gc(), f;
  while ((ch < '0' || ch > '9') && ch != '-') ch = gc();
  f = (ch == '-' ? ch = gc(), -1 : 1);
  while (ch >= '0' && ch <= '9') n = n * 10 + (ch ^ 48), ch = gc();
  n *= f;
}

int const MAXN = 1e5 + 5;
int Be[MAXN * 4], En[MAXN * 4], Dis[MAXN * 4];
int a[MAXN];

void Add(int x, int len, int b, int e, int f) {
  Be[x] += b;
  En[x] += f * len;
  Dis[x] += f;
}
void Pushdown(int x, int l, int r) {
  int mid = (l + r) >> 1;
  Add(lc, mid - l + 1, Be[x], Be[x] + Dis[x] * (mid - l), Dis[x]);
  Add(rc, r - mid, Be[x] + Dis[x] * (mid - l + 1), En[x], Dis[x]);
  Be[x] = En[x] = Dis[x] = 0;
}
void Modify(int x, int l, int r, int i, int j, int b, int e) {
  if (i <= l && r <= j) return Add(x, r - l + 1, b, e, 1);
  Pushdown(x, l, r);
  int mid = (l + r) >> 1;
  if (i <= mid) Modify(lc, l, mid, i, j, b, min(e, b + mid - i));
  if (j > mid) Modify(rc, mid + 1, r, i, j, max(b, b + mid - i + 1), e);
}
int Query(int x, int l, int r, int to) {
  if (l == r) return Be[x];
  int mid = (l + r) >> 1;
  Pushdown(x, l, r);
  if (to <= mid) return Query(lc, l, mid, to);
  else return Query(rc, mid + 1, r, to);
}

signed main() {

#ifdef LOCAL
  FILEIO("a");
#endif

  int n, m, ans = 0; read(n), read(m);
  for (RI i = 1; i <= n; ++i) read(a[i]);
  for (RI i = 1; i < n; ++i)
    ans += (a[i + 1] - a[i] + m) % m;
  for (RI i = 1; i < n; ++i) {
    if (a[i + 1] > a[i]) Modify(1, 1, m, a[i] + 1, a[i + 1], 0, a[i + 1] - a[i]);
    else {
      Modify(1, 1, m, a[i] + 1, m, 0, m - a[i] - 1);
      Modify(1, 1, m, 1, a[i + 1], m - a[i], (a[i + 1] - a[i] + m) % m);
    }
  }
  int Max = 0;
  for (RI i = 1; i <= m; ++i)
    Max = max(Max, Query(1, 1, m, i));
  printf("%lld\n", ans - Max);

  return 0;
}

