LL total = 0, ans;
struct rec {
	LL d, c;
	inline void operator += (const int &v) {d += v, ++ c;}
	inline void operator += (const rec &v) {d += v.d, c += v.c;}
	inline void operator -= (const rec &v) {d -= v.d, c -= v.c;}
}bg[maxN], ed[maxN], s;

int main() {

	n = ri(), m = ri();
	rep (i, 1, n) p[i] = ri();
	rep (i, 2, n) {
		int x = p[i-1], y = p[i];
		if (x == y) continue;
		if (x < y) {
			total += y - x;
			bg[x+1] += 0, ed[y] += y - x - 1;
		}
		else {
			int d = m - x;
			if (x < m) bg[x+1] += 0;
			bg[1] += d, ed[y] += d + y - 1;
			total += d + y;
		}
	}

	ans = total;
	rep (i, 1, m) {
		s.d += s.c;
		s += bg[i];
		ans = min(ans, total - s.d);
		s -= ed[i];
	}
