const int maxn=1e5+1e2;
const int maxs=4e6+1e2;

int a[maxn],cnt=0,root1[maxn],root2[maxn],size=0;

struct node
{
	int l, r;
}q[maxn];

struct seg
{
	LL lsum;
	int num,l,r;
}tr1[maxs],tr2[maxs];

void insert(int l,int r,int &now,int v1,int v2,seg *tr)
{
	tr[++cnt]=tr[now];
	now=cnt;
	tr[now].lsum+=v1;
	tr[now].num++;
	if(l==r)return;
	int mid=(l+r)>>1;
	if(v2<=mid)insert(l,mid,tr[now].l,v1,v2,tr);
	else insert(mid+1,r,tr[now].r,v1,v2,tr);
}

seg merge(seg t1,seg t2,int op)
{
	seg t;
	t.lsum=t1.lsum+op*t2.lsum;
	t.num=t1.num+op*t2.num;
	return t;
}

seg query(int l,int r,int now1,int now2,int ql,int qr,seg *tr)
{
	if(ql<=l&&r<=qr)return merge(tr[now1],tr[now2],-1);
	int mid=(l+r)>>1;
	if(qr<=mid)return query(l,mid,tr[now1].l,tr[now2].l,ql,qr,tr);
	if(ql>mid)return query(mid+1,r,tr[now1].r,tr[now2].r,ql,qr,tr);
	return merge(query(l,mid,tr[now1].l,tr[now2].l,ql,qr,tr),query(mid+1,r,tr[now1].r,tr[now2].r,ql,qr,tr),1);
}

bool cmp(node t1,node t2)
{
	return t1.l<t2.l;
}

int getint()
{
	char ch;int b=1;
	for(ch=getchar();ch>'9'||ch<'0';ch=getchar())if(ch=='-')b=-1;
	int num=ch-'0';
	for(ch=getchar();ch>='0'&&ch<='9';ch=getchar())num=num*10+ch-'0';
	return num*b;
}

int main()
{
	int n=getint(),m=getint();
	for(int i=1;i<=n;i++)a[i]=getint();
	LL sum=0;
	for(int i=1;i<n;i++)
	{
		q[i].l=a[i];
		q[i].r=a[i+1];
		if(q[i].l<q[i].r)sum+=q[i].r-q[i].l;
		else sum+=(m-q[i].l)+q[i].r;
	}
	sort(q+1,q+n,cmp);
	int now=1;
	for(int i=1;i<=m;i++)
	{
		root1[i]=root1[i-1];
		root2[i]=root2[i-1];
		while(q[now].l==i&&now<=n)
		{
			if(q[i].l<q[i].r)insert(1,m,root1[i],q[now].l,q[now].r,tr1);
			else insert(1,m,root2[i],q[now].l,q[now].r,tr2);
			now++;
		}
	}
	LL ans=1e17;
	for(int i=1;i<=m;i++)
	{
		seg t1=query(1,m,root1[i-1],root1[0],i,m,tr1);
		seg t2=query(1,m,root2[m],root2[i],i,m,tr2);
	//	printf("%d %d %I64d %I64d %I64d %I64d\n",t1.num,t2.num,t1.lsum,t2.lsum,t1.rsum,t2.rsum);
		LL re=0;
		re+=-((LL)i*t1.num-t1.lsum)+t1.num;
		//printf("%I64d ",re);
		re+=-((LL)m*t2.num-t2.lsum+(LL)i*t2.num)+t2.num;
		ans=min(ans,sum+re);
		//printf("%I64d\n",re);
	}
	printf("%lld\n",ans);
	return 0;
}

