    for (int i=1; i<n; ++i) {
        without += (a[i] - a[i-1] + m) % m;
    }
    printf("without: %lld\n", without);
    */

    vector<ll> b(m+1, 0);
    vector<ll> ac(m+1, 0);

    for (int i=1; i<n; ++i) {
        int prev = a[i-1], next = a[i];

        if (next < prev) {
            int without = next + m - prev;
            b[0] += next+1; // <= without
            ac[0] -= 1;

            b[next+1] += without;
            ac[next+1] += 1;

            if (prev+1 < m) {
                ac[prev+1] -= 1;
            }
        } else { // prev < next
            int without = next - prev;
            b[0] += without;
            // ac[0] += 0;
            ac[prev+1] -= 1;

            b[next+1] += without;
            ac[next+1] += 1;
        }
    }

#ifdef DEBUG
