    cout << "c:" << ac << endl;
#endif
    rep(i, m) {
        b[i+1] += b[i];
        ac[i+1] += ac[i];
    }
    rep(i, m) {
        ac[i+1] += ac[i];
    }
#ifdef DEBUG
    cout << "b:" << b << endl;
    cout << "c:" << ac << endl;
#endif
    vector<ll> d(m, 0);
