void solve() {
    cin >> n >> m;
    FOR(i, 0, n) {
        cin >> a[i], a[i]--;
    }
    FOR(i, 0, n - 1) {
        int l = a[i], r = a[i + 1];
        if (l <= r) {
            f[l + 1] += r + 1;
            f[r + 1] -= r + 1;
            g[l + 1] --;
            g[r + 1]++;

            f[r + 1] += r - l;

            f[0] += r - l;
            f[l + 1] -= r - l;
        }
        else if (l > r) {
            f[l + 1] += m + r + 1;
            g[l + 1]--;

            f[0] += r + 1;
            f[r + 1] -= r + 1;
            g[0]--;
            g[r + 1]++;

            f[r + 1] += (m - l - 1) + (r + 1);
            f[l + 1] -= (m - l - 1) + (r + 1);
        }
    }
    long long ans = LINF;
    FOR(i, 0, m) {
        if (i) {
            f[i] += f[i - 1];
            g[i] += g[i - 1];
        }
        chkmin(ans, f[i] + i * g[i]);
    }
    cout << ans << "\n";
}

