    for (int i=1; i<n; i++)
    {
        int t = A[i-1]<=A[i] ? A[i-1] : A[i-1]-m;
        if (t<0)
            c += 1 + A[i],
            x++;
        else
            c += A[i] - t;
    }

    long long ans = c;
    for (int i=1; i<m; i++)
    {
        for (int t: T2[i-1])
        {
            x--;
            c += (A[t] - A[t-1] + m) % m - 1;
        }
        for (int t: T1[i-1])
        {
            x++;
            c++;
        }
        c -= x;
        ans = min(ans, c);
    }
    printf("%lld\n", ans);
}

