    if (l < r) AddLad(l + 1, r, val + l + 1);
  } else {
    val = r + m - l;
    AddSeg(r + 1, l, val);
    if (l < m) AddLad(l + 1, m, val + l + 1);
    val -= m - l;
    AddLad(1, r, val + 1);
  }
}
