	{
		q[i].l=a[i];
		q[i].r=a[i+1];
		if(q[i].l<q[i].r)sum+=q[i].r-q[i].l;
		else sum+=(m-q[i].l)+q[i].r;
	}
	sort(q+1,q+n,cmp);
	int now=1;
	for(int i=1;i<=m;i++)
	{
		root1[i]=root1[i-1];
		root2[i]=root2[i-1];
		while(q[now].l==i&&now<n)
		{
			if(q[i].l<q[i].r)insert(1,m,root1[i],q[now].l,q[now].r,tr1,&cnt1);
			else insert(1,m,root2[i],q[now].l,q[now].r,tr2,&cnt2);
			now++;
		}
	}
	LL ans=1e17;
	for(int i=1;i<=m;i++)
	{
		seg t1=query(1,m,root1[i-1],root1[0],i,m,tr1);
		seg t2=query(1,m,root2[m],root2[i],i,m,tr2);
	//	printf("%d %d %I64d %I64d %I64d %I64d\n",t1.num,t2.num,t1.lsum,t2.lsum,t1.rsum,t2.rsum);
		LL re=0;
