		//printf("%I64d ",re);
		re+=-((LL)m*t2.num-t2.lsum+(LL)i*t2.num)+t2.num;
		ans=min(ans,sum+re);
		//printf("%I64d\n",re);
	}
	printf("%I64d\n",ans);
	return 0;
}

