template<class T> class Segment_Tree_Range_Sum_Query {
	size_t N,M;
	T ini;
	vector<T> node;

public:
	Segment_Tree_Range_Sum_Query(const vector<T> & ar, const T ini) : M(ar.size()), ini(ini) {
		for (N = 1; N < M; N *= 2);
		node.resize(2 * N - 1, ini);
		for (int i = 0; i < M; ++i) node[i + N - 1] = ar[i];
		for (int i = N - 2; i >= 0; --i) node[i] = node[2 * i + 1]+node[2 * i + 2];
	}

	Segment_Tree_Range_Sum_Query(const size_t M, const T ini) : M(M), ini(ini) {
		for (N = 1; N < M; N *= 2);
		node.resize(2 * N - 1, ini);
	}

	void update(size_t idx, const T var) {
		idx += (N - 1);
		node[idx] += var;
		while (idx > 0) {
			idx = (idx - 1) / 2;
			node[idx] = node[2 * idx + 1]+node[2 * idx + 2];
		}
	}

	T getvar(const int a, const int b, int k = 0, int l = 0, int r = -1) {
		if (r < 0) r = N;
		if (r <= a || b <= l) return ini;
		if (a <= l && r <= b) return node[k];
		T vl = getvar(a, b, 2 * k + 1, l, (l + r) / 2);
		T vr = getvar(a, b, 2 * k + 2, (l + r) / 2, r);
		return vl+vr;
	}

	T operator[](size_t i) {
		return getvar(i, i + 1);
	}

	T operator[](pair<size_t, size_t> p) {
		return getvar(p.first, p.second);
	}


	void print(){
		cout << "{ " << getvar(0,1);
		for(int i = 1; i < M; ++i) cout << ", " << getvar(i,i+1);
		cout << " }" << endl;
	}
};


int main() {
	ll n,m; cin >> n >> m;
	V<ll> a(n);
	for(int i = 0; i < n; ++i) cin >> a[i];

	Segment_Tree_Range_Sum_Query<ll> Seg1(2*m+2,0),Seg2(2*m+2,0),Seg3(2*m+2,0),Seg4(2*m+2,0);

	for(int i = 0; i < n-1; ++i) Seg1.update(a[i] - (a[i+1]>a[i]?0:m) + m,1);
	for(int i = 0; i < n-1; ++i) Seg2.update(a[i] - (a[i+1]>a[i]?0:m) + m,a[i] - (a[i+1]>a[i]?0:m));

	ll sum = 0;
	for(int i = 1; i < n; ++i) sum += a[i];
	ll ans = sum;
	for(int i = 0; i < n-1; ++i) ans -= (a[i] - (a[i+1]>a[i]?0:m) );

	V<P<ll,int>> ord;
	for(int i = 1; i < n; ++i) ord.push_back({a[i],i});

	sort(ALL(ord));
	for(auto e:ord){
		ll key = e.first;
		int idx = e.second;
		ll x = Seg1[{0,key+m}];
		ll y = Seg3[{0,key}];
		ll cnt = sum - (Seg2[{key+m,2*m+2}]+(key-1)*x + Seg4[{key-m + m,2*m+2}]+(key-m -1)*y);

		chmin(ans,cnt);
		ll z = a[idx-1] - (a[idx]>a[idx-1]?0:m);
		Seg1.update(z + m,-1);
		Seg2.update(z + m,-z);
		Seg3.update(z + m, 1);
		Seg4.update(z + m, z);

	}
	cout << ans << endl;
	return 0;
}

