template<typename T>struct fenwick_tree{
	vector<T> x;
	fenwick_tree(int n){
		int m=1;
		while(m<n)m*=2;
		x=vector<T> (m);
	}
	// [i,j)区間
	void range(int i,int j, T d){
		if(i!=0){
			range(0,j,d);
			range(0,i,-d);
			return;
		}
		j-=1;
		for( ;j>=0;j=(j&(j+1))-1){
			x[j]+=d;
		}
	}
	T point(int k){
		T ret=0;
		for(;k<x.size(); k|=k+1) ret+=x[k];
		return ret;
	}
};

void _main(istream &inp){
	ll n,m;
	inp >> n >> m;
	fenwick_tree<ll> ft1(m);
	fenwick_tree<ll> ft0(m);
	vl a(n);
	rep(i,n) inp >> a[i];
	rep(i,n)a[i]-=1;
	ll tot = 0;
	rep(i,n-1){
		ll x = a[i];
		ll y = a[i+1];
		if(x<y){
			tot += y-x;
			ft1.range(x+1, y+1,1);
			ft0.range(x+1, y+1,-x-1);
		}
		else{
			tot += y+m-x;
			ft1.range(x+1,m,1);
			ft0.range(x+1,m,-x-1);
			ft1.range(0,y+1,1);
			ft0.range(0,y+1,m-x-1);
		}
	}
	ll mini = -1;
//	deb(n);deb(m);deb(a);
	rep(i,m){
		ll res = tot - ft1.point(i)*i - ft0.point(i);
		if(mini==-1 || res<mini){
			mini = res;
		}
//		deb(i);deb(res);debl;
	}
	cout << mini << endl;

}

