void add( int from, int to ){

	if ( from == to ) return;

	if ( from < to ){
		b[0] += to - from;
		a[from + 1] -= 1;

		a[to] += 1;
		b[to + 1] += to - from - 1;
	}
	else{
		b[0] += to + 1;
		a[0] -= 1;

		a[to] += 1;
		b[to + 1] += m + to - from - 1;

		a[from + 1] -= 1;
	}

}

