		if(A[i] < A[i+1]) kukan.push_back(pair<ll,ll>{A[i],A[i+1]});
		else kukan.push_back(pair<ll,ll>{A[i],A[i+1]+m});
	}
	sort(all(kukan));
	priority_queue<pair<ll,ll>, vector<pair<ll,ll>>, greater<pair<ll,ll>>> que;
	ll val = 0;
	int ki = 0;
	ll toku = 0;
	ll max_toku = 0;
	rep(t,2*m+1){
		while(que.size() > 0 && que.top().first == t){
			pair<ll,ll> top = que.top();
			que.pop();
			val--;
			toku -= top.first - top.second - 1;
		}
		toku += val;
		while(ki < n-1 && kukan[ki].first == t){
			que.push(pair<ll,ll>{kukan[ki].second, kukan[ki].first});
			val++;
			ki++;
		}
		chmax(max_toku, toku);
		//cout<<toku<<" ";
		//cout<<que.size()<<" ";
	}
	//cout<<endl;
	ll ans = 0;
	rep(i,A.size()-1){
		if(A[i] < A[i+1]) ans += A[i+1] - A[i];
		else ans += A[i+1] - A[i] + m;
	}
	ans -= max_toku;
	cout<<ans<<endl;
	//cout<<max_toku<<endl;
	return 0;
}

