void update(long long *BIT,int idx,int val){
    assert(idx > 0) ;
    while(idx < MAXN) {
        BIT[idx] += val ;
        idx += (idx & -idx) ;
    }
}
long long query(long long *BIT,int idx){
    long long ret = 0 ;
    while(idx){
        ret += BIT[idx] ;
        idx -= (idx & -idx) ;
    }
    return ret ;
}
void rangeUpdate(long long *BIT,int l,int r,int val){
    if(l <= r){
        l++ ;
        r++ ;
        update(BIT,l,val) ;
        update(BIT,r+1,-val) ;
    }
}
