	for (int i=2;i<=n;i++)
	{
		scanf("%lld",&to);
		if (from<to)
		{
			update(1,from,1,m,1,0,to-from);
			update(from+1,to,1,m,1,-1,to+1);
			update(to+1,m,1,m,1,0,to-from);
		}
		else
		{
			update(1,to,1,m,1,-1,to+1);
			update(to+1,from,1,m,1,0,to-from+m);
			update(from+1,m,1,m,1,-1,to+m+1);
		}
		from=to;
	}
	ans=1e18;
	for (long long i=1;i<=m;i++)
	{
		ans=min(ans,query(i));
	}
	printf("%lld\n",ans);
	return 0;
}

