int dd(int x1, int x2) { /// x1 -> x2
    if (x1 <= x2) return x2 - x1;
    return x2 - x1 + m - 1;
}

int dist(int i, int x) { /// i -> i + 1
    return min(dd(a[i], a[i + 1]), dd(a[i], x) + dd(x, a[i + 1]));
}

int get_cnt(int x) {
    int res = 0;
    rep(i, 0, n - 1)
        res += dist(i, x);
    return res;
}

