        if (a[i] < a[i + 1]) {
            op[(a[i] + 1) % m]++;
            cl[a[i + 1]]++;
            add[a[i + 1]] += dd(a[i], a[i + 1]) - 1;
        } else {
            op[(a[i] + 1) % m]++;
