using namespace std;
typedef long long ll;
struct node{
	int l, r, m, cnt; ll sum;
	node *lch, *rch;
	node(){}
	node(int L, int R):l(L), r(R){
		m=(l+r)>>1; cnt=sum=0;
		lch=rch=NULL;
	}
}pn[200010], *root;
int n, m, nT, cnt[100010];
inline int rd(){
	int a=0; char c=getchar();
	while(!isdigit(c)) c=getchar();
	while(isdigit(c)) (a*=10)+=c-'0', c=getchar();
	return a;
}
void build(node *p){
	if(p->r-p->l==1) return;
	p->lch=&(pn[nT++]=node(p->l, p->m)); build(p->lch);
	p->rch=&(pn[nT++]=node(p->m, p->r)); build(p->rch);
}
void modify(node *p, int l, int r, int v){
	if(r<=p->l||p->r<=l) return;
	if(l<=p->l&&p->r<=r){
		p->cnt++; p->sum+=v;
		return;
	}
	modify(p->lch, l, r, v); modify(p->rch, l, r, v);
}
ll query(node *p, int k){
	ll ret=p->cnt*k-p->sum;
	if(p->r-p->l==1) return ret;
	return ret+query(k<p->m?p->lch:p->rch, k);
}
int query2(node *p, int k){
	if(p->r-p->l==1) return p->cnt;
	return p->cnt+query2(k<p->m?p->lch:p->rch, k);
}
int main(){
	n=rd(), m=rd(); ll tot=0;
	root=&(pn[nT++]=node(1, m+1)); build(root);
	int a=rd(), b;
	for(int i=1;i<n;i++){
		b=rd(); cnt[a]++;
		if(a<b) modify(root, a, b+1, a), tot+=b-a;
		else{
			modify(root, a, m+1, a);
			modify(root, 1, b+1, a-m);
			tot+=m-a+b;
		}
		a=b;
	}
	ll ma=0;
	for(int i=1;i<=m;i++)
		ma=max(ma, query(root, i)-query2(root, i)+cnt[i]);
	printf("%lld\n", tot-ma);
	return 0;
}

