#define ls u << 1
#define rs u << 1 | 1
const int N = 100005;
int n, m, a[N];
LL f[N << 2], d[N << 2];
bool mark[N << 2];

void pd(int u, int l, int r) {
    if(mark[u]) {
        int mid = (l + r) / 2;
        f[ls] += f[u], f[rs] += (f[u] + d[u] * (mid - l + 1));
        d[ls] += d[u], d[rs] += d[u];
        mark[ls] = mark[rs] = 1;
        f[u] = d[u] = mark[u] = 0;
    }
}

void upd(int u, int l, int r, int L, int R, int F, int D) {
    if(l == L && r == R) {
        f[u] += F;
        d[u] += D;
        mark[u] = 1;
        return;
    }
    pd(u, l, r);
    int mid = (l + r) / 2;
    if(R <= mid) upd(ls, l, mid, L, R, F, D);
    else if(L > mid) upd(rs, mid + 1, r, L, R, F, D);
    else {
        upd(ls, l, mid, L, mid, F, D);
        upd(rs, mid + 1, r, mid + 1, R, F + D * (mid + 1 - L), D);
    }
}

LL query(int u, int l, int r, int x) {
    if(l == r) return f[u];
    pd(u, l, r);
    int mid = (l + r) / 2;
    return x <= mid ? query(ls, l, mid, x) : query(rs, mid + 1, r, x);
}

int main()
{
    scanf("%d%d", &n, &m);
    for(int i = 1; i <= n; i++) scanf("%d", &a[i]);
    for(int i = 2; i <= n; i++) {
        int last = a[i - 1], cur = a[i];
        if(last < cur) {
            upd(1, 1, m, last + 1, cur, cur - last, -1);
            upd(1, 1, m, 1, last, cur - last, 0);
            if(cur + 1 <= m) upd(1, 1, m, cur + 1, m, cur - last, 0);
        }
        else {
            int step = m - last + cur;
            if(last + 1 <= m) upd(1, 1, m, last + 1, m, step, -1);
            upd(1, 1, m, 1, cur, step - (m - last), -1);
            upd(1, 1, m, cur + 1, last, step, 0);
        }
    }
    LL ans = 1e18;
    for(int i = 1; i <= m; i++) ans = min(ans, query(1, 1, m, i));
    cout << ans << endl;
    return 0;
}

