	auto add = [&](int l, int r, long long a, long long b) {
		imos0[l] += a;
		imos0[r] -= a;

		imos0[l] -= b * l;
		imos0[r] += b * l;

		imos1[l] += b;
		imos1[r] -= b;
	};

	auto f = [&](int k) {
		return imos0[k] + imos1[k] * k;
	};

	std::vector<int> a(n);
	for (int i = 0; i < n; i++) {
		std::cin >> a[i];
	}

	for (int i = 0; i + 1 < n; i++) {
		int d = a[i + 1] > a[i] ? a[i + 1] - a[i] : a[i + 1] + m - a[i];

		// x=a[i+1] -> 1
		// x=a[i+1]-1 -> 2
		// x=a[i+1]-2 -> 3
		// ... 
		// x=a[i+1]-(d-1) -> d
		// x=a[i+1]-d -> d

		add(a[i + 1] + m - (d - 1), a[i + 1] + m + 1, d, -1);
		add(a[i + 1] + 1, a[i + 1] + m - (d - 1), d, 0);
	}

