// Fenwick tree with ranged updates and point queries. Complexity: O(log(n))
template<typename T> struct FenwickTree {
    int N;  vector<T> A;
    FenwickTree(int n): N(n+1), A(N) {}                    // Create tree with n elements
    void adjust(int b, T v) { for (;b;b-=b&-b) A[b]+=v; }              // Add v to A[0,b)
    void adjust(int a,int b, T v) { adjust(b,v), adjust(a,-v); }       // Add v to A[a,b)
    T pq(int i) { T r=0; for (i++;i<N;i+=i&-i) r+=A[i]; return r;	}           // Get A[i]
};

int main(){
    std::ios_base::sync_with_stdio(false); cin.tie(0);
    int n, m;
    cin >> n >> m;
    vi arr(n);
    ll Ma = 0;
    for (int i = 0; i < n; i++) {
        cin >> arr[i];
        arr[i] %= m;
    }
    FenwickTree<ll> tree(m+10);

    vector<ll> acc(m+10), dec(m+10);
    for (int i = 1; i < n; i++){
        int a = arr[i-1], b = arr[i];
        if (a < b) {
            Ma += b-a;
            acc[a+2]++;
            dec[b]++;
            tree.adjust(b+1, m, -(b-1-a));
        } else {
            Ma += (b + m - a);
            acc[a+2]++;
            //
            int c = m-(a+2);
            acc[0]++;
            tree.adjust(0, b+1, c);
            // minus
            dec[b]++;
            tree.adjust(b+1, m, -(b+1));
        }
    }
    ll best = LLONG_MIN/2;
    ll accum = 0;
    ll sum = 0;
    for (int i = 0; i < m; i++){
        accum += acc[i];
        sum += accum;
        ll cur = sum + tree.pq(i);
        best = max(best, cur);
        accum -= dec[i];
    }
    cout << Ma - best << endl;
}

