    LazySegmentTree seg2(vector<ll>(100000+10,0));
    rep(i,n-1){
        if(a[i]<a[i+1]){
            seg1.add(0,a[i],a[i+1]-a[i]);
            seg1.add(a[i],a[i+1],1+a[i+1]);
            seg2.add(a[i],a[i+1],1);
