using namespace std;
struct nodo
{
	ll valor;
	ll totbarrera,inicial;
	nodo(){}
};
nodo tree[tam];

void push(nodo &algo,ll &pnodo,ll &iz,ll &der)
{
	if (algo.totbarrera+algo.inicial!=0)
	{
		if (iz!=der)
		{
			nodo &hijo1=tree[pnodo*2];
			nodo &hijo2=tree[pnodo*2+1];

			hijo1.totbarrera+=algo.totbarrera;
			hijo2.totbarrera+=algo.totbarrera;

			ll m=(iz+der)/2;
			hijo1.inicial+=algo.inicial;
			hijo2.inicial+=algo.inicial+(m-iz+1);
		}
		else
		{
			algo.valor+=algo.totbarrera+algo.inicial;
		}
		//algo.inicial=algo.totbarrera=0;
	}else assert(algo.totbarrera==0 && algo.inicial==0);
	algo.inicial=algo.totbarrera=0;
}
void clr()
{
	forr(i,0,tam)
	{
		tree[i].valor=tree[i].totbarrera=tree[i].inicial=0;
	}
}

ll v[tam];
ll N,M;


void query(ll pnodo,ll iz,ll der,ll li,ll ri,nodo &cambio)
{

	if (iz>ri || der<li)
		return;
	push(tree[pnodo],pnodo,iz,der);
	if (iz>=li && der<=ri)
	{
		//<<"entro "<<iz<<' '<<der<<endl;
		tree[pnodo].totbarrera+=cambio.totbarrera;
		tree[pnodo].inicial+=cambio.inicial;
		cambio.inicial+=(der-iz+1);
		return;
	}
	initseg;
	query(new_nodo,iz,mid,li,ri,cambio);
	query(new_nodo+1, mid+1,der,li,ri,cambio);
}
ll buscar(ll pnodo,ll iz,ll der)
{
	push(tree[pnodo],pnodo,iz,der);
	if (iz==der)
	{
		return tree[pnodo].valor;
	}
	initseg;
	return max(buscar(new_nodo,iz,mid)
		,		buscar(new_nodo+1,mid+1,der));

}
void change(ll pos1,ll pos2)
{
	pos1++,pos2++;
	nodo cambio;
	cambio.totbarrera=1;
	cambio.inicial=0;
	if (pos1>pos2)
	{
		//<<"camibol 2";
		//<<pos1<<' '<<M<<' '<<1<<' '<<pos2<<endl;
		query(1,1,M,pos1,M,cambio);
		query(1,1,M,1,pos2,cambio);
	}
	else
	{
		//<<"cambio 1\n";
		//<<pos1<<" "<<pos2<<endl;
		query(1,1,M,pos1,pos2,cambio);
	}
}
