int N, M;

int main(){
  cin.tie(0);
  ios_base::sync_with_stdio(false);

  cin >> N >> M;
  VI xs(N);
  REP(i,N){
	cin >> xs[i];
	--xs[i];
  }

  VL del(M+10);
  LL sum = 0;
  REP(i,N-1){
	LL d;
	if(xs[i] < xs[i+1]){
	  d = xs[i+1] - xs[i];
	  sum += min(d, 1LL + xs[i+1]);
	}
	else{
	  d = M - xs[i] + xs[i+1];
	  sum += min(d, 1LL + xs[i+1]);
	}

	int l = xs[i+1] - d + 1;
	if(0 <= l){
	  del[l]--;
	  del[xs[i+1]]++;
	  del[xs[i+1]] += d-1;
	  del[xs[i+1]+1] -= d-1;
	}
	else{
	  l = xs[i+1] + 1;
	  del[0]--;
	  del[xs[i+1]]++;
	  del[xs[i+1]] += d-1;
	  del[xs[i+1]+1] -= d-1;
	  del[M-d+l]--;
	}
  }

  REP(i,M) del[i+1] += del[i];

  LL ans = sum;
  REP(i,M){
	mini(ans, sum);
	sum += del[i];
  }
  cout << ans << endl;

  return 0;
