template <typename T>
class CircleVector
    : private std::vector<T, std::allocator<T>> {
   public:
	using std::vector<T>::vector;
	T &operator[](int i) {
		int sz = this->size();
		i = (i % sz + sz) % sz;
		return vector<T, std::allocator<T>>::operator[](i);
	}
};

signed main() {
	int n, m;
	cin >> n >> m;

	vector<int> a(n);
	for (int i = 0; i < n; i++) {
		cin >> a[i];
		a[i]--;
	}

	int s = a[0];

	CircleVector<vector<P>> t(m);

	auto dist = [&](int s, int t) {
		if (s <= t)
			return t - s;
		else
			return m - s + t;
	};

	REP(i, 1, n) {
		if (dist(a[i - 1], a[i]) >= 2) {
			t[a[i - 1] + 2].push_back(P(i, -1));
			t[a[i] + 1].push_back(P(i, dist(a[i - 1], a[i]) - 1));
		}
	}

	vector<int> v(m, 0);
	vector<int> mp(n, 0);
	int ad = 0;
	int sz = 0;
	rep(i, m * 3) {
		int j = i % m;
		each(k, t[j]) {
			if (mp[k.first] == 0 && k.second == -1) {
				sz++;
				mp[k.first] = 1;
			} else if (mp[k.first] == 1 && k.second != -1) {
				sz--;
				ad -= k.second;
				mp[k.first] = -1;
			}
		}
		ad += sz;
		v[j] += ad;
	}

	int best = -1;
	int ma = 0;
	rep(i, m) {
		if (ma < v[i]) {
			ma = v[i];
			best = i;
		}
	}

	int ans = 0;
	REP(i, 1, n) {
		//s -> a[i]
		ans += min(dist(a[i - 1], a[i]), dist(best, a[i]) + 1);
	}
	cout << ans << endl;

	return 0;
}

