		if (a[i] < a[i + 1]) {
			sum += item = a[i + 1] - a[i];

			if (item > 1) {
				imos[a[i] + 2] -= 1;
				imos[a[i + 1] + 1] += item;
				imos[a[i + 1] + 2] -= (item - 1);

				imos[m + a[i] + 2] -= 1;
				imos[m + a[i + 1] + 1] += item;
				imos[m + a[i + 1] + 2] -= (item - 1);
			}
		}
		else {
			sum += item = (m - (a[i] - a[i + 1]));

			if (item > 1) {
				imos[a[i] + 2] -= 1;
				imos[m + a[i + 1] + 1] += item;
				imos[m + a[i + 1] + 2] -= (item - 1);
			}
		}

	}

	sll delta = 0;
	sll deltadelta = 0;
	for (i = 0; i < m * 2; i++) {
		deltadelta += imos[i];
		delta += deltadelta;
		if (result > delta) result = delta;
	}

	result += sum;
	assert(result > 0);

	printf("%lld\n", result);

	return 0;
}

