template<typename T> class BIT {
   private:
      vector<T> bit;
      int len;
   public:
      BIT(int n) : len(n+1), bit(n+1) {}
      void add(int i, T x) {
         i += 1;
         while (i < len) {
            bit[i] += x;
            i += i & -i;
         }
      }
      T sum(int i) {
         i += 1;
         T s = 0;
         while (i > 0) {
            s += bit[i];
            i -= i & -i;
         }
         return s;
      }
};
template<typename T> class CircleRAQ {
   private:
      BIT<T> bit;
      int mod;
   public:
      CircleRAQ(int n, int mod_n=MOD_N) : bit(n), mod(mod_n) {}
      void add(int l, int r, int x) {
         bit.add(l, x);
         bit.add((r+1) % mod, -x);
         if (l > (r+1) % mod) bit.add(0, x);
      }
      T val(int i) {
         return bit.sum(i);
      }
};

