void pushdown(int node, int L, int R) {
	if (leaf[node]) {
		val[node] += _lz[node].FI;
		_lz[node] = mp(0, 0);
		return;
	}

	int mid = (L + R) >> 1;
	int rem = mid - L + 1;
	_lz[node * 2].FI += _lz[node].FI;
