#include <bits/stdc++.h>
#define mid (left+right)/2
using namespace std;
const int MAXN = 100010;
int a[MAXN];
int x;
int m;
long long st[4 * MAXN];
int lazy[4 * MAXN];
bool lazied[MAXN];
void propagate(int idx, int left, int right){
    if(lazied[idx]){
        st[idx] += 1ll * lazy[idx] * (right - left + 1) + 1ll * (right - left) * (right - left + 1) / 2;
        if(left != right){
            lazied[2 * idx] = true;
            lazy[2 * idx] += lazy[idx];
            lazied[2 * idx + 1] = true;
            lazy[2 * idx + 1] += lazy[idx] + (mid - left + 1);
        }
        lazy[idx] = 0;
        lazied[idx] = false;
    }
}
void update(int idx, int left, int right, int l, int r, int val){
    //cout << idx << " " << left << " " << right << " " << l << " " << r << " " << val << endl;
    if(l <= left && right <= r){
        lazy[idx] += val;
        lazied[idx] = true;
        return;
    }
    propagate(idx, left, right);
    if(r > mid) update(2 * idx + 1, mid + 1, right, l, r, val + (mid - l + 1));
    if(l <= mid) update(2 * idx, left, mid, l, r, val);
    propagate(2 * idx, left, mid);
    propagate(2 * idx + 1, mid + 1, right);
    st[idx] = st[2 * idx] + st[2 * idx + 1];
}
long long query(int idx, int left, int right, int l, int r){
    propagate(idx, left, right);
    if(l <= left && right <= r) return st[idx];
    long long ret = 0;
    if(r > mid) ret += query(2 * idx + 1, mid + 1, right, l, r);
    if(l <= mid) ret += query(2 * idx, left, mid, l, r);
    return ret;
}
int dist(int x, int y){
    int ret = y - x;
    if(ret < 0) ret += m;
    return ret;
}
int main(){
    int n;
    cin >> n >> m;
    long long bad = 0;
    for(int i = 1; i <= n; i++) cin >> a[i];
    for(int i = 2; i <= n; i++){
        int cur = a[i];
        int prev = a[i - 1];
        bad += dist(prev, cur);
        if(cur == prev) continue;
        if(cur >= prev){
            //cout << prev + 1 << " " << cur << " " << 0 << endl;
            update(1, 1, m, prev + 1, cur, 0);
        } else {
            if(prev != m) {
                update(1, 1, m, prev + 1, m, 0);
                //cout << prev + 1 << " " << m << " " << 0 << endl;
            }
            int taken = m - (prev + 1);
            //cout << 1 << " " << cur << " " << taken + 1 << endl;
            update(1, 1, m, 1, cur, taken + 1);
        }
        //for(int i = 1; i <= m; i++) cout << query(1, 1, m, i, i) << " " ;
        //cout << endl;
    }
    long long maxx = 0ll;
    for(int i = 1; i <= m; i++){
        //cout << query(1, 1, m, i, i) << endl;
        maxx = max(maxx, query(1, 1, m, i, i));
    }
    cout << bad - maxx << endl;
    return 0;
}

