int to_next_simple(const int k1, const int k2) {
    if (k1 <= k2) {
        return k2 - k1;
    } else {
        return M + k2 - k1;
    }
}

int to_next(const int k1, const int k2, const int x) {
    return std::min(to_next_simple(k1, k2), 1 + to_next_simple(x, k2));
}

int step_add(const int k, const int add) {
    if (k + add <= M) {
        return k + add;
    } else {
        k + add - M;
    }
}

