			d[a[i + 1] + 1] -= a[i + 1] - a[i] + m;
			d[a[i + 1] + 2] += a[i + 1] - a[i] + m - 1;
			Ans += a[i + 1] - a[i] + m;
		}
	for(int i = 1; i <= m; i++)
		d[i] += d[i - 1];
	for(int i = 1; i <= m; i++)
		d[i] += d[i - 1];
	ll S = 0;
	for(int i = 1; i <= m; i++) S = max(S, d[i]);
	printf("%lld\n", Ans - S);
}

