	for (int i = 2; i <= m; ++i)
		f[i] += f[i - 1];
	for (int i = 2; i <= m; ++i)
		f[i] += f[i - 1];

	s64 res = -*max_element(f + 1, f + m + 1);
	for (int i = 2; i <= n; ++i)
		res += a[i] - a[i - 1] + (a[i] > a[i - 1] ? 0 : m);

	cout << res << endl;

	return 0;
}

