			add(vl[i-1]+1,m,m-vl[i-1]+vl[i],-1);
		}
	}
	for(int i=1;i<=m;i++) cost_d[i]+=cost_d[i-1];
	for(int i=1;i<=m;i++) cost[i]+=cost[i-1]+cost_d[i];
	long long minv=cost[1];
	for(int i=2;i<=m;i++) {
		if(minv>cost[i]) minv=cost[i];
	}
	cout << minv << endl;
	return 0;
}

