struct Event{
    bool b;
    int val;
    int ind;
    Event(int ind ,int val, bool b) : ind(ind), val(val), b(b) {}
};

int comp(Event &e1, Event &e2){
    if(e1.ind < e2.ind) return 1;
    if(e1.ind > e2.ind) return 0;
    return e1.b == true && e2.b == false;
}

int32_t main()
{
    ios_base::sync_with_stdio(false); cout << fixed <<setprecision(0);
    int n, m; cin >> n >> m;
    int last, sum = 0;
    vector<Event> arr;
    for(int i=0, cur = 0;i<n;i++){
        last = cur;
        cin >> cur; --cur;
        if(i == 0) continue;
        sum += (cur - last + m) % m;
        if(last < cur){
            arr.push_back({last, -1, false});
            arr.push_back({cur+1, cur - last - 1, true});
        }
        else{
            arr.push_back({last, -1, false});
            arr.push_back({m , m-1-cur - 1, true});

            arr.push_back({0, m-last - 1, false});
            arr.push_back({cur+1, cur - last + m -1, true});
        }
    }
    sort(all(arr), comp);
    int op = 0, maxi = 0, value = 0;
    for(int i = 0, pnt = 0; i<=m-1;i++){
        for(;pnt < arr.size() && arr[pnt].ind == i && arr[pnt].b == true;pnt++){
            value -= arr[pnt].val;
            op--;
        }
        int tmp = 0;
        value += op;
        for(;pnt < arr.size() && arr[pnt].ind == i && arr[pnt].b == false;pnt++){
            value += arr[pnt].val;
            tmp += (arr[pnt].val == 0);
            op++;
        }
        value += tmp;
        maxi = max(maxi, value - tmp);
    }
    cout << sum - maxi << endl;
    return 0;
}

