ll calc(vector<int>&a,int x,int m){
  ll ans=0;
  int n=a.size();
  for(int j=1;j<n;j++){
     ans+=min((a[j]>=a[j-1]?a[j]-a[j-1]:m-a[j-1]+a[j]),1+(a[j]>=x?a[j]-x:m-x+a[j]));
  }
  return ans;
}

