void solve()
{
    int n,m,i,a,b;
    in2(n,m);
    vi v(n);
    read(v,i,n);
    rep(i,n-1)
    {
        a=v[i],b=v[i+1];
        if(a==b)
            continue;
        if(a<b)
        {
            add(sum,1,a,b-a);
            add(sum,a+1,b,1+b);
            add(num,a+1,b,1);
            add(sum,b+1,m,b-a);
        }
        if(a>b)
        {
            add(sum,1,b,1+b);
            add(num,1,b,1);
            add(sum,b+1,a,b+m-a);
            add(sum,a+1,m,b+m+1);
            add(num,a+1,m,1);
        }
    }
    prefix(sum,m);
    prefix(num,m);
    lp(i,1,m+1)
        num[i]*=i,sum[i]-=num[i];
    ll ans=sum[1];
    lp(i,1,m+1)
        remin(ans,sum[i]);
    llout(ans);
}
