int read()
{
	int x=0,f=1;char ch=getchar();
	while (ch<'0'||ch>'9'){if (ch=='-') f=-1;ch=getchar();}
	while (ch>='0'&&ch<='9'){x=x*10+ch-'0';ch=getchar();}
	return x*f;
}
int n,m,now,ans;
int a[Maxn],cnt[Maxn],cntt[Maxn];
long long cnt1[Maxn],cntt1[Maxn];
int main()
{
	n=read(),m=read();
	memset(cnt,0,sizeof(cnt));
	memset(cntt,0,sizeof(cntt));
	memset(cnt1,0,sizeof(cnt1));
	memset(cntt1,0,sizeof(cntt1));
	for (int i=1;i<=n;i++) 
	{
		a[i]=read();
		if (i>2) ++cnt[a[i]];
		if (i<n) ++cntt[a[i]];
	}
	ans=0;
	int r=0;
	for (int i=1;i<n;i++)
	{
		if (a[i+1]>a[i]) ans+=a[i+1]-a[i];
		else ans+=a[i+1];
		if (a[i+1]>a[i]) cnt1[a[i+1]]+=a[i+1]-a[i];
		else cnt1[a[i+1]]+=m-a[i]+a[i+1];
		if (a[i+1]>a[i]) cntt1[a[i]]+=a[i+1]-a[i];
		else 
		{
			cntt1[a[i]]+=m-a[i]+a[i+1];
			if (a[i]!=m) ++r;
		}
	}
	now=ans;
	for (int i=2;i<=m;i++)
	{
		now=now-cnt[i-1]+cnt1[i-1];
		r-=cnt[i-1];
		r+=cntt[(i-2)%m==0?m:(i-2)%m];
		now-=r;
		ans=min(ans,now);
	}
	printf("%d\n",ans);
	return 0;
}

