            num += G[i-1][k];
            a--;
        }
        a += y[i];
        z[i] = num - a;
    }
    ans = INF;
    for(i=1;i<=m;i++){
        ans = min(ans,z[i]);
        //pe(i);p(z[i]);
    }
    p(ans);

    return 0;
}

