int main() {
  int N, M;
  cin >> N >> M;
  for (int i = 0; i < N; i++) {
    int ai;
    cin >> ai;
    a[i] = ai-1;
  }
  // count separation that satisfies a_i < x < a_i+1
  for (int i = 1; i < N; i++) {
    int begin = a[i-1] + 1;
    int end = a[i];
    if (begin > end) {
      end += M;
    }
    m[begin]++;
    m[end]--;
  }

  // for (int i = 0; i < 2*M; i++) {
  //   cout << m[i] << " ";
  // }
  // cout << endl;

  for (int i = 1; i < 2*M; i++) {
    m[i] += m[i-1];
  }
  // cout << "sep count:" << endl;
  // for (int i = M; i < 2*M; i++) {
  //   m[i-M] += m[i];
  //   cout << m[i-M] << " ";
  // }
  // cout << endl;

  ll count = 0; // count when x = 1
  for (int i = 1; i < N; i++) {
    if (a[i-1] < a[i]) {
      count += a[i] - a[i-1];
    }
    else {
      count += a[i] + 1;
    }
  }
  // cout << "x = 0: " << count << endl;
  ll ans = count;
  for (int i = 1; i < M; i++) {
    ll cx = count - m[i-1];
    for (int j = 1; j < N; j++) {
      if (a[j] == i-1) {
	cx += (M + a[j] - a[j-1]) % M - 1;
      }
    }
    //cout << "x = " << i << ": " << cx << endl;
    ans = min(ans, cx);
    count = cx;
  }
  cout << ans << endl;
}

