const int MAXN = 1e5 + 5;

ll sweep[MAXN], flat[MAXN];

ll m;
ll global;

void add(ll x, ll y) {
  if(x < y && y - x > 1) {
    sweep[x + 2] += +1;
    sweep[y + 1] += -1;
    flat[y + 1] += abs(1 - (y - x));

    global += y - x;
  }
  else if(x > y) {
    sweep[1] += 1;
    sweep[y + 1] -= 1;
    flat[y + 1] += abs(1 - (m - x + y));

    sweep[x + 2] += 1;

    global += x;
  }
  else if(x < y && y - x == 1) {
    global += 1;
  }
}

int a[MAXN];

int main() {

  int n; cin >> n >> m;
  REP(i, n) {
    cin >> a[i];
  }

  REP(i, n - 1) {
    add(a[i], a[i + 1]);
  }

  ll sol = 0, tmp = 0, current = 0;

  FOR(i, 1, m + 1) {
    tmp += sweep[i];
    current += flat[i] - tmp;
    sol = min(sol, current);
  }
  cout << sol + global;
}

