int n,a[101010],tot = 0,m;
struct Node {
	int st,ed,lazy,gx;
	Node *l,*r;
}*root,pool[404040];
inline void buildt (Node *&now,int st,int ed) {
	now = &pool[++tot];
	now->st = st;
	now->ed = ed;
	now->gx = now->lazy = 0;
	if (st == ed)
		return ;
	buildt(now->l,st,(st+ed)/2);
	buildt(now->r,(st+ed)/2+1,ed);
}
inline void down(Node *now) {
	if (now->st == now->ed)
		return ;
	if (!now->lazy)
		return ;
	now->l->lazy += now->lazy-(now->ed-now->l->ed)*now->gx;
	now->l->gx += now->gx;
	now->r->lazy += now->lazy;
	now->r->gx += now->gx;
	now->gx = now->lazy = 0;
}
inline void Add(Node *now,int pos,int v) {
	if (now->st > pos || now->ed <= pos-v)
		return ;
	if (now->st > pos-v && now->ed <= pos) {
		now->lazy += v+now->ed-pos;
		now->gx++;
		return ;
	}
	down(now);
	Add(now->l,pos,v);
	Add(now->r,pos,v);
}
inline int getmax(Node *now) {
	if (now->st == now->ed)
		return now->lazy;
	down(now);
	return max(getmax(now->l),getmax(now->r));
}
