			dis += m;
		ans += dis;
		dis--;
		Add(root,a[i+1],dis);
		if (dis > a[i+1])
			Add(root,m,dis-a[i+1]);
		//getmax(root);
	}
	ans -= getmax(root);
	printf("%d",ans);
	return 0;
}

