void modify(int v,int l,int r,int ql,int qr,int k,int b){
 //   printf("%d %d %d %d %d %d\n",l,r,ql,qr,k,b);
    if(qr<ql)return;
    if(l>=ql&&r<=qr){
        K[v]+=k;
        B[v]+=b;
        return;
    }int mid=(l+r)>>1;
    if(mid>=ql)modify(v<<1,l,mid,ql,qr,k,b);
    if(mid<qr)modify((v<<1)|1,mid+1,r,ql,qr,k,b);
}

ll query(int v,int l,int r,int pos){
    if(l==r)return (ll)K[v]*l+B[v];
    K[v<<1]+=K[v];
    K[(v<<1)|1]+=K[v];
    K[v]=0;
    B[v<<1]+=B[v];
    B[(v<<1)|1]+=B[v];
    B[v]=0;
    int mid=(l+r)>>1;
    if(mid>=pos)return query(v<<1,l,mid,pos);
    else return query((v<<1)|1,mid+1,r,pos);
}

