class Imos {
public:
    const unsigned int N;
    vector<long long> dp;
    Imos(unsigned int N) : N(N) {
        dp = vector<long long>(N + 10);
    }

    // [a, b]にkを加える
    void add(int a, int b, int k) {
        dp[a] += k;
        dp[b + 1] -= k;
    }

    // 円環状で[a, b]にk加える
    void add_circle(int a, int b, int k) {
        if (a <= b) {
            add(a, b, k);
        }
        else {
            add(b, N, k);
            add(0, b, k);
        }
    }

    void build() {
        for (int i = 0; i < dp.size() - 1; ++i) {
            dp[i + 1] += dp[i];
        }
    }

    void print() {
        for (int i = 0; i < dp.size(); ++i) {
            if (i != 0) { cout << " "; }
            cout << dp[i];
        }
        cout << endl;
    }

};


void solve(long long m, vector<long long> &a){

    Imos imos1(m), imos2(m);
    LL naive = 0;
    FOR(i, 0, a.size() - 1) {
        int b = a[i];
        int e = a[i + 1];

        if (b <= e){
            // [b + 1, e]
            imos1.add(b + 1, e, -(b + 1));
            imos2.add(b + 1, e, 1);

            naive += e - b;
        }
        else{
            imos1.add(b + 1, m - 1, -(b + 1));
            imos1.add(0, e, m - b - 1);

            imos2.add(b + 1, m - 1, 1);
            imos2.add(0, e, 1);

            naive += m - (b - e);
        }
    }
    imos1.build();
    imos2.build();

    LL ans = LONG_LONG_MAX;
    FOR(i, 0, m) {
        ans = min(ans, naive - (imos1.dp[i] + i * imos2.dp[i]));
    }

    cout << ans << endl;
}

