	for (int i=1;i<=n;++i) scanf("%d",a+i);
	LL sum=0;
	for (int i=1;i<n;++i) {
		sum+=dist(a[i],a[i+1]);
		if (a[i]<a[i+1]) {
			if (dist(a[i],a[i+1])<=1) continue;
			s.add(1,1,a[i]+2,a[i+1]);
		} else {
			if (dist(a[i],a[i+1])<=1) continue;
			if (a[i]<m-1) s.add(1,1,a[i]+2,m);
			int b=dist(a[i],1)-1;
			s.add(1,b,1,a[i+1]);
		}
	}
	LL mx=0;
	for (int i=1;i<=n;++i) {
		LL t=s.query(i);
		if (t>mx) mx=t; 
	}
