	for(int i = 1; i < n; ++i) {
		if(a[i] <= a[i+1]) {
			upd(0, a[i], a[i+1] - a[i]);
			upd(a[i+1] + 1, m - 1, a[i+1] - a[i]);

			upd(a[i] + 1, a[i+1], 1 + a[i + 1]);
			upd_minus(a[i] + 1, a[i+1]);
		}
		else {
			upd(a[i+1] + 1, a[i], a[i+1] + m - a[i]);

			upd(0, a[i+1], 1 + a[i+1]);
			upd_minus(0, a[i+1]);

			upd(a[i] + 1, m - 1, 1 + m + a[i + 1]);
			upd_minus(a[i] + 1, m - 1);
		}
	}
	for(int i = 0; i < m; ++i) {
		if(i > 0) {
			val[i] += val[i-1];
			p[i] += p[i-1];
		}
		if(ans == -1 || ans >= p[i] - val[i] * i)
			ans = p[i] - val[i] * i;
	}
	cout << ans << endl;
	return 0;
}

