  /// 1 + a[i + 1] - fav - a[i + 1] + a[i]
  /// 1 - fav + a[i]
  /// a[i] > a[i + 1] && fav <= a[i + 1]
  /// 1 + a[i + 1] - fav - a[i + 1] + a[i] - m
  /// 1 - fav + a[i] - m
  /// 1 + (fav - a[i + 1] + m) - (a[i] - a[i + 1] + m)
  /// 1 + fav - a[i]

  for(int i = 1; i < n; ++i){
