  ll cand = sum;

  out(sum);
  out(xfory);
  out(imos);

  rep(f, 1, m) {
    forr(x, xfory[f]) {
      cand--;
      cand += (f+m-x)%m;
    }
    cand -= imos[f];
    out(f, imos[f], cand);
    amin(ans, cand);
  }

  return ans;
}

