    repx(i, 1, N){
        if(a[i - 1] > a[i]) cnt += (LL)(a[i] + (M - a[i - 1] > 0));
        else if(a[i] == M)  cnt++;
        else                cnt += (LL)(a[i] - a[i - 1]);
    }

    // 3. 増加分.
    repx(i, 1, N) up[a[i]] += (LL)((a[i] + M - a[i - 1]) % M - 1);
    // rep(i, M + 1) printf("i=%d up=%d\n", i, up[i]);

    // 4. 減少分.
