        cur = bef + up[idx] - down[idx];
        // printf("cur=%d bef=%d up=%d down=%d\n", cur, bef, up[idx], down[idx]);

        // 最小値更新.
        ans = min(ans, cur);

        // 前回分更新.
        bef = cur;
    }
    printf("%lld\n", ans);
    return 0;

}

