const int maxn = 2e5 + 5;

int n , a[maxn] , m;
ll s[maxn * 4] , lz[maxn * 4];
ll cnt[maxn * 4];
ll ans[maxn];

void Push(int x , int l , int r){
//    cout << l << " " << r << " " << x << " " << cnt[x] << " " << lz[x] << endl;
    if(l == r)return;
    lz[x * 2] += lz[x];
    lz[x * 2 + 1] += lz[x] + ((l + r) / 2 - l + 1) * cnt[x];
    cnt[x * 2] += cnt[x];
    cnt[x * 2 + 1] += cnt[x];
    lz[x] = cnt[x] = 0;
}

void update(int x , int l , int r , int L , int R , int delta){
//    Push(x , l , r);
//    cout << x << " " << l << " " << r << " " << L << " " << R << " " << delta << endl;
    if(L > r || l > R)return ;
    if(L <= l && r <= R){
        lz[x] += delta + l - L;
        cnt[x]++;
        return;
    }
    int mid = l + r >> 1;
    update(x * 2 , l , mid , L , R , delta);
    update(x * 2 + 1 , mid + 1 , r , L , R , delta);
}

void Build(int x , int l , int r){
    Push(x , l , r);
    if(l == r){
        ans[l] = lz[x];
        return;
    }
    int mid = l + r >> 1;
    Build(x * 2 , l , mid);
    Build(x * 2 + 1 , mid + 1 , r);
}

