            update(1 ,1,m,a[i]+1,a[i+1],0);
//            cout << a[i] + 1 << " " << a[i + 1] << " " << 0 << endl;
            res += a[i + 1] - a[i];
        }else{
            update(1 , 1 , m , a[i]+1,m,0);
            update(1 , 1 , m , 1,a[i + 1],m - a[i]);
//            cout << a[i] + 1 << " " << m << " " << 0 << endl;
//            cout << 1 << " " << a[i + 1] << " " << m - a[i] << endl;
            res += m - a[i] + a[i + 1];
        }
    }
