vector<int> v2l[maxn],v2r[maxn];

ll res[maxn];
int main() {
#ifdef suiyuan2009
  freopen("in.cpp","r",stdin);
#endif
  cin>>n>>m;
  ll sum=0;
  for(int i=1;i<=n;i++){
    cin>>a[i];
    if(i>1){
      if(a[i]>a[i-1]){
        sum+=a[i]-a[i-1];
        if(a[i-1]+1<a[i]) {
          v1r[a[i]].push_back(a[i-1]);
          v1l[a[i-1]].push_back(a[i]);
        }
      } else {
        int tt=m-a[i-1]+a[i];
        sum+=tt;
        if(tt>1){
          v2l[a[i-1]].push_back(a[i]+m);
          v2r[a[i]+m].push_back(a[i-1]);
        }
      }
    }
  }
  ll reduce=0;
  int cnt=0;
  int cnt0=v1l[1].size();
  for(int i=2;i<=m;i++){
    reduce+=cnt;
    res[i]+=reduce;
    cnt+=cnt0;
    cnt0=v1l[i].size();
    cnt-=v1r[i].size();
    for(int j=0;j<(int)v1r[i].size();j++){
      int tt=v1r[i][j];
      reduce-=(i-tt-1);
    }
  }
  reduce=0,cnt=0,cnt0=0;
  for(int i=1;i<=m;i++){
    cnt+=v2l[i].size();
    reduce+=(m-i)*(ll)v2l[i].size();
  }
  res[1]+=reduce;
  cnt-=v2r[m+1].size();
  for(int i=0;i<(int)v2r[m+1].size();i++){
    int tt=v2r[m+1][i];
    reduce-=m-tt;
  }
  for(int i=m+2;i<m+m;i++){
    reduce+=cnt;
    res[i-m]+=reduce;
    cnt-=v2r[i].size();
    for(int j=0;j<(int)v2r[i].size();j++){
      int tt=v2r[i][j];
      reduce-=(i-tt-1);
    }
  }
  ll mx=0;
  for(int i=1;i<=m;i++)mx=max(mx,res[i]);
  cout<<sum-mx<<endl;
  return 0;
}

