#define N 100005

int n, m, arr[N];
int f(int);
inline int dis(int, int);

int main(){
	srand(time(NULL));
	ios_base::sync_with_stdio(0);cin.tie(0);
	cin>>n>>m;
	for(int i=0;i<n;i++) cin>>arr[i];
	double step=m, tt=0.9;
	int x=rand()%m + 1, y=f(x);
	while(step>1){
		int newX = max(0, int(x+((rand()&1)?1:-1)*rand()/(3*step))%m), newY=f(newX);
		if(newY < y){
			x = newX; 
			y = newY;
		}
		step*=tt;
	}
	cout<<y<<'\n';
	return 0;
}

inline int dis(int p, int q){
	return q>=p? q - p : q + m - p;
}

int f(int b){
	int r=0;
	for(int i=1;i<n;i++)
		r += min(dis(arr[i-1], arr[i]), dis(b, arr[i])+1);
	return r;
}

