int calc(int x){
  int sum = 0;
  for(int i=1;i<n;i++){
    int a = A[i-1] - 1,b = A[i] - 1;
    if(a == b) continue;
    int cost = min((m + b - a)%m,(m + b - x)%m + 1);
    sum+=cost;
  }
  return sum;
}

signed main(){

