      Sum[a+1]++,Sum[b]--;
      Sum[m+a+1]++,Sum[m+b]--;
      Sum2[b] += b-a-1;
      Sum2[m+b] += b-a-1;
    }
    else {
      Sum[a+1]++,Sum[m+b]--;
      Sum2[b+m] += b+m-a-1;
