#define N_MAX 300000

ull n, m;
ull a[N_MAX];
sll imos[N_MAX + 5];

ull solve() {
	sll i, j;
	sll result = 0;
	ull sum = 0;
	ull item;

	for (i = 0; i < n; i++) {
		a[i]--;
	}

	for (i = 0; i < n - 1; i++) {
		if (a[i] < a[i + 1]) {
			sum += item = a[i + 1] - a[i];

			if (item > 1) {
				imos[a[i] + 2] -= 1;
				imos[a[i + 1] + 1] += item;
				imos[a[i + 1] + 2] -= (item - 1);

				imos[m + a[i] + 2] -= 1;
				imos[m + a[i + 1] + 1] += item;
				imos[m + a[i + 1] + 2] -= (item - 1);
			}
		}
		else {
			sum += item = (m - (a[i] - a[i + 1]));

			if (item > 1) {
				imos[a[i] + 2] -= 1;
				imos[m + a[i + 1] + 1] += item;
				imos[m + a[i + 1] + 2] -= (item - 1);
			}
		}

	}

	sll delta = 0;
	sll deltadelta = 0;
	for (i = 0; i < m * 2; i++) {
		deltadelta += imos[i];
		delta += deltadelta;
		if (result > delta) result = delta;
	}

	result += sum;
	assert(result <= 0);

	printf("%ll\n", result);

	return 0;
}

