            S[++ tot] = (node){a + 1, -1, 1 + a};
            S[++ tot] = (node){b + 1, 1, -a - 1};
        }
        else
        {
            K --;
            B += b + 1;
            S[++ tot] = (node){b + 1, 1, (m - a + b) - (b + 1)};
            S[++ tot] = (node){a + 1, -1, 1 + a};
        }
    }
    sort(S + 1, S + tot + 1, comp);
    for (int i = 1, j = 1; i <= m; ++ i)
    {
        while (j <= tot && S[j].p <= i)
        {
            K += S[j].k;
            B += S[j].b;
            j ++;
        }
        // cerr << K * i + B << endl;
        ans = min(ans, K * i + B);
