//        cout << "mx: " << mx << endl;
//        cout << 1 << ' ' << l << ' ' << r << endl;
        if (l <= r && chk(l) && chk(r)) {
            tr.upd(l, r, mx, 0);
        }
        l = pos + 1;
        r = min(m, pos + m - mx + 1);
//        cout << 2 << ' ' << l << ' ' << r << endl;
        if (l <= r && chk(l) && chk(r)) {
            tr.upd(l, r, mx, 0);
        }
        l = max((num) 1, pos - mx + 2);
        r = pos;
        f = 1 + (pos - l);
//        cout << 3 << ' ' << l << ' ' << r << endl;
        if (l <= r && chk(l) && chk(r)) {
            tr.upd(l, r, f + (l - 1), -1);
        }
        l = pos + m - mx + 2;
