void go(int i, int l, int r, int num, int ind){
    if (r - l == 1){
        num += rmq[i].num;
        ind += rmq[i].ind;
        ans = min(ans, num - l * ind);
        return;
    }
    int mm = (l + r) / 2;
    go(2*i+1, l, mm, num + rmq[i].num, ind + rmq[i].ind);
    go(2*i+2, mm, r, num + rmq[i].num, ind + rmq[i].ind);
}
void change(int i, int l, int r, int l1, int r1, int first, int second){
    if (l1 >= r1) return;
    if (l1 == l && r1 == r){
        rmq[i].num += first;
        rmq[i].ind += second;
        return;
    }
    int mm = (l + r) / 2;
    change(2*i+1, l, mm, l1, min(r1, mm), first, second);
    change(2*i+2, mm, r, max(l1, mm), r1 , first, second);
}
signed main()
{
    cin >> n >> m;
    for (int i=0;i<n;i++){
        cin >> ai;
        data.push_back(ai-1);
    }
    for (int i=0;i<4*m;i++){
        Vertex v;
        v.num = 0;
        v.ind = 0;
        rmq.push_back(v);
    }
    for (int i=0;i<n-1;i++){
        int f = data[i];
        int s = data[i+1];
        if (f < s){
            change(0, 0, m, f+1, s+1, s+1, 1);
            change(0, 0, m, 0, f+1, (s-f), 0);
            change(0, 0, m, s+1, m, (s-f), 0);
        }
        else{
            change(0, 0, m, s+1, f+1, (s+m-f), 0);
            change(0, 0, m, f+1, m, m+s+1, 1);
            change(0, 0, m, 0, s+1, s+1, 1);
        }
    }
    ans = 1e18;
    go(0, 0, m, 0, 0);
    cout << ans << endl;
    return 0;
}

