const int MAXN = 1e5 + 5;

int N, M;
int A[MAXN];

void input()
{
    read(N); read(M);
    for (int i = 1; i <= N; ++i) {
        read(A[i]);
        --A[i];
    }
}

inline int dist(int s, int t)
{
    return (t - s + M) % M;
}

void solve()
{
    LL bias = 0;
    for (int i = 1; i < N; ++i) {
        bias += dist(A[i], A[i + 1]);
    }

    vector<Pii> events;
    LL val = 0, add = 0;
    LL ans = 1e18;

    for (int i = 1; i < N; ++i) {
        int s = A[i], t = A[i + 1];
        if (dist(s, t) <= 1)
            continue;
        if (s != 0 && dist(s, 0) + dist(0, t) == dist(s, t)) {
            val += dist(s, 0) - 1;
            add += 1;
        }
        events.push_back(MP(s + 1, 0));
        events.push_back(MP(t + 1, -(dist(s, t) - 1)));
    }
    std::sort(ALL(events));
    // printf("val=%lld\n", val);
    chkmin(ans, bias - val);

    for (int i = 1, j = 0; i < M; ++i) {
        for (; j < SZ(events) && events[j].x <= i; ++j) {
            val += events[j].y - !events[j].y;
            add += (events[j].y < 0 ? -1 : 1);
        }
        val += add;
        // printf("%d: %lld %lld\n", i, val, add);
        chkmin(ans, bias - val);
    }

    printf("%lld\n", ans);
}

int main()
{
#ifdef __DEBUG
    freopen("E.in", "r", stdin);
    freopen("E.out", "w", stdout);
#endif

    input();
    solve();
}

