void push(int v,int tl,int tr) {
	for (int i = 0; i < 2; i++) {
		lazy[v*2][i] += lazy[v][i]; 
		lazy[v*2+1][i] += lazy[v][i]; 
		lazy[v][i]=0;
	}
}
void get(int v,int tl,int tr) {
	if (tl == tr) {
		ll a = lazy[v][0]*tl;
		a += lazy[v][1];
		mx = max(mx,{a,tl});
		return;
	}
	int tm = (tl + tr)/2;
	push(v,tl,tr);
	get(v*2,tl,tm);
	get(v*2+1,tm+1,tr);
}
void add(int v,int tl,int tr,int l,int r,int type,int val) {
	if (r < tl || l > tr || l > r) return;
	if (l <= tl && r >= tr) {
		if (type == 0) {
			lazy[v][0]++;
		}
		else lazy[v][1] += val;
		return;
	}
	int tm = (tl + tr)/2;
	push(v,tl,tr);
	add(v*2,tl,tm,l,r,type,val);
	add(v*2+1,tm+1,tr,l,r,type,val);
}
