inline void work(int x, int y)
{
	b[x] += x; 
	k[x]--; 
	k[y]++; 
	if (x < y)
	{
		b[1] += y - x; 
		b[y] -= x; 
	}
	else
	{
		b[1] += y; 
		b[y] += m - x; 
		k[1]--; 
	}
}
int main()
{
	// freopen("ARC077-E.in", "r", stdin); 
	scanf("%d%d", &n, &m); 
	for (int i = 0; i < n; i++)
		scanf("%d", arr + i); 
