		work(arr[i] + 1, arr[i + 1] + 1); 
	ll ans = 1e18; 
	for (int i = 1; i <= m; i++)
	{
		k[i] += k[i - 1]; 
		b[i] += b[i - 1]; 
		ans = std::min(ans, k[i] * i + b[i]); 
	}
	printf("%lld\n", ans);
	return 0; 
}

