    v[i]=x-1LL;
  }
  ll ans = 0LL;
  vector<ll> B(M*2LL,0LL);
  for(ll i = 0; i < N-1LL; i++){
    if(v[i]<v[i+1]) {
      if(v[i+1]-v[i]<2LL) continue;
      B[v[i]+2]++;
      B[v[i+1]+1]--;
      ans+=v[i+1]-v[i];
    }
    if(v[i]>v[i+1]){
      if(v[i+1]+M-v[i]<2LL) continue;
      B[v[i]+2LL]++;
      B[v[i+1]+M+1]--;
      ans+=v[i+1]+M-v[i];
    }
  }
  for(ll i = 1LL; i < M*2LL; i++){
    B[i]=B[i-1]+B[i];
  }
  for(ll i = 0; i < N-1LL; i++){
    if(v[i]<v[i+1]) {
      if(v[i+1]-v[i]<2LL) continue;
      B[v[i+1]+1]-=v[i+1]-v[i]-1;
    }
    if(v[i]>v[i+1]){
      if(v[i+1]+M-v[i]<2LL) continue;
      B[v[i+1]+M+1]-=v[i+1]+M-v[i]-1;
    }
  }
  for(ll i = 1LL; i<M*2LL; i++){
    B[i]=B[i-1]+B[i];
  }
  vector<ll> A(M);
  for(ll i = 0LL; i < M;i++){
    A[i]=B[i]+B[i+M];
  }
  ll t = 0LL;
  for(auto x:A) {
    chmax(t,x);
  }
  ans-=t;
  cout<<ans<<endl;
}

