const int N = 100 * 1000 + 10;

ll delta_a[N];
ll delta_b[N];

void add_segm(int init_val, int l, int r) {
    delta_b[l]++;
    delta_a[l] += init_val - 1;
    delta_b[r + 1]--;
    delta_a[r + 1] -= init_val + (r - l); 
}

int main() {
#ifdef LOCAL
    // freopen("input", "r", stdin);
