    vector<int> a(n);
    for (int i = 0; i < n; i++) {
        cin >> a[i];
        --a[i];
    }
    for (int i = 0; i < n - 1; i++) 
        res += (a[i + 1] - a[i] + m) % m;
    if (m == 2) {
        cout << res << '\n';
        return 0;
    }
    for (int i = 0; i < n - 1; i++) {
        if (a[i] == a[i + 1])
            continue;
        if ((a[i] + 1) % m == a[i + 1])
            continue;
        int s = (a[i] + 2) % m;
        if (s <= a[i + 1])
            add_segm(1, s, a[i + 1]);
        else {
            add_segm(1, s, m - 1);
            add_segm(m - s % m + 1, 0, a[i + 1]);
        }
    }
    ll cura = 0;
    ll curb = 0;
    ll ans = res;
    for (int i = 0; i < m; i++) {
        curb += delta_b[i];
        cura += delta_a[i] + curb;
        ans = min(ans, res - cura);
    }
    //cerr << endl;
