	if(r<=mid) add(l,r,g,o+o);
	else if(l>mid) add(l,r,g,o+o+1);
	else add(l,mid,g,o+o),add(mid+1,r,L{g.x+g.y*(mid-l+1),g.y},o+o+1);
}
