using namespace std;

typedef long long ll;

int n, m;
vector<int> pos[100000 + 100];
ll a[100000 + 100];

int main() {
	cin >> n >> m;
	for (int i = 0; i < n; i++) {
		cin >> a[i];
		pos[a[i]].push_back(i);
	}

	ll ans = 0, cur = 0;
	int shortcut = 0;
	for (int i = 1; i < n; i++) {
		if (((m + a[i] - a[i - 1]) % m) >= ((m + a[i] - 1) % m) + 1) {
			//次のステップでshortcutから外れないものの個数を数え上げる。
			if (a[i] != 1) {
				//次から外れないもの
				shortcut++;
				cur += ((m + a[i] - 1) % m) + 1;
			}
			else cur += (m + a[i] - a[i - 1]) % m;
			ans += ((m + a[i] - 1) % m) + 1;
		}
		else ans += ((m + a[i] - a[i - 1]) % m), cur += ((m + a[i] - a[i - 1]) % m);

	}

	for (int x = 2; x <= m; x++) {

		cur -= shortcut;

		ans = min(ans, cur);

		//始点がx-1のものは、shortcutを使った方がより短いか同じ移動距離になる。
		for (int i = 0; i < pos[x - 1].size(); i++) {
			int idx = pos[x - 1][i];
			if (idx != n - 1) {//n-1番目ならば、始点にはなりえない。
				shortcut++;
			}
		}
		//終点がxのものは、shortcutから外して固定の移動距離になる。
		for (int i = 0; i < pos[x].size(); i++) {
			int idx = pos[x][i];
			if (idx != 0) {//0番目ならば、終点にはなりえない。
				shortcut--;
				cur += (m + a[idx] - a[idx - 1]) % m;
			}
		}

	}
	cout << ans << endl;
	return 0;
}

