template <typename T>
class LazySegmentTree {
	const int n;
	const T id;
	vector<T> data, data2;
	int size(int n) {
		int res = 1;
		while (res < n) res <<= 1;
		return res;
	}
	T sub(int l, int r, int node, int lb, int ub) {
		if (ub <= l || r <= lb) return id;
		if (l <= lb && ub <= r) {
			return data[node] + data2[node] * (ub - lb);
		}
		return data2[node] * (min(r, ub) - max(l, lb))
			+ sub(l, r, node * 2, lb, (lb + ub) / 2)
			+ sub(l, r, node * 2 + 1, (lb + ub) / 2, ub);
	}
	void suc(int l, int r, int node, int lb, int ub, T val) {
		if (ub <= l || r <= lb) return;
		if (l <= lb && ub <= r) {
			data2[node] += val;
			return;
		}
		data[node] += val * (min(r, ub) - max(l, lb));
		suc(l, r, node * 2, lb, (lb + ub) / 2, val);
		suc(l, r, node * 2 + 1, (lb + ub) / 2, ub, val);
	}
public:
	LazySegmentTree(int n_) :
		n(size(n_)), id(0), data(n * 2, id), data2(n * 2, id) {}
	void add(int l, int r, T val) {
		suc(l, r + 1, 1, 0, n, val);
	}
	T getSum(int l, int r) {
		return sub(l, r + 1, 1, 0, n);
	}
};

int main()
{
	ll n, m, res = 0;
	cin >> n >> m;
	vector<int> a(n);
	for(int i = 0;i < n;i++){
		cin >> a[i]; a[i]--;
	}
	LazySegmentTree<ll> lst(m);
	for(int i = 1;i < n;i++){
		res += (a[i] + m - a[i - 1]) % m;
		if(a[i] > a[i - 1]){
			lst.add(a[i - 1] + 2, a[i], 1);
			lst.add(a[i] + 1, a[i] + 1, -(a[i] - a[i - 1] - 1));
		}
		else if(a[i] < a[i - 1]){
			if(a[i - 1] + 2 <= m - 1){
				lst.add(a[i - 1] + 2, m - 1, 1);
				lst.add(0, 0, m - 1 - a[i - 1] - 1);
			}
			lst.add(max(0ll, a[i - 1] + 2 - m), a[i], 1);
			lst.add(a[i] + 1, a[i] + 1, -(a[i] + m - a[i - 1] - 1));
		}
	}
	ll ma = 0;
	for(int i = 0;i < m;i++){
		ma = max(ma, lst.getSum(0, i));
	}
	cout << res - ma << endl;
	return 0;
}

