	//freopen(".out","w",stdout);
	n=read(),m=read();
	for(LL i=2,x=read();i<=n;i++){
		LL y=read();
		if(x<y) tot+=y-x,q[++K]=seg(x,y),q[++K]=seg(x+m,y+m);
		else tot+=(y+m-x),q[++K]=seg(x,y+m); x=y;
	}sort(q+1,q+K+1),ans=tot;
//	return 0;
//	printf(" tot = %lld\n",tot);
//	for(LL i=1;i<=K;i++) printf("[ %d , %d ]\n",q[i].ls,q[i].rs);
	for(LL i=1;i<=K;i++) ins(rt[i],rt[i-1],1,m<<1,q[i].ls);
	for(LL now=0,i=(m<<1);i;i--){
		while(now<K&&q[now+1].rs>=i) now++;
		LL Cnt=0; LL Sum=0;
		qry(rt[now],1,m<<1,i,Cnt,Sum);
		ans=min(ans,tot-(Cnt*i-Sum)+Cnt);
//		if(ans==3) printf(" i = %d    Cnt = %d   Sum = %lld\n",i,Cnt,Sum );
	} write(ans),putchar('\n'); return 0;
}

