#define all(a) (a).begin(), (a).end()

ll count(ll a, ll b, int M) {
    return b - a + (a <= b ? 0 : M);
}

int main() {
    int N, M; cin >> N >> M;
    vl a(N);
    rep(i,N) cin >> a[i];
    // rep(i,N) a[i]--;

    vl imos(2*M+1, 0);
    rng(i,1,N) {
        int l = a[i-1]+2;
        int r = a[i]+1+(a[i-1]<a[i]?0:M);
        imos[l]++;
        imos[r]--;
    }
    rep(i,2*M) imos[i+1] += imos[i];
    rng(i,1,N) {
        int l = a[i-1]+2;
        int r = a[i]+1+(a[i-1]<a[i]?0:M);
        imos[r] -= r - l;
    }
    rep(i,2*M) imos[i+1] += imos[i];

    ll fav = 1, mx = 0;
    rep(i,2*M+1) {
        if (imos[i] > mx) {
            mx = imos[i];
            fav = i % M;
        }
    }

    int ans = 0;
    rng(i,1,N) {
        ans += min(count(a[i-1], a[i], M), count(fav, a[i], M) + 1);
    }
    cout << ans << endl;
    return 0;
}

