		if (a[i]<a[i+1] && a[i+1]-a[i]>=2) update(1,a[i]+2,a[i+1],1);
		//cout<<i<<endl;
		if (a[i]>a[i+1])
		{
			if (a[i]+2<=m) update(1,a[i]+2,m,1);
			if (m-a[i]>=1)
				update(1,1,a[i+1],m-a[i]);
			else
				if (a[i+1]>=2) update(1,2,a[i+1],1);

		}
		//cout<<query(1,4)<<endl;
