int main(){
  int N, M; scanf("%d%d", &N, &M);
  for(int i = 1; i <= N; i++) scanf("%d", &p[i]);

  for(int i = 2; i <= N; i++){
    int s = p[i - 1], e = p[i];
    int n = (e > s ? e - s : e - s + M);

    int rs = 1 + e - n, re = e;

    if(rs < 1){
      xv[1]--; cv[1] += e + 1;
      xv[e + 1]++; cv[e + 1] -= e + 1;
      cv[e + 1] += n; cv[rs + M] -= n;
      xv[rs + M]--; cv[rs + M] += e + M + 1;
      xv[M + 1]++; cv[M + 1] -= e + M + 1;
    }
    else{
      cv[1] += n; cv[rs] -= n;
      xv[rs]--; cv[rs] += e + 1;
      xv[re + 1]++; cv[re + 1] -= e + 1;
      cv[re + 1] += n; cv[M + 1] -= n;
    }
  }

  for(int i = 2; i <= M; i++){
    xv[i] += xv[i - 1]; cv[i] += cv[i - 1];
  }

  long long ans = LLONG_MAX;

  for(int i = 1; i <= M; i++){
    long long res = xv[i] * i + cv[i];
    if(res < ans) ans = res;
  }

  printf("%lld\n", ans);
  return 0;
}

