class RAQRMiQ :public SegTree<T, T> {
public:
	RAQRMiQ(int size, const T& def = T()) :SegTree<T, T>(size, def, INF, [](T a, T b) {return min(a, b); }, [](T a, T b) {return a + b; }, [](int range, T a, T b) {return a + b; }) {};
};
template<typename T>
class RAQRMaQ :public SegTree<T, T> {
