using namespace std;
long long n,a[101010],tot = 0,m;
struct Node {
	long long st,ed,lazy,gx;
	Node *l,*r;
}*root,pool[404040];
inline void buildt (Node *&now,long long st,long long ed) {
	now = &pool[++tot];
	now->st = st;
	now->ed = ed;
	now->gx = now->lazy = 0;
	if (st == ed)
		return ;
	buildt(now->l,st,(st+ed)/2);
	buildt(now->r,(st+ed)/2+1,ed);
}
inline void down(Node *now) {
	if (now->st == now->ed)
		return ;
	if (!now->lazy)
		return ;
	now->l->lazy += now->lazy-(now->ed-now->l->ed)*now->gx;
	now->l->gx += now->gx;
	now->r->lazy += now->lazy;
	now->r->gx += now->gx;
	now->gx = now->lazy = 0;
}
inline void Add(Node *now,long long pos,long long v) {
	if (now->st > pos || now->ed <= pos-v)
		return ;
	if (now->st > pos-v && now->ed <= pos) {
		now->lazy += v+now->ed-pos;
		now->gx++;
		return ;
	}
	down(now);
	Add(now->l,pos,v);
	Add(now->r,pos,v);
}
inline long long getmax(Node *now) {
	if (now->st == now->ed)
		return now->lazy;
	down(now);
	return max(getmax(now->l),getmax(now->r));
}
int main() {
	scanf("%lld%lld",&n,&m);
	for (int i = 1;i <= n; i++)
		scanf("%lld",&a[i]);
	buildt(root,1,m);
	long long dis,ans = 0;
	for (int i = 1;i < n; i++) {
		dis = a[i+1]-a[i];
		if (dis < 0)
			dis += m;
		ans += dis;
		dis--;
		Add(root,a[i+1],dis);
		if (dis > a[i+1])
			Add(root,m,dis-a[i+1]);
		//getmax(root);
	}
	ans -= getmax(root);
	printf("%lld",ans);
	return 0;
}

