  ll count = 0; // count when x = 1
  for (int i = 1; i < N; i++) {
    int begin = a[i-1] + 1;
    int end = a[i];
    if (begin > end) {
      end += M;
    }
    m[begin]++;
    m[end]--;

    if (a[i-1] < a[i]) {
      count += a[i] - a[i-1] ;
    }
    else {
      count += a[i] + 1;
    }

    additional_push[a[i]] +=  (M + a[i] - a[i-1]) % M - 1;
  }

  for (int i = 1; i < 2*M; i++) {
    m[i] += m[i-1];
    if (i >= M) {
