        if(x < pre)
            x += m;
        totall += x - pre;
        dis1[pre+1]++;
        dis1[x+1]--;
        dis2[pre+1] += pre+1;
        dis2[x+1] -= pre+1;
        pre = (x <= m ? x : x-m);
    }
    for(int i=1; i<=2*m; i++) {
        dis1[i] += dis1[i-1];
        dis2[i] += dis2[i-1];
    }
    LL answer = INF;
    for(int i=1; i<=2*m; i++) {
        LL x = dis1[i]*i - dis2[i];
        answer = min(answer, totall - x);
    }
    printf("%lld\n", answer);
}

