	for(int i = 0; i < n-1; ++i) Seg1.add(a[i] - (a[i+1]>a[i]?0:m) + m,1);
	for(int i = 0; i < n-1; ++i) Seg2.add(a[i] - (a[i+1]>a[i]?0:m) + m,a[i] - (a[i+1]>a[i]?0:m));

	ll sum = 0;
	for(int i = 1; i < n; ++i) sum += a[i];
