using namespace std;
int M,N,favor; // f = favorite
int count(int x, int y){
  if(x < y){
    if(x < favor && favor <= y) return y - favor + 1;
    else return y - x;
  }
  else{

    if(y < favor && favor <= x) return M - (x - y);
    else {
      int temp = (y - favor);
      if(temp < 0) temp += M;
      return temp + 1;
    }
  }
}

int main(){
  cin >> N >> M;
  int order[N], start[M], end[M], endcount[M], dist[M];
  for(int i = 0; i < N ; i++){
    cin >> order[i];
    start[i] = end[i] = 0;
  }
  for(int i = 0 ; i < M; i++){
    start[i] = end[i] = endcount[i] = dist[i] = 0;
  }
  for(int i = 0; i < N; i++){
    if(i != N - 1) start[order[i] - 1] += 1;
    if(i != 0){favor = order[i-1];
      end[order[i] - 1] += count(order[i-1],order[i]);
      //cout <<  count(order[i-1], order[i])  << "\n";
      endcount[order[i] - 1] += 1;
    }
  }
  //count at 0
  favor = 1;
  dist[0] = 0;
  int loss = 0,gain = 0;
  for(int i = 1; i < N; i++){
    dist[0] += count(order[i-1], order[i]);
    if(order[i-1] > 1){
      if(order[i] < order[i-1] && order[i] > 1) gain++;
    }
    else gain++;
  }
  loss = end[0] - endcount[0];
  int startcount = start[0];
  //cout << start[0] << "\n";
  int out = dist[0];
  for(int i = 1; i < M; i++){
      favor++;
      dist[i] = dist[i-1] + loss - gain + startcount;
      loss = end[i] - endcount[i];
      gain = gain - endcount[i] + start[i];
      startcount = start[i];
      out = (dist[i] < out) ? dist[i] : out;
      //cout << dist[i-1] << "\n";
  }
  cout << out << "\n";
  return 0;
}

