void seglazy(int i)
{
    if (i<131072) {
        if (seglazy1[i]) {
            seglazy1[i*2]+=seglazy1[i];
            seglazy1[i*2+1]+=seglazy1[i];
            seglazy1[i]=0;
        }
        if (seglazy2[i]) {
            seglazy2[i*2]+=seglazy2[i];
            seglazy1[i*2]+=seglazy2[i]*((seg2[i]-seg1[i]+1)/2);
            seglazy2[i*2+1]+=seglazy2[i];
            seglazy2[i]=0;
        }
    }
}

void segadd1(int i,int u,int v,int w)
{
    if (v<seg1[i] || seg2[i]<u) return;
    if (u<=seg1[i] && seg2[i]<=v) {
        seglazy1[i]+=w;
        return;
    }
    seglazy(i);
    segadd1(i*2,u,v,w);
    segadd1(i*2+1,u,v,w);
}

void segadd2(int i,int u,int v)
{
    if (v<seg1[i] || seg2[i]<u) return;
    if (u<=seg1[i] && seg2[i]<=v) {
        seglazy1[i]+=v-seg2[i];
        seglazy2[i]++;
        return;
    }
    seglazy(i);
    segadd2(i*2,u,v);
    segadd2(i*2+1,u,v);
}

