      Add(a[i + 1] + 1, m - 1, 0, diff);
    } else {
      int diff = a[i + 1] - a[i] + m;
      Add(a[i + 1] + 1, a[i], 0, diff);
      Add(a[i] + 1, m - 1, -1, diff + a[i] + 1);
      Add(0, a[i + 1], -1, a[i + 1] + 1);
    }
  }
  for (int i = 0; i < m; i++) {
    k[i + 1] += k[i];
    b[i + 1] += b[i];
  }
