	//printf("%d %d %d\n", sizeof(int), sizeof(long), sizeof(long long));
	while (scanf("%d %d", &n, &m)==2) {
		int a[n];
		scan_ai(a, n);

		long g[m], h[m];
		memset(g, 0, sizeof(g));
		memset(h, 0, sizeof(h));
		array_delta_create(g, m);
		array_delta_create(h, m);

		/*
		steps from s to t:
		s<=t:
			x s t: t-s      0<x<=s
			s x t: t-x+1    s<x<=t
			s t x: t-s      t<x<=m
		s>t:
			x t s: t-x+1    0<x<=t
			t x s: t+m-s    t<x<=s
			t s x: t+m-x+1  s<x<=m

		sum[i=0..n-1](x) = g*x + h
			s = a[i]
			t = a[i+1]
		*/
		for (int i=0; i<n-1; i++) {
			int s = a[i], t = a[i+1];
			if (s <= t) {
				//0<x<=s
				array_delta_range_add(h, 0, s, t-s);
				//s<x<=t
				array_delta_range_add(h, s, t, t+1);
				array_delta_range_add(g, s, t, -1);
				//t<x<=m
				array_delta_range_add(h, t, m, t-s);
			}
			else {
				//0<x<=t
				array_delta_range_add(h, 0, t, t+1);
				array_delta_range_add(g, 0, t, -1);
				//t<x<=s
				array_delta_range_add(h, t, s, t+m-s);
				//s<x<=m
				array_delta_range_add(h, s, m, t+m+1);
				array_delta_range_add(g, s, m, -1);
			}
		}
		array_partial_sum_create(g, m);
		array_partial_sum_create(h, m);
		//print_al(g, m); print_al(h, m);

		long minz = LONG_MAX;
		int minx = 0;
		for (int x=1; x<=m; x++) {
			long z = g[x-1] * x + h[x-1];
			//printf("g=%ld h=%ld z=%ld\n", g[x-1], h[x-1], z);
			if (z < minz) {
				minz = z;
				minx = x;
			}
		}
		//printf("%d\n", minx);
		printf("%ld\n", minz);
	}
}

