      if(a[i] < a[i + 1]){
        count[a[i] + 1]++;
        count[a[i + 1]]--;
      }
      else{
        if(a[i + 1] >= 2){
          count[1]++;
          count[a[i + 1]]--;
        }
        if(a[i] + 1 <= m){
          count[a[i] + 1]++;
          count[m]--;
        }
      }
    }

