    static int mod = 1_000_000_007;
    // int mod = 998244353;
    long inf = Long.MAX_VALUE/2;


    void solve(){
        int n = ni();
        int m = ni();
        int[] a = new int[n];
        for(int i = 0; i < n; i++){
            a[i] = ni();
        }
        int[][] range = new int[n-1][2];
        long cost = 0;
        for(int i = 0; i < n-1; i++){
            int s = a[i];
            int t = a[i+1];
            if(s<=t){
                range[i][0] = s;
                range[i][1] = t;
            }
            else{
                range[i][0] = s;
                range[i][1] = t+m;
            }
            cost += range[i][1] - range[i][0];
        }

        int[] slist = new int[2*m+1];
        int[] tlist = new int[2*m+1];
        long[] tsum = new long[2*m+1];
        int sum = 0;
        for(int i = 0; i < n-1; i++){
            slist[range[i][0]+1]++;
            tlist[range[i][1]]++;
            tsum[range[i][1]] += range[i][1] - range[i][0] - 1;
            if(range[i][1]>=m){
                sum++;
                cost -= (m-range[i][0])-1;
            }
        }
        long ans = inf;
        for(int x = 0; x < m; x++){
            // out.println(x+" "+cost+" "+sum);
            // cost -= sum;
            ans = Math.min(ans, cost);
            sum += slist[x];
            sum -= tlist[x];
            sum -= tlist[x+m];
            cost += tsum[x];
            cost += tsum[x+m];
            cost -= sum;
        }
        out.println(ans);
    }


