public class Main {
    public static void main(String[] args) {
        FastScanner fsc = new FastScanner();
        int n = fsc.nextInt();
        int m = fsc.nextInt();
        long[] d = new long[m];
        long sum = 0;
        int pre = fsc.nextInt() - 1;
        for (int i = 1; i < n; i++) {
            int now = fsc.nextInt() - 1;
            int to = now;
            int fr = pre;
            if (fr < to) {
                if (fr + 2 < m) {
                    d[fr + 2] += 1;
                }
                if (to + 1 < m) {
                    d[to + 1] += -to + fr;
                }
                if (to + 2 < m) {
                    d[to + 2] += to - fr - 1;
                }
            } else {
                if (fr + 2 < m) {
                    d[fr + 2] += 1;
                }
                d[0] += m - fr - 1;
                d[1] += 1 - (m - fr - 1);
                if (to + 1 < m) {
                    d[to + 1] += -to - m + fr;
                }
                if (to + 2 < m) {
                    d[to + 2] += to + m - fr - 1;
                }
            }

            if (now > pre) {
                sum += now - pre;
            } else {
                sum += now + m - pre;
            }
            pre = now;
        }
        fsc.close();
        for (int i = 1; i < m; i++) {
            d[i] += d[i - 1];
        }
        long max = d[0];
        for (int i = 1; i < m; i++) {
            d[i] += d[i - 1];
            max = max(max, d[i]);
        }
        System.out.println(sum - max);
    }
}

