import static java.lang.Math.max;

import java.io.IOException;
import java.io.InputStream;
import java.util.NoSuchElementException;

public class Main {
    public static void main(String[] args) {
        FastScanner fsc = new FastScanner();
        int n = fsc.nextInt();
        int m = fsc.nextInt();
        long[] d = new long[m + 2];
        long sum = 0;
        int pre = fsc.nextInt() - 1;
        for (int i = 1; i < n; i++) {
            int now = fsc.nextInt() - 1;
            if (pre < now) {
                d[pre + 2] += 1;
                d[now + 1] += -now + pre;
                d[now + 2] += now - pre - 1;
                sum += now - pre;
            } else {
                d[pre + 2] += 1;
                d[0] += m - pre - 1;
                d[1] += 1 - (m - pre - 1);
                d[now + 1] += -now - m + pre;
                d[now + 2] += now + m - pre - 1;
                sum += now + m - pre;
            }
            pre = now;
        }
        fsc.close();
        d[1] += d[0];
        long max = max(d[0], d[1]);
        for (int i = 2; i < m + 1; i++) {
            d[i] += d[i - 1];
            d[i - 1] += d[i - 2];
            max = max(max, d[i - 1]);
        }
        System.out.println(sum - max);
    }
}

