import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.InputMismatchException;
import java.util.NoSuchElementException;

public class Main {

	static PrintWriter out;
	static InputReader ir;

	static void solve() {
		int n = ir.nextInt();
		int m = ir.nextInt();
		int[] a = ir.nextIntArray(n);
		long[] imos1 = new long[m + 2];
		long[] imos2 = new long[m + 2];
		for (int i = 0; i < n - 1; i++) {
			if (a[i + 1] > a[i]) {
				imos1[a[i] + 1] += a[i + 1] + 1;
				imos1[a[i + 1] + 1] -= a[i + 1] + 1;
				imos2[a[i] + 1]++;
				imos2[a[i + 1] + 1]--;
				imos1[1] += a[i + 1] - a[i];
				imos1[a[i] + 1] -= a[i + 1] - a[i];
				imos1[a[i + 1] + 1] += a[i + 1] - a[i];
				imos1[m + 1] -= a[i + 1] - a[i];
			} else {
				imos1[a[i] + 1] += m + a[i + 1] + 1;
				imos1[m + 1] -= m + a[i + 1] + 1;
				imos2[a[i] + 1]++;
				imos2[m + 1]--;
				imos1[1] += a[i + 1] + 1;
				imos1[a[i + 1] + 1] -= a[i + 1] + 1;
				imos2[1]++;
				imos2[a[i + 1] + 1]--;
				imos1[a[i + 1] + 1] += m + a[i + 1] - a[i];
				imos1[a[i] + 1] -= m + a[i + 1] - a[i];
			}
		}
		for (int i = 0; i < m + 1; i++) {
			imos1[i + 1] += imos1[i];
			imos2[i + 1] += imos2[i];
		}
		long mi = 1L << 60;
		for (int i = 1; i <= m; i++)
			mi = Math.min(imos1[i] - i * imos2[i], mi);
		out.println(mi);
	}

	public static void main(String[] args) {
		ir = new InputReader(System.in);
		out = new PrintWriter(System.out);
		solve();
		out.flush();
	}

	static class InputReader {

		private InputStream in;
		private byte[] buffer = new byte[1024];
		private int curbuf;
		private int lenbuf;

		public InputReader(InputStream in) {
			this.in = in;
			this.curbuf = this.lenbuf = 0;
		}

		public boolean hasNextByte() {
			if (curbuf >= lenbuf) {
				curbuf = 0;
				try {
					lenbuf = in.read(buffer);
				} catch (IOException e) {
					throw new InputMismatchException();
				}
				if (lenbuf <= 0)
					return false;
			}
			return true;
		}

		private int readByte() {
			if (hasNextByte())
				return buffer[curbuf++];
			else
				return -1;
		}

		private boolean isSpaceChar(int c) {
			return !(c >= 33 && c <= 126);
		}

		private void skip() {
			while (hasNextByte() && isSpaceChar(buffer[curbuf]))
				curbuf++;
		}

		public boolean hasNext() {
			skip();
			return hasNextByte();
		}

		public String next() {
			if (!hasNext())
				throw new NoSuchElementException();
			StringBuilder sb = new StringBuilder();
			int b = readByte();
			while (!isSpaceChar(b)) {
				sb.appendCodePoint(b);
				b = readByte();
			}
			return sb.toString();
		}

		public int nextInt() {
