        FastScanner fsc = new FastScanner();
        int n = fsc.nextInt();
        int m = fsc.nextInt();
        long[] d = new long[m + 2];
        long sum = 0;
        int pre = fsc.nextInt() - 1;
        for (int i = 1; i < n; i++) {
            int now = fsc.nextInt() - 1;
            int del = now - pre;
            if (del < 0) {
                d[0] += m - pre - 1;
                d[1] += 1 - (m - pre - 1);
                del += m;
            }
            d[pre + 2] += 1;
            d[now + 1] -= del;
            d[now + 2] += del - 1;
            sum += del;
            pre = now;
        }
        fsc.close();
        d[1] += d[0];
        long max = d[0];
        for (int i = 2; i < m + 1; i++) {
            d[i] += d[i - 1];
