        for (int i = 0; i+1 < n ; i++) {
            imo[a[i]+2] += 1;
            int to = (a[i+1] < a[i]) ? a[i+1]+m : a[i+1];
            imo[to+1] -= 1;
        }

        for (int i = 1; i < imo.length ; i++) {
            imo[i] += imo[i-1];
        }

        for (int i = 0; i+1 < n ; i++) {
            int to = (a[i+1] < a[i]) ? a[i+1]+m : a[i+1];
            int d = to-a[i]-1;
            imo[to+1] -= d;
        }
        for (int i = 1 ; i < imo.length ; i++) {
            imo[i] += imo[i-1];
        }

        long total = 0;
        for (int i = 1 ; i < n ; i++) {
            total += dist(a[i-1], a[i], m);
        }

        long best = 0;
        for (int i = 0; i < m ; i++) {
            long t = 0;
            for (int j = i; j < imo.length ; j += m) {
                t += imo[j];
            }
            best = Math.max(best, t);
        }
