public class Main {
    static InputStream is;
    static PrintWriter out;
    static String INPUT = "";

    void solve() {
        int n = ni();
        int m = ni();
        int a[] = na(n);
        int b[] = Arrays.copyOf(a, n);
        Arrays.sort(b);
        b = ex(b);
        int x = Integer.MAX_VALUE;
        for (int i : b) {
            int t = calc(a, m, i);
            if (x > t) {
                x = t;
            }
        }
        out.println(x);
    }

    int[] ex(int[] o) {
        int r[] = new int[o.length], ri = -1;
        for (int i = 0; i < o.length; ++i) {
            if (ri == -1 || r[ri] != o[i]) {
                r[++ri] = o[i];
            }
        }
        return Arrays.copyOf(r, ri + 1);
    }

    int calc(int a[], int m, int x) {
        int n = a.length;
        int v = 0;
        for (int i = 0; i + 1 < n; ++i) {
            int t;
            if (a[i] > a[i + 1]) {
                t = m - a[i] + a[i + 1];
            } else {
                t = a[i + 1] - a[i];
            }
            int r;
            if (x > a[i + 1]) {
                r = m - x + a[i + 1] + 1;
            } else {
                r = a[i + 1] - x + 1;
            }
            v += Math.min(t, r);
        }
        return v;
    }

