class Main {
	public static void main(String[] args) throws IOException {
		Scanner sc = new Scanner(System.in);
		int n = sc.nextInt();
		int m = sc.nextInt();
		int[] a = new int[n];
		sc.fill(a);

		int[] diff = new int[n];
		for (int i = 1; i < a.length; i++) {
			if (a[i - 1] < a[i]) {
				diff[i] = a[i] - a[i - 1];
			} else {
				diff[i] = m + a[i] - a[i - 1];
			}
		}

		long min = Integer.MAX_VALUE;
		OUTER_LOOP: for (int i = 1; i <= m; i++) {
			long sum = 0;
			for (int j = 1; j < a.length; j++) {
				if (i == a[j]) {
					sum += 1;
				} else if (a[j] < i) {
					sum += Math.min(m + a[j] - i + 1, diff[j]);
				} else {
					sum += Math.min(a[j] - i + 1, diff[j]);
				}
				if (min < sum) {
					continue OUTER_LOOP;
				}
			}

			min = Math.min(min, sum);
		}

		System.out.println(min);
	}

