                imos[range[i][1]]--;
            }
            tsum[range[i][1]] += range[i][1] - range[i][0] - 1;
            if(range[i][1]>=m){
                sum++;
                cost -= (m-range[i][0])-1;
            }
        }
        for(int i = 1; i <= 2*m; i++){
