        count[a[i + 1]]--;
      }
      else{
        if(a[i + 1] >= 2){
          count[2]++;
          count[a[i + 1]]--;
        }
        if(a[i] + 1 <= m){
          count[a[i] + 1]++;
          count[m]--;
        }
      }
    }

    int t = 0;
    for(int i = 1; i <= m; i++){
      count[i] += count[i - 1];
      if(DEBUG){
        System.out.println("count[" + i + "] = " + count[i]);
