			if(a[i-1] + 2 <= m-1 && a[i-1] + 1 + l >= m-1) {
				c += 1;
			} else if(a[i-1] + 2 + l == m-1) {
				c -= l;
			}

			if(a[i-1] + 2 <= m-1 && a[i-1] + 1 + l >= m-1) {
