    static InputStream is;
    static PrintWriter out;
    static String INPUT = "";

    void solve() {
        int n = ni();
        int m = ni();
        int a[] = na(n);
        int min = 1, max = m;
        while (max - min > 500) {
            int q = 5;
            int x[] = new int[q];
            int v[] = new int[q];
            int d = (max - min) / q;
            for (int i = 0; i < q; ++i) {
                x[i] = min + d * i;
                v[i] = calc(a, m, x[i]);
            }
            int ti = 0, tv = Integer.MAX_VALUE;
            for (int i = 0; i + 1 < q; ++i) {
                int t = v[i] + v[i + 1];
                if (tv > t) {
                    tv = t;
                    ti = i;
                }
            }
            min = min + d * ti;
            max = min + d;
        }
        int x = Integer.MAX_VALUE;
        for (int i = min; i <= max; ++i) {
            int t = calc(a, m, i);
            if (x > t) {
                x = t;
            }
        }
        out.println(x);
    }

    int calc(int a[], int m, int x) {
        int n = a.length;
        int v = 0;
        for (int i = 0; i + 1 < n; ++i) {
            int t;
            if (a[i] > a[i + 1]) {
                t = m - a[i] + a[i + 1];
            } else {
                t = a[i + 1] - a[i];
            }
            int r;
            if (x > a[i + 1]) {
                r = m - x + a[i + 1] + 1;
            } else {
                r = a[i + 1] - x + 1;
            }
            v += Math.min(t, r);
        }
        return v;
    }

    public static void main(String[] args) throws Exception {
        long S = System.currentTimeMillis();
        is = INPUT.isEmpty() ? System.in : new ByteArrayInputStream(INPUT.getBytes());
        out = new PrintWriter(System.out);

        new Main().solve();
        out.flush();
        long G = System.currentTimeMillis();
        tr(G - S + "ms");
    }

