public class Imos{
	private const int mod=(int)1e9+7;
	private long[] a,h,c,ra;
	private int o,n;
	public Imos(int n,int o){
		this.o=o;
		this.n=n;
		a=new long[n+o];
		h=new long[n+o];
		c=new long[o];
		ra=new long[n+o];
		ra[0]=ra[1]=1;
		for(int i = 2;i<ra.Length;i++) {
			ra[i]=ra[i-1]*i;
			if(i>o){ra[i]/=i-o+1;}
		}
		for(int i = 0;i<((o+1)>>1);i++) {ra[o-i-1]=ra[i]*=ra[o-i-1];}
	}
	public void Add1(int l,int r,long a,long b){
		h[l]+=a;
		h[l+1]-=a-b;
		h[r+1]-=a+(r-l+1)*b;
		h[r+2]+=a+(r-l)*b;
	}
	public void Add2(int l,int r,long b){
		h[l]+=b;
		h[l+1]+=b;
		h[r+1]-=(r-l+2)*(r-l+2)*b;
		h[r+2]+=((r-l+1)*(r-l+1)*2+(r-l+1)*2-1)*b;
		h[r+3]-=(r-l+1)*(r-l+1)*b;
	}
	public void Addc(int l,int r,long b){
		int p=r-l;
		h[l]+=b;
		long f=ra[p+o]*b;
		for(int i = 1;i<=o;i++) {
			h[r+i]+=f/ra[i-1]*((i&1)==1?-1:1);
			f*=p+i;
			f/=p+i+1;
		}
	}
	public void Addt(int l,int r,long b){
		int p=r-l;
		h[l]+=b;
		h[r+1]-=(p+2)*(p+3)/2*b;
		h[r+2]+=(p+1)*(p+3)*b;
		h[r+3]-=(p+1)*(p+2)/2*b;
	}
	public void Go(){
		for(int i = 1;i<n;i++) {
			c[0]+=h[i];
			for(int j = 1;j<o;j++) {c[j]+=c[j-1];}
			a[i]=c[o-1];
		}
	}
	public long this[int i]{get{return a[i];}}
	public override string ToString()=>string.Join(" ",a);
}
