	public class Program
	{
		static void Main(string[] args)
		{
			Scanner cin = new Scanner();
			int n = cin.Int();
			int m = cin.Int();
			var a = cin.ArrayInt(n, -1);

			int max = m * 2 + 2;
			long ans = 0;
			var minus = new int[max];
			var plus = new int[max];
			for (int i = 1; i < n; i++) {
				ans += (a[i] - a[i - 1] + m) % m;

				if (a[i] > a[i - 1]) {
					if (a[i - 1] + 2 <= a[i]) {
						minus[a[i - 1] + 2 + m] += -1;
						minus[a[i] + 1 + m] += 1;
					}

					plus[a[i] + 1 + m] += Math.Max(0, a[i] - a[i - 1] - 1);
				} else {
					if (a[i - 1] + 2 <= a[i] + m) {
						minus[a[i - 1] + 2] += -1;
						minus[a[i] + 1 + m] += 1;
					}

					plus[a[i] + 1 + m] += Math.Max(0, a[i] + m - a[i - 1] - 1);
				}
			}

			var minusSum = new int[max];
			minusSum[0] = minus[0];
			for (int i = 1; i < max; i++) {
				minus[i] += minus[i - 1];
				minusSum[i] = minusSum[i - 1] + minus[i];
				plus[i] += plus[i - 1];
			}

			var sum = new int[max];
			for (int i = 0; i < max; i++) {
				sum[i] = minusSum[i] + plus[i];
			}

			ans += sum.Where((x, index) => index >= m && index < m * 2).Min();
			Console.WriteLine(ans);
		}
	}

