public class Program
{
    private int N, M;
    private int[] A;
    public void Solve()
    {
        var sc = new Scanner();
        N = sc.NextInt();
        M = sc.NextInt();
        A = sc.IntArray().Select(i => i-1).ToArray();

        long s = 0;
        long[] imos = new long[M+2];
        long[] imos2 = new long[M + M + 2];

        for (int i = 0; i < N-1; i++)
        {
            if (A[i] < A[i + 1])
            {
                s += A[i + 1] - A[i];
                imos[A[i] + 2]++;
                imos[A[i + 1] + 1]--;
                imos[A[i + 1] + 1] -= A[i + 1] - A[i] - 1;
                imos[A[i + 1] + 2] += A[i + 1] - A[i] - 1;
            }
            else
            {
                s += A[i + 1] + M - A[i];
                imos2[A[i] + 2]++;
                imos2[A[i + 1] + M + 1]--;
                imos2[A[i + 1] + M + 1] -= A[i + 1] + M - A[i] - 1;
                imos2[A[i + 1] + M + 2] += A[i + 1] + M - A[i] - 1;
            }
        }

        for (int i = 1; i < M+2; i++)
        {
            imos[i] += imos[i - 1];
        }
        for (int i = 1; i < M+2; i++)
        {
            imos[i] += imos[i - 1];
        }

        for (int i = 1; i < M+M+2; i++)
        {
            imos2[i] += imos2[i - 1];
        }
        for (int i = 1; i < M+M+2; i++)
        {
            imos2[i] += imos2[i - 1];
        }

        long max = 0;
        for (int i = 0; i < M; i++)
        {
            max = Math.Max(max, imos[i]+imos2[i]+imos2[i+M]);
        }

        Console.WriteLine(s - max);
    }

    public static void Main(string[] args) => new Program().Solve();
}

