		{
			Scanner cin = new Scanner();
			int n = cin.Int();
			int m = cin.Int();
			var a = cin.ArrayInt(n, -1);

			int max = m;
			var minus = new int[max];
			var plus = new int[max];
			long init = 0;
			for (int i = 1; i < n; i++) {
				if (a[i] > a[i - 1]) {
					init += a[i] - a[i - 1];

					if (a[i - 1] + 2 <= a[i]) {
						minus[a[i - 1] + 2] += -1;
						if (a[i] + 1 < m) {
							minus[a[i] + 1] += 1;
						}
					}

					if (a[i] + 1 != m) {
						plus[((a[i] + 1) % m)] += Math.Max(0, a[i] - a[i - 1] - 1);
					}
				} else {
					init += a[i] + 1;

					if (a[i - 1] + 2 < m) {
						minus[a[i - 1] + 2] += -1;
						if (a[i - 1] + 2 != m - 1) {
							minus[m - 1] += 1;
						}
					}

					if (a[i - 1] == m - 1) {
						if (a[i] > 0) {
							minus[1] += -1;
							minus[a[i] + 1] += 1;
						}
					} else {
						if (a[i] > 0) {
							minus[0] += -1;
							minus[a[i] + 1] += 1;
						}
					}

					plus[((a[i] + 1) % m)] += Math.Max(0, a[i] + m - a[i - 1] - 1);
				}
			}

			for (int i = 1; i < max; i++) {
				minus[i] += minus[i - 1];
			}

			var sum = new int[max];
			for (int i = 0; i < max; i++) {
				sum[i] = minus[i] + plus[i];
			}

			long value = init;
			long ans = init;
			for (int i = 1; i < m; i++) {
				value += sum[i];
				ans = Math.Min(ans, value);
			}

			Console.WriteLine(ans);
		}
	}

