				} else {
					if (a[i - 1] + 2 <= a[i] + m) {
						minus[a[i - 1] + 2] += -1;
						minus[a[i] + 1 + m] += 1;
					}

					plus[a[i] + 1 + m] += Math.Max(0, m - (a[i - 1] - a[i]) - 1);
				}
			}

			var minusSum = new int[max];
			minusSum[0] = minus[0];
			for (int i = 1; i < max; i++) {
				minus[i] += minus[i - 1];
				minusSum[i] = minusSum[i - 1] + minus[i];
				plus[i] += plus[i - 1];
			}

			var sum = new int[max];
			for (int i = 0; i < max; i++) {
				sum[i] = minusSum[i] + plus[i];
			}

			ans += sum.Where((x, index) => index >= m && index < m * 2).Min();
			Console.WriteLine(ans);
		}
	}

	public class Scanner
	{
		private readonly char[] delimiter_ = new char[] { ' ' };
		private string[] buf_;
		private int index_;

		public Scanner()
		{
			buf_ = new string[0];
			index_ = 0;
		}

		public string Next()
		{
			if (index_ < buf_.Length) {
				return buf_[index_++];
			}

			string st = Console.ReadLine();
			while (st == "") {
				st = Console.ReadLine();
			}

			buf_ = st.Split(delimiter_, StringSplitOptions.RemoveEmptyEntries);
			if (buf_.Length == 0) {
				return Next();
			}

			index_ = 0;
			return buf_[index_++];
		}

		public int Int() => int.Parse(Next());
		public long Long() => long.Parse(Next());
		public double Double() => double.Parse(Next());

		public int[] ArrayInt(int N, int add = 0)
		{
			int[] Array = new int[N];
			for (int i = 0; i < N; i++) {
				Array[i] = Int() + add;
			}
			return Array;
		}

		public long[] ArrayLong(int N, long add = 0)
		{
			long[] Array = new long[N];
			for (int i = 0; i < N; i++) {
				Array[i] = Long() + add;
			}
			return Array;
		}

		public double[] ArrayDouble(int N, double add = 0)
		{
			double[] Array = new double[N];
			for (int i = 0; i < N; i++) {
				Array[i] = Double() + add;
			}
			return Array;
		}
	}
}

