public class Solver
{
    public void Solve()
    {
        int n = ReadInt();
        int m = ReadInt();
        var a = ReadIntArray();

        long x = 0;
        var g = Init<List<int>>(m * 2 + 2);
        int c = 0;
        for (int i = 1; i < n; i++)
        {
            if (a[i - 1] < a[i])
            {
                x += a[i] - a[i - 1];
                g[a[i - 1] + 1].Add(0);
                g[a[i] + 1].Add(a[i] - a[i - 1]);
                g[a[i - 1] + 1 + m].Add(0);
                g[a[i] + 1 + m].Add(a[i] - a[i - 1]);
            }
            else
            {
                c++;
                x -= m - a[i - 1];
                int h = a[i] + m;
                x += h - a[i - 1];
                g[a[i - 1] + 1].Add(0);
                g[h + 1].Add(h - a[i - 1]);
                g[a[i] + 1].Add(h - a[i - 1]);
            }
        }

        long ans = x;
        for (int i = 2; i < 2 * m + 2; i++)
        {
            x -= c;
            foreach (int e in g[i])
                if (e == 0)
                    c++;
                else
                {
                    c--;
                    x += e;
                }
            ans = Math.Min(ans, x);
        }

        Write(ans);
    }

