class Sol{
	public void Solve(){

		long ini = 0;
		for(int i=0;i<N-1;i++){
			var x = A[i] < A[i+1] ? A[i+1] - A[i] : M - (A[i]-A[i+1]);
			var y = 1 + (0 <= A[i+1] ? A[i+1] - 0 : M - (0 - A[i+1]));
//Console.WriteLine("{0} {1}",x,y);
			ini += Math.Min(y,x);
		}

		var imos = new int[M+2];
		for(int i=0;i<N-1;i++){
			int ma = A[i] <= A[i+1] ? A[i+1] - A[i] : M - (A[i]-A[i+1]);

			imos[A[i+1]] -= (-1);
			if(A[i+1] - (ma - 1) >= 0){
				imos[A[i+1]-(ma - 1)] += -1;
			} else {
				imos[0] += -1;

				imos[M] -= -1;
				imos[M - (ma-1 - A[i+1])] += -1;
			}

			imos[A[i+1]] += (ma - 1);
			imos[A[i+1]+1] -= (ma - 1);
		}

		long[] sum = new long[M+2];
		for(int i=0;i<M;i++){
			sum[i] += imos[i];
			if(i>0) sum[i] += sum[i-1];
		}

		long ans = ini;
		long cur = ini;
		for(int i=0;i<M-1;i++){
			cur += sum[i];
			ans = Math.Min(ans,cur);
		}
		Console.WriteLine(ans);

	}
	int N,M;
	int[] A;
