namespace ARC077
{
    public class E
    {
        private void Run()
        {
            var input = Console.ReadLine().Trim().Split();
            var n = int.Parse(input[0]);
            var m = int.Parse(input[1]);
            var A = Console.ReadLine().Trim().Split().Select(int.Parse).Select(a => a - 1).ToArray(); // to 0-based

            var x = A.Last();
            long result = 0;
            int current = A[0];
            foreach (var a in A.Skip(1))
            {
                result += Math.Min(
                    (m + (a - current)) % m,
                    (m + (a - x) + 1) % m);
                current = a;
            }
            Console.WriteLine(result);
        }

        public static void Main()
        {
            var old = Console.Out;
            using (var writer = new System.IO.StreamWriter(Console.OpenStandardOutput()) { AutoFlush = false })
            {
                Console.SetOut(writer);
                new E().Run();
                Console.Out.Flush();
                Console.SetOut(old);
            }
        }
    }
}

