public class Solver
{
    public void Solve()
    {
        int n = ReadInt();
        int m = ReadInt();
        var a = ReadIntArray();

        long x = 0;
        var g = Init<List<int>>(m * 2 + 2);
        for (int i = 1; i < n; i++)
        {
            if (a[i - 1] < a[i])
            {
                x += a[i] - a[i - 1];
                g[a[i - 1] + 1].Add(0);
                g[a[i] + 1].Add(a[i] - a[i - 1]);
                g[a[i - 1] + 1 + m].Add(0);
                g[a[i] + 1 + m].Add(a[i] - a[i - 1]);
            }
            else
            {
                int h = a[i] + m;
                x += h - a[i - 1];
                g[a[i - 1] + 1].Add(0);
                g[a[i] + 1 + m].Add(h - a[i - 1]);
            }
        }

        long ans = x;
        int c = 0;
        for (int i = 2; i < 2 * m + 2; i++)
        {
            x -= c;
            foreach (int e in g[i])
                if (e == 0)
                    c++;
                else
                {
                    c--;
                    x += e + 1;
                }
            ans = Math.Min(ans, x);
        }

        Write(ans);
    }

