function main(){
  var n = next(), m = next();
  var a = nexts(n);
  var b = xArray(0,m*2+3);
  var sum = 0;
  for(var i = 1; i < n; i++){
    var c = a[i-1], d = a[i];
    if(d < c)d += m;
    var x = d-c;
    b[c+2]--, b[d+1] += x, b[d+2] -= x-1;
    sum += x;
  }
  var tot = 0;
  for(var i = 2; i < m*2+1; i++){
    tot += b[i];
    b[i] = b[i-1] + tot;
  }
  var ans = sum;
  for(var i = 1; i <= m; i++){
    var t = sum + b[i] + b[i+m];
    if(t < ans)ans = t;
  }
  return ans;
}

