  auto e = new long[](m);
  long d0 = 0;
  long x0 = 0;
  foreach (i; iota(n - 1)) {
    auto prev = a[i];
    auto next = a[i + 1];
    auto delta = (next + m - prev) % m;
    e[prev] += 1;
    e[(next + m - 1) % m] -= delta;
    e[next] += delta - 1;
    if (prev > next) {
      if (next == 0) {
        d0 -= (delta - 1);
      } else {
        d0 += 1;
      }
      x0 += max(0L, ((next + m - prev) % m) - (next + 1));
    }
  }
  auto d = new long[](m);
  d[0] = d0;
  foreach (i; iota(m - 1)) {
    d[i + 1] = d[i] + e[i];
  }
  auto x = new long[](m);
  x[0] = x0;
  foreach (i; iota(m - 1)) {
    x[i + 1] = x[i] + d[i];
