            imos1[s + 1] -= 1;
            imos1[t + 1] += 1;

            imos0[t + 1] += t - s;
        }
        else {
            imos0[1] += t + 1;
            imos0[t + 1] -= t + 1;
            imos1[1] -= 1;
            imos1[t + 1] += 1;

            imos0[t + 1] += m - s + t;
            imos0[s + 1] -= m - s + t;

            imos0[s + 1] += t + m;
            imos1[s + 1] -= 1;
        }
    }

    foreach (i ; 0 .. m) {
        imos0[i + 1] += imos0[i];
        imos1[i + 1] += imos1[i];
    }

    long ans = 1L * m * n;

    foreach (i ; 1 .. m + 1) {
        ans = min(ans, imos0[i] + imos1[i] * i);
    }

    writeln(ans);
}


