    int[] xs = K.iota.map!(i => i/K).array;
    while(s > 0.1) {
        int y = xs.minElement!(x => calc(x));
        s /= 1.5;
        foreach(i; 0..K) {
            xs[i] = (y+s*(-K/2+i)+M).to!int%M;
        }
    }
    xs.map!(x => calc(x)).reduce!min.writeln;
}

