fn main() {
    input!(n: usize, m: usize, a: [usize1; n]);
    let mut start = vec![vec![]; m];
    let mut end = vec![vec![]; m];
    for i in 0..(n - 1) {
        let from = a[i];
        let to = a[i + 1];
        start[from].push(to);
        end[to].push(from);
    }

    let mut total = 0;
    let mut count = 0;
    for from in 0..m {
        for &to in start[from].iter() {
            if from > to {
                count += 1;
                total += to + 1;
            } else {
                total += to - from;
            }
        }
    }
    let mut ans = total;
    for cur in 1..m {
        for &from in end[cur - 1].iter() {
            count -= 1;
            let to = cur - 1;
            total += (to + m - from) % m;
            total -= 1;
        }
        total -= count;

        ans = cmp::min(ans, total);
        count += start[cur - 1].len();
    }
    println!("{}", ans);
}

