fn main() {
    let out = std::io::stdout();
    let mut out = BufWriter::new(out.lock());
    macro_rules! puts {
        ($($format:tt)*) => (write!(out,$($format)*).unwrap());
    }

    input!{
      n: usize,
      m: usize,
      aa: [usize1; n],
    }

    let mut direct = vec![0; m];
    let mut imos = vec![0i64; m*2];

    for i in 0..n-1 {
        let a = aa[i];
        let mut b = aa[i+1];
        if a == b {
            continue;
        }
        if b < a {
            b += m;
        }

        imos[a+1] += 1;
        imos[b] -= 1;
        direct[b%m] += b - a - 1;
    }

    let mut count = vec![0; m];
    let mut cur = 0;
    for i in 0..2*m {
        cur += imos[i];
        count[i%m] += cur;
    }

    let mut score = 0;
    let x = 0;
    for i in 0..n-1 {
        let a = aa[i];
        let b = aa[i+1];
        score += min((b + m - a) % m, (b + m - x) % m + 1);
    }
    let mut ans = score;

    for x in 1..m {
        score += direct[x-1];
        score -= count[x-1] as usize;
        ans = min(ans, score);
    }
    puts!("{}\n", ans);
}

