}

fn main() {
    let n = read::<usize>();
    let m = read::<usize>();
    let mut aseq = vec![0; n];
    for i in 0..n {
        aseq[i] = read::<usize>() - 1;
    }
    let mut ds0 = vec![0i64; 2 * m];
    let mut ds1 = vec![0i64; 2 * m];
    let mut sum = 0;
    for i in 0..n - 1 {
        let d = (m + aseq[i + 1] - aseq[i]) % m;
        sum += d;
        if d > 0 {
            ds1[aseq[i] + 1] += 1;
            ds1[aseq[i] + d] -= 1;
