fn main() {
    input! { n, m, a: [usize1; n] };
    let add = AnyMonoid::new(0i64, |&x, &y| x + y);
    let mut seg = LazySegmentTree::new(
        m * 2,
        add.clone(),
        add,
        |&x, &y| x + y,
        |&x, y| x * y as i64,
    );
    let mut d = 0;
    for i in 0..n - 1 {
        let (l, r) = if a[i] < a[i + 1] {
            (a[i], a[i + 1])
        } else {
            (a[i], a[i + 1] + m)
        };
        d += r - l;
        seg.update(l + 2, r + 1, 1);
        seg.update(r + 1, r + 2, l as i64 - r as i64 + 1);
    }
    let mut ans = d as i64;
    for i in 0..m {
        let x = seg.query(0, i + 1) + seg.query(0, i + m + 1);
        ans = std::cmp::min(ans, d as i64 - x);
    }
    println!("{}", ans);
}

