#[derive(Copy, Clone, Eq, PartialEq, Debug)]
struct Seg {
    head: usize,
    tail: usize,
}

impl Ord for Seg {
    fn cmp(&self, other: &Seg) -> cmp::Ordering {
        other.tail.cmp(&self.tail)
    }
}

impl PartialOrd for Seg {
    fn partial_cmp(&self, other: &Seg) -> Option<cmp::Ordering> {
        Some(self.cmp(other))
    }
}

fn main() {
    let mut sc = Scanner::new();
    let n = sc.read();
    let m = sc.read();
    let a: Vec<usize> = sc.read_vec(n);

    let mut tails: Vec<Vec<usize>> = vec![vec![]; m];
    let mut total_distance = 0;
    let mut current_decrease = 0;
    let mut tail_heap = BinaryHeap::new();
    for i in 1..n {
        let from = a[i - 1] - 1;
        let to = a[i] - 1;
        let distance = (to + m - from) % m;
        total_distance += distance;
        if from > to {
            let warped = m - from - 1;
            current_decrease += warped;
            tail_heap.push(Seg {
                head: from,
                tail: to,
            });
            tails[from].push(to + m);
        } else {
            tails[from].push(to);
        }
    }

    let mut ans = total_distance - current_decrease;
    // eprintln!(
    //     "{} {} {} {:?}",
    //     ans, total_distance, current_decrease, tail_heap
    // );
    for x in 1..m {
        while let Some(Seg { head, tail }) = tail_heap.pop() {
            if tail < x {
                assert!(tail == x - 1);
                // eprintln!("head={} to={}", head, tail);
                current_decrease -= (tail + m - head) % m - 1;
            } else {
                tail_heap.push(Seg {
                    head: head,
                    tail: tail,
                });
                break;
            }
        }
        current_decrease += tail_heap.len();
        ans = cmp::min(ans, total_distance - current_decrease);
        // eprintln!("{:?}", tail_heap);
        // eprintln!("{} {} {}", ans, total_distance, current_decrease);

        for &tail in tails[x - 1].iter() {
            tail_heap.push(Seg {
                head: x,
                tail: tail,
            });
        }
    }
    println!("{}", ans);
}

struct Scanner {
    ptr: usize,
    length: usize,
    buf: Vec<u8>,
    small_cache: Vec<u8>,
}

#[allow(dead_code)]
impl Scanner {
    fn new() -> Scanner {
        Scanner {
            ptr: 0,
            length: 0,
            buf: vec![0; 1024],
            small_cache: vec![0; 1024],
        }
    }

    fn load(&mut self) {
        use std::io::Read;
        let mut s = std::io::stdin();
        self.length = s.read(&mut self.buf).unwrap();
    }

    fn byte(&mut self) -> u8 {
        if self.ptr >= self.length {
            self.ptr = 0;
            self.load();
            if self.length == 0 {
                self.buf[0] = b'\n';
                self.length = 1;
            }
        }

        self.ptr += 1;
        return self.buf[self.ptr - 1];
    }

    fn is_space(b: u8) -> bool {
        b == b'\n' || b == b'\r' || b == b'\t' || b == b' '
    }

    fn read_vec<T>(&mut self, n: usize) -> Vec<T>
    where
        T: std::str::FromStr,
        T::Err: std::fmt::Debug,
    {
        (0..n).map(|_| self.read()).collect()
    }

    fn usize_read(&mut self) -> usize {
        self.read()
    }

    fn read<T>(&mut self) -> T
    where
        T: std::str::FromStr,
        T::Err: std::fmt::Debug,
    {
        let mut b = self.byte();
        while Scanner::is_space(b) {
            b = self.byte();
        }

        for pos in 0..self.small_cache.len() {
            self.small_cache[pos] = b;
            b = self.byte();
            if Scanner::is_space(b) {
                return String::from_utf8_lossy(&self.small_cache[0..(pos + 1)])
                    .parse()
                    .unwrap();
            }
        }

        let mut v = self.small_cache.clone();
        while !Scanner::is_space(b) {
            v.push(b);
            b = self.byte();
        }
        return String::from_utf8_lossy(&v).parse().unwrap();
    }
}

use std::cmp;

fn main() {
    let (r, w) = (std::io::stdin(), std::io::stdout());
    let mut sc = IO::new(r.lock(), w.lock());

    let n: usize = sc.read();
    let m: usize = sc.read();
    let a: Vec<usize> = (0..n).map(|_| sc.read::<usize>() - 1).collect::<Vec<_>>();

    let mut prev = vec![vec![]; 3 * m + 1];
    let mut start = vec![0; 3 * m + 1];
    let mut sum = 0;
    for i in 1..n {
        let from = a[i - 1];
        let to = a[i];
        if from > to {
            prev[to + m].push(from);
            start[from] += 1;
            sum += to + m - from;
        } else {
            prev[to].push(from);
            prev[to + m].push(from + m);
            start[from] += 1;
            start[from + m] += 1;
            sum += to - from;
        }
    }

    let mut max = 0;
    let mut carry = 0;
    let mut segments = 0;
    for i in 0..(3 * m + 1) {
        carry += segments;
        max = cmp::max(max, carry - segments);
        for &prev in prev[i].iter() {
            assert!(segments > 0);
            assert!(carry >= i - prev);
            segments -= 1;
            carry -= i - prev;
        }
        segments += start[i];
    }
    assert_eq!(segments, 0);
    assert_eq!(carry, 0);
    println!("{}", sum - max);
}

pub struct IO<R, W: std::io::Write>(R, std::io::BufWriter<W>);

impl<R: std::io::Read, W: std::io::Write> IO<R, W> {
    pub fn new(r: R, w: W) -> IO<R, W> {
        IO(r, std::io::BufWriter::new(w))
    }
    pub fn write<S: std::ops::Deref<Target = str>>(&mut self, s: S) {
        use std::io::Write;
        self.1.write(s.as_bytes()).unwrap();
    }
    pub fn read<T: std::str::FromStr>(&mut self) -> T {
        use std::io::Read;
        let buf = self
            .0
            .by_ref()
            .bytes()
            .map(|b| b.unwrap())
            .skip_while(|&b| b == b' ' || b == b'\n' || b == b'\r' || b == b'\t')
            .take_while(|&b| b != b' ' && b != b'\n' && b != b'\r' && b != b'\t')
            .collect::<Vec<_>>();
        unsafe { std::str::from_utf8_unchecked(&buf) }
            .parse()
            .ok()
            .expect("Parse error.")
    }
    pub fn vec<T: std::str::FromStr>(&mut self, n: usize) -> Vec<T> {
        (0..n).map(|_| self.read()).collect()
    }
    pub fn chars(&mut self) -> Vec<char> {
        self.read::<String>().chars().collect()
    }
}

