fn dist(u: usize, v: usize, n: usize) -> usize {
    if u <= v {
        v - u
    } else {
        v + n - u
    }
}

fn add2(fr: usize, to: usize, d: i64, x2: &mut Vec<i64>) {
    let l = (to - fr + 1) as i64;
    x2[fr] += 1;
    x2[to+1] -= l + 1;
    x2[to+2] += l;

    x2[fr] += d - 1;
    x2[fr+1] -= d - 1;
    x2[to+1] -= d - 1;
    x2[to+2] += d - 1;
}

fn main() {
    let (n, m): (usize, usize) = read();
    let mut a: Vec<usize> = readnc();
    for i in 0..n {
        a[i] -= 1;
    }

    let mut sum = 0;
    for i in 1..n {
        sum += dist(a[i-1], a[i], m);
    }

    let mut x0 = vec![0; m+2];
    let mut x1 = vec![0; m+2];
    let mut x2 = vec![0; m+2];

    for i in 1..n {
        let fr = a[i-1];
        let to = a[i];
        if dist(fr, to, m) <= 1 {
            continue
        }
        let fr = (fr + 2) % m;
        if fr <= to {
            add2(fr, to, 1, &mut x2);
        } else {
            add2(fr, m-1, 1, &mut x2);
            add2(0, to, (m - fr + 1) as i64, &mut x2);
        }
    }

    x1[0] = x2[0];
    for i in 1..m+1 {
        x1[i] = x1[i-1] + x2[i];
    }
    x0[0] = x1[0];
    for i in 1..m+1 {
        x0[i] = x0[i-1] + x1[i];
    }

    let mut bestdec = 0;
    for i in 0..m {
        bestdec = max(bestdec, x0[i]);
    }
    println!("{}", sum as i64 - bestdec);
}

