fn main() {
    let (r, w) = (std::io::stdin(), std::io::stdout());
    let mut sc = IO::new(r.lock(), w.lock());

    let n: usize = sc.read();
    let m: usize = sc.read();
    let a: Vec<usize> = (0..n).map(|_| sc.read::<usize>() - 1).collect::<Vec<_>>();

    let mut prev = vec![vec![]; 2 * m + 1];
    let mut start = vec![0; 2 * m + 1];
    let mut sum = 0;
    for i in 1..n {
        let from = a[i - 1];
        let to = a[i];
        if from > to {
            prev[to + m].push(from);
            start[from] += 1;
            sum += to + m - from;
        } else {
            prev[to].push(from);
            prev[to + m].push(from + m);
            start[from] += 1;
            start[from + m] += 1;
            sum += to - from;
        }
    }

    let mut max = 0;
    let mut carry = 0;
    let mut segments = 0;
    for i in 0..(2 * m + 1) {
        max = cmp::max(max, carry);
        carry += segments;
        for &prev in prev[i].iter() {
            assert!(segments > 0);
            assert!(carry >= i - prev);
            segments -= 1;
            carry -= i - prev;
        }
        segments += start[i];
    }
    println!("{}", sum - max);
}

pub struct IO<R, W: std::io::Write>(R, std::io::BufWriter<W>);

impl<R: std::io::Read, W: std::io::Write> IO<R, W> {
    pub fn new(r: R, w: W) -> IO<R, W> {
        IO(r, std::io::BufWriter::new(w))
    }
    pub fn write<S: std::ops::Deref<Target = str>>(&mut self, s: S) {
        use std::io::Write;
        self.1.write(s.as_bytes()).unwrap();
    }
    pub fn read<T: std::str::FromStr>(&mut self) -> T {
        use std::io::Read;
        let buf = self
            .0
            .by_ref()
            .bytes()
            .map(|b| b.unwrap())
            .skip_while(|&b| b == b' ' || b == b'\n' || b == b'\r' || b == b'\t')
            .take_while(|&b| b != b' ' && b != b'\n' && b != b'\r' && b != b'\t')
            .collect::<Vec<_>>();
        unsafe { std::str::from_utf8_unchecked(&buf) }
            .parse()
            .ok()
            .expect("Parse error.")
    }
    pub fn vec<T: std::str::FromStr>(&mut self, n: usize) -> Vec<T> {
        (0..n).map(|_| self.read()).collect()
    }
    pub fn chars(&mut self) -> Vec<char> {
        self.read::<String>().chars().collect()
    }
}

