    let mut d = 1;
    while d * 2 <= m {
         d *= 2;
    }
    let mut cur = (12 * a[0] + 3) % m;
    let mut answer: i64 = i64::max_value();
    loop {
        let (x, y, z) = (
            compute(&a, (cur+m-1)%m, m),
            compute(&a, cur, m),
            compute(&a, (cur+1)%m, m)
        );
        answer = min(min(answer, x), min(y, z));
        if x >= y && y <= z {
            break
        } else if y - x > y - z {
            // go to left
            cur = (cur + m - d) % m;
        } else {
            // go to right
            cur = (cur + m + d) % m;
        }
        if d != 1 {
            d /= 2;
        }
    }
    println!("{}", answer);
}

