fn main() {
    input! {
        n: usize, m: usize,
        a: [usize1; n]
    };

    let mv = |f:usize, t:usize| ifv!(f<=t, t-f, t+m-f);
    let between = |f:usize, t:usize, c:usize| ifv!(f<=t, f <= c && c <= t,  f <= c || c <= t);

    let mut best = 0;
    for i in 1..n {
        best += min(mv(a[i-1], a[i]), 1 + mv(0, a[i])) as i64;
    }

    let mut decin = 0i64;
    for i in 1..n {
        if mv(a[i-1], a[i]) >= 2 {
            decin += ifv!(between((a[i-1]+2)%m, a[i], 0), 1, 0);
        }
    }
    let mut dec_filter = vec![0i64; m+1];
    let mut add = vec![0i64; m+1];
    for i in 1..n {
        if mv(a[i-1], a[i]) >= 2 {
            dec_filter[(a[i-1]+2)%m] += 1;
            dec_filter[(a[i]+1)%m] -= 1;
            add[(a[i]+2)%m] += mv(a[i-1], a[i]) as i64;
        }
    }

    let mut last = best;
    for i in 1..m {
        decin += dec_filter[i];
        let mut to = last;
        to -= decin;
        to += add[i];
        best = min(best, to);
        // debug!(i, decin, add[i], last, to);
        last = to;
    }
    println!("{}", best);
}

