fn main() {
    let v = read_vec::<usize>();
    let (n, m) = (v[0], v[1]);
    let a = read_vec::<usize>()
        .into_iter()
        .map(|x| x - 1)
        .collect::<Vec<_>>();
    let sum = (1..n).map(|x| (m + a[x] - a[x - 1]) % m).sum::<usize>() as i64;
    let mut count = vec![0i64; 2 * m];
    let mut rate = vec![0i64; 2 * m];
    for i in 1..n {
        let cost;
        if a[i] >= a[i - 1] {
            cost = a[i] - a[i - 1];
            count[a[i]] += 1;
            count[a[i - 1] + 1] -= 1;
            rate[a[i]] += cost as i64 - 1;
        } else {
            cost = m + a[i] - a[i - 1];
            count[m + a[i]] += 1;
            count[a[i - 1] + 1] -= 1;
            rate[m + a[i]] += cost as i64 - 1;
        }
    }
    let mut current_count = 0;
    let mut gain = vec![0; 2 * m];
    let mut current_gain = 0;
    for i in (0..2 * m).rev() {
        current_gain -= current_count;
        current_gain += rate[i];
        gain[i] = current_gain;
        current_count += count[i];
    }

    let max_gain = (0..m).map(|x| gain[x] + gain[m + x]).max().unwrap();
    println!("{}", sum - max_gain);
}

fn read<T: std::str::FromStr>() -> T {
    let mut s = String::new();
