    let mut cost: Vec<i64> = vec![0; m*2 + 2];
    let mut num: Vec<i64> = vec![0; m*2 + 2];
    let mut all_cost: i64 = 0;

    for (u, v) in a.windows(2).map(|w| interval(w, m)).filter(|&(u, v)| u != v) {
        let d = (v - u) as i64;
        all_cost += d;
