    parent:Vec<Vec<usize>>,
    depth:Vec<usize>,
    root:usize,
}
impl LCA{
    pub fn new(G:Vec<Vec<usize>>, N:usize)->Self{
        let D = (f64::log2(N as f64)) as usize + 2;
        LCA{G:G, parent:vec![vec![0;N+1];D], depth:vec![0;N+1], root:N}
    }
    pub fn getP(&mut self, v:usize, p:usize, d:usize){
        self.parent[0][v] = p;
        self.depth[v] = d;
        for i in 0..self.G[v].len(){
            if self.G[v][i] != p{
                let n = self.G[v][i];
                self.getP(n, v, d+1);
            }
        }
    }
    pub fn init(&mut self){
        let root = self.root;
        self.getP(root, 0, 0);
        let V = self.depth.len();
        let logN = f64::log2(V as f64) as usize + 2;
        for k in 0..logN-1{
            for v in 1..root+1{
                if self.parent[k][v] == 0{
                    self.parent[k+1][v] = 0;
                }
                else{
                    self.parent[k+1][v] = self.parent[k][self.parent[k][v]];
                }
            }
        }
    }
    fn ft(&self, f:usize, d:usize)->usize{
        let mut now = f;
        let mut now2 = 0;
        let V = self.depth.len();

        let logN = f64::log2(V as f64) as usize + 2;
        let mut v = f;
        for k in 0..logN{
            if (d >> k) & 1 == 1{
                v = self.parent[k][v];
            }
        }

        return v;
    }
    fn lca(&mut self,u:usize, v:usize)->usize{
        let mut u = u;
        let mut v = v;
        if self.depth[u] > self.depth[v]{
            mem::swap(&mut u, &mut v);
        }
        let mut V = self.depth.len();
        let logN = f64::log2(V as f64) as usize + 2;
        for k in 0..logN{
            if ((self.depth[v] - self.depth[u]) >> k)&1 == 1{
                v = self.parent[k][v];
            }
        }
        if u == v{return u;}
        for k in (0..logN).rev(){
            if self.parent[k][u] != self.parent[k][v]{
                u = self.parent[k][u];
                v = self.parent[k][v];
            }
        }
        return self.parent[0][u];
    }
}
