    let mut imos1 = vec![0; 2 * m + 1];
    let mut imos2 = vec![0; 2 * m + 1];
    let mut sum = 0;
    for a in a.windows(2) {
        let x = a[0];
        let y = a[1];
        if x < y {
            let d = y - x;
            sum += d;
            let r = y;
            let l = x;
            imos2[r] -= d;
            imos2[l] += d;
            imos1[r] += 1;
            imos1[l] -= 1;
            imos2[l] -= d;
        } else {
            let d = y + m - x;
            sum += d;
            let r = y + m;
            let l = x;
            imos2[r] -= d;
            imos2[l] += d;
            imos1[r] += 1;
            imos1[l] -= 1;
            imos2[l] -= d;
        }
    }
    for i in (0..(2 * m)).rev() {
        imos1[i] += imos1[i + 1];
    }
    for i in (0..(2 * m)).rev() {
        imos2[i] += imos1[i] + imos2[i + 1];
    }
    let mut ans = sum;
    for i in 0..m {
        let cost = sum + imos2[i] + imos2[i + m];
        ans = std::cmp::min(ans, cost);
    }
    println!("{}", ans);
}

