use proconio::input;

fn main() {
    input!(n: usize, m: usize, a: [proconio::marker::Usize1; n]);
    let mut seq = vec![0; m + 2];
    fn add(l: usize, r: usize, x: i64, seq: &mut [i64]) {
        let d = r - l;
        seq[l] += x;
        seq[l + 1] += -x + 1;
        seq[l + d] += -x - d as i64;
        seq[l + d + 1] += x + d as i64 - 1;
    }
    fn collect(seq: &[i64]) -> Vec<i64> {
        let mut seq = seq.to_vec();
        for _ in 0..2 {
            for i in 0..seq.len() - 1 {
                seq[i + 1] += seq[i];
            }
        }
        let m = seq.len() - 2;
        assert_eq!(&[seq[m], seq[m + 1]], &[0, 0]);
        for _ in 0..2 {
            seq.pop();
        }
        seq
    }
    for i in 0..n - 1 {
        let s = a[i];
        let t = a[i + 1];
        if s < t {
            if 1 < t - s {
                add(s + 1, t + 1, 0, seq.as_mut_slice());
            }
        } else {
            if s < m - 1 {
                add(s + 1, m, 0, seq.as_mut_slice());
            }
            add(0, t + 1, (m - 1 - s) as i64, seq.as_mut_slice());
        }
    }

    let mut standard = 0;
    let mut prv = a[0];
    for &x in a.iter().skip(1) {
        standard += if prv < x { x - prv } else { x + m - prv } as i64;
        prv = x;
    }
    println!("{}", standard - collect(&seq).iter().max().unwrap());
}

