// お気に入りが1のときの回数
fn ans1(aa: &Vec<i64>) -> i64 {
    let n = aa.len();
    let mut last = aa[0];
    let mut cnt = 0;
    for i in 1..n {
        let next = aa[i];
        if last < next {
            // lastとnextの間に1があることはない
            cnt += next - last;
        } else {
            // 必ずお気に入りを押したほうが良い
            cnt += next - 1 + 1;
        }
        last = next;
    }

    cnt
}

fn solve(m: usize, aa: Vec<i64>) -> i64 {
    let n = aa.len();
    let mut last = aa[0] as usize;
    let mut ms = vec![0 as i64; m+2];

    for i in 1..n {
        let next = aa[i] as usize;
        if last < next {
            ms[last+1] += 1;
            ms[next] -= 1;
        } else {
            ms[last+1] += 1;
            ms[m+1] -= 1;
            ms[0] += 1;
            ms[next] -= 1;
        }
        last = next;
    }

    // a_iとa_{i+1}間にxがあるようなi
    let mut acc = vec![0; m+1];
    acc[0] = ms[0];
    for i in 1..m+1 {
        acc[i] = acc[i-1] + ms[i];
    }

//    println!("acc = {:?}", acc);

    let mut ans = vec![0; m+1];
    ans[1] = ans1(&aa);

//    println!("ans1 = {}", ans[1]);

    // a_{i+1} = x であるi
    let mut add1 = vec![0; m+1];
    let mut last = aa[0] as usize;
    for i in 1..n {
        let next = aa[i] as usize;
        if 1 <= next && next < m {
            add1[next+1] += ((next + m - last) % m) as i64 - 1;
        }
        last = next;
    }

    for i in 2..m+1 {
        ans[i] = add1[i] + ans[i-1] - acc[i-1];
    }

//    println!("ans = {:?}", ans);

    let mut min_ = std::i64::MAX;
    for i in 1..m+1 {
        if ans[i] < min_ {
            min_ = ans[i];
        }
    }

    min_
}

fn main() {
