pub struct XorShift4 {
    x: u32,
    y: u32,
    z: u32,
    w: u32,
}

impl XorShift4 {
    pub fn new() -> XorShift4 {
        XorShift4 { 
            x: 123456789,
             y: 362436069,
              z: 521288629,
               w: 88675123 }
    }

    fn next_u32(&mut self) -> u32 {
        let x = self.x;
        let t = x ^ (x << 11);
        self.x = self.y;
        self.y = self.z;
        self.z = self.w;
        let w = self.w;
        self.w = w ^ (w >> 19) ^ (t ^ (t >> 8));
        self.w
    }
}
fn f(from: i32, to: i32, m: i32) -> i32 {
    if from <= to {
        to - from
    } else {
        to + m - from
    }
}
fn compute(a: &Vec<i32>, base: i32, m: i32) -> i64 {
    let mut ans: i64 = 0;
    for i in 0..(a.len()-1) {
        let (x, y) = (a[i], a[i+1]);
        let (a1, a2) = (f(x, y, m), 1+f(base, y, m));
        ans += min(a1, a2) as i64;
    }
    ans
}
fn main() {
    let mut xorshift = XorShift4::new();
    let (_, m): (i32, i32) = readln();
    let a_: Vec<i32> = readln();
    let a: Vec<i32> = a_.iter().map(|x| x-1).collect();
    let mut d = 1;
    while d * 2 <= m {
         d *= 2;
    }
    let mut answer: i64 = i64::max_value();
    for i in 0..10 {
        let mut cur = (xorshift.next_u32() as i32 % m);
        loop {
            let (x, y, z) = (
                compute(&a, (cur+m-1)%m, m),
                compute(&a, cur, m),
                compute(&a, (cur+1)%m, m)
            );
            answer = min(min(answer, x), min(y, z));
            if x >= y && y <= z {
                break
            } else if y - x > y - z {
                // go to left
                cur = (cur + m - d) % m;
            } else {
                // go to right
                cur = (cur + m + d) % m;
            }
            if d != 1 {
                d /= 2;
            }
        }
    }
    println!("{}", answer);
}

