    }

    pub struct Reader {
        buf: VecDeque<String>,
    }

    #[allow(dead_code)]
    impl Reader {
        pub fn new() -> Reader {
            Reader { buf: VecDeque::new() }
        }

        fn update_buf(&mut self) {
            if self.buf.is_empty() {
                self.buf = _read_vec_deque_string();
            }
        }

        pub fn next<T>(&mut self) -> T
        where
            T: FromStr,
            T::Err: Debug,
        {
            self.update_buf();
            self.buf.pop_front().unwrap().parse::<T>().unwrap()
        }

        pub fn next_n<T>(&mut self, n: usize) -> Vec<T>
        where
            T: FromStr,
            T::Err: Debug,
        {
            let mut vec: Vec<T> = Vec::with_capacity(n);

            for _ in 0..n {
                vec.push(self.next());
            }
            vec
        }
    }
}

fn main() {
    let mut reader = reader::Reader::new();

    let n: usize = reader.next();
    let m: usize = reader.next();
    let mut a: Vec<usize> = reader.next_n(n);
    for i in 0..n {
        a[i] -= 1;
    }

    let mut cnt: Vec<i64> = vec![0; 4 * m];
    let mut sum: Vec<i64> = vec![0; 4 * m];
    let mut t: i64 = 0;
    for i in 0..n - 1 {
        t += ((m + a[i + 1] - a[i]) % m) as i64;
        if (a[i] < a[i + 1] && a[i] + 2 > a[i + 1]) ||
            (a[i] > a[i + 1] && a[i] + 2 > a[i + 1] + m)
        {
            continue;
        }
        for j in 0..3 {
            if a[i] < a[i + 1] {
                cnt[a[i] + 2 + m * j] += 1;
                cnt[a[i + 1] + 1 + m * j] -= 1;
                sum[a[i + 1] + 1 + m * j] -= (a[i + 1] - a[i] - 1) as i64;
            } else if j > 0 {
                cnt[a[i] + 2 + m * (j - 1)] += 1;
                cnt[a[i + 1] + 1 + m * j] -= 1;
                sum[a[i + 1] + 1 + m * j] -= (a[i + 1] + m - a[i] - 1) as i64;
            }
        }
    }

    let mut c = 0;
    let mut max = 0;
    for i in 1..m * 3 {
        // println!("i={}, cnt={}, sum={}", i, cnt[i], sum[i]);

        c += cnt[i];
        c = std::cmp::max(0, c);
        sum[i] += sum[i - 1] + c;
        max = std::cmp::max(max, sum[i]);
    }
    let ans = t - max;
    println!("{}", ans);
}

