fn main() {
    input! {
        n: usize, m: usize,
        a: [usize1; n]
    };

    let mv = |f:usize, t:usize| ifv!(f<=t, t-f, t+m-f);
    let between = |f:usize, t:usize, c:usize| ifv!(f<=t, f <= c && c <= t,  c <= f || c <= t);

    let mut best = 0;
    for i in 1..n {
        best += min(mv(a[i-1], a[i]), 1 + mv(0, a[i])) as i64;
    }

    let mut decin = 0i64;
    for i in 1..n {
        if mv(a[i-1], a[i]) >= 2 {
            decin += ifv!(between((a[i-1]+2)%m, a[i], 0), 1, 0);
        }
    }

    let mut dec_filter = vec![0i64; m+1];
    let mut add = vec![0i64; m+1];
    for i in 1..n {
        if mv(a[i-1], a[i]) >= 2 {
            dec_filter[(a[i-1]+2)%m] += 1;
            dec_filter[(a[i]+1)%m] -= 1;
            add[(a[i]+1)%m] += (mv(a[i-1], a[i])-1) as i64;
        }
    }

    let mut last = best;
    for i in 1..m {
        decin += dec_filter[i];
        let mut to = last;
        to -= decin;
        to += add[i];
        best = min(best, to);
        // debug!(i, decin, add[i], last, to);
        last = to;
    }
    println!("{}", best);
}

pub struct XorShift4 {
    x: u32,
    y: u32,
    z: u32,
    w: u32,
}

impl XorShift4 {
    pub fn new() -> XorShift4 {
        XorShift4 { 
            x: 123456789,
             y: 362436069,
              z: 521288629,
               w: 88675123 }
    }

    fn next_u32(&mut self) -> u32 {
        let x = self.x;
        let t = x ^ (x << 11);
        self.x = self.y;
        self.y = self.z;
        self.z = self.w;
        let w = self.w;
        self.w = w ^ (w >> 19) ^ (t ^ (t >> 8));
        self.w
    }
}
fn f(from: i32, to: i32, m: i32) -> i32 {
    if from <= to {
        to - from
    } else {
        to + m - from
    }
}
fn compute(a: &Vec<i32>, base: i32, m: i32) -> i64 {
    let mut ans: i64 = 0;
    for i in 0..(a.len()-1) {
        let (x, y) = (a[i], a[i+1]);
        let (a1, a2) = (f(x, y, m), 1+f(base, y, m));
        ans += min(a1, a2) as i64;
    }
    ans
}
fn main() {
    let mut xorshift = XorShift4::new();
    let (_, m): (i32, i32) = readln();
    let a_: Vec<i32> = readln();
    let a: Vec<i32> = a_.iter().map(|x| x-1).collect();
    let mut d = 1;
    while d * 2 <= m {
         d *= 2;
    }
    let mut answer: i64 = i64::max_value();
    for i in 0..50 {
        let mut cur = (xorshift.next_u32() as i32 % m);
        loop {
            let (x, y, z) = (
                compute(&a, (cur+m-1)%m, m),
                compute(&a, cur, m),
                compute(&a, (cur+1)%m, m)
            );
            answer = min(min(answer, x), min(y, z));
            if x >= y && y <= z {
                break
            } else if y - x > y - z {
                // go to left
                cur = (cur + m - d) % m;
            } else {
                // go to right
                cur = (cur + m + d) % m;
            }
            if d != 1 {
                d /= 2;
            }
        }
    }
    println!("{}", answer);
}

