        let to = a[i + 1];
        start[from].push(to);
        end[to].push(from);
    }

    let mut total = 0;
    let mut count = 0;
    for from in 0..m {
        for &to in start[from].iter() {
            if from > to {
                count += 1;
                total += to + 1;
            } else {
                total += to - from;
            }
        }
    }
    // eprintln!("cur=0 {}", total);
    let mut ans = total;
    for cur in 1..m {
