            count -= 1;
            let to = cur - 1;
            total += (to + m - from) % m;
            total -= 1;
        }
        total -= count;

        ans = cmp::min(ans, total);
        // eprintln!("cur={} {}", cur, total);
        count += start[cur - 1].len();
    }
    println!("{}", ans);
