    let mut carry = BinaryHeap::new();
    let mut sum = 0;
    for i in 1..n {
        let prev = a[i - 1];
        let next = a[i];
        if prev < next {
            let length = next - prev;
            sum += length;
            ends[prev].push(next);
        } else {
            let length = next + m - prev;
            sum += length;
            value += m - prev;
            ends[prev].push(next + m);
            carry.push((-(next as i64), length));
        }
    }

