    #[allow(dead_code)]
    pub fn gets<T: FromStr>() -> Vec<T>
    where
        <T as FromStr>::Err: Debug,
    {
        let mut line: String = String::new();
        stdin().read_line(&mut line).unwrap();
        line.split_whitespace()
            .map(|t| t.parse().unwrap())
            .collect()
    }


    #[allow(dead_code)]
    pub fn get2<T: FromStr, U: FromStr>() -> (T, U)
    where
        <T as FromStr>::Err: Debug,
        <U as FromStr>::Err: Debug,
    {
        let mut line: String = String::new();
        stdin().read_line(&mut line).unwrap();
        let mut iter = line.split_whitespace();
        (
            iter.next().unwrap().parse().unwrap(),
            iter.next().unwrap().parse().unwrap(),
        )
    }
}

fn main() {
    let (_n, m): (usize, usize) = util::get2();
    let a: Vec<usize> = util::gets::<usize>().into_iter().map(|x| x - 1).collect();

    let mut to: Vec<Vec<usize>> = vec![Vec::new(); m];
    for v in a.windows(2) {
        to[v[1]].push(v[0]);
    }

    let mut imos = vec![0i64; m];
    for v in a.windows(2) {
        if v[0] < v[1] {
            imos[v[0] + 1] += 1;
            imos[v[1]] -= 1;
        } else {
            if v[0] + 1 != m {
                imos[v[0] + 1] += 1;
            }
            imos[0] += 1;
            imos[v[1]] -= 1;
        }
    }
    for i in 1..imos.len() {
        imos[i] += imos[i - 1];
    }

    let zero = a.windows(2)
        .map(|v| min((v[1] + m - v[0]) % m, 1 + (v[1] + m - 0) % m))
        .sum::<usize>();

    let mut sum = zero as i64;
    let mut v = vec![zero as i64];

    for i in 1..m {
        let inc = to[i - 1]
            .iter()
            .map(|&from| (i - 1 + m - from) % m - 1)
            .sum::<usize>();
        let dec = imos[i - 1];
        sum = sum + inc as i64 - dec;
        v.push(sum);
    }

    println!("{}", v.iter().min().unwrap());
}

use proconio::input;

fn main() {
    input!(n: usize, m: usize, a: [proconio::marker::Usize1; n]);
    let mut seq = vec![0; m + 2];
    fn add(l: usize, d: usize, x: i64, seq: &mut [i64]) {
        seq[l] += x;
        seq[l + 1] += -x + 1;
        seq[l + d] += -x - d as i64;
        seq[l + d + 1] += x + d as i64 - 1;
    }
    fn collect(seq: &[i64]) -> Vec<i64> {
        let mut seq = seq.to_vec();
        for _ in 0..2 {
            for i in 0..seq.len() - 1 {
                seq[i + 1] += seq[i];
            }
        }
        let n = seq.len() - 2;
        assert_eq!(&[seq[n], seq[n + 1]], &[0, 0]);
        for _ in 0..2 {
            seq.pop();
        }
        seq
    }
    for i in 0..n - 1 {
        let s = a[i];
        let t = a[i + 1];
        if s < t {
            if 1 < t - s {
                add(s + 1, t - s, 0, seq.as_mut_slice());
            }
        } else {
            if s < n - 1 {
                add(s + 1, n - 1 - s, 0, seq.as_mut_slice());
            }
            add(0, t, (n - s) as i64, seq.as_mut_slice());
        }
    }

    let mut standard = 0;
    let mut prv = a[0];
    for &x in a.iter().skip(1) {
        standard += if prv < x { x - prv } else { x + m - prv } as i64;
        prv = x;
    }
    println!("{}", standard - collect(&seq).iter().max().unwrap());
}
